window.__Q=window.__Q||{};window.__Q["prev/4/A1"]=[{"q":"引起巨脾的白血病是","o":["急性淋巴细胞白血病","急性红白血病","急性单核细胞白血病","慢性粒细胞白血病","急性粒细胞白血病"],"a":3,"e":"慢性髓系白血病以中性粒细胞显著增多和脾脏明显肿大为特征，巨脾可下达盆腔；Ph染色体及BCR::ABL1融合基因是其分子标志。"},{"q":"以肝内纤维组织增生为主，而少有假小叶形成的肝硬化是","o":["胆汁性肝硬化","乙肝肝硬化","丙肝肝硬化","药物性肝硬化","肝豆状核变性引起的肝硬化"],"a":0,"e":"胆汁性肝硬化以肝内纤维组织增生、纤维条索分割原有肝小叶为主，无明显肝细胞再生和假小叶改建，实质更接近肝纤维化。"},{"q":"硬皮病的特征性病变为","o":["全身多个器官间质纤维化","全身细小动脉玻璃样变、硬化","全身皮肤小血管硬化","全身性皮肤变硬，胶原纤维增生","全身皮肤多发性肉芽肿形成并纤维化"],"a":0,"e":"系统性硬化以全身多个器官间质纤维化和炎症性改变为特征，皮肤变硬只是其突出表现，内脏受累程度决定预后。"},{"q":"大叶性肺炎患者，明显的发绀症状常出现在哪一期","o":["充血水肿期","红色肝样变期","灰色肝样变期","溶解消散期","病变恢复期"],"a":1,"e":"红色肝样变期肺泡腔内充满纤维蛋白和大量红细胞，肺泡通气严重障碍，血氧合不足，故发绀等缺氧症状明显。"},{"q":"属于生理性肥大的组织器官是","o":["功能亢进的甲状腺","运动员的有关肌肉肥大","高血压患者的心脏","慢性增殖性炎的扁桃体","垂体腺瘤患者的肾上腺"],"a":1,"e":"生理性肥大指生理条件下器官负荷增加所致的肥大，如运动员骨骼肌因长期锻炼而肥大；甲状腺功能亢进、高血压心脏病属病理性肥大。"},{"q":"引起儿童期肾病综合征最常见的肾炎类型是","o":["急性弥漫性毛细血管内增生性肾小球肾炎","新月体性肾小球肾炎","弥漫性膜性肾小球肾炎","微小病变性肾小球病","弥漫性膜增生性肾小球肾炎"],"a":3,"e":"微小病变性肾小球病是儿童期肾病综合征最常见的类型，光镜下肾小球基本正常，电镜下仅见足细胞足突消失，无免疫沉积物。"},{"q":"如图所示，诊断为","o":["脑的卡他性炎","脑的纤维素性炎","脑的浆液性炎","脑表面化脓与积脓","脑脓肿"],"a":3,"e":"官方题库缺失图片"},{"q":"子宫内膜癌中最常见的类型是","o":["鳞状细胞癌","子宫内膜样腺癌","腺棘皮癌","腺鳞癌","浆液性乳头状癌"],"a":1,"e":"子宫内膜癌绝大多数为子宫内膜样腺癌，与子宫内膜增生及雌激素长期持续作用有关。浆液性乳头状癌和透明细胞癌较少，预后较差。"},{"q":"老年人产生萎缩的器官主要是","o":["心、肾","脑、心","肝、肺","心、肺","肾、脑"],"a":1,"e":"老年期萎缩以脑和心最明显，脑重量减轻、心脏体积缩小，属生理性萎缩。肾、肝、肺等器官虽也有一定萎缩，但不如脑和心显著。"},{"q":"诊断肿瘤最可靠的方法是","o":["CT检查","X线透视","超声波检查","脱落细胞学检查","活组织检查"],"a":4,"e":"活组织检查取病变组织制成切片，可直接观察细胞和结构异型性，是诊断肿瘤最可靠的方法；细胞学及影像学检查只能提供参考。"},{"q":"脓肿最常见的致病菌是","o":["溶血性链球菌","铜绿假单胞菌","金黄色葡萄球菌","白色葡萄球菌","草绿色链球菌"],"a":2,"e":"脓肿最常见的致病菌是金黄色葡萄球菌，其产生血浆凝固酶使纤维蛋白原转为纤维蛋白，故病灶局限并易形成迁徙性脓肿。"},{"q":"动脉粥样硬化主要发生在","o":["细、小动脉","大、中动脉","细、小静脉","大、中静脉","毛细血管"],"a":1,"e":"动脉粥样硬化主要累及主动脉及大、中动脉，在其内膜形成脂纹、纤维斑块和粥样斑块；细动脉和小动脉发生的是玻璃样变或纤维素样坏死。"},{"q":"风湿性心内膜炎的后期病变不包括","o":["心内膜下纤维化","腱索增粗和缩短","瓣叶之间发生粘连","心室壁肉柱变扁平","瓣膜增厚、卷曲、缩短及钙化"],"a":0,"e":"风湿性心内膜炎反复发作后瓣膜增厚、变硬、卷曲、缩短及钙化，瓣叶粘连、腱索增粗缩短，导致狭窄和关闭不全；心内膜下纤维化见于心内膜心肌纤维化等病。"},{"q":"肝细胞发生广泛变性，点状坏死，符合上述病变特点的是","o":["急性普通型肝炎","轻度慢性肝炎","重度慢性肝炎","重型肝炎","亚急性重型肝炎"],"a":0,"e":"急性普通型肝炎以肝细胞广泛水肿变性为主，坏死轻微，呈肝小叶内散在单个至数个肝细胞的点状坏死，伴少量炎细胞浸润。"},{"q":"属于慢性心包炎改变的是","o":["化脓性心包炎","缩窄性心包炎","出血性心包炎","浆液性心包炎","浆液纤维素性心包炎"],"a":1,"e":"缩窄性心包炎由心包腔内渗出物机化和瘢痕形成引起，脏壁两层粘连使心脏舒张期充盈受限；其余类型均属急性渗出性心包炎。"},{"q":"最常见的脑出血原因是","o":["血液病","原发性高血压","血管畸形","血管瘤破裂","脑脓肿"],"a":1,"e":"乳头状癌是原发性甲状腺癌中最常见的类型，青少年女性多见，生长缓慢、恶性程度低，10年生存率80%以上；虽有较早的颈淋巴结转移，但预后并不差。"},{"q":"一般心肌缺血多长时间内，梗死心肌细胞内的糖原消失","o":["5分钟","8分钟","10分钟","15分钟","30分钟"],"a":4,"e":"心肌细胞缺血20～30分钟即发生不可逆性损伤，心肌梗死后30分钟内梗死区心肌细胞内糖原减少或消失，PAS染色可显示。"},{"q":"肺石棉沉着症并发的最常见的恶性肿瘤是","o":["喉癌","肺癌","食管癌","胃癌","恶性胸膜间皮瘤"],"a":4,"e":"石棉肺并发的恶性肿瘤按发生率由高至低依次为恶性胸膜间皮瘤、肺癌、食管癌、胃癌和喉癌；50%～80%的恶性胸膜间皮瘤患者有石棉接触史。"},{"q":"手术后好发血栓的部位是","o":["下肢静脉","肾动脉","颈静脉","冠状动脉","门静脉"],"a":0,"e":"下肢深静脉和盆腔静脉血栓常发生于心力衰竭、久病和术后卧床患者，静脉血栓发生率约为动脉的4倍，故术后好发部位为下肢静脉。"},{"q":"一般不会出现肉芽组织的病变是","o":["结核空洞","脓肿壁","化生病灶","动脉粥样硬化","陈旧性心肌梗死"],"a":2,"e":"肉芽组织见于结核空洞壁、脓肿壁、动脉粥样硬化斑块及机化中的心肌梗死灶。化生是上皮或间叶组织转变为另一种分化成熟组织，不伴肉芽组织形成。"},{"q":"泌尿系统最常见的恶性肿瘤是","o":["输尿管鳞状细胞癌","Wilms瘤","肾细胞癌","输尿管移行细胞癌","膀胱移行细胞癌"],"a":2,"e":"官方答案为【肾细胞癌】，但依据教材，正确答案为【膀胱移行细胞癌】。膀胱癌是泌尿系统最常见的恶性肿瘤，移行细胞癌占90%以上；肾细胞癌只是肾脏最常见的恶性肿瘤。"},{"q":"炎症反应中最有防御作用的是","o":["组织增生","动脉充血","发热反应","吞噬作用","液体渗出"],"a":3,"e":"白细胞渗出并吞噬、杀灭病原微生物是炎症防御功能的核心环节；液体渗出仅能稀释毒素，发热和组织增生属全身反应与修复过程。"},{"q":"膀胱癌的最常见组织学类型是","o":["肉瘤样癌","鳞状细胞癌","未分化癌","腺癌","移行细胞癌"],"a":4,"e":"膀胱癌绝大多数为尿路上皮（移行细胞）癌，占90%以上；鳞状细胞癌约占3%～7%，腺癌不足2%。"},{"q":"急性感染性心内膜炎的最常见的病原体是","o":["金黄色葡萄球菌","白假丝酵母菌","肠球菌","溶血性链球菌","草绿色链球菌"],"a":0,"e":"急性感染性心内膜炎最常见的病原体是金黄色葡萄球菌，少数为肺炎链球菌和A群链球菌；亚急性感染性心内膜炎仍以草绿色链球菌为主。"},{"q":"持续高热易发生变性坏死的脏器主要是","o":["心、肝、胃","心、脾、胃","心、肝、肾","肝、脾、心","胃、肝、脾"],"a":2,"e":"持续高热时心、肝、肾等实质器官代谢旺盛、耗氧增加，最易发生细胞水肿、脂肪变甚至凝固性坏死，故这些脏器最易受累。"},{"q":"引起心肌炎最常见的原因是","o":["醉酒","细菌感染","免疫反应","药物中毒","柯萨奇B组病毒"],"a":4,"e":"病毒性心肌炎最常见的病原体是柯萨奇B组病毒，其次为柯萨奇A组病毒、埃可病毒和腺病毒，病毒直接损害心肌并引起免疫性损伤。"},{"q":"动脉粥样硬化斑块中泡沫细胞的主要来源是","o":["内皮细胞和巨噬细胞","平滑肌细胞","单核细胞和平滑肌细胞","淋巴细胞和内皮细胞","中性粒细胞和单核细胞"],"a":2,"e":"动脉粥样硬化斑块中的泡沫细胞由血中单核细胞来源的巨噬细胞及中膜迁入内膜的平滑肌细胞摄取脂质后形成。"},{"q":"下列哪种疾病无肺透明膜形成","o":["流感病毒肺炎","成人呼吸窘迫综合征","大叶性肺炎","腺病毒肺炎","新生儿呼吸窘迫综合征"],"a":2,"e":"大叶性肺炎为肺泡内纤维蛋白性炎，肺泡壁结构保持完整，不形成透明膜；透明膜见于新生儿呼吸窘迫综合征、ARDS及流感病毒、腺病毒肺炎。"},{"q":"成人型呼吸窘迫综合征早期最有诊断意义的病理组织学变化是","o":["部分肺泡萎陷","肺泡壁充血水肿","肺泡腔充满水肿液","透明膜形成","毛细血管内中性粒细胞聚集"],"a":3,"e":"ARDS早期肺泡上皮和毛细血管内皮损伤，通透性增高，富蛋白水肿液在肺泡内表面凝集成薄层红染的透明膜，是诊断该病最有意义的组织学改变。"},{"q":"关于亚急性感染性心内膜炎，下列哪项描述是错误的","o":["常引起栓塞","常由草绿色链球菌引起","可在拔牙或尿道手术后发生","常发生在原有病变的心瓣膜上","常在二尖瓣闭锁缘形成单行排列、灰白色、粟粒大小的赘生物"],"a":4,"e":"亚急性感染性心内膜炎多在原有病变的瓣膜上形成菜花状赘生物，由细菌、纤维蛋白和坏死组织构成，松脆易脱落引起栓塞。二尖瓣闭锁缘单行排列的粟粒大疣状赘生物见于风湿性心内膜炎。"},{"q":"鼻咽癌的好发部位是位于鼻咽的","o":["顶部","前壁","外侧壁","咽隐窝","顶部和侧壁"],"a":0,"e":"鼻咽癌最常发生于鼻咽顶部，其次为外侧壁和咽隐窝，前壁最少见；该处黏膜下淋巴组织丰富，早期即可出现颈部淋巴结转移。"},{"q":"大叶性肺炎红色肝样变期属于哪一种炎症","o":["出血性炎","纤维素性炎","出血浆液性炎","出血纤维素性炎","出血化脓性炎"],"a":3,"e":"大叶性肺炎的基本病变为纤维素性炎，红色肝样变期肺泡腔内充满纤维蛋白并含大量红细胞，故属出血性纤维素性炎；灰色肝样变期红细胞溶解吸收，转为纤维素性炎。"},{"q":"除下列哪项外均为中晚期食管癌的肉眼类型","o":["髓质型","蕈伞型","平坦型","溃疡型","缩窄型"],"a":2,"e":"中晚期食管癌肉眼分为髓质型、蕈伞型、溃疡型和缩窄型；平坦型属早期食管癌的肉眼类型。"},{"q":"属于原位癌的是","o":["小肝癌","大肠黏膜下癌","胃黏膜内癌","早期食管癌","乳腺导管原位癌"],"a":2,"e":"原位癌指癌变累及上皮全层但未突破基底膜向下浸润，胃黏膜内癌未突破黏膜肌层，归入高级别上皮内瘤变；大肠黏膜下癌已浸润黏膜下层，属浸润癌。"},{"q":"非霍奇金淋巴瘤按细胞来源分类，分为","o":["B细胞性和T细胞性","滤泡型和弥漫型","低度和高度恶性","外周型和中枢型","大细胞性和小细胞性"],"a":0,"e":"非霍奇金淋巴瘤按细胞来源分为B细胞性和T/NK细胞性两大类，各型均起源于相应分化阶段的淋巴细胞。"},{"q":"上皮非典型性增生是指","o":["上皮细胞增生，但极性不丧失","不转移","不浸润上皮下层","上皮细胞异型增生，排列紊乱，极性消失","不会进一步发展为原位癌或浸润癌"],"a":3,"e":"上皮非典型性增生指上皮细胞增生并出现异型性，排列紊乱、极性消失，但尚未突破基底膜；异型细胞累及上皮全层即为原位癌。"},{"q":"下列所有情况均符合肺出血肾炎综合征，除外","o":["患者可出现咯血和血尿","患者常死于肺出血和尿毒症","电镜下未发现电子致密物的沉积","免疫荧光显示肾小球内颗粒状IgG沉积","免疫荧光显示肾小球内线状IgG沉积"],"a":3,"e":"肺出血肾炎综合征由抗基底膜抗体引起，免疫荧光示基底膜线性IgG沉积，电镜下无电子致密物，临床有咯血和血尿，常死于肺出血和尿毒症。颗粒状沉积见于免疫复合物型肾炎。"},{"q":"哪一型大肠癌多见于青年人，且预后较差","o":["隆起型","溃疡型","浸润型","胶样型","息肉型"],"a":3,"e":"胶样型大肠癌含大量黏液，切面呈胶冻状，多见于青年人，恶性程度高、预后较差；隆起型、溃疡型和浸润型多见于中老年人，以溃疡型最多见。"},{"q":"风湿性心内膜炎的特征性病变是","o":["心瓣膜水肿","心瓣膜溃疡、穿孔","心瓣膜混合血栓形成","心瓣膜闭锁缘上疣状血栓形成","心瓣膜增厚变形"],"a":3,"e":"风湿性心内膜炎在二尖瓣闭锁缘形成单行排列的白色血栓，呈疣状，故称疣状心内膜炎；瓣膜溃疡穿孔见于感染性心内膜炎。"},{"q":"长管状骨骨折时可能引起的栓塞是","o":["空气栓塞","脂肪栓塞","血栓栓塞","细胞栓塞","细菌栓塞"],"a":1,"e":"长骨骨折时骨髓脂肪细胞破裂，脂滴经破裂的骨髓静脉窦进入血流引起脂肪栓塞，栓子主要阻塞肺动脉分支和毛细血管。"},{"q":"急性普通型肝炎的病变特点是","o":["肝细胞广泛变性，坏死严重","肝细胞广泛变性，炎细胞浸润明显","肝细胞广泛变性，坏死轻微","肝细胞广泛变性，淤胆明显","肝细胞广泛变性，Kupffer细胞增生活跃"],"a":2,"e":"急性普通型肝炎以肝细胞广泛水肿、气球样变为主，坏死仅呈散在点状，故为广泛变性而坏死轻微，临床常见肝大和肝区压痛。"},{"q":"关于毒性甲状腺肿的发病机制，目前认为最可能是","o":["自身免疫反应","食物中含有致甲状腺肿的物质","病毒引起的甲状腺炎症","甲状腺异常增生形成的新生物","土壤和水中缺碘"],"a":0,"e":"毒性甲状腺肿（Graves病）目前认为与自身免疫有关，血中存在多种抗甲状腺自身抗体并可与其他自身免疫病并存。碘缺乏是地方性甲状腺肿的病因，并非本病主要机制。"},{"q":"漏出性出血常见的部位是","o":["小静脉","小动脉","大动脉","毛细血管","大静脉"],"a":3,"e":"漏出性出血多发生于毛细血管，因其管壁菲薄、内皮连接少，缺氧、感染、中毒或维生素C缺乏时通透性增高，红细胞漏出。"},{"q":"淋巴结癌转移时，癌细胞首先出现在","o":["副皮质区","淋巴滤泡中心","淋巴结门部","边缘窦","淋巴结的髓质"],"a":3,"e":"癌细胞经输入淋巴管首先到达淋巴结被膜下的边缘窦，随后累及整个淋巴结使其肿大变硬，并可侵出包膜与相邻淋巴结融合成团。"},{"q":"有关流行性脑脊髓膜炎的描述中，错误的是","o":["皮肤有瘀点和瘀斑","脑膜刺激征","颅内压升高症状","血性脑脊液","脑脊液中糖含量降低"],"a":3,"e":"流脑为化脓性脑膜炎，脑脊液压力升高、外观混浊、蛋白增多、糖降低，涂片可找到脑膜炎双球菌；血性脑脊液见于蛛网膜下腔出血。"},{"q":"形成神经细胞卫星现象是下列哪一种细胞的增生","o":["小胶质细胞","星形胶质细胞","少突胶质细胞","淋巴细胞","中性粒细胞"],"a":2,"e":"一个神经元由5个或以上少突胶质细胞围绕称卫星现象，见于灰质；小胶质细胞包围吞噬坏死神经元则为噬神经细胞现象。"},{"q":"碎片状坏死发生的部位是","o":["肝小叶中央静脉","肝小叶周边界板区","肝小叶中间区","肾皮质区","肾髓质区"],"a":1,"e":"碎片状坏死发生在肝小叶周边界板处，该处肝细胞灶性坏死崩解并有炎症细胞浸润，故又称界面性肝炎，常见于慢性肝炎。"},{"q":"原发性肝癌最常见的组织学类型是","o":["未分化癌","胆管上皮癌","肝细胞癌","类癌","混合性肝癌"],"a":2,"e":"肝细胞癌起源于肝细胞，占原发性肝癌的75%～85%，是最常见的组织学类型，易侵犯门静脉形成癌栓并发生血道转移。"},{"q":"下列哪项不符合病毒性肺炎的特点","o":["常见病因是流感病毒","间质性肺炎","中性粒细胞浸润","检出病毒包涵体","透明膜形成"],"a":2,"e":"病毒性肺炎早期为间质性肺炎，渗出细胞以淋巴细胞、单核细胞为主，故中性粒细胞浸润不符合其特点；流感病毒是最常见病因，胞质内可见病毒包涵体，重症可形成透明膜。"},{"q":"膀胱癌最突出的临床表现是","o":["无痛性血尿","膀胱刺激征","尿路梗阻","蛋白尿和管型尿","腹部肿块"],"a":0,"e":"膀胱癌最常见的症状是间歇性无痛性血尿，由肿瘤乳头断裂、表面坏死溃疡出血所致；膀胱刺激征多见于合并感染或原位癌。"},{"q":"肺小细胞癌不会引起","o":["肺性骨关节病","肌无力综合征","类癌综合征","Cushing综合征","甲状腺功能亢进"],"a":4,"e":"肺小细胞癌可异位分泌ACTH、ADH等激素，引起类癌综合征、Cushing综合征、肌无力综合征和肺性骨关节病；甲状腺功能亢进与之无关。"},{"q":"肝硬化时蜘蛛痣发生的主要原因是","o":["血管内压增高","雌激素灭活减少","凝血机制障碍","门静脉压增高","低蛋白血症"],"a":1,"e":"肝硬化时肝细胞对雌激素的灭活能力下降，血中雌激素水平升高，使小动脉末梢扩张而形成蜘蛛痣，与门静脉压升高和凝血障碍无关。"},{"q":"食管肿瘤在显微镜下如图可见肿瘤细胞排列呈腺样结构，这种肿瘤最可能是","o":["未分化癌","腺癌","鳞癌Ⅰ级","鳞癌Ⅲ级","鳞状上皮乳头状瘤"],"a":1,"e":"官方题库缺失图片"},{"q":"关于肾细胞癌，下列哪项描述是正确的","o":["常在早期即有临床症状","大部分患者因血尿、腰痛和腰部肿块三联症被发现","最常见的组织病理学形态为透明细胞癌","转移少见，发生时也只局限于肾周","肉眼上肿瘤切面实性，灰白色，含少量脂质"],"a":2,"e":"肾细胞癌最常见的组织学类型是透明细胞癌，占70%~80%，癌细胞胞质透明，含脂质和糖原；早期多无症状，三联症出现时多属晚期。"},{"q":"来源于三个胚层组织的肿瘤称","o":["癌肉瘤","混合瘤","畸胎瘤","错构瘤","胚胎瘤"],"a":2,"e":"畸胎瘤由性腺或胚胎剩件中的全能细胞发生，含两个以上胚层的多种组织成分，结构混乱，可同时见到皮肤、软骨和腺体等。"},{"q":"金黄色葡萄球菌引起","o":["导管周围乳腺炎","乳腺导管扩张症","脂肪坏死","肉芽肿性乳腺炎","急性乳腺炎"],"a":4,"e":"急性乳腺炎多由金黄色葡萄球菌经乳头皲裂或乳管侵入引起，属化脓性炎；导管周围乳腺炎、肉芽肿性乳腺炎与分泌物潴留及自身免疫反应有关。"},{"q":"导致肉眼所见“虎斑心”的形态改变的是心肌细胞发生","o":["淀粉样变性","脂肪变性","脂褐素沉积","细胞水肿","黏液样变性"],"a":1,"e":"严重贫血和缺氧时心肌细胞发生脂肪变性，脂滴在心室壁和乳头肌呈黄白色条纹与暗红色心肌相间，形成虎斑心。"},{"q":"下列组织发生的肿瘤不能称为癌的是","o":["肠上皮","血管内皮","肝细胞","胆管上皮","甲状腺腺上皮"],"a":1,"e":"癌是上皮组织来源的恶性肿瘤，肠上皮、肝细胞、胆管上皮和甲状腺腺上皮发生的肿瘤均称癌。血管内皮属间叶组织，其恶性肿瘤称血管肉瘤。"},{"q":"引起卵巢krukenberg瘤的是","o":["肝癌","肺癌","胃肠道癌","乳腺癌","子宫颈癌"],"a":2,"e":"Krukenberg瘤多由胃肠道黏液癌，特别是胃的印戒细胞癌经种植或淋巴道、血行转移至卵巢，镜下为富于黏液的印戒细胞弥漫浸润。"},{"q":"毛细血管内增生性肾小球肾炎的肉眼变化主要呈现","o":["大白肾","大红肾","颗粒性固缩肾","瘢痕肾","多囊肾"],"a":1,"e":"毛细血管内增生性肾小球肾炎肾脏表面充血并有散在粟粒大小出血点，呈大红肾或蚤咬肾。大白肾见于膜性肾小球病，颗粒性固缩肾见于慢性肾炎。"},{"q":"确定癌的主要依据是","o":["灰白、质硬","瘤细胞呈巢状排列","出现病理性核分裂象","细胞异型性明显","40岁以上中老年人"],"a":1,"e":"癌起源于上皮组织，镜下癌细胞呈巢状、腺管状或条索状排列，与间质分界较清，可见细胞间桥或角化珠，是与肉瘤鉴别的主要依据。"},{"q":"下列关于乳腺导管内乳头状瘤的描述错误的是","o":["多见于中老年妇女","恶变率极低","乳腺肿物多位于乳晕下","绝大多数是多发性","直径一般小于2cm"],"a":3,"e":"乳腺导管内乳头状瘤多位于乳晕下大导管内，常为单发、体积小、恶变率低，多见于中年经产妇；多发性者属乳头状瘤病，性质不同。"},{"q":"几乎无纤维、血管、间质的肿瘤是","o":["横纹肌肉瘤","肝细胞癌","黑色素瘤","淋巴瘤","绒毛膜癌"],"a":4,"e":"绒毛膜癌由滋养层细胞高度增生构成，癌组织内无绒毛结构，也无自身纤维血管间质，依靠宿主血管供血，故几乎无纤维、血管和间质。"},{"q":"不符合慢性支气管炎咳嗽咳痰的病理基础是","o":["黏膜上皮杯状细胞增多","浆液细胞黏液化","黏液腺增生","管壁充血水肿，炎性渗出","纤毛细胞增生"],"a":4,"e":"慢性支气管炎时杯状细胞增多、浆液腺黏液化、黏液腺增生以及管壁充血水肿渗出共同导致咳痰；纤毛柱状上皮变性坏死脱落、纤毛细胞减少。"},{"q":"在化脓性炎中，坏死组织的液化分解是由于下列哪一类细胞的浸润所致","o":["巨噬细胞","中性粒细胞","嗜酸性粒细胞","淋巴细胞","浆细胞"],"a":1,"e":"脓肿中大量中性粒细胞浸润后坏死成为脓细胞，释放蛋白溶解酶使坏死组织液化形成脓液，故坏死组织的液化分解由中性粒细胞所致。"},{"q":"下列属于T细胞性淋巴瘤的恶性肿瘤是","o":["淋巴浆细胞性淋巴瘤","蕈样霉菌病/Sezary综合征","滤泡性淋巴瘤","套细胞淋巴瘤","绿色瘤"],"a":1,"e":"蕈样肉芽肿病及Sézary综合征是原发于皮肤的成熟T细胞淋巴瘤，瘤细胞表达CD4；淋巴浆细胞性、滤泡性和套细胞淋巴瘤属B细胞肿瘤，绿色瘤为髓系白血病细胞浸润。"},{"q":"下列关于冠状动脉粥样硬化性心脏病的叙述，哪一项是错误的","o":["左心侧壁的梗死常由左前降支阻塞引起","透壁性心肌梗死的发生机制常与粥样斑块继发血栓形成有关","心内膜下心肌梗死灶常为多发性小灶性","心肌梗死时服用硝酸酯类药物不能缓解疼痛","冠状动脉病变最常见而严重的分支为左前降支"],"a":0,"e":"左心室侧壁由左冠状动脉旋支供血，其梗死由左旋支阻塞引起，而非左前降支；左前降支阻塞主要引起左心室前壁、心尖及室间隔前2/3梗死，该支病变最常见也最严重。"},{"q":"下列哪种不是神经系统变性疾病","o":["Alzheimer病","Parkinson病","外伤","慢性进行性舞蹈病","纹状体黑质变性"],"a":2,"e":"神经变性疾病是以神经元原发性变性为特征的一组疾病，Alzheimer病、Parkinson病、慢性进行性舞蹈病和纹状体黑质变性均属此类。外伤属外因性损伤，不是变性病。"},{"q":"下列哪项是急性出血性胰腺炎的表现","o":["胰腺肿大、变硬","腹腔内少量渗出","广泛出血坏死","局限性脂肪坏死","中性粒细胞及单核细胞浸润"],"a":2,"e":"急性出血坏死型胰腺炎以胰腺广泛出血坏死为特征，胰腺肿大、质软呈暗红色，分叶结构模糊，腹腔可有大量血性渗出和脂肪坏死。"},{"q":"创伤性脂肪栓塞时，栓塞部位通常是","o":["肝","肾","肺","脑","心"],"a":2,"e":"创伤性脂肪栓塞时脂滴经破裂静脉入右心，随血流首先阻塞肺动脉分支及毛细血管；直径小于20μm的脂滴可通过肺循环引起全身器官栓塞。"},{"q":"有关原发性高血压的叙述，下列错误的是","o":["高血压病常引起左心室肥大","高血压常引起下肢坏疽","高血压可继发糖尿病","高血压晚期的肾脏常为颗粒性固缩肾","脑出血是高血压病的主要致死原因"],"a":2,"e":"高血压病引起左心室向心性肥大、晚期出现颗粒性固缩肾，脑出血是最常见死因；糖尿病与高血压有共同遗传背景且常并存，但高血压不会继发糖尿病。"},{"q":"胃肠道的恶性肿瘤经血道首先转移到","o":["肺","淋巴结","肝","骨","脑"],"a":2,"e":"胃肠道恶性肿瘤细胞侵入门静脉系统，随门静脉血流首先停留于肝窦，故肝是最先发生血道转移的部位；肺转移多见于经体循环静脉回流的肿瘤。"},{"q":"乳腺癌中最常见的类型是","o":["小叶原位癌","粉刺癌","浸润性导管癌","浸润性小叶癌","伴髓样特征的癌"],"a":2,"e":"浸润性癌非特殊型即既往所称浸润性导管癌，占乳腺癌的大多数，由导管原位癌发展而来；小叶原位癌和粉刺癌属非浸润性癌。"},{"q":"下列关于心肌梗死的合并症的描述，哪项是错误的","o":["心脏破裂多见","可引起心源性休克","附壁血栓多见于左心室","室壁瘤较多见","常引起急性充血性心力衰竭"],"a":4,"e":"官方答案为【常引起急性充血性心力衰竭】，但依据教材，正确答案为【心脏破裂多见】。心力衰竭是心肌梗死最常见的并发症，而心脏破裂发生率低，属少见并发症。"},{"q":"IgA肾病的超微结构改变主要是","o":["系膜区电子致密物沉积","内皮下电子致密物沉积","上皮下电子致密物沉积","基膜内电子致密物沉积","肾小球内没有电子致密物沉积"],"a":0,"e":"IgA肾病以系膜区IgA沉积为特征，电镜下见系膜区电子致密物沉积，伴系膜细胞和基质增生。内皮下沉积见于膜增生性肾炎，上皮下沉积见于膜性肾病。"},{"q":"手术切口为何选择术后5～7日拆线","o":["伤口内肉芽组织已长满","伤口两侧出现胶原纤维连接","伤口内成肌纤维细胞大量形成","伤口内成纤维细胞增生达高峰","炎症基本消失"],"a":1,"e":"肉芽组织约第3天填满创口，第5~7天伤口两侧出现胶原纤维连接，抗张力强度增加而达临床愈合标准，此时可以拆线。"},{"q":"骨髓瘤起源于","o":["淋巴细胞","浆细胞","粒细胞","单核细胞","造血干细胞"],"a":1,"e":"骨髓瘤起源于浆细胞，瘤细胞表达CD138、CD38等浆细胞标记，不表达CD19和CD20，故又称浆细胞骨髓瘤。"},{"q":"伤寒带菌者细菌一般居留于","o":["结肠","胆囊","小肠","肝脏","直肠"],"a":1,"e":"伤寒痊愈后少数患者胆囊内长期带菌并随胆汁间断排菌，成为慢性带菌者，是伤寒传播的重要传染源。"},{"q":"下列哪种类型为不累及肺泡的肺气肿","o":["全腺泡型","腺泡中央型","腺泡周围型","不规则型","间质性肺气肿"],"a":4,"e":"肺泡性肺气肿包括腺泡中央型、全腺泡型、腺泡周围型和不规则型，病变均累及肺泡；间质性肺气肿是气体进入肺间质，不累及肺泡腔。"},{"q":"下述哪种肿瘤的发生可与化生有关","o":["皮肤鳞状细胞癌","肾盂移行细胞癌","肠黏液腺癌","肝胆管上皮癌","肠型胃癌"],"a":4,"e":"慢性萎缩性胃炎伴肠上皮化生后，化生的柱状上皮可进一步发生异型增生而癌变，故肠型胃癌的发生与肠上皮化生密切相关。"},{"q":"慢性轻度肝炎细胞坏死的特点是","o":["点状坏死","灶性坏死","碎片状坏死","大块坏死","溶解性坏死"],"a":0,"e":"慢性轻度肝炎以点状坏死为主，即肝小叶内散在单个至数个肝细胞坏死，伴门管区炎症；碎片状坏死见于中、重度，桥接坏死提示病变活动较重。"},{"q":"急性弥漫性增生性肾小球肾炎和急性肾盂肾炎患者，尿液检查最大的不同是","o":["红细胞","脱落细胞","纤维素","细菌","蛋白"],"a":3,"e":"急性肾盂肾炎为化脓性炎，尿中可见大量中性粒细胞和细菌；急性弥漫性增生性肾小球肾炎为变态反应性炎，尿检以血尿、蛋白尿为主，尿中无细菌。"},{"q":"关于心肌梗死的描述，下列哪项是错误的","o":["梗死灶形态不规则","病变多属出血性梗死","全层梗死可致心脏破裂","梗死多发生在左心室前壁或心尖部","病变累及心室壁心腔侧1/3称心内膜下梗死"],"a":1,"e":"心肌梗死多属贫血性梗死，梗死灶不规则呈地图状，周边有充血出血带，累及心内膜可继发附壁血栓，透壁性梗死可致心脏破裂。"},{"q":"风湿性心肌炎会出现以下哪种特征性结构","o":["Osler结节","Negri小体","Aschoff小体","环形红斑","McCallum斑"],"a":2,"e":"风湿病的特征性病变为风湿小体即Aschoff小体，是增生期肉芽肿性病变，对诊断风湿病有意义。Osler结节见于感染性心内膜炎。"},{"q":"下列哪项病变可发生转移性钙化","o":["结核病时的干酪样坏死","胰腺炎时的脂肪坏死","结缔组织的透明变性","甲状旁腺功能亢进","血吸虫病时的虫卵结节"],"a":3,"e":"转移性钙化发生于甲状旁腺功能亢进、维生素D摄入过多和肾衰竭等引起的高血钙状态，钙盐沉积于肾、肺、胃等正常组织的间质和血管壁。"},{"q":"关于风湿病的论述中，哪一项是错误的是","o":["风湿病是累及全身结缔组织的变态反应性疾病","心脏病变对患者危害最大","风湿性心内膜炎引起的慢性心瓣膜病严重影响心脏功能","风湿性关节炎常可导致关节畸形","皮下结节和环形红斑对临床诊断风湿病有帮助"],"a":3,"e":"风湿性关节炎为浆液性渗出性炎，呈游走性、多发性，累及膝踝肩腕等大关节，愈后不留畸形；导致关节畸形强直的是类风湿关节炎。"},{"q":"脑动脉粥样硬化最常见的部位是","o":["大脑中动脉","大脑前动脉","大脑后动脉","大脑中动脉及Willis环","基底动脉及大脑后动脉"],"a":3,"e":"脑动脉粥样硬化最常见于颈内动脉起始部、基底动脉、大脑中动脉和基底动脉环，管腔狭窄可致脑萎缩、脑软化和脑出血。"},{"q":"抑制动脉粥样硬化发病的因素是","o":["胆固醇","高密度脂蛋白","低密度脂蛋白","极低密度脂蛋白","β脂蛋白"],"a":1,"e":"高密度脂蛋白将外周组织胆固醇逆向转运至肝脏代谢，具有抗动脉粥样硬化作用；低密度、极低密度和β脂蛋白升高则促进斑块形成。"},{"q":"肺气肿的病变部位在","o":["肺泡","支气管","呼吸性细支气管以远的肺组织","管径＜2mm的小支气管","终末细支气管"],"a":2,"e":"肺气肿是末梢肺组织即呼吸性细支气管以远的肺组织含气量过多伴肺泡间隔破坏，导致肺体积膨大、弹性减弱、通气功能降低。"},{"q":"下列哪种疾病最不可能发生结缔组织玻璃样变","o":["结核病的干酪样坏死","纤维型星形胶质细胞瘤","肺硅沉着病","慢性胸膜炎","心肌梗死"],"a":1,"e":"结缔组织玻璃样变见于纤维组织增生老化的病灶，如结核干酪坏死灶机化、硅肺、慢性胸膜炎和心肌梗死瘢痕；胶质瘢痕不含胶原纤维，不发生此种改变。"},{"q":"脑萎缩的大体特征是","o":["脑沟加深，脑回变窄","脑沟加深，脑回增宽","脑沟变窄，脑回增宽","脑沟变窄，脑回变窄","脑沟变浅，脑回变窄"],"a":0,"e":"脑萎缩时皮质变薄，脑回变窄、脑沟增宽加深，以额叶、颞叶和顶叶最显著，切面可见代偿性脑室扩张。"},{"q":"关于急性重型肝炎的病变特点，不正确的是","o":["肝明显缩小，包膜皱缩","肝实质弥漫大块坏死","网状支架塌陷","肝质地柔软","肝细胞再生结节形成"],"a":4,"e":"急性重型肝炎起病急、病程短，肝细胞弥漫性大片坏死，网状支架塌陷，肝体积显著缩小、包膜皱缩、质地柔软，尚无再生结节形成。"},{"q":"诊断肉瘤的主要依据是","o":["青年人","无包膜","肺部转移","异型性大，分裂象","瘤细胞弥漫分布，与间质分界不清"],"a":4,"e":"肉瘤细胞多不成巢、弥漫生长，实质与间质分界不清，间质血管丰富而纤维组织少，这是与癌巢状结构最重要的镜下区别，网状纤维见于瘤细胞之间。"},{"q":"下列关于纤维素性炎症的叙述中，哪项是正确的","o":["合并有少量中性粒细胞浸润时应称为化脓性纤维素性炎","当出现机化以后便引起纤维素性粘连","其好发部位为黏膜、浆膜和肺","假膜的必有成分是纤维素、白细胞、浆膜间皮细胞和细菌","咽部假膜常与其下方的黏膜疏松粘连，易剥脱而引发严重后果"],"a":2,"e":"纤维蛋白性炎好发于黏膜、浆膜和肺组织。假膜由纤维素、中性粒细胞和坏死黏膜组织构成，咽部假膜与黏膜粘连紧密不易脱落。"},{"q":"下列属于良性肿瘤的是","o":["肾母细胞瘤","精原细胞瘤","髓母细胞瘤","淋巴瘤","葡萄胎"],"a":4,"e":"葡萄胎属良性滋养细胞病变，绒毛水肿呈葡萄状且局限于宫腔；肾母细胞瘤、精原细胞瘤、髓母细胞瘤和淋巴瘤均为恶性肿瘤。"},{"q":"肿瘤对放射治疗和化学治疗的敏感性取决于","o":["是否有变性坏死","是否有包膜","瘤细胞的分化程度","主、间质的比例","发生的部位"],"a":2,"e":"肿瘤对放疗、化疗的敏感性取决于瘤细胞的分化程度，分化越低者生长越活跃、处于增殖周期的细胞越多，对射线和药物越敏感。"},{"q":"局灶性节段性肾小球硬化的临床特点是","o":["极少出现血尿和高血压","激素治疗效果好","多表现为肾病综合征","多见于中、老年人","少量蛋白尿"],"a":2,"e":"局灶性节段性肾小球硬化多见于青少年，多表现为肾病综合征，常伴血尿和高血压，对糖皮质激素治疗反应差，可缓慢进展至肾衰竭。"},{"q":"下列哪个病变可能引起大量蛋白尿","o":["肾小球脏层上皮细胞增生","系膜增生","肾小球毛细血管袢粘连","肾小球毛细血管基底膜呈虫蛀状","肾小球内皮细胞增生"],"a":3,"e":"膜性肾小球病时免疫复合物使基底膜弥漫增厚，银染色见钉突形成，基底膜出现虫蛀状缺损，滤过屏障破坏导致大量蛋白尿。系膜或内皮细胞增生一般不引起大量蛋白尿。"},{"q":"引起亚急性感染性心内膜炎的常见病原体是","o":["草绿色链球菌","金黄色葡萄球菌","产气荚膜梭状芽孢杆菌","柯萨奇B组病毒","朊病毒"],"a":0,"e":"亚急性感染性心内膜炎主要由毒力较弱的甲型溶血性链球菌（草绿色链球菌）引起，约占75%，肠球菌次之。金黄色葡萄球菌是急性感染性心内膜炎最常见的病原体。"},{"q":"AIDS患者血液检查减少最明显的是","o":["淋巴细胞","中性粒细胞","巨噬细胞","NK细胞","树突细胞"],"a":0,"e":"HIV主要侵犯CD4+ T淋巴细胞，导致淋巴细胞大量破坏、耗竭，故AIDS患者血液检查减少最明显的是淋巴细胞。晚期淋巴结淋巴细胞几乎消失殆尽，脾内淋巴细胞亦高度耗竭。"},{"q":"慢性乙型肝炎时出现毛玻璃样肝细胞的原因是","o":["滑面内质网增生，内质网池内有大量HBsAg颗粒","线粒体肿胀","粗面内质网内有大量HBsAg颗粒","核糖体增多","高尔基体复合体内有大量HBsAg颗粒"],"a":0,"e":"毛玻璃样肝细胞电镜下见滑面内质网增生，内质网池内有较多HBsAg颗粒，免疫组化HBsAg阳性。粗面内质网及高尔基体并非其形成部位。"},{"q":"乳腺癌最常见的组织学类型是","o":["浸润性小叶癌","髓样癌","浸润性导管癌","导管原位癌为主的浸润性导管癌","小管癌"],"a":2,"e":"浸润性癌非特殊型即原称的浸润性导管癌，由导管原位癌发展而来，癌细胞突破基底膜呈巢索状浸润间质，约占乳腺癌的70%，是最常见的类型。"},{"q":"干酪样坏死好发于","o":["风湿病","伤寒","结核","麻风","梅毒"],"a":2,"e":"干酪样坏死是结核病的特征性病变，镜下为红染无结构的颗粒状物，对结核病病理诊断具有意义。风湿病为纤维素样坏死，伤寒为凝固性坏死。"},{"q":"单核巨噬细胞在局部增生、聚集而形成的结节状病灶称","o":["炎性假瘤","炎性息肉","炎性浸润","肉芽肿","肉芽组织"],"a":3,"e":"巨噬细胞及其衍生细胞在局部增生、聚集，形成境界清楚的结节状病灶，称肉芽肿；由上皮样细胞和多核巨细胞构成者为感染性肉芽肿，如结核结节。"},{"q":"NK/T细胞淋巴瘤，常发生部位是","o":["肠道","淋巴结","鼻腔","皮肤","扁桃体"],"a":2,"e":"NK/T细胞淋巴瘤多累及结外，鼻腔是最典型的好发部位，其次为口腔腭部、鼻咽和鼻窦；临床表现为顽固性鼻塞、鼻出血和鼻面部肿胀，肿瘤常呈血管中心性浸润破坏。"},{"q":"容易转移到脊椎的癌是","o":["胃癌","肾癌","前列腺癌","卵巢癌","膀胱癌"],"a":2,"e":"前列腺癌易经椎静脉丛转移至脊椎骨，因该静脉丛与骨盆静脉丛存在吻合支，转移可先于肺；甲状腺癌、肾癌和乳腺癌也易发生骨转移。"},{"q":"与子宫颈癌发生密切相关的病毒是","o":["单纯疱疹病毒","人乳头瘤病毒","EB病毒","腺病毒","巨细胞病毒"],"a":1,"e":"高危型人乳头瘤病毒HPV-16、18感染是子宫颈癌发生的主要因素，其E6、E7蛋白分别使p53和Rb失活，导致细胞恶性转化。"},{"q":"以下哪类肿瘤不发生转移","o":["高分化癌","原位癌","早期浸润癌","微小癌","霍奇金病"],"a":1,"e":"原位癌癌变仅限于上皮层内、不突破基底膜，无血管和淋巴管侵入，故不发生转移。早期浸润癌、微小癌已突破基底膜，霍奇金病为恶性淋巴瘤，均可发生转移。"},{"q":"图中的主要成分是","o":["增生的肉芽组织","纤维蛋白沉积","血小板和纤维蛋白","红细胞和纤维蛋白","纤维蛋白"],"a":2,"e":"官方题库缺失图片"},{"q":"炎症早期出现炎性充血时，最先累及的血管为","o":["细动脉","小动脉","细静脉","小静脉","毛细血管"],"a":0,"e":"炎症早期致炎因子经轴突反射和血管活性胺作用，使细动脉最先扩张、血流加快，局部氧合血红蛋白增多而呈鲜红色，随后毛细血管和小静脉扩张转为淤血。"},{"q":"急性病毒性肝炎时，最常见的炎症细胞是","o":["中性粒细胞","嗜酸性粒细胞","单核细胞","淋巴细胞","浆细胞"],"a":3,"e":"急性病毒性肝炎时肝细胞水肿、点状坏死，门管区炎症以淋巴细胞浸润为主，库普弗细胞和多形核白细胞少见。"},{"q":"关于慢性肺源性心脏病，下列哪项是错误的","o":["能够导致肺循环阻力增加的疾病可引起慢性肺源性心脏病","慢性支气管炎是最常见的原发疾病","间质性肺炎引起肺间质纤维化可并发慢性肺源性心脏病","慢性肺源性心脏病发生的关键环节是肺动脉高压","右心肥大、扩张是其病变特点"],"a":2,"e":"肺心病是慢性肺疾病使肺循环阻力增加、肺动脉高压所致右心室肥大扩张的心脏病，慢支并发肺气肿最常见；间质性肺炎以肺间质炎症为主，一般不引起肺循环阻力持续升高。"},{"q":"动脉粥样硬化的继发性病变中最危险的是","o":["钙化","斑块内出血","斑块破裂","动脉瘤形成","粥样瘤性溃疡"],"a":2,"e":"斑块破裂使纤维帽破损，粥样物入血形成胆固醇栓子，胶原暴露又继发血栓形成，可致急性冠脉综合征或脑梗死，是最危险的继发病变。"},{"q":"下列描述与浆液性囊腺瘤不相符的是","o":["多为单侧发生","可有乳头状结构","常为多房性生长","囊壁为单层立方上皮","恶变率高"],"a":2,"e":"浆液性囊腺瘤多为单侧、单房，囊壁被覆单层立方或柱状上皮，可有乳头状突起；多房性生长是黏液性囊腺瘤的特点。"},{"q":"较多嗜酸性粒细胞浸润见于","o":["伤寒杆菌感染","变态反应或寄生虫感染","乙型脑炎病毒感染","溶血性链球菌感染","葡萄球菌感染"],"a":1,"e":"寄生虫感染和IgE介导的过敏反应以嗜酸性粒细胞浸润为主，其颗粒中的主要碱性蛋白对寄生虫有毒性；细菌感染以中性粒细胞为主，病毒感染多为单核巨噬细胞或淋巴细胞。"},{"q":"诊断肝硬化最可靠的依据是","o":["白球蛋白比值倒置","面部、胸前蜘蛛痣","脾肿大","腹水","肝穿刺活检，镜下见假小叶形成"],"a":4,"e":"肝硬化时纤维组织分割并包绕肝小叶形成假小叶，是诊断肝硬化的病理学金标准，肝穿刺活检镜下见假小叶即可确诊。"},{"q":"扩张型心肌病的病变特点是","o":["室间隔不匀称肥厚","不伴有附壁血栓","心肌间质纤维化","心肌细胞不均匀性肥大","心肌细胞数量增多"],"a":2,"e":"扩张型心肌病以心腔扩张、室壁变薄为特点，镜下心肌细胞肥大与萎缩交错，心肌间质纤维化并见微小坏死或瘢痕灶；室间隔不匀称肥厚见于肥厚型心肌病。"},{"q":"慢性胃溃疡最常见的并发症是","o":["出血","穿孔","梗阻","癌变","粘连"],"a":0,"e":"慢性胃溃疡最常见的并发症是出血，因溃疡底部血管被侵蚀破裂所致。穿孔、幽门梗阻和癌变发生率较低，出血居并发症首位。"},{"q":"下列哪项不是肉芽组织的作用","o":["抗感染保护创面","填补伤口及其他组织缺损","机化血栓","包裹坏死、炎性渗出物及其他异物","能抗牵拉"],"a":4,"e":"肉芽组织可抗感染保护创面、填补组织缺损、机化血栓及坏死渗出物并包裹异物。抗牵拉是瘢痕组织的作用，肉芽组织质地柔软，不具备此功能。"},{"q":"炎症时渗出的纤维素是指下列哪种成分","o":["纤维组织","纤维蛋白","纤维细胞","纤维蛋白原","胶原纤维"],"a":1,"e":"炎症时渗出的纤维素即纤维蛋白，由纤维蛋白原在凝血酶作用下转变而成，镜下呈红染网状或条索状，可被溶解吸收或机化。"},{"q":"痢疾杆菌感染，结肠发生","o":["蜂窝织炎","表面化脓","浆液性炎","假膜性炎","出血性炎"],"a":3,"e":"痢疾杆菌感染结肠后形成假膜性炎，假膜由纤维蛋白、坏死上皮、中性粒细胞和细菌构成，属纤维素性炎，脱落后遗留不规则浅表溃疡。"},{"q":"前列腺癌血行转移的最常见部位是","o":["颅骨","脊椎骨","股骨","盆骨","肋骨"],"a":1,"e":"前列腺癌细胞侵入骨盆静脉后经椎静脉丛吻合支播散，故血行转移以脊椎骨最常见，其次为股骨近端、盆骨和肋骨，且多为成骨性转移。"},{"q":"下面关于大叶性肺炎不正确的描述是","o":["肺泡壁毛细血管可扩张、充血","肺泡壁结构通常遭到破坏","肺泡腔内可有大量红细胞、少量中性粒细胞和巨噬细胞","病变常累及肺大叶的全部或大部","主要由肺炎球菌引起的以肺泡内纤维素渗出为主的炎症"],"a":1,"e":"大叶性肺炎为肺泡内纤维蛋白性炎，肺泡壁毛细血管扩张充血，但肺泡壁结构通常完整不被破坏，故病变消散后肺组织可恢复正常。破坏支气管壁和肺泡结构的是小叶性肺炎。"},{"q":"流行性乙型脑炎的病变部位最轻微的是","o":["大脑皮层","脊髓","丘脑","中脑","基底核"],"a":1,"e":"流行性乙型脑炎病变以大脑皮质、基底核、视丘最重，中脑次之，脊髓最轻，故临床以意识障碍、抽搐等脑部症状为主。"},{"q":"新月体主要由下列哪种细胞增生形成","o":["系膜细胞","足细胞","内皮细胞","壁层上皮细胞/巨噬细胞","中性粒细胞"],"a":3,"e":"新月体由增生的壁层上皮细胞和渗出的单核巨噬细胞构成，可伴中性粒细胞浸润，后期纤维化转为纤维性新月体，压迫毛细血管丛并闭塞球囊腔。"},{"q":"流行性乙型脑炎的主要病变中不包括","o":["脑实质有上皮样细胞小灶形成","脑组织中胶质结节形成","脑小血管周围淋巴细胞“血管套”形成","筛网状软化灶","神经细胞变性坏死"],"a":0,"e":"流行性乙型脑炎的基本病变为神经细胞变性坏死、卫星现象和噬神经细胞现象、胶质结节形成、血管套及筛网状软化灶；上皮样细胞小灶是结核等肉芽肿性炎的表现。"},{"q":"如图，可能的疾病是","o":["急性肾小球肾炎","急进性肾小球肾炎","慢性肾小球肾炎","慢性肾盂肾炎","肾癌"],"a":3,"e":"官方题库缺失图片"},{"q":"脑动脉发生栓塞，其栓子最可能来自","o":["下肢浅静脉血栓","下肢深静脉血栓","左心室附壁血栓","肺动脉血栓","下腔静脉血栓"],"a":2,"e":"脑属体循环，动脉栓塞的栓子约80%来自左心腔，左心室附壁血栓脱落后经主动脉进入脑动脉；下肢深静脉血栓多引起肺动脉栓塞。"},{"q":"化脓性炎中，坏死组织的溶解液化是由于下列哪一类细胞存在所致","o":["炎症部位坏死的组织细胞","浸润的巨噬细胞","浸润的浆细胞","浸润的嗜酸性粒细胞","脓细胞"],"a":4,"e":"脓液中变性坏死的中性粒细胞称脓细胞，其释放的蛋白水解酶使坏死组织溶解液化，从而形成脓液和脓腔。"},{"q":"如图，此图的病变属","o":["肥大","化生","萎缩","增生","扩大"],"a":2,"e":"官方题库缺失图片"},{"q":"肺出血肾炎综合征的病理类型为","o":["新月体性肾小球肾炎","微小病变性肾小球病","膜性肾小球肾炎","膜增生性肾小球肾炎","IgA肾病"],"a":0,"e":"肺出血肾炎综合征由抗GBM抗体引起，肺与肾小球基膜同时受损，肾小球壁层上皮细胞增生形成新月体，属急进性（新月体性）肾小球肾炎，表现为咯血伴血尿。"},{"q":"见于甲床，直径1cm的紫蓝色结节是","o":["血管球瘤","血管外皮瘤","肉芽组织型血管瘤","上皮样血管内皮瘤","毛细血管瘤"],"a":0,"e":"血管球瘤由血管球细胞构成，好发于甲床下，呈紫蓝色小结节，直径多在1cm以内，局部触痛明显，属良性肿瘤。"},{"q":"胰头癌早期扩散的主要方式是","o":["直接蔓延至胆总管和十二指肠","经门静脉转移到肝","经血行转移至肺","经淋巴道转移至腹腔淋巴结","腹腔内种植性转移"],"a":0,"e":"胰头癌早期即直接蔓延至胆总管和十二指肠，引起阻塞性黄疸；淋巴道转移和经门静脉的肝内转移多在稍后发生。"},{"q":"Ⅱ型膜性增生性肾小球肾炎的特征性表现，除外","o":["GBM中出现不规则的带状电子密度极高的沉积物","免疫荧光显示肾小球以C3沉积为主","光镜下见肾小球细胞增多，基底膜增厚","银染色显示GBM增厚并分离，呈双轨状","电镜下见内皮下出现致密沉积物，免疫荧光呈颗粒状"],"a":4,"e":"Ⅱ型膜增生性肾小球肾炎为致密沉积物病，大量块状高电子密度物沿基膜致密层呈带状沉积，免疫荧光以C3为主而无IgG和C1q；内皮下沉积物见于Ⅰ型。"},{"q":"细小动脉壁玻璃样变最常见于下列哪种疾病","o":["急性弥漫性增生性肾小球肾炎","急性肾盂肾炎","快速进行性肾小球肾炎","急进型高血压","缓进型高血压"],"a":4,"e":"细小动脉壁玻璃样变又称细动脉硬化，因血浆蛋白渗入及基底膜样物质沉积使管壁增厚、管腔狭窄，常见于缓进型高血压和糖尿病的肾、脑、脾细小动脉。"},{"q":"关于炎症的论述，下列正确的是","o":["炎症反应均对机体有利","炎症是一种防御反应","任何有机体均可发生炎症","损伤必然导致炎症","炎症是活体组织的损伤"],"a":1,"e":"炎症是活体组织对致炎因子及损伤所发生的以防御为主的反应，具有抗感染、清除坏死组织和修复损伤的积极作用，反应过度时也可造成损害。"},{"q":"下肢骨折后，石膏固定，长期不活动，使患肢变细，肌肉萎缩，属于","o":["压迫性萎缩","内分泌性萎缩","营养不良性萎缩","去神经性萎缩","失用性萎缩"],"a":4,"e":"骨折后石膏固定、长期不活动使肌肉工作负荷减少、功能代谢低下，属失用性萎缩；石膏过紧压迫神经血管时则兼有压迫性和神经性因素。"},{"q":"Krukenberg瘤的本质是","o":["胃癌","肠癌","卵巢癌","肝癌","肾癌"],"a":0,"e":"Krukenberg瘤是胃黏液癌尤其印戒细胞癌经种植或淋巴道、血行转移至双侧卵巢形成的转移性黏液腺癌，本质为胃癌的卵巢转移。"},{"q":"细胞因子主要由哪些细胞产生","o":["肥大细胞和血小板","中性粒细胞和嗜酸性粒细胞","淋巴细胞和单核细胞","中性粒细胞和嗜碱性粒细胞","肥大细胞和嗜碱性粒细胞"],"a":2,"e":"细胞因子主要由活化的淋巴细胞和单核巨噬细胞产生，前者产生淋巴因子，后者产生单核因子，共同参与炎症与免疫调节。"},{"q":"关于病毒性肝炎的肝细胞基本病变，下列选项错误的是","o":["气球样变","细胞质疏松化","嗜酸性变","肝细胞糖原沉积","肝细胞溶解性坏死"],"a":3,"e":"病毒性肝炎的基本病变为肝细胞水肿即气球样变、嗜酸性变和溶解性坏死；肝细胞糖原沉积是糖原贮积病等代谢性疾病的表现。"},{"q":"化脓性炎症的主要特征为","o":["血清渗出","血浆蛋白渗出","中性粒细胞渗出","纤维蛋白渗出","血清渗出、血浆蛋白渗出及纤维蛋白渗出"],"a":2,"e":"化脓性炎以中性粒细胞渗出为主，并伴不同程度的组织坏死和脓液形成；浆液渗出和纤维蛋白渗出分别见于浆液性炎和纤维蛋白性炎。"},{"q":"判断良恶性肿瘤的主要组织学特征是","o":["肿瘤细胞排列紊乱","肿瘤细胞核的异型性","肿瘤细胞的多型性","肿瘤细胞质嗜碱性","肿瘤细胞失去极性"],"a":1,"e":"判断良恶性主要看细胞核的异型性，包括核增大、核质比增高、核深染、核仁明显和病理性核分裂象；细胞排列紊乱和失去极性属结构异型性，特异性较低。"},{"q":"下列有关流行性脑脊髓炎的述说错误的是","o":["脑膜刺激征","脑膜充血","颅内压增高","脑脊液浑浊","筛状软化灶"],"a":4,"e":"筛状软化灶是乙型脑炎的特征性病变；流脑表现为脑膜充血、脓性渗出、颅内压增高和脑膜刺激征，脑脊液混浊。"},{"q":"均来源于甲状腺滤泡上皮细胞的肿瘤是","o":["髓样癌、乳头状癌、未分化癌","乳头状癌、滤泡癌、嗜酸细胞型腺瘤","非典型腺瘤、乳头状癌、髓样癌","髓样癌、滤泡癌、滤泡性腺瘤","嗜酸细胞型腺瘤、髓样癌、滤泡癌"],"a":1,"e":"甲状腺滤泡上皮可发生乳头状癌、滤泡癌及嗜酸细胞型腺瘤。髓样癌起源于滤泡旁C细胞，属神经内分泌肿瘤，降钙素阳性而TG阴性，含髓样癌的组合均不成立。"},{"q":"只有一个开口的病理性盲管是","o":["糜烂","溃疡","窦道","瘘管","空洞"],"a":2,"e":"窦道是组织坏死后形成的只开口于皮肤或黏膜表面的深在性盲管；两端均有开口、沟通两个腔隙者称瘘管。"},{"q":"与肾病综合征发生最密切相关的肾小球病变是","o":["基膜增厚","中性粒细胞浸润","系膜细胞增生","内皮细胞增生","肾小球硬化"],"a":0,"e":"肾病综合征以大量蛋白尿为特征，其基础是滤过膜损伤、基膜增厚及足细胞足突融合致蛋白漏出；中性粒细胞浸润和内皮细胞增生见于急性弥漫性增生性肾炎。"},{"q":"原发性肝癌是指","o":["胆管上皮发生的癌","肝细胞和肝内胆管上皮发生的癌","肝细胞发生的癌","肝细胞和肝外胆管上皮发生的癌","来自库普弗细胞的恶性肿瘤"],"a":1,"e":"原发性肝癌起源于肝细胞或肝内胆管上皮细胞，分为肝细胞癌、肝内胆管癌和混合型，其中肝细胞癌占75%～85%。肝外胆管发生的癌不属原发性肝癌。"},{"q":"不符合子宫内膜癌描述的是","o":["生长较缓慢","多见于年轻女性","主要为淋巴道转移","常引起阴道流血","与雌激素刺激有关"],"a":1,"e":"子宫内膜癌多见于绝经后中老年妇女，与长期雌激素刺激、肥胖、糖尿病和不孕有关，生长较慢，主要表现为阴道流血，以淋巴道转移为主，年轻女性发病率低。"},{"q":"肾盂肾炎最主要的感染途径是","o":["上行性感染","血源性感染","邻近器官炎症的蔓延","医源性感染","多途径感染"],"a":0,"e":"肾盂肾炎以上行性感染为主要途径，细菌自尿道、膀胱沿输尿管或输尿管周围淋巴管上行至肾盂、肾盏和肾间质，致病菌以大肠埃希菌最多。"},{"q":"液化性坏死好发生于下列哪种器官","o":["脑","心","肝","脾","肺"],"a":0,"e":"液化性坏死因坏死组织含凝固蛋白少、水解酶多或富含水分和磷脂而发生溶解液化。脑组织富含磷脂和水分，缺血后形成软化灶，是液化性坏死的典型部位。"},{"q":"下列哪项不属于微小病变性肾小球病的病变特点","o":["又称为脂性肾病","是引起成人肾病综合征的最常见原因","光镜下肾小球基本正常，肾小管上皮有脂质沉积","蛋白尿的主要成分是小分子的白蛋白，属于选择性蛋白尿","皮质类固醇激素治疗大都效果明显"],"a":1,"e":"引起成人肾病综合征最常见的原因是膜性肾小球病；微小病变性肾小球病又称脂性肾病，光镜下肾小球基本正常，表现为足突消失和选择性蛋白尿，对糖皮质激素敏感。"},{"q":"高血压病脑出血好发的部位是","o":["枕叶","基底节","脑桥","小脑","顶叶"],"a":1,"e":"高血压脑出血多见于基底节，尤以豆状核区最多，因豆纹动脉自大脑中动脉呈直角发出，直接承受高压血流冲击和牵引而易于破裂。"},{"q":"假小叶的显微镜下的特点不包括","o":["再生的肝细胞结节","增生的纤维组织分隔包绕","小胆管和假胆管增生","肝细胞内嗜酸性小体","慢性炎细胞浸润"],"a":3,"e":"假小叶由纤维组织分割包绕的再生肝细胞团构成，其中央静脉缺如、偏位或有两个以上，汇管区可被包入，并伴小胆管增生和慢性炎细胞浸润；嗜酸性小体属单个细胞凋亡。"},{"q":"下列变化属于坏死的病理改变的是","o":["细胞体积肿大，细胞质内有红染颗粒","细胞体积缩小，细胞质内有脂褐素颗粒","细胞核膜破裂，染色质崩解为小碎片","细胞核增大，细胞核的DNA含量增加","细胞体积正常或稍大，出现双核"],"a":2,"e":"核膜破裂、染色质崩解为小碎片称为核碎裂，是细胞坏死时细胞核的三大改变之一，另两者为核固缩和核溶解。细胞肿大伴红染颗粒属细胞水肿，脂褐素见于萎缩。"},{"q":"肺气肿是指肺内残气增多，持续扩张性病变，主要累及","o":["肺内细小支气管","终末细支气管","左、右支气管","呼吸性细支气管及远端肺组织","局限于肺泡"],"a":3,"e":"肺气肿是末梢肺组织即呼吸性细支气管、肺泡管、肺泡囊和肺泡含气量过多伴肺泡间隔破坏，残气量增多，肺体积膨大。"},{"q":"下列哪项不属于大叶性肺炎的特征","o":["通常1周后病变消散","受累肺叶通气良好","有时肺发生纤维化","常由肺炎球菌引起","肺泡内充满纤维蛋白性渗出物"],"a":1,"e":"大叶性肺炎时肺泡内充满纤维蛋白性渗出物，肺泡壁结构完整，受累肺叶实变、通气功能严重障碍。病变多由肺炎球菌引起，约1周后溶解消散，少数机化遗留纤维化。"},{"q":"病理诊断肉瘤的主要依据是","o":["间质稀少","血液供应丰富","有肺转移","瘤细胞呈弥散分布","浸润性生长"],"a":3,"e":"肉瘤起源于间叶组织，瘤细胞多弥漫分布、不形成癌巢，间质血管丰富，与实质分界不清，这是与癌鉴别的主要组织学依据；浸润性生长为良恶性肿瘤共有。"},{"q":"易并发肺肉质变的肺部疾病是","o":["间质性肺炎","大叶性肺炎","小叶性肺炎","病毒性肺炎","干酪样肺炎"],"a":1,"e":"大叶性肺炎肺泡腔内纤维蛋白渗出过多而中性粒细胞渗出少、蛋白水解酶不足，纤维蛋白不能被溶解而机化，肺组织呈褐色肉样，即肺肉质变。"},{"q":"新月体性肾小球肾炎的主要病变是","o":["肾球囊脏层上皮细胞增生","毛细血管壁纤维蛋白样坏死","单核细胞渗出于肾球囊内","中性粒细胞渗出于肾球囊内","肾球囊壁层上皮细胞增生和巨噬细胞增生"],"a":4,"e":"新月体性肾小球肾炎的组织学特征是肾球囊壁层上皮细胞增生伴单核巨噬细胞渗出，形成新月体，压迫毛细血管丛。脏层上皮细胞增生见于微小病变性肾小球病。"},{"q":"具有发热作用的炎症介质是","o":["IL-1","C3a","IL-8","C5a","IL-10"],"a":0,"e":"IL-1和TNF作用于下丘脑体温调节中枢，通过增加前列腺素合成引起发热；C3a、C5a主要致血管扩张和通透性增高，IL-8为趋化因子，IL-10为抗炎因子。"},{"q":"败血症是指","o":["细菌大量入血，血中可查到细菌，但可无中毒症状","细菌毒素入血，引起中毒症状","细菌产物被吸收入血引起中毒症状","细菌入血繁殖并产生毒素从而引起中毒症状，并在一些器官形成脓肿","细菌入血，繁殖并产生毒素，并有中毒症状"],"a":4,"e":"败血症指细菌入血后大量繁殖并产生毒素，引起全身中毒症状，血培养可阳性，伴皮肤黏膜出血点及脾和淋巴结肿大。仅有细菌入血而无中毒症状者为菌血症。"},{"q":"以下哪项病变有助于对尖锐湿疣的诊断","o":["多量角化不全细胞","凹空细胞","表皮棘层肥厚","乳头状瘤样增生","角质层肥厚"],"a":1,"e":"凹空细胞即挖空细胞，核大深染、核周胞质空化呈空晕，出现于表皮浅层，是HPV感染所致尖锐湿疣的诊断性细胞。"},{"q":"急性、慢性粒细胞白血病时，在骨内、骨膜下或其他器官内，出现白血病细胞形成的瘤结节，该瘤为","o":["黄色瘤","白色瘤","棕色瘤","绿色瘤","转移瘤"],"a":3,"e":"绿色瘤是粒细胞白血病（尤其急性粒细胞白血病）时，未成熟粒细胞在骨膜下、骨内或软组织形成的瘤结节，因含髓过氧化物酶呈绿色而得名。"},{"q":"关于湿性坏疽的描述，下列不正确的是","o":["常继发于肠、子宫及肺等内脏器官的坏死","坏死组织与周围组织边界不清","常有恶臭味","若发于肢体末端，只有动脉的阻塞","全身中毒症状明显"],"a":3,"e":"湿性坏疽多发生于与外界相通的内脏，也可发生于动脉阻塞兼静脉回流受阻的肢体；因水分多、腐败菌繁殖旺盛而肿胀恶臭、界限不清，伴明显全身中毒症状。"},{"q":"左锁骨上淋巴结转移性腺癌的原发部位最可能是","o":["乳腺","甲状腺","食管","胃","肝脏"],"a":3,"e":"左锁骨上淋巴结即Virchow淋巴结，接受胸导管引流的腹腔脏器淋巴，胃癌细胞经胸导管转移至此，故其转移性腺癌多提示胃原发。"},{"q":"决定创伤愈合后局部组织抗牵拉的因素是","o":["创伤愈合的时间","创面大小和深度","是否伴有感染","愈合过程中肉芽组织的量","愈合部位胶原的含量"],"a":4,"e":"愈合后局部抗牵拉强度取决于胶原纤维的数量与排列，胶原沉积越多、交联越充分，张力强度越高；肉芽组织量和愈合速度只影响愈合过程，不决定最终抗张力。"},{"q":"脾动脉分支完全阻塞可引起脾的","o":["出血性梗死","脓毒性梗死","液化性坏死","贫血性梗死","坏疽"],"a":3,"e":"脾组织致密、侧支循环不充分，动脉分支完全阻塞后局部缺血坏死而出血少，属贫血性梗死；梗死灶呈楔形，尖端指向脾门，底朝向包膜。"},{"q":"下述组织或器官的体积增大，仅由肥大引起的是","o":["哺乳期的乳腺","功能亢进的甲状腺","健美运动员的骨骼肌","妊娠期的子宫","促肾上腺皮质激素细胞腺瘤患者的肾上腺"],"a":2,"e":"健美运动员骨骼肌增粗仅由肌细胞体积增大所致，属单纯肥大；哺乳期乳腺、功能亢进的甲状腺、妊娠期子宫和ACTH腺瘤患者的肾上腺均伴细胞增生。"},{"q":"关于凋亡叙述，下列错误的是","o":["凋亡的发生与基因调节有关","活体内单个细胞或小团细胞的死亡","又称程序性细胞死亡","细胞质膜破裂，核也碎裂","不引起急性炎症反应"],"a":3,"e":"凋亡为单个细胞或小团细胞的程序性死亡，受基因调控，细胞皱缩、染色质凝聚并形成凋亡小体，胞膜完整且不引起急性炎症反应；胞膜破裂、核碎裂见于坏死。"},{"q":"右下肢静脉血栓脱落主要栓塞于","o":["肺动脉","下腔静脉","右心房","右心室","右下肢大静脉"],"a":0,"e":"下肢深静脉血栓脱落后经右心房、右心室进入肺动脉，栓塞肺动脉及其分支，95%以上的肺动脉栓子来自膝以上的深静脉。"},{"q":"下列哪种肾脏疾病肾组织免疫荧光检查在肾小球内找不到免疫球蛋白和补体的沉积","o":["弥漫性膜性肾小球肾炎","弥漫性系膜增生性肾小球肾炎","微小病变性肾小球病","弥漫性膜增生性肾小球肾炎","肺出血肾炎综合征"],"a":2,"e":"微小病变性肾小球病免疫荧光无免疫球蛋白和补体沉积，电镜下仅见足突融合、无电子致密物；膜性、膜增生性和系膜增生性肾炎均有免疫复合物沉积。"},{"q":"青年女性急性乳腺炎的重要病因是","o":["乳腺增生","乳腺发育不良","病毒感染","乳汁淤积伴细菌感染","哺乳次数多"],"a":3,"e":"急性乳腺炎多见于哺乳期，乳汁淤积为细菌繁殖提供条件，金黄色葡萄球菌经乳头破损处侵入引起化脓性炎。"},{"q":"下列哪项病变不会引起梗死","o":["血管受压","动脉痉挛","血管瘤","血栓形成","栓塞"],"a":2,"e":"梗死由动脉血流阻断引起，常见原因为血栓形成、栓塞、动脉痉挛和血管受压；血管瘤是血管的良性肿瘤，本身不阻断血流。"},{"q":"下列哪种恶性瘤属于T细胞型淋巴瘤","o":["毛细胞淋巴瘤","蕈样霉菌病","套细胞淋巴瘤","滤泡性淋巴瘤","淋巴母细胞淋巴瘤"],"a":1,"e":"蕈样霉菌病是原发于皮肤的T细胞淋巴瘤，瘤细胞亲表皮生长形成Pautrier微脓肿。毛细胞、套细胞和滤泡性淋巴瘤均属B细胞肿瘤。"},{"q":"马氏斑（McCllum's patch）位于","o":["左心房","左心室","右心房","右心室","心外膜"],"a":0,"e":"McCallum斑是风湿性心内膜炎时左心房后壁心内膜因血流反流冲击而发生的灶状增厚，故位于左心房，其本质为心内膜纤维性增厚，可伴附壁血栓。"},{"q":"下列哪项不是活检获取病变组织的方法","o":["纤维支气管镜刷片","局部切除","钳取","细针吸取","搔刮"],"a":0,"e":"活检是切取病变组织做切片检查，包括钳取、局部切除、搔刮和细针吸取；纤维支气管镜刷片收集的是脱落细胞，属细胞学检查。"},{"q":"有关氧化氮的描述错误的是","o":["包括一氧化氮和二氧化氮","吸入后与呼吸道中的氧气相互作用","生成硝酸和亚硝酸","可损害呼吸道上皮","哮喘患者对二氧化氮敏感"],"a":1,"e":"氮氧化物中二氧化氮水溶性强，吸入后与呼吸道黏膜水分作用生成硝酸和亚硝酸，损害呼吸道上皮；一氧化氮吸入后主要与血红蛋白结合。"},{"q":"下述哪种病变只是由纤维素及血小板组成","o":["亚急性感染性心内膜炎的赘生物","风湿性心内膜炎的赘生物","心肌梗死的附壁血栓","静脉内柱状血栓的体部","静脉内柱状血栓的尾部"],"a":1,"e":"风湿性心内膜炎的赘生物为白色血栓，镜下仅由血小板和少量纤维蛋白构成，不含细菌；亚急性感染性心内膜炎赘生物内可见细菌团。"},{"q":"下列不符合病毒性肺炎的是","o":["早期表现为间质性肺炎","以中性粒细胞浸润为主","常见病因是流感病毒","部分病例可有透明膜形成","上皮细胞内可见病毒包涵体"],"a":1,"e":"病毒性肺炎早期为间质性肺炎，浸润细胞以淋巴细胞和单核细胞为主，而非中性粒细胞；流感病毒为常见病因，上皮细胞内可见病毒包涵体，重症可形成透明膜。"},{"q":"常发生在肝硬化基础上的肝肿瘤是","o":["肝炎后肝癌","弥漫型肝癌","巨块型肝癌","多结节型肝癌","肝内转移癌"],"a":3,"e":"多结节型肝癌常在肝硬化基础上发生，肝内散在多个大小不等的癌结节；巨块型多无明显肝硬化，弥漫型则癌组织弥漫浸润全肝。"},{"q":"急性弥漫性增生性肾小球肾炎最主要的病变特点是","o":["肾球囊壁层上皮细胞增生","肾小球毛细血管壁纤维素样坏死","肾小球系膜细胞和内皮细胞增生","肾小球毛细血管内血栓形成及基底膜增厚","肾小球内中性粒细胞浸润"],"a":2,"e":"急性弥漫性增生性肾小球肾炎的病变特点是弥漫性毛细血管内皮细胞和系膜细胞增生，伴中性粒细胞和巨噬细胞浸润；壁层上皮细胞增生形成新月体见于急进性肾炎。"},{"q":"心衰细胞见于","o":["右心衰竭时肺泡腔内","肺水肿时肺泡腔内","脾淤血时脾脏内","左心衰竭时肺泡腔内","肝淤血时肝脏内"],"a":3,"e":"心衰细胞是吞噬含铁血黄素的巨噬细胞，见于左心衰竭所致的慢性肺淤血，肺泡腔内与水肿液、红细胞并存，肺切面呈棕褐色。"},{"q":"肝组织呈碎片状坏死或桥接坏死见于","o":["急性重型肝炎","亚急性重症肝炎","慢性持续性肝炎","慢性活动性肝炎","急性普通型肝炎"],"a":3,"e":"碎片状坏死和桥接坏死见于慢性活动性肝炎，即中、重度慢性肝炎，提示炎症活动度高，常伴纤维化并进展为肝硬化。"},{"q":"区域性心肌梗死最常发生的部位是","o":["左心室后壁","左心室侧壁","左心室前壁","室间隔后1/3","右心室"],"a":2,"e":"区域性心肌梗死多由左冠状动脉前降支闭塞所致，梗死区位于左心室前壁、心尖部及室间隔前2/3，范围与闭塞血管的供血区一致。"},{"q":"下列哪种慢性风湿性心瓣膜病中不引起肺淤血","o":["二尖瓣狭窄","二尖瓣关闭不全","三尖瓣狭窄","主动脉瓣狭窄","主动脉瓣关闭不全"],"a":2,"e":"三尖瓣狭窄使右心室舒张期充盈受阻，体循环淤血，肺循环血量减少，不引起肺淤血。二尖瓣狭窄和关闭不全、主动脉瓣狭窄和关闭不全致左心衰竭，肺静脉压增高，引起肺淤血。"},{"q":"肠上皮化生常见于","o":["慢性萎缩性胃炎","急性感染性胃炎","急性刺激性胃炎","疣状胃炎","慢性浅表性胃炎"],"a":0,"e":"慢性萎缩性胃炎以胃黏膜变薄、腺体减少为特点，常伴肠上皮化生，并可见假幽门腺化生；急性胃炎多为可逆性炎症，一般不出现化生。"},{"q":"镜影细胞最主要的特点是","o":["为多核瘤巨细胞","细胞大、胞质丰富、呈双色性","有大的嗜酸性核仁","核大、核膜厚、核呈空泡状","双核并列、有大的嗜酸性核仁、如影随形"],"a":4,"e":"镜影细胞为双核并列的R-S细胞，两核形态对称如影随形，各含一个与红细胞大小相当的大嗜酸性核仁，核仁周围有空晕，为霍奇金淋巴瘤的诊断性细胞。"},{"q":"下列哪一类型的肝炎易演变为坏死后性肝硬化","o":["急性黄疸性肝炎","急性普通肝炎","慢性活动性肝炎","亚急性重型肝炎","慢性持续性肝炎"],"a":3,"e":"亚急性重型肝炎肝细胞大片坏死伴结节状再生，纤维组织增生，易演变为坏死后性（大结节型）肝硬化。急性普通型肝炎多可痊愈，不发展为该型肝硬化。"},{"q":"关于霍奇金病，有诊断意义的细胞是","o":["类上皮细胞","陷窝细胞","镜影细胞","异物巨细胞","异型性组织细胞"],"a":2,"e":"双核R-S细胞的两个核面对面排列、彼此对称，形似镜中之影，称镜影细胞，是霍奇金淋巴瘤具有诊断意义的细胞。"},{"q":"下列哪种肿瘤的恶性型归入癌","o":["腺瘤","纤维瘤","脂肪瘤","滑膜瘤","血管瘤"],"a":0,"e":"腺瘤为腺上皮的良性肿瘤，其恶性型即腺癌；纤维瘤、脂肪瘤、血管瘤、滑膜瘤均起源于间叶组织，恶性型分别称纤维肉瘤、脂肪肉瘤、血管肉瘤和滑膜肉瘤，不称癌。"},{"q":"梅毒引起的心血管病变主要见于","o":["主动脉","冠状动脉","肾动脉","颈总动脉","肺动脉"],"a":0,"e":"梅毒三期病变累及心血管时，主要侵犯主动脉，引起梅毒性主动脉炎、主动脉瓣关闭不全和主动脉瘤。"},{"q":"大叶性肺炎肉质变是因为","o":["局部组织缺血","纤维素渗出较多","机体抵抗力降低","中性粒细胞数量过少","合并其他细菌感染"],"a":3,"e":"肺肉质变源于中性粒细胞渗出过少、蛋白水解酶不足，肺泡内纤维蛋白不能被溶解吸收而机化，肺组织呈褐色肉样实变。"},{"q":"股静脉内较大的血栓完全机化需要","o":["2天","1周","2周","1个月","2个月"],"a":2,"e":"血栓形成后1～2天开始机化，较大的血栓约2周可完全机化；机化后血栓与血管壁紧密黏着而不再脱落，并可因内皮长入而形成再通。"},{"q":"心力衰竭细胞最常见于","o":["左心衰竭","右心衰竭","肺水肿","肝淤血","肺炎"],"a":0,"e":"左心衰竭致肺淤血，肺泡腔内红细胞被巨噬细胞吞噬并分解为含铁血黄素，形成心力衰竭细胞，可随痰咳出；右心衰竭引起体循环淤血，不产生该细胞。"},{"q":"恶性腱鞘巨细胞瘤的特征不包括","o":["易浸润周围软组织","瘤细胞以异型的组织细胞样滑膜细胞为主","转移多见，易复发","多位于指和腕关节屈侧","极为罕见"],"a":2,"e":"恶性腱鞘巨细胞瘤极罕见，瘤细胞以异型的组织细胞样滑膜细胞为主，易浸润周围软组织，可复发而转移少见，多位于指和腕关节屈侧。"},{"q":"下列哪项最符合远隔器官转移瘤的特点","o":["与原发瘤组织学类型不同","在远隔器官内形成单个转移灶","分化程度同原发肿瘤","多个圆形结节，散在分布于脏器边缘，可形成“癌脐”","淋巴道转移的结果"],"a":3,"e":"血行转移灶边界清楚、常为多个、散在分布于器官表面，瘤结节中央出血坏死下陷形成癌脐，其组织学类型与原发瘤一致。"},{"q":"下列哪项符合慢性肺源性心脏病的演进","o":["支气管肺炎→代偿性肺气肿→慢性肺源性心脏病","慢性支气管炎→阻塞性肺气肿→慢性肺源性心脏病","间质性肺炎→间质性肺气肿→慢性肺源性心脏病","大叶性肺炎→肺肉质变→慢性肺源性心脏病","肺癌阻塞、压迫支气管→肺气肿→慢性肺源性心脏病"],"a":1,"e":"慢性支气管炎引起细支气管炎及细支气管周围炎，导致阻塞性通气障碍和肺气肿，肺毛细血管床减少及缺氧使肺循环阻力增高，最终发展为慢性肺源性心脏病。"},{"q":"肺癌的早期诊断中最有价值的检查是","o":["早期症状的发现","纤维支气管镜活检","X线检查","CT检查","血液检查"],"a":1,"e":"纤维支气管镜可直接观察段以上支气管的病变并取活组织做病理检查，组织学确诊，是中央型肺癌早期诊断最有价值的方法。"},{"q":"低度恶性的上皮性肿瘤是","o":["浆液性囊腺瘤","黏液性囊腺瘤","浆液性囊腺癌","黏液性囊腺癌","交界性浆液性囊腺瘤"],"a":4,"e":"交界性浆液性囊腺瘤的组织形态和生物学行为介于良、恶性之间，属交界性肿瘤，即低度恶性。浆液性囊腺瘤为良性，浆液性囊腺癌为恶性。"},{"q":"下列哪项不是真性肿瘤","o":["白血病","动脉瘤","蕈样肉芽肿","霍奇金淋巴瘤","鲍温病"],"a":1,"e":"动脉瘤是动脉壁局部薄弱或结构破坏后向外膨出形成的局限性扩张，属血管病变而非肿瘤；白血病、蕈样肉芽肿、霍奇金淋巴瘤和鲍温病均有真性肿瘤性增生。"},{"q":"急性左心衰竭时常引起","o":["肺水肿","眼睑水肿","脑水肿","下肢水肿","心包积液"],"a":0,"e":"急性左心衰竭时左心房压和肺静脉压骤升，肺毛细血管静水压增高，液体渗入肺间质和肺泡，引起急性肺水肿而出现呼吸困难和粉红色泡沫痰。"},{"q":"下列最符合鳞状细胞癌的特征的是","o":["发生于原有单层扁平上皮的覆盖部位","呈外生性生长","癌细胞的排列及形态仍保留单层扁平上皮的某些特征","癌珠形成","主要经淋巴道转移"],"a":2,"e":"鳞状细胞癌的癌细胞呈巢状排列，具有细胞间桥和角化珠，即癌珠形成，是鳞癌分化的特征性形态。教材指出分化较差的鳞癌无角化珠、细胞间桥少或无，故癌珠形成最符合鳞癌特征。"},{"q":"腺上皮鳞化后发生恶性变，所形成的恶性肿瘤称为","o":["腺癌","腺棘皮癌","腺鳞癌","鳞状细胞癌","低分化腺癌"],"a":3,"e":"腺上皮发生鳞状上皮化生后恶变，其分化方向已转为鳞状上皮，形成的恶性肿瘤称鳞状细胞癌；腺上皮本身恶变才称腺癌。"},{"q":"在门脉性肝硬化与坏死后肝硬化病变的区别中，不包括","o":["假小叶的大小","纤维间隔的厚薄","炎细胞浸润的轻重","肝内小血管改建的有无","肝细胞坏死的多少"],"a":3,"e":"门脉性肝硬化假小叶大小较一致、纤维间隔细而均匀、炎细胞浸润轻；坏死后性者假小叶大小不一、间隔宽窄不匀、坏死明显，但两者均有肝内血管改建。"},{"q":"关于高血压小动脉的病变叙述中，下列错误的是","o":["中膜平滑肌细胞肥大和增生","膜内胶原和弹性纤维增多","内膜弹性纤维增多","内膜内血浆蛋白渗入，发生玻璃样变","内弹力膜分裂"],"a":3,"e":"高血压小动脉病变以中膜平滑肌细胞肥大增生、胶原和弹性纤维增多、内弹力膜分裂及内膜下血浆蛋白渗入玻璃样变为特点，弹性纤维增多位于中膜而非内膜。"},{"q":"与硅肺发病关系最密切的细胞是","o":["成纤维细胞","中性粒细胞","巨噬细胞","CD4+T细胞","B细胞"],"a":2,"e":"硅尘被肺泡巨噬细胞吞噬后损伤溶酶体膜，使细胞崩解并释放硅尘和炎症介质，刺激成纤维细胞增生与胶原沉积，故巨噬细胞是硅肺发病的关键细胞。"},{"q":"毛玻璃样肝细胞可见于","o":["急性普通型肝炎","慢性普通型肝炎","急性重型肝炎","亚急性重型肝炎","酒精性肝病"],"a":1,"e":"毛玻璃样肝细胞是HBsAg在滑面内质网蓄积所致，见于HBsAg携带者和慢性肝炎患者，故慢性普通型肝炎可见。急性肝炎和重型肝炎以坏死为主，无此改变。"},{"q":"如图，卵巢黏液性囊腺瘤的特点是","o":["细胞有明显异型性","无黏液分泌","囊壁内衬单层立方上皮","囊壁内衬单层高柱状上皮","乳头分支多而复杂，细胞层次增多，超过3层以上"],"a":3,"e":"官方题库缺失图片"},{"q":"关于淋巴瘤的叙述，错误的是","o":["青少年多见，是儿童最常见的恶性肿瘤之一","肉眼呈结节状，可有假包膜，切面呈“鱼肉样”","是原发于淋巴结和结外淋巴组织的恶性肿瘤","分为霍奇金病、非霍奇金病和白血病三大类型","淋巴组织结构破坏，瘤细胞弥漫分布，瘤细胞间可有网状纤维穿插包绕"],"a":3,"e":"淋巴瘤分霍奇金淋巴瘤和非霍奇金淋巴瘤两大类，白血病属造血系统肿瘤，不列入淋巴瘤分类；瘤细胞弥漫分布、切面呈鱼肉样为其特点。"},{"q":"脓肿时病变局限在局部主要是由于","o":["细菌的毒素","血浆凝固酶的作用","中性粒细胞的浸润","脓液的黏稠度大","脓肿膜的形成"],"a":1,"e":"金黄色葡萄球菌产生血浆凝固酶，使纤维蛋白原转变为纤维蛋白并包裹病灶，使炎症局限而形成脓肿；链球菌的透明质酸酶和链激酶则促其沿组织间隙扩散。"},{"q":"下列可确诊支气管扩张症的是","o":["肺实变体征","咳大量脓痰","反复咯血","肺部湿啰音","支气管碘油造影"],"a":4,"e":"支气管扩张症以支气管持久性不可逆扩张伴管壁纤维性增厚为特征，支气管碘油造影可直接显示扩张的支气管形态而确诊。咳大量脓痰、反复咯血和肺部湿啰音均为临床表现，缺乏特异性。"},{"q":"慢性肝淤血肉眼观如图所示，关于其形态特征说法不正确的是","o":["色暗红，体积增大，切面湿润","色灰白，体积缩小，切面干燥","重量增加，质地变硬","切面可见红黄相间的条纹","又称槟榔肝"],"a":1,"e":"官方题库缺失图片"},{"q":"以“满天星”图像为病变特点的疾病是","o":["皮肤T细胞型淋巴瘤","淋巴母细胞性淋巴瘤","组织细胞型淋巴瘤","Burkitt淋巴瘤","霍奇金病"],"a":3,"e":"Burkitt淋巴瘤由中等大小、形态一致的淋巴细胞弥漫增生，其间散在吞噬碎片的巨噬细胞，形成“满天星”图像。该瘤与CMYC基因因染色体易位而过度表达有关。"},{"q":"流行性乙型脑炎的噬神经细胞现象是由（ ）侵入神经细胞内产生的","o":["巨噬细胞","小胶质细胞","淋巴细胞","巨噬细胞和小胶质细胞","小胶质细胞和淋巴细胞"],"a":3,"e":"噬神经细胞现象指坏死的神经元被增生的小胶质细胞或血源性巨噬细胞吞噬，故由巨噬细胞和小胶质细胞共同参与。小胶质细胞属单核巨噬细胞系统。"},{"q":"流行性脑脊髓膜炎的传染途径主要是通过","o":["呼吸道","皮肤","泌尿道","蚊子叮咬后经血","消化道"],"a":0,"e":"流脑经呼吸道传播，患者和带菌者为传染源，病原体借飞沫由鼻咽部侵入，冬春季引起流行；皮肤瘀点瘀斑是败血症期的表现，并非侵入途径。"},{"q":"甲状腺乳头状癌的核特征不包括","o":["磨玻璃核","核大深染、染色质粗糙、明显核仁","核沟","核内包涵体","细胞核拥挤重叠"],"a":1,"e":"甲状腺乳头状癌的核特征为毛玻璃核、核沟、核内假包涵体及核拥挤重叠；核大深染、染色质粗糙伴明显核仁见于未分化癌等类型。"},{"q":"严重肝实质疾病引起出血的原因是","o":["凝血因子消耗过多","凝血因子合成减少","红细胞破坏","血小板生成减少","凝血因子无功能"],"a":1,"e":"严重肝实质疾病时肝细胞合成纤维蛋白原、凝血酶原及凝血因子Ⅴ、Ⅶ、Ⅸ、Ⅹ等减少，导致出血倾向。凝血因子消耗过多见于弥散性血管内凝血。"},{"q":"下列关于Crohn病的描述，哪一项是错误的","o":["病变主要累积回肠末端","可引起肠穿孔及瘘管形成","病变呈节段性","溃疡呈地图状","常见非干酪样肉芽肿"],"a":3,"e":"Crohn病好发于回肠末端，病变呈节段性分布，肠壁全层炎可致穿孔和瘘管形成，并可见非干酪样肉芽肿；地图状溃疡见于肠菌痢的假膜性炎。"},{"q":"肠阿米巴病引起的最常见的并发症为","o":["肺脓肿","心包炎","脑脓肿","脓胸","肝脓肿"],"a":4,"e":"肠阿米巴病的滋养体侵入肠壁小静脉，经门静脉入肝形成阿米巴肝脓肿，是本病最常见的并发症，多位于肝右叶，肺和脑脓肿较少见。"},{"q":"下列组织对缺氧的耐受性依次为","o":["脑＞肝＞肾","肾＞肝＞脑","肝＞脑＞肾","肝＞肾＞脑","肾＞脑＞肝"],"a":1,"e":"各器官对缺氧的耐受性由高至低为肾、肝、脑，脑神经元最敏感，缺血数分钟即发生不可逆损伤；骨骼肌和纤维结缔组织耐受性最强。"},{"q":"高血压失代偿期心脏变为","o":["左心室向心性肥大","左心室明显扩张","左心室乳头肌明显增粗","左心室心肌收缩力加强","心肌出现弥漫性纤维化"],"a":1,"e":"高血压失代偿期左心室由向心性肥大转为离心性肥大，心腔明显扩张而室壁相对变薄，心肌收缩力下降，最终出现左心衰竭。"},{"q":"急性重型肝炎肝细胞常见而普遍的病变是","o":["坏死","变性","再生","萎缩","化生"],"a":0,"e":"急性重型肝炎以肝细胞严重而广泛的大块坏死为特征，坏死自小叶中央迅速向四周扩展，仅小叶周边残留少许变性肝细胞，故肝体积显著缩小。"},{"q":"流式细胞技术样本单细胞悬液的细胞数不应少于","o":["5个","10个","25个","20个","15个"],"a":1,"e":"流式细胞术要求细胞逐个通过激光束产生散射和荧光信号，单细胞悬液细胞数过少则无法获得有效检测结果，故不应少于10个。"},{"q":"子宫颈早期浸润癌是指","o":["癌细胞未突破基膜","癌细胞突破基膜，浸润深度不超过基膜下5mm","癌细胞突破基膜，浸润深度不超过基膜下7mm","癌细胞未突破基膜，但已累及腺体","癌细胞突破基底膜，但未累及腺体"],"a":1,"e":"早期浸润癌指癌细胞突破基底膜向固有层间质浸润，深度不超过基底膜下5mm，肉眼不能辨认，仅在镜下确诊；超过5mm者为浸润癌。"},{"q":"减压病的栓塞是","o":["血栓栓塞","羊水栓塞","气体栓塞","脂肪栓塞","虫卵栓塞"],"a":2,"e":"减压病是气体栓塞的一种，从高气压环境迅速转入常压或低气压环境时，血中溶解的氮气迅速游离形成气泡而阻塞血管。"},{"q":"伤寒的病变特点除外","o":["脾肿大","病灶中较多中性粒细胞浸润","伤寒肉芽肿形成","回肠下段集合和孤立淋巴小结肿大","皮肤玫瑰疹"],"a":1,"e":"伤寒是急性单核巨噬细胞增生性炎，病灶内以伤寒细胞为主，中性粒细胞极少，形成伤寒肉芽肿，并见脾大、回肠淋巴小结肿大和皮肤玫瑰疹。"},{"q":"下列哪种细胞属于永久性细胞","o":["表皮细胞","心肌细胞","肾小管上皮细胞","肝细胞","造血细胞"],"a":1,"e":"永久性细胞出生后不再分裂增生，受损后由瘢痕修复，包括神经细胞、骨骼肌细胞和心肌细胞；表皮、肝细胞、肾小管上皮和造血细胞属不稳定细胞或稳定细胞。"},{"q":"关于子宫平滑肌瘤的叙述，下列哪项错误","o":["女性生殖系统中最常见的肿瘤","肿瘤境界清楚，但常无包膜","可发生黏液变性","常发生恶变","瘤组织呈编织状排列"],"a":3,"e":"子宫平滑肌瘤是女性生殖系统最常见的肿瘤，境界清楚但常无包膜，可发生黏液变性，瘤细胞呈编织状排列，恶变率很低。"},{"q":"尿路梗阻或尿液排泄不畅所致的肾盂积水，肾实质发生的病变为","o":["营养不良性萎缩","神经性萎缩","失用性萎缩","压迫性萎缩","内分泌性萎缩"],"a":3,"e":"尿路梗阻致肾盂积水，肾盂内压升高并压迫周围肾组织，使肾皮质、髓质因缺血缺氧而萎缩，属压迫性萎缩；失用性萎缩由负荷减少引起。"},{"q":"肺孢子虫病较为特征的组织病理学改变是肺泡内出现大量的","o":["红细胞","淋巴细胞","水肿液","泡沫样渗出物","中性粒细胞"],"a":3,"e":"肺孢子菌肺炎时肺泡腔内充满由浆液、纤维蛋白和成团病原体构成的泡沫样渗出物，肺泡间隔增厚，是其特征性组织学改变，常见于AIDS患者。"},{"q":"大叶性肺炎的病理变化，除外","o":["肺组织大面积广泛实变","肺泡性炎","以纤维素渗出为主","可合并肺肉质变","常有肺泡壁结构破坏"],"a":4,"e":"大叶性肺炎为肺泡内纤维蛋白性炎，肺泡壁毛细血管受压但结构完整，故不破坏肺泡壁；病变消散后肺组织结构可完全恢复。"},{"q":"肝细胞弥漫性水样变性主要见于","o":["急性重型肝炎","亚急性重型肝炎","慢性持续性肝炎","急性普通型肝炎","淤胆型肝炎"],"a":3,"e":"急性普通型肝炎以肝细胞广泛气球样变即水样变性为最主要病变，伴嗜酸性变和点状坏死，坏死轻而再生明显。"},{"q":"慢性阻塞性肺病最常见于","o":["支气管哮喘","支气管扩张","肺脓肿","肺结核球","慢性支气管炎"],"a":4,"e":"慢性阻塞性肺疾病主要包括慢性支气管炎和肺气肿，以慢性支气管炎最常见，长期反复发作致气道狭窄、呼气阻力增加和肺功能不全。"},{"q":"甲状腺滤泡性腺瘤和滤泡癌的鉴别诊断最重要的是","o":["滤泡大小","被膜是否受侵犯","是否有包膜和血管侵犯","淋巴结是否有转移","远处器官是否有转移"],"a":2,"e":"滤泡癌与滤泡性腺瘤的滤泡形态极为相似，鉴别关键是肿瘤有无包膜和血管侵犯，须对肿瘤与包膜交界处多处取材切片观察。"},{"q":"冰冻切片时下列哪种组织需要厚切片","o":["骨髓","淋巴","肌肉","脂肪","纤维"],"a":3,"e":"脂肪组织质软且含大量脂质，冰冻切片难以切薄，需较厚切片才能保持结构完整，并常需做苏丹Ⅲ等脂肪染色。"},{"q":"肿瘤的生长速度主要取决于","o":["肿瘤是良性还是恶性","肿瘤细胞的生长分数和肿瘤细胞的生成与丢失之比","肿瘤所处部位是否有足够的生长空间","肿瘤间质血管是否丰富","机体的免疫状态"],"a":1,"e":"肿瘤生长速度主要取决于生长分数及瘤细胞生成与丢失的比例；多数恶性肿瘤细胞的倍增时间并不比正常细胞短，故倍增时间不是主要因素。"},{"q":"第二期梅毒的主要表现是","o":["主动脉炎","硬性下疳","梅毒疹","软性下疳","树胶样肿形成"],"a":2,"e":"二期梅毒在硬性下疳出现7～8周后发生，螺旋体大量繁殖引起全身皮肤黏膜梅毒疹和淋巴结肿大，镜下为血管周围炎，传染性强。"},{"q":"肉瘤的肉眼特点通常为","o":["结节状、有包膜，切面灰白质硬","结节状、有包膜，切面灰白质软","分叶状，可有或无包膜，切面灰红或粉红色，质硬","形状不定，切面灰白色，质硬，干燥","不规则结节状，有无完整包膜不定，切面灰红色，湿润质软如鱼肉状"],"a":4,"e":"肉瘤体积常较大，多呈不规则结节状，有无完整包膜不定，切面灰红或灰白、湿润，质软如鱼肉状，常伴出血坏死。癌切面多灰白、质硬、干燥。"},{"q":"不属于化脓性炎的疾病是","o":["急性细菌性心内膜炎","急性蜂窝织炎性阑尾炎","急性肾盂肾炎","急性风湿性心内膜炎","皮肤疖痈"],"a":3,"e":"急性风湿性心内膜炎是变态反应性炎症，瓣膜闭锁缘形成白色血栓即疣状赘生物，无脓性渗出；其余各项均由化脓菌引起，属化脓性炎。"},{"q":"下述哪种情况不容易引起空气栓塞","o":["胸部外伤损伤深静脉","分娩时子宫强烈收缩","头颈部外伤损伤深静脉","静脉穿刺输液","儿童青枝骨折"],"a":4,"e":"空气栓塞多因静脉损伤破裂，外界空气由缺损处进入血流所致，如头颈胸壁及肺手术或创伤损伤静脉、正压静脉输液等。儿童青枝骨折不涉及静脉破裂进气。"},{"q":"肝细胞癌患者最有诊断意义的血清学指标是","o":["甲胎蛋白","癌胚抗原","碱性磷酸酶","酸性磷酸酶","γ-谷氨酰转肽酶"],"a":0,"e":"甲胎蛋白是肝细胞癌最有诊断价值的血清标志物，约70%患者升高，可用于高危人群筛查和疗效监测；癌胚抗原主要与消化道腺癌相关。"},{"q":"下述关于四肢动脉粥样硬化的叙述中，哪项是错误的","o":["四肢动脉粥样硬化常见于下肢动脉","可以继发血栓形成","可引起肢体局部坏疽","较小动脉管腔狭窄，就易产生严重后果","行走时可出现跛行症状"],"a":3,"e":"四肢动脉粥样硬化以下肢动脉为重，可继发血栓形成致肢体坏疽，行走时出现间歇性跛行；因侧支循环丰富，较小动脉狭窄一般不引起严重后果。"},{"q":"关于肺疾病的叙述，下列哪项是正确的","o":["肺气肿发生气流受阻的主要病因是小气道病变","支原体主要引起小叶性肺炎","支气管肺炎常作为独立疾病发生","硅沉着病主要由直径＜5μm的粉尘引起","α1-抗胰蛋白酶缺乏是肺气肿的主要原因"],"a":0,"e":"肺气肿气流受限主要因小气道壁慢性炎症、纤维化及肺弹性回缩力下降；硅沉着病由直径小于5μm的硅尘致病，抗胰蛋白酶缺乏仅占少数。"},{"q":"脑膜瘤来源于","o":["硬脑膜","软脑膜和硬脑膜","蛛网膜","软脑膜","脑神经鞘膜"],"a":2,"e":"脑膜瘤起源于蛛网膜帽状细胞，常与硬脑膜广泛附着，呈膨胀性生长，球形或分叶状，境界清楚、包膜完整，切面灰白质韧。"},{"q":"高血压时，血管壁玻璃样变性常见于","o":["冠状动脉","肾弓形动脉","主动脉","肾小球入球动脉","脑基底动脉"],"a":3,"e":"高血压时细动脉玻璃样变最易累及肾入球动脉、视网膜动脉和脾中央动脉，系血浆蛋白渗入血管壁所致。"},{"q":"成人呼吸窘迫综合征发病机制中最关键的因素是","o":["血氧含量下降","微血管内血栓形成","呼吸膜损伤","肺泡活性物质合成和分泌减少","小动脉壁纤维蛋白样坏死"],"a":2,"e":"ARDS时中性粒细胞及炎症介质损伤肺毛细血管内皮和肺泡上皮，呼吸膜通透性增高，富含蛋白的液体渗入肺泡，导致进行性低氧血症，故呼吸膜损伤是中心环节。"},{"q":"在机化的血栓中形成与原血管腔相沟通的毛细血管，使部分血流得以恢复，这种现象称为","o":["血栓脱落","侧支循环形成","血栓机化","血栓硬化","再通"],"a":4,"e":"血栓机化过程中水分被吸收使血栓收缩出现裂隙，新生内皮细胞长入并相互吻合，使被阻塞血管部分恢复血流，此过程称为再通。"},{"q":"细菌性痢疾所致溃疡的形态是","o":["溃疡长轴与肠长轴垂直","溃疡呈烧瓶状","溃疡边缘堤状隆起","溃疡呈地图状","溃疡长轴与肠长轴平行"],"a":3,"e":"细菌性痢疾为假膜性肠炎，假膜脱落后形成大小不等、形状不规则的地图状浅表溃疡；肠结核溃疡呈环形，长轴与肠长轴垂直。"},{"q":"葡萄簇型横纹肌肉瘤之主要形态特征是","o":["幼稚横纹肌细胞","原始间叶细胞","丰富的黏液样基质","紧靠黏膜下方有一宽带状的细胞密集区，细胞核大，核分裂易见，称为“形成层”","肿瘤表面被覆上皮糜烂溃疡形成"],"a":3,"e":"葡萄簇型横纹肌肉瘤紧靠黏膜下方有一宽带状细胞密集区，细胞核大、核分裂易见，称为“形成层”，为其主要形态特征。"},{"q":"子宫颈鳞状上皮非典型增生是指","o":["上皮细胞有异型性，完全失去分化能力","上皮细胞变成癌细胞，但基底膜完整","上皮细胞呈不规则形增生，钉突延长，基底膜不完整","上皮细胞既具有异型性，但又保持其分化能力","子宫颈柱状上皮被鳞状上皮代替"],"a":3,"e":"非典型增生指上皮细胞增生并出现异型性，但仍保留一定分化能力，未达癌细胞程度；异型细胞占据上皮全层且失去分化时即为原位癌。"},{"q":"气性坏疽是湿性坏疽的一种特殊形式，主要是合并了","o":["结核杆菌感染","产气荚膜杆菌感染","金黄色葡萄球菌感染","链球菌感染","白假丝酵母菌感染"],"a":1,"e":"气性坏疽是深达肌肉的开放性创伤合并产气荚膜杆菌等厌氧菌感染，细菌分解坏死组织产生大量气体，触诊有捻发感。"},{"q":"尿道发生肿瘤，尿路阻塞，肉眼观肾体积增大，肾实质变薄，称为","o":["肥大","变性","萎缩","发育不良","增生"],"a":2,"e":"尿路阻塞使肾盂积水、肾实质长期受压并缺血，肾单位萎缩，肾体积虽增大而实质变薄，属压迫性萎缩，并非肥大或增生。"},{"q":"下列哪项不是绒癌的特征","o":["子宫肌层内可见侵蚀的绒毛","呈暗红色、出血坏死的肿块","主要为血行转移","可有阴道结节出现","刮宫后hCG不恢复正常"],"a":0,"e":"绒毛膜癌由滋养细胞构成，无绒毛结构，此为与侵袭性葡萄胎的关键区别；肿瘤呈暗红色出血坏死肿块，主要经血行转移，阴道壁可出现转移结节，hCG持续升高。"},{"q":"急性炎症时组织变红的主要原因是","o":["血管内血栓形成","动脉性充血","肉芽组织形成","静脉性充血","血管扩张"],"a":1,"e":"急性炎症早期小动脉和毛细血管扩张、血流量增加，局部氧合血红蛋白增多而变红，属动脉性充血这一主动过程。"},{"q":"类风湿性关节炎关节固定的主要原因是","o":["骨质疏松","慢性炎症，肉芽组织和瘢痕形成","肌痉挛","软骨变性","关节附近小动脉炎"],"a":1,"e":"类风湿性关节炎滑膜慢性炎症及血管翳形成，肉芽组织增生并纤维化、瘢痕形成，最终导致关节纤维性固定。"},{"q":"胃中分化腺癌，侵及固有肌层，未侵犯浆膜时，肿瘤分期为","o":["TX","T1","T2","T3","T4"],"a":2,"e":"胃癌侵及固有肌层而未穿透浆膜，属T2期；T1限于黏膜及黏膜下层，T3侵及浆膜下结缔组织，T4穿透浆膜或侵犯邻近结构。"},{"q":"葡萄胎患者经彻底刮宫后，连续监测血、尿中hCG，如持续升高，说明","o":["正常","胎儿仍存活","恶变","怀孕","复发"],"a":2,"e":"葡萄胎彻底清宫后血hCG应逐渐降至正常，若持续升高或下降后又升高，提示滋养细胞残留并恶变，可发展为侵袭性葡萄胎或绒毛膜癌。"},{"q":"胃最常见的两种良性肿瘤是","o":["平滑肌瘤和纤维瘤","脂肪瘤和腺瘤","神经纤维瘤和腺瘤","腺瘤和平滑肌瘤","纤维瘤和血管瘤"],"a":3,"e":"胃良性肿瘤以腺瘤和平滑肌瘤最常见，前者起源于黏膜上皮，后者起源于固有肌层，二者构成胃良性肿瘤的主要类型。"},{"q":"下列哪项对良性胃溃疡的大体形态描述是错误的","o":["圆形或椭圆形","溃疡边缘整齐","溃疡底部凹凸不平，有坏死","周围黏膜皱襞向溃疡集中","直径一般＜2cm"],"a":2,"e":"良性胃溃疡底部平坦洁净，凹凸不平并有坏死出血是恶性溃疡的表现；良性溃疡呈圆形或椭圆形、边缘整齐、直径多小于2cm，周围黏膜皱襞向溃疡集中。"},{"q":"重度慢性乙型病毒性肝炎时，肝细胞质出现毛玻璃样改变的原因是","o":["粗面内质网内有大量HBsAg","滑面内质网内有大量HBsAg","线粒体肿胀","胞质内细胞器的变性","肝细胞水肿"],"a":1,"e":"毛玻璃样肝细胞是HBsAg在滑面内质网内大量蓄积所致，电镜下见滑面内质网增生、网池内充满HBsAg颗粒，免疫组化HBsAg阳性。"},{"q":"动脉粥样硬化继发性病变中最危险的并发症是","o":["动脉瘤的形成","血栓的形成","钙化","斑块内出血","斑块破裂"],"a":0,"e":"动脉粥样硬化继发性病变包括斑块内出血、斑块破裂、血栓形成、钙化及动脉瘤形成，其中动脉瘤破裂可致致命性大出血，是最危险的并发症。教材明确指出动脉瘤最严重的并发症为破裂出血。"},{"q":"小叶性肺炎的病变范围","o":["以呼吸性细支气管为中心","以终末细支管为中心","以细支气管为中心","以支气管为中心","以肺泡管为中心"],"a":2,"e":"小叶性肺炎是以细支气管为中心的肺组织化脓性炎，又称支气管肺炎，病灶自细支气管向周围肺泡扩展，呈小叶性分布。"},{"q":"亚急性感染性心内膜炎皮肤表现为","o":["Osler结节","Negri小体","Aschoff小体","环形红斑","McCallum斑"],"a":0,"e":"亚急性感染性心内膜炎因微栓塞和超敏反应，在指趾末端出现紫红色痛性小结节即Osler结节，亦可伴甲下线状出血。环形红斑和Aschoff小体见于风湿病。"},{"q":"关于胃癌的发生，下列哪项错误","o":["来源于胃腺颈部的干细胞","与肠上皮化生有关","与假幽门腺化生关系密切","与非典型增生有关","来源于胃小凹底部的干细胞"],"a":4,"e":"官方答案为【来源于胃小凹底部的干细胞】，但依据教材，正确答案为【与假幽门腺化生关系密切】。胃癌发生自胃腺颈部和胃小凹底部的组织干细胞，与肠上皮化生相关；假幽门腺化生为胃体腺萎缩后的腺体改变，与胃癌关系不密切。"},{"q":"细胞在生长过程中，如果互相接触，则生长停止，这种现象叫","o":["再生性增生","生长的接触抑制","修复","完全再生","二期愈合"],"a":1,"e":"细胞生长至互相接触时增殖停止的现象称接触抑制，由细胞膜接触及缝隙连接参与调控，是正常细胞增殖的重要调节机制，肿瘤细胞常丧失此特性。"},{"q":"老年男性，曾是一名石棉矿矿工，尸检见胸膜腔内有一肿块，约5cm×4cm×3cm大小，如图所示，应首先考虑的诊断为","o":["胸膜斑","胸膜孤立性纤维瘤","周围型肺腺癌累及胸膜","恶性胸膜间皮瘤","结核性胸膜炎伴纤维斑块形成"],"a":3,"e":"石棉接触史是恶性胸膜间皮瘤的重要病因，50%～80%患者有石棉接触史，肿瘤沿胸膜表面弥漫浸润扩展。胸膜斑为石棉肺的非肿瘤性纤维化斑块。"},{"q":"以下病变最不可能是慢性酒精中毒引起的是","o":["脂肪肝","酒精性肝炎","肝硬化","肝细胞内Mallory小体形成","肝细胞内含铁血黄素沉着"],"a":4,"e":"慢性酒精中毒引起脂肪肝、酒精性肝炎和肝硬化，肝细胞内出现Mallory小体；含铁血黄素沉着见于慢性肺淤血和反复出血等情况。"},{"q":"关于传染性单核细胞增多症的叙述，下列哪项是错误的","o":["累及血液、肝脾与肾","周围血中淋巴细胞增多，并出现异型性，伴发热，喉痛","由EB病毒引起，抗EB病毒抗体滴度增加","淋巴结内可出现肉芽肿和小脓肿","全身淋巴结明显肿大"],"a":3,"e":"传染性单核细胞增多症由EB病毒感染B淋巴细胞引起，表现为发热、咽痛、全身淋巴结肿大和异型淋巴细胞增多；淋巴结肉芽肿和小脓肿形成是猫抓病的病变。"},{"q":"子宫颈上皮内瘤变（CIN）是指","o":["轻度不典型增生","原位癌","重度不典型增生","不同程度的不典型增生和原位癌的统称","浸润性癌"],"a":3,"e":"子宫颈上皮内瘤变指宫颈上皮被不同程度异型细胞取代，包括CIN Ⅰ～Ⅲ级，涵盖轻、中、重度异型增生及原位癌，均未突破基底膜，属癌前病变。"},{"q":"易发生干性坏疽的器官是","o":["肺","肝","肠","四肢","心"],"a":3,"e":"干性坏疽常见于动脉阻塞而静脉回流仍通畅的四肢末端，坏死区干燥皱缩呈黑色，与正常组织界限清楚，腐败变化较轻。"},{"q":"下列哪项不是原发性肺结核病的特点","o":["初次感染","儿童多见","原发综合征","支气管播散","大多可自愈"],"a":3,"e":"原发性肺结核经淋巴道和血道播散，支气管播散是继发性肺结核空洞、干酪性肺炎的扩散方式，故不属于原发综合征的特点。"},{"q":"炎性水肿的主要原因是","o":["血浆胶体渗透压降低","毛细血管壁通透性增高","淋巴管阻塞","静脉压升高","醛固酮、抗利尿激素水平增高"],"a":1,"e":"炎症时组胺等介质使毛细血管壁通透性增高，富含蛋白的血浆渗出到组织间隙，形成炎性水肿，其渗出液蛋白含量高、比重高。"},{"q":"炎症早期局部组织呈鲜红色是因为","o":["炎性肉芽组织形成","静脉淤血","动脉性充血","红细胞漏出","炎细胞渗出"],"a":2,"e":"炎症早期细动脉扩张、血流加快，局部氧合血红蛋白增多，故组织呈鲜红色；至淤血期血流缓慢、还原血红蛋白增多，颜色转为暗红。"},{"q":"风湿病时，链球菌的何种成分与结缔组织发生反应","o":["链球菌溶血素“O”","链球菌多糖","链球菌透明质酸","胞壁C抗原","胞壁M抗原"],"a":4,"e":"A群乙型溶血性链球菌细胞壁的M蛋白与人心肌、心瓣膜及脑组织存在共同抗原表位，感染后产生的抗体与之交叉反应而引起风湿病。"},{"q":"关于慢性溃疡性结肠炎，下列哪项是错误的","o":["病因不明，多数认为与自身免疫有关","病变可累及结肠各段，偶可见回肠","本病仅限于肠溃疡，不伴全身性疾病","肠黏膜可有假息肉形成","溃疡局部肠黏膜上皮有癌变的可能"],"a":2,"e":"溃疡性结肠炎为原因不明的慢性结肠炎，常伴游走性多关节炎、葡萄膜炎和硬化性胆管炎等肠外表现，病变连续弥漫，可有假息肉形成并发生癌变。"},{"q":"关于梅毒疹，错误的叙述是","o":["可见于全身皮肤黏膜","为斑丘疹","可不治自愈","见于第二期梅毒","镜下为血管炎和肉芽肿性病变"],"a":4,"e":"二期梅毒疹为全身皮肤黏膜的斑丘疹，可不治自愈；镜下为真皮浅层血管周围浆细胞、淋巴细胞浸润，血管炎伴肉芽肿形成见于三期梅毒。"},{"q":"以下哪点与高分化恶性肿瘤不符","o":["异型性较小","常见于老年人","侵袭性较小","不发生转移","肿瘤体积较小"],"a":3,"e":"恶性肿瘤无论分化高低均具有浸润和转移的能力，高分化者仅异型性小、生长较慢、侵袭性较小；不发生转移不是高分化恶性肿瘤的特点。"},{"q":"继发性肺结核最常见的临床类型是","o":["局灶型肺结核","浸润型肺结核","肺结核球","干酪样肺炎","慢性纤维空洞型肺结核"],"a":1,"e":"浸润型肺结核是继发性肺结核中最常见的活动性类型，多由局灶型肺结核发展而来，X线示锁骨下云絮状阴影，可经支气管播散。"},{"q":"关于克罗恩病的病变，下列错误的是","o":["病变主要累及结肠","病变肠黏膜高度水肿如铺路石","黏膜面常形成裂隙状溃疡","临床上呈慢性经过","病变局限呈节段性分布"],"a":0,"e":"克罗恩病主要累及回肠末端，其次为结肠、回肠近端和空肠，病变呈节段性分布，黏膜呈铺路石样并有纵行裂隙状溃疡，临床呈慢性经过。"},{"q":"关于弥漫性非毒性甲状腺肿错误的说法是","o":["分为增生期、胶质贮积期、结节期、出血囊性变期","可伴有甲状腺功能亢进","常呈地域性分布，与缺碘密切相关","增生的甲状腺滤泡可以形成乳头","甲状腺内形成大小不等的结节，常伴有出血、坏死、囊性变及钙化"],"a":0,"e":"弥漫性非毒性甲状腺肿按发展过程分为增生期、胶质贮积期和结节期，并无出血囊性变期，出血、囊性变只是结节期的继发改变。"},{"q":"人类免疫缺陷病毒的传播途径不包括","o":["性接触传播","输血和血制品的应用","母婴垂直传播","应用污染的针头静脉注射","呼吸道传播"],"a":4,"e":"HIV主要存在于血液、精液、阴道分泌物和乳汁中，传播途径为性接触、血液（输血及血制品、污染针头注射）和母婴垂直传播。呼吸道传播不是HIV的传播途径，其为结核、SARS等的传播方式。"},{"q":"引起肾盂肾炎最主要的病原菌是","o":["肺炎杆菌","葡萄球菌","链球菌","副大肠杆菌","大肠杆菌"],"a":4,"e":"肾盂肾炎致病菌主要为革兰氏阴性杆菌，其中大肠埃希菌占绝大多数，其次为变形杆菌、产气杆菌、肠杆菌和葡萄球菌。"},{"q":"下列疾病或病变中属于化脓性炎的是","o":["结肠嗜酸性脓肿","肝阿米巴脓肿","脊柱旁冷脓肿","睾丸树胶样肿","淋病尿道炎"],"a":4,"e":"淋病奈瑟菌引起尿道黏膜的化脓性炎，渗出物为大量中性粒细胞；阿米巴脓肿、冷脓肿和树胶样肿分别为液化性坏死、干酪样坏死和凝固性坏死。"},{"q":"可导致肝脏肿大的疾病不包括","o":["肺源性心脏病","普通型肝炎","重型肝炎","糖尿病","酒精性肝病"],"a":2,"e":"重型肝炎时肝细胞大片坏死，肝体积显著缩小而非肿大；肺心病淤血、普通型肝炎和酒精性肝病均可引起肝大。"},{"q":"膜增生性肾小球肾炎的特点是肾小球的","o":["肾球囊壁层上皮增生，形成大量新月体","毛细血管丛内皮细胞显著增生肥大","系膜细胞增生伴基质增多，基膜增厚，及双轨征形成","肾球囊壁增厚，肾小球周围纤维化","基底膜伸出钉突状突起"],"a":2,"e":"膜增生性肾小球肾炎的组织学特点为系膜细胞增生、系膜基质增多，伴基膜增厚，因系膜细胞插入致基底膜呈双轨状。新月体见于急进性肾小球肾炎，钉突为膜性肾小球病的特征。"},{"q":"以下哪项不引起左心室肥大","o":["二尖瓣关闭不全","第三期梅毒","二尖瓣狭窄","主动脉瓣关闭不全","原发性高血压"],"a":2,"e":"二尖瓣狭窄时左心室充盈减少、负荷减轻，左心室不肥大甚至萎缩，左心房则扩大；二尖瓣关闭不全、主动脉瓣病变和高血压均使左心室负荷增加而肥大。"},{"q":"下列哪项不是慢性淤血的后果","o":["实质细胞的增生","出血","含铁血黄素沉积","间质细胞增生","可并发血栓形成"],"a":0,"e":"慢性淤血可致淤血性出血、含铁血黄素沉积、间质纤维组织增生及血栓形成；实质细胞因缺氧而发生萎缩、变性甚至坏死，不会增生。"},{"q":"系统性红斑狼疮患者皮肤损害的典型病变表现为","o":["皮下小结","蜘蛛痣","肢体环形红斑","面部蝶形红斑","出血点"],"a":3,"e":"SLE的特征性皮损为面颊部对称性蝶形红斑，镜下见表皮萎缩、毛囊角质栓、基底细胞液化及真皮血管周围淋巴细胞浸润；环形红斑和皮下小结是风湿病的表现。"},{"q":"外科病理学应用最广泛的病理学研究方法是","o":["尸体剖验","细胞培养和组织培养","动物实验","电镜","活检"],"a":4,"e":"活体组织检查从活体获取病变组织行病理诊断，能直接确定病变性质，是外科病理学中应用最广泛的研究方法。"},{"q":"下肢静脉内血栓脱落易引起","o":["下肢坏疽","脑动脉栓塞","肝脏梗死","肺动脉栓塞","肾动脉栓塞"],"a":3,"e":"肺动脉栓塞的栓子95%以上来自膝以上的下肢深部静脉，特别是腘静脉、股静脉和髂总静脉。下肢静脉血栓脱落后随血流经右心进入肺动脉，故引起肺动脉栓塞。"},{"q":"慢性酒精中毒引起的病变，当戒酒后可完全恢复的是","o":["酒精性肝炎","脂肪肝","小结节性肝硬化","大结节性肝硬化","混合结节性肝硬化"],"a":1,"e":"酒精性脂肪肝是慢性酒精中毒最常见的肝脏病变，戒酒后肝内脂滴可逐渐吸收、病变完全恢复；酒精性肝炎和肝硬化则难以逆转。"},{"q":"多发生在青年妇女的霍奇金淋巴瘤是","o":["结节硬化型","富于淋巴细胞的经典型","混合细胞型","淋巴细胞减少型","结节性淋巴细胞为主型"],"a":0,"e":"结节硬化型约占经典型霍奇金淋巴瘤的40%～70%，多见于青年妇女，好发于颈部及纵隔淋巴结，肿瘤细胞为陷窝细胞。"},{"q":"卵巢肿瘤中最常见的是","o":["浆液性肿瘤","黏液性肿瘤","生殖细胞肿瘤","性索间质肿瘤","转移性肿瘤"],"a":0,"e":"卵巢上皮性肿瘤最常见，其中浆液性肿瘤居首位，包括良性、交界性和恶性三类；黏液性肿瘤次之，生殖细胞肿瘤和性索间质肿瘤相对少见。"},{"q":"新生的毛细血管、成纤维细胞长入血肿内的过程为","o":["化生","栓塞","机化","再通","血栓形成"],"a":2,"e":"新生肉芽组织长入并取代坏死组织、血栓、血肿或异物的过程称机化，最终形成瘢痕；血栓机化后因内皮细胞长入可形成再通。"},{"q":"下列关于乙型脑炎病理改变的描述中，正确的是","o":["病变以小脑最为严重","病变在大脑皮层最轻微","神经细胞变性坏死为主要病变","病变累及脊髓前角神经细胞","病变组织中有中性粒细胞浸润"],"a":2,"e":"乙型脑炎病变广泛累及脑脊髓实质，以大脑皮质、基底核和视丘最重，脊髓最轻，基本病变为神经细胞变性坏死。"},{"q":"急性普通性肝炎的病理临床联系中，错误的是","o":["弥漫肝细胞变性-肝肿大","肝包膜紧张-肝区痛","部分肝细胞坏死-SGPT升高","肝细胞脂肪变性-厌油腻饮食","胆红素摄取、结合、分泌障碍"],"a":3,"e":"急性普通型肝炎因肝细胞广泛气球样变致肝肿大、包膜紧张而肝区痛，坏死使转氨酶升高，胆红素代谢障碍出现黄疸；厌油腻源于胆汁分泌排泄障碍，与肝细胞脂肪变性无直接关系。"},{"q":"高血压时心脏向心性肥大指","o":["左心室心肌肥厚而心腔不扩张","左心室心肌肥厚而心腔扩张","左心室壁厚度正常而心腔明显扩张","左心室、左心房心肌明显肥厚","左右心室心肌均肥厚"],"a":0,"e":"高血压时左心室后负荷增加引起代偿性肥大，心室壁增厚可达1.5～2.0cm，心腔不扩张甚至相对缩小，称向心性肥大；失代偿后转为离心性肥大。"},{"q":"慢性肺源性心脏病的特征不包括","o":["阻塞性通气功能障碍","肺循环阻力增加","肺动脉压升高","右心室肥厚","右心室扩张"],"a":0,"e":"慢性肺源性心脏病由肺疾病致肺循环阻力增加、肺动脉压升高，引起右心室肥厚和扩张；阻塞性通气功能障碍是慢支、肺气肿的表现，属病因环节而非本病特征。"},{"q":"最多见的原发性颅内肿瘤是","o":["胶质瘤","脑膜瘤","血管网状细胞瘤","神经鞘瘤","髓母细胞瘤"],"a":0,"e":"颅内原发性肿瘤中胶质瘤约占40%，为最多见者，其次为脑膜瘤和神经鞘瘤。转移性肿瘤以肺癌脑转移多见。"},{"q":"慢性胃溃疡经久难愈的局部因素主要是","o":["局部溃疡过大","局部溃疡过深","溃疡周边组织水肿","溃疡底部神经纤维变性、断裂","溃疡底部小动脉增生性内膜炎"],"a":4,"e":"溃疡底瘢痕组织内小动脉因炎症刺激发生增殖性内膜炎，管壁增厚、管腔狭窄并可有血栓形成，致局部血供不足、再生受限，故溃疡经久难愈。"},{"q":"下列不会导致支气管扩张症的疾病是","o":["肺结核","慢性支气管炎","小叶性肺炎","大叶性肺炎","肺囊性纤维化"],"a":3,"e":"支气管扩张多继发于肺结核、慢性支气管炎、小叶性肺炎和肺囊性纤维化等破坏管壁的病变；大叶性肺炎肺泡壁结构完整，一般不引起支气管扩张。"},{"q":"组织损伤的修复过程起始于","o":["损伤早期","损伤后期","炎症起始期","炎症后期","炎症静止期"],"a":2,"e":"组织损伤后炎症反应即启动，渗出与增生同时进行，成纤维细胞和内皮细胞在炎症起始期已开始增殖，故修复起始于炎症起始期而非炎症消退之后。"},{"q":"下列哪项不是变异型R-S细胞","o":["“爆米花”细胞","多形性R-S细胞","未分化R-S细胞","陷窝细胞","上皮样细胞"],"a":4,"e":"霍奇金淋巴瘤的变异型R-S细胞包括爆米花细胞、多形性R-S细胞、未分化R-S细胞和陷窝细胞；上皮样细胞是结核等肉芽肿中巨噬细胞衍生的细胞。"},{"q":"骨折愈合的最终阶段应是","o":["骨性骨痂形成","骨痂改建","纤维性骨痂连接","骨样组织中有钙盐沉着","完成了软骨化骨过程"],"a":1,"e":"骨折愈合依次为血肿形成、纤维性骨痂形成、骨性骨痂形成和骨痂改建，最后编织骨改建为成熟板层骨，恢复正常骨结构。"},{"q":"有关室间隔缺损的描述错误的是","o":["高位膜部缺损最多见","血液自右向左分流","早期患儿不出现发绀","晚期可出现肺动脉高压","可出现传导阻滞"],"a":1,"e":"室间隔缺损时左心室压高于右心室，血液自左向右分流，早期不出现发绀；晚期肺血管病变致肺动脉高压，可逆转为右向左分流而出现发绀，高位膜部缺损最多见。"},{"q":"肿瘤发生血行转移的依据是","o":["肿瘤细胞进入静脉","血液中发现有肿瘤","血管中发现有肿瘤栓子","远处器官形成同一类型肿瘤","肿瘤细胞进入淋巴管"],"a":3,"e":"血行转移的确切证据是在远隔器官形成与原发瘤同类型的肿瘤；血中查见瘤细胞或瘤细胞栓子仅提示播散，未必形成转移灶。"},{"q":"肿瘤经血行转移的最常累及的器官是","o":["肺、脑","肝、肺","肺、骨","肝、脑","肝、骨"],"a":4,"e":"官方答案为【肝、骨】，但依据教材，肿瘤经血行转移最常累及的器官为肺，肺是全身静脉血流首先到达的器官，故最常见转移部位应为肺、肝。"},{"q":"不是急性胰腺炎临床表现的是","o":["血清钙、钾、钠离子水平下降","血清淀粉酶升高","血清碱性磷酸酶活性增高","休克","持续性腹痛"],"a":2,"e":"急性胰腺炎时胰酶外溢引起胰腺及周围脂肪坏死，血清淀粉酶升高，脂肪坏死皂化消耗钙致血钙降低，并可出现休克和持续腹痛。碱性磷酸酶升高见于胆道梗阻和骨病，非本病特点。"},{"q":"以下关于胰腺癌的描述，不准确的是","o":["吸烟是重要的危险因素","以腺癌最常见","以胰头部最多见","60%的患者有K-ras基因突变","大多发病隐匿"],"a":3,"e":"胰腺癌K-ras基因突变率高达90%左右而非60%，故该描述不准确；胰头癌最多见，腺癌为最常见组织学类型，起病隐匿。"},{"q":"下列哪一类型的霍奇金淋巴瘤的预后最好","o":["结节硬化型","弥漫纤维化型的淋巴细胞减少型","网状细胞型的淋巴细胞减少型","混合细胞型","淋巴细胞为主型"],"a":4,"e":"淋巴细胞为主型霍奇金淋巴瘤背景为大量小淋巴细胞、R-S细胞少，病变较局限，预后在各型中最好；淋巴细胞减少型预后最差。"},{"q":"脾、肾梗死灶肉眼检查的主要特点为","o":["多呈楔形、灰白色、界限清楚","多呈不规则形、暗红色、界限不清","多呈楔形、暗红色、界限不清","多呈地图形、暗红色、界限不清","多呈地图形、灰白色、界限清楚"],"a":0,"e":"脾、肾由终末动脉供血，梗死灶切面呈楔形，属贫血性梗死故呈灰白色，与周围组织界限清楚，边缘可见充血出血带。"},{"q":"与获得性免疫缺陷综合征发病密切的病毒是","o":["HCV","HBV","HPV","HIV","EBV"],"a":3,"e":"艾滋病由人类免疫缺陷病毒HIV感染引起，病毒选择性破坏CD4+T淋巴细胞，造成严重免疫缺陷，继发机会性感染、肿瘤和神经系统症状。"},{"q":"腺泡中央型肺气肿病变主要累及","o":["肺小叶","终末细支气管","肺泡囊","呼吸性细支气管","细支气管"],"a":3,"e":"腺泡中央型肺气肿因呼吸性细支气管慢性炎症和弹性减退而呈囊状扩张，肺泡管和肺泡囊扩张不明显，多见于中老年吸烟者。"},{"q":"下列属于恶性肿瘤的是","o":["多形性腺瘤","甲状腺腺瘤","乳腺纤维腺瘤","脂肪母细胞瘤","肾母细胞瘤"],"a":4,"e":"肾母细胞瘤又称Wilms瘤，由原始肾组织发生，多见于儿童，属恶性肿瘤；多形性腺瘤、甲状腺腺瘤、纤维腺瘤和脂肪母细胞瘤均为良性。"},{"q":"关于大叶性肺炎下列哪项是错误的","o":["由细菌感染引起","病变多从肺泡开始","炎症不破坏肺泡壁结构","患者常有胸痛及咳铁锈色痰","以中性粒细胞渗出为主的炎症"],"a":4,"e":"大叶性肺炎是主要由肺炎链球菌引起的纤维素性炎，病变从肺泡开始且不破坏肺泡壁结构，临床有胸痛和铁锈色痰；渗出以纤维蛋白为主。"},{"q":"风湿性心包炎时心包脏层病变属于","o":["肉芽肿性炎","纤维素性炎","化脓性炎","浆液、纤维素性炎","特异性增生性炎"],"a":3,"e":"风湿性心外膜炎病变主要累及心外膜脏层，呈浆液性或纤维蛋白性炎症，故为浆液、纤维素性炎。化脓性心包炎由化脓菌侵袭所致。"},{"q":"HE制片中最常用的脱水剂","o":["丙酮","正丁醇","乙醇","环乙酮","叔丁醇"],"a":2,"e":"乙醇是最常用的脱水剂，可与水任意比例混合，梯度乙醇脱水后经二甲苯透明即可浸蜡包埋；丙酮和正丁醇仅用于有特殊要求的标本。"},{"q":"病毒性肺炎特点中不包括","o":["常是上呼吸道病毒感染向下蔓延所致","细胞内可检见包涵体","病变严重者，肺泡内可出现脓性渗出物","肺组织内出现灶状坏死","炎症从支气管、细支气管开始沿肺间质发展"],"a":2,"e":"病毒性肺炎以肺间质炎症为主，肺泡腔内为浆液、少量纤维蛋白、红细胞和巨噬细胞，出现脓性渗出物提示继发细菌感染，不属其本身特点。"},{"q":"下列哪一种疾病不会引起肺门淋巴结肿大","o":["支气管肺炎","支气管扩张症","肺癌","肺结核","肺硅沉着症"],"a":1,"e":"支气管扩张症病变局限于支气管及周围肺组织，肺门淋巴结一般不肿大；支气管肺炎、肺癌、肺结核和硅肺均可引起肺门淋巴结肿大。"},{"q":"如图为脑出血的大体观，有关该病变的叙述正确的是","o":["通常出血量小","属漏出性出血","多由于较大的血管破裂所致","由毛细血管和毛细血管后静脉通透性增加所致","凝血因子缺乏亦是主要原因"],"a":2,"e":"官方题库缺失图片"},{"q":"下列哪项因素一般与慢性胃炎无关","o":["长期慢性刺激","自身免疫损伤","幽门螺杆菌感染","十二指肠液反流","遗传因素"],"a":4,"e":"慢性胃炎主要由幽门螺杆菌感染、长期理化刺激、十二指肠液反流和自身免疫损伤引起；遗传因素不是其公认的致病因素。"},{"q":"动脉瘤是指","o":["动脉发生的良性肿瘤","动脉血管破裂形成的血肿","动脉内血栓形成并机化","血管壁的局部扩张","动脉发生的恶性肿瘤"],"a":3,"e":"动脉瘤是动脉壁局部薄弱后向外膨出形成的局限性扩张，并非真性肿瘤，可呈囊状或梭形，破裂可引起致命性大出血。"},{"q":"小叶性肺炎不会出现的并发症是","o":["肺脓肿","呼吸衰竭","支气管扩张","肺肉质变","心力衰竭"],"a":3,"e":"肺肉质变是大叶性肺炎的并发症，因肺泡内纤维蛋白渗出物机化所致；小叶性肺炎的并发症为肺脓肿、呼吸衰竭、心力衰竭和支气管扩张。"},{"q":"哪项描述符合瘢痕组织的特点","o":["细胞间有丰富的液体成分","组织内有大量的毛细血管","组织色泽鲜红、质地柔软","组织质地较硬、缺乏弹性","组织内有较多的炎性细胞"],"a":3,"e":"瘢痕组织由大量致密胶原纤维束构成，细胞和血管稀少，肉眼苍白半透明、质硬韧而缺乏弹性，可致瘢痕收缩和挛缩；色泽鲜红、富血管是肉芽组织的特点。"},{"q":"胶质结节中，增生的细胞主要是","o":["星形胶质细胞","内皮细胞","少突胶质细胞","大脑锥体神经元","小胶质细胞"],"a":4,"e":"胶质结节即小胶质细胞结节，是中枢神经系统感染时小胶质细胞局灶性增生聚集而成，多位于坏死神经元附近或小血管旁；星形胶质细胞增生则形成胶质瘢痕。"},{"q":"原发性肺结核的特点不包括","o":["多见于儿童","形成原发综合征","急性全身性粟粒性结核多见","肺门淋巴结易受累","原发病灶常见于肺上叶下部或肺下叶上部近脏胸膜处"],"a":2,"e":"原发性肺结核多见于儿童，形成原发综合征，肺门淋巴结易受累，原发灶常位于肺上叶下部或下叶上部近胸膜处。急性全身粟粒性结核多继发于继发性肺结核。"},{"q":"乳头溢液或溢血多发生于","o":["乳腺纤维腺瘤","乳腺导管癌","乳腺小叶癌","乳腺导管内乳头状瘤","乳腺腺病"],"a":3,"e":"乳腺导管内乳头状瘤位于扩张的导管内，乳头轴心富含薄壁血管，易出血，故以乳头溢液或溢血为主要临床表现。"},{"q":"属于漏出性出血的是","o":["溃疡出血","结核空洞性出血","创伤性出血","DIC出血","支气管扩张性出血"],"a":3,"e":"DIC时凝血因子和血小板大量消耗，微血管内皮受损、通透性增高，血液经扩大的内皮间隙漏出，属漏出性出血；溃疡、创伤和支气管扩张出血为破裂性出血。"},{"q":"下列关于心内膜下心肌梗死的描述，哪项是错误的","o":["梗死仅累及心室壁内侧的1/3的心肌","梗死波及肉柱及乳头肌","梗死灶常表现为小灶状坏死","严重者坏死灶融合引起环状梗死","梗死灶不规则地分布于左心室四周"],"a":3,"e":"心内膜下心肌梗死严重时病灶扩大融合累及整个心内膜下心肌，引起环状梗死，故该描述正确而非错误。其余各项均符合教材对心内膜下心肌梗死的描述。"},{"q":"关于正常子宫内膜的基本结构，下列哪一点是错误的","o":["子宫内膜分为基底层和功能层","致密层为功能层的表层","海绵层腺体最多","基底层对卵巢激素反应最敏感","功能层有周期性变化"],"a":3,"e":"子宫内膜功能层随卵巢激素周期性变化而增生、分泌和脱落，基底层不受激素周期性影响，月经后由其增生修复功能层。"},{"q":"良性高血压晚期会引起","o":["继发性颗粒性固缩肾","肾水变性","原发性颗粒性固缩肾","肾凹陷性瘢痕","肾盂积水"],"a":2,"e":"良性高血压晚期因入球小动脉玻璃样变和肾实质缺血，肾单位萎缩、纤维化，肾表面呈均匀细颗粒状，称原发性颗粒性固缩肾。"},{"q":"出现箭头所指图1、2改变的可能的肾炎是","o":["急性肾小球肾炎","急进性肾小球肾炎","急性肾盂肾炎","慢性肾盂肾炎","肾癌"],"a":1,"e":"官方题库缺失图片"},{"q":"主动脉粥样硬化时，病变最严重的部位是","o":["升主动脉","主动脉弓","降主动脉","主动脉根部","腹主动脉"],"a":4,"e":"主动脉粥样硬化好发于主动脉后壁及其分支开口处，以腹主动脉病变最为严重，其后依次为胸主动脉、主动脉弓和升主动脉。"},{"q":"在大多数类型的组织损伤中血管通透性升高的速发反应主要是下列哪种因素影响","o":["补体","细菌毒素","过敏毒素","组胺","坏死分解产物"],"a":3,"e":"组胺作用于血管内皮细胞H1受体，使其迅速收缩、细胞间隙增宽，是速发型血管通透性升高的主要介质，作用时间短暂。"},{"q":"下面疾病中，低度恶性的肿瘤是","o":["鳞状细胞癌","鳞状细胞乳头状瘤","疣状癌","牙龈瘤","黏膜白斑"],"a":2,"e":"疣状癌为高分化鳞状细胞癌，呈疣状或菜花状外生性生长，生长缓慢、浸润局限，极少转移，属低度恶性肿瘤。"},{"q":"急性重型肝炎的病变性质是","o":["以肝细胞变性为主的炎症","以肝细胞坏死为主的炎症","以肝细胞增生为主的炎症","以汇管区渗出为主的炎症","以汇管区增生为主的炎症"],"a":1,"e":"急性重型肝炎以肝细胞广泛大片坏死为主，坏死区网状纤维支架塌陷，库普弗细胞增生，炎症细胞浸润相对较轻，属变质性炎。"},{"q":"下列哪项不是生殖细胞起源的肿瘤","o":["无性细胞瘤","葡萄胎","颗粒细胞瘤","畸胎瘤","绒癌"],"a":2,"e":"颗粒细胞瘤起源于卵巢性索间质，属性索间质肿瘤；无性细胞瘤、畸胎瘤、绒癌和葡萄胎均起源于生殖细胞。"},{"q":"关于梗阻性黄疸的描述错误的是","o":["具有诊断特异性","是胰头癌最重要的临床表现","往往呈进行性加重","大部分患者出现黄疸时已属中晚期胰腺癌","可以出现在慢性胰腺炎患者"],"a":0,"e":"梗阻性黄疸是胰头癌最重要也最常首发的表现，多呈进行性加重，出现时多属中晚期，慢性胰腺炎也可因胆总管受压而出现；但其缺乏特异性。"},{"q":"侵袭性葡萄胎与葡萄胎的主要不同是","o":["滋养细胞增生","绒毛水肿","hCG水平增高","绒毛间质血管消失","绒毛及滋养细胞侵蚀子宫肌层的深层"],"a":4,"e":"侵袭性葡萄胎与葡萄胎的根本区别在于水泡状绒毛侵入子宫肌层和血管，引起肌层出血坏死，甚至穿出子宫或经血道转移至肺、脑。"},{"q":"下列哪种变性是发生于细胞内","o":["脂肪变性","细动脉玻璃样变","淀粉样变性","黏液样变性","营养不良性钙化"],"a":0,"e":"脂肪变性是细胞内脂质蓄积，属细胞内变性；细动脉玻璃样变、淀粉样变性、黏液样变性和营养不良性钙化均发生于细胞外间质。"},{"q":"慢性炎症中，最常见的细胞是","o":["嗜酸性粒细胞","淋巴细胞","中性粒细胞","肥大细胞","嗜碱性粒细胞"],"a":1,"e":"慢性炎症灶内浸润的细胞以淋巴细胞、浆细胞和单核巨噬细胞为主，其中淋巴细胞最为常见；中性粒细胞见于急性炎症或慢性炎症急性发作时。"},{"q":"初次吸入结核杆菌，最早引起的肺内病变是","o":["原发综合征","沿支气管出现广泛渗出","结核性淋巴结炎","原发灶的渗出及坏死","肺门淋巴结结核"],"a":3,"e":"初次感染结核分枝杆菌时，细菌在肺上叶下部或下叶上部近胸膜处引起渗出性病灶并发生干酪样坏死，即原发灶，肺门淋巴结结核在其后出现。"},{"q":"细胞肿胀常发生于下述哪一组脏器","o":["心、肺、肾","心、脑、肾","胰、脾、肾","心、肝、肾","脑、肠、肺"],"a":3,"e":"细胞肿胀即细胞水肿，好发于代谢活跃、对缺氧敏感的实质器官，以心、肝、肾最为常见，镜下胞质疏松淡染并出现空泡，严重者呈气球样变。"},{"q":"下列癌的恶性程度相对较低的是","o":["卵巢黏液腺癌","肺小细胞癌","皮肤基底细胞癌","肝胆管细胞癌","肾盂移行细胞癌"],"a":2,"e":"皮肤基底细胞癌多见于老年人面部，生长缓慢，呈局部浸润性生长，极少转移，恶性程度低。肺小细胞癌、胆管细胞癌及肾盂移行细胞癌侵袭转移能力均强。"},{"q":"慢性支气管炎患者通气和换气功能障碍的病变基础是","o":["支气管黏膜上皮细胞变性、坏死脱落","支气管壁腺体增生、肥大","支气管壁充血、水肿、淋巴细胞和浆细胞浸润","急、慢性细支气管炎及细支气管周围炎","支气管管壁平滑肌束断裂，萎缩"],"a":3,"e":"慢性支气管炎并发急、慢性细支气管炎及细支气管周围炎，使小气道管壁增厚、管腔狭窄并形成黏液栓，是通气和换气功能障碍的病变基础。"},{"q":"肱静脉血栓形成可引起","o":["肺动脉栓塞","尺动脉栓塞","桡动脉栓塞","脑动脉栓塞","肾动脉栓塞"],"a":0,"e":"肱静脉属上肢深静脉，血栓脱落后经腋静脉、锁骨下静脉和上腔静脉入右心，最终栓塞肺动脉分支，引起肺动脉栓塞。"},{"q":"关于风湿性肉芽肿的叙述，下列哪项是错误的","o":["中心部位有较多纤维蛋白","多发生于心肌间质血管旁","常伴有淋巴细胞、浆细胞浸润","特征性细胞是Aschoff细胞","是风湿病的特征性病变，具有诊断意义"],"a":0,"e":"风湿小体中央为纤维素样坏死，周围为风湿细胞即Aschoff细胞，并伴淋巴细胞、浆细胞浸润，多位于心肌间质血管旁，具诊断意义；较多纤维蛋白见于新月体。"},{"q":"伤寒的传播途径是","o":["消化道传播","呼吸道传播","血液传播","接触传播","内源性感染"],"a":0,"e":"伤寒沙门菌随粪便、尿排出体外，经污染的水和食物经口感染，属消化道传播；病变以回肠末段淋巴组织增生、坏死和溃疡形成为特征。"},{"q":"嗜铬细胞瘤最常见于","o":["肾上腺髓质","主动脉旁副节细胞","肾上腺皮质","甲状旁腺细胞","胰岛细胞"],"a":0,"e":"嗜铬细胞瘤约90%发生于肾上腺髓质，由嗜铬细胞构成，分泌去甲肾上腺素和肾上腺素，引起阵发性高血压；肾上腺外者称副神经节瘤。"},{"q":"正常淋巴滤泡生发中心免疫表型特点是","o":["CD20+，BCL2+","CD3+，BCL2+","CD19+，BCL2+","CD20+，BCL2-","CD3+，BCL2-"],"a":3,"e":"正常生发中心细胞表达B细胞标记CD20，因BCL2基因未活化而呈BCL2阴性；滤泡性淋巴瘤因t(14;18)易位而高表达Bcl-2蛋白。"},{"q":"容易发生出血性梗死的器官是","o":["心","肾","脑","脾","肠"],"a":4,"e":"肠梗死时肠壁组织疏松、吻合支丰富且伴严重淤血，动脉阻塞后血液经吻合支涌入坏死区，故形成出血性梗死；心、肾、脾、脑多发生贫血性梗死。"},{"q":"肝穿刺活检，镜下表现如图。应诊断为","o":["急性普通型肝炎","慢性中度肝炎","肝细胞肝癌","急性重型肝炎","亚急性重型肝炎"],"a":2,"e":"官方题库缺失图片"},{"q":"食管癌的直接浸润一般不会引起","o":["食管-气管瘘","肺脓肿","脓胸","大出血","颈部淋巴结肿大"],"a":4,"e":"食管癌直接浸润可穿透食管壁累及气管形成食管气管瘘，继发肺脓肿和脓胸，侵蚀大血管可致大出血。颈部淋巴结肿大属淋巴道转移，不是直接浸润所致。"},{"q":"克罗恩病的病变特点不包括","o":["黏膜面有裂隙状溃疡形成","肠壁各层见大量慢性炎症细胞浸润","部分病例肠壁有结核样肉芽肿结构","病变常呈节段性分布","肉芽肿中心有干酪样坏死，不易和结核鉴别"],"a":4,"e":"克罗恩病的结核样肉芽肿由上皮样细胞和多核巨细胞构成，中央无干酪样坏死，是与肠结核鉴别的关键；病变呈节段性分布，伴裂隙状溃疡和全层炎。"},{"q":"胃癌的最主要转移途径是","o":["血行转移","直接蔓延","淋巴道转移","消化道内转移","腹腔内种植"],"a":2,"e":"胃癌以淋巴道转移为主要途径，首先转移至幽门下及胃小弯淋巴结，再至腹主动脉旁、肝门等淋巴结，晚期经胸导管至左锁骨上淋巴结。"},{"q":"B型慢性萎缩性胃炎好发于","o":["贲门","胃小弯","胃大弯","胃窦部","胃底部"],"a":3,"e":"B型慢性萎缩性胃炎与幽门螺杆菌感染有关，病变多在胃窦部，壁细胞抗体阴性，胃酸轻中度降低；A型属自身免疫性，累及胃体和胃底。"},{"q":"甲状腺腺瘤与结节性甲状腺肿的主要区别是","o":["发病年龄和性别不同","有无完整的包膜，瘤内组织结构是否一致","结节的数目不同","滤泡中有无胶质","前者肿块为单个，大小不超过3cm"],"a":1,"e":"甲状腺腺瘤多单发、有完整包膜，瘤内滤泡及滤泡上皮大小一致；结节性甲状腺肿常多发、无完整包膜，滤泡大小不一，两者据此鉴别。"},{"q":"从图中所示的主要病理改变中，下列哪一项是错误的","o":["筛状软化灶","淋巴细胞浸润的围管现象","蛛网膜下腔见大量中性粒细胞","神经细胞变性坏死","形成胶质结节"],"a":2,"e":"官方题库缺失图片"},{"q":"如图所示，它属于下列哪个部位的何种病变","o":["黏膜的纤维素性炎","浆膜的纤维素性炎","黏膜的浆液性炎","浆膜的浆液性炎","化脓性炎"],"a":0,"e":"官方题库缺失图片"},{"q":"创伤一期愈合和二期愈合的差异主要是","o":["是否为手术切口","是否经过扩创术","是否有大量肉芽组织形成","创面是否有出血","创面是否有炎症反应"],"a":2,"e":"二期愈合因组织缺损大、坏死多或伴感染，需从伤口底部及边缘长出大量肉芽组织填平缺损，故瘢痕较大；一期愈合创缘对合良好，肉芽组织少。"},{"q":"原发性肝癌的肉眼分型不包括","o":["结节型","弥漫型","巨块型","混合型","小肝癌"],"a":3,"e":"原发性肝癌肉眼分为巨块型、多结节型、弥漫型和特殊类型如小肝癌；混合型指肝细胞癌与胆管癌两种组织学成分并存，属组织学分型而非肉眼分型。"},{"q":"发生液化性坏死基本条件应包括","o":["含有较多的可凝固蛋白","组织淤血较严重","组织比较松软","产生蛋白酶较多","有腐败菌感染"],"a":3,"e":"液化性坏死发生于可凝固蛋白少而水解酶多的组织，坏死细胞及浸润的中性粒细胞释放大量蛋白水解酶，使组织溶解液化。"},{"q":"下列哪项属于肝功能不全的表现","o":["脾大","胃肠道淤血","蜘蛛痣","腹水","侧支循环形成"],"a":2,"e":"蜘蛛痣是肝功能不全时雌激素灭活减少、体内雌激素水平升高致小动脉末梢扩张形成的血管痣，压迫其中心可使其消失。脾大、胃肠道淤血、腹水、侧支循环形成属门静脉高压表现。"},{"q":"伤寒肠道病变的好发部位是","o":["空肠","横结肠","乙状结肠","回盲部","回肠末端"],"a":4,"e":"伤寒肠道病变以回肠下段集合和孤立淋巴小结的病变最为常见和明显，故好发部位为回肠末端。病变按髓样肿胀、坏死、溃疡、愈合四期发展。"},{"q":"具有高比重，静置凝固，黄色浑浊等性状的腹水见于","o":["门静脉高压","右心衰竭","慢性肾炎","低蛋白血症","腹膜炎"],"a":4,"e":"腹膜炎所致腹水为渗出液，蛋白含量高、比重高于1.018，静置后自行凝固，外观浑浊呈黄色；门静脉高压、右心衰竭和低蛋白血症引起的是漏出液，比重低而清亮。"},{"q":"胃活检切片，镜下表现如图，应诊断为","o":["低分化腺癌","髓样癌","印戒细胞癌","硬癌","癌肉瘤"],"a":2,"e":"官方题库缺失图片"},{"q":"在我国引起肺源性心脏病最常见的疾病是","o":["肺结核","硅沉着症","支气管哮喘","支气管扩张症","慢性支气管炎伴肺气肿"],"a":4,"e":"我国肺心病绝大多数由慢性支气管炎并发阻塞性肺气肿引起，肺组织破坏使毛细血管床减少，缺氧又致肺小动脉痉挛，形成肺动脉高压。"},{"q":"胃癌的好发部位是","o":["胃体","胃底部","胃窦部","胃大弯","胃小弯"],"a":2,"e":"胃癌好发于胃窦部，尤其小弯侧，其次为贲门、胃底和胃体；该处黏膜与致癌物接触时间长，慢性炎症和肠上皮化生发生率高。"},{"q":"下列哪种恶性肿瘤属于B细胞型淋巴瘤","o":["霍奇金淋巴瘤","滤泡性淋巴瘤","蕈样肉芽肿（蕈样霉菌病）","恶性组织细胞增生症","Sezary综合征"],"a":1,"e":"滤泡性淋巴瘤来源于生发中心B细胞，瘤细胞表达CD20、CD10和Bcl-6，伴t(14;18)易位；蕈样肉芽肿和Sezary综合征属T细胞淋巴瘤。"},{"q":"目前我国死亡率最高的肿瘤是","o":["肝癌","胃癌","乳腺癌","子宫颈癌","肺癌"],"a":4,"e":"我国恶性肿瘤死亡率以肺癌居首，2020年死亡约71.5万，其后依次为肝癌、胃癌、食管癌和结直肠癌。"},{"q":"关于中央型肺癌的特点，应除外","o":["由段以上支气管发生","位于肺门部","多是小细胞肺癌","较易被纤维支气管镜检查发现","巨大癌块环绕癌变支气管"],"a":2,"e":"中央型肺癌起源于段及段以上支气管，位于肺门部，癌块常环绕支气管生长，纤维支气管镜易于发现；组织学以鳞状细胞癌最多见，小细胞癌只占其中一部分。"},{"q":"下列有关病毒性心肌炎的叙述，哪项是不正确的","o":["常由柯萨奇B组病毒感染引起","病毒通过B淋巴细胞介导引起炎症反应","晚期有明显的间质纤维化","心肌细胞变性、坏死","心肌间质内炎细胞浸润"],"a":1,"e":"病毒性心肌炎多由柯萨奇B组病毒引起，病毒直接损伤心肌细胞，并通过T细胞介导的免疫反应致病，晚期出现明显间质纤维化。"},{"q":"交界性肿瘤是指","o":["既有癌组织，又有肉瘤成分的肿瘤","侵犯表皮和真皮交界部位的肿瘤","介于良性和恶性之间的肿瘤","侵犯黏膜和黏膜基层交界部位的肿瘤","既有腺癌成分、又有鳞癌成分的肿瘤"],"a":2,"e":"交界性肿瘤的组织形态和生物学行为介于良性与恶性之间，如卵巢交界性浆液性乳头状囊腺瘤，可局部复发但极少转移；含癌与肉瘤成分者为癌肉瘤。"},{"q":"容易发生肠粘连、狭窄的疾病为","o":["阿米巴病","细菌性痢疾","伤寒","结核","息肉"],"a":3,"e":"肠结核干酪样坏死溃疡愈合后纤维组织增生、瘢痕收缩，易致肠腔狭窄和肠粘连；阿米巴病、细菌性痢疾和伤寒少见此后果。"},{"q":"梅毒的特征性病变是","o":["明显干酪样坏死","玫瑰疹","树胶样肿","象皮肿","异物肉芽肿"],"a":2,"e":"树胶样肿又称梅毒瘤，是三期梅毒的特征性病变，中央为凝固性坏死，周围有上皮样细胞和淋巴细胞，质韧如树胶，可致器官变形。"},{"q":"神经元单纯性萎缩一般不常伴有","o":["周围血管性淋巴细胞浸润","明显的胶质细胞增生","嗜神经细胞现象","神经细胞内包涵体","缺血性病变"],"a":1,"e":"单纯性神经元萎缩为慢性渐进性变性，特征为胞体及胞核固缩、消失，无明显尼氏小体溶解，一般不伴炎症反应，胶质细胞增生不明显。嗜神经细胞现象、血管周围淋巴细胞浸润及缺血性病变均可见于神经元损伤性病变。"},{"q":"肿瘤分期是指","o":["肿瘤细胞的分化程度","肿瘤细胞的恶性程度","肿瘤细胞核分裂象的多少","肿瘤的生长范围和扩散程度","肿瘤细胞的浸润及转移能力"],"a":3,"e":"肿瘤分期指恶性肿瘤的生长范围和播散程度，依据原发灶大小、浸润深度、淋巴结转移和远处转移判定；分化程度和核分裂象数目属分级指标。"},{"q":"黏液变性是指","o":["组织间质内出现大量的类黏液","黏液腺分泌过多","胃印戒细胞癌的癌细胞中有大量黏液","浆液腺发生黏液化而分泌大量黏液","支气管黏膜上皮中的杯状细胞分泌黏液"],"a":0,"e":"黏液变性是组织间质内氨基多糖等类黏液积聚，HE染色呈淡蓝色胶状，间质胶原纤维断裂变疏松，见于甲状腺功能减退的黏液水肿。"},{"q":"伤寒增生的细胞是","o":["淋巴细胞","单核巨噬细胞","中性粒细胞","嗜酸性粒细胞","浆细胞"],"a":1,"e":"伤寒的病变以单核巨噬细胞系统增生为特征，巨噬细胞吞噬伤寒沙门菌后体积增大、胞质丰富，形成伤寒细胞并聚集成伤寒小结；本病外周血中性粒细胞和嗜酸性粒细胞减少。"},{"q":"下述哪种病变不会出现冠状动脉粥样硬化","o":["心肌的变性和坏死","心肌内糖原沉积","心肌间质出血","心肌的代偿性肥大","心肌内纤维化"],"a":1,"e":"冠状动脉粥样硬化使心肌缺血缺氧，引起心肌变性坏死、间质纤维化及代偿性肥大，可伴心内膜下出血；心肌糖原沉积见于糖原贮积症。"},{"q":"肿瘤生长分数是指","o":["肿瘤细胞中处于增殖阶段的细胞比例","肿瘤细胞中处于合成前期的细胞比例","肿瘤细胞中处于有丝分裂期的细胞比例","肿瘤细胞中处于合成前、后期的细胞比例","肿瘤细胞中处于合成期的细胞比例"],"a":0,"e":"生长分数指肿瘤细胞群体中处于增殖状态的细胞比例，处于增殖状态的细胞不断分裂繁殖。"},{"q":"在活体内血栓形成过程中的启动因素是","o":["激活内源性凝血系统","血小板的黏集","激活外源性凝血系统","合成前列环素","生成纤溶酶原活化因子"],"a":1,"e":"血栓形成时血小板黏附于受损内膜裸露的胶原并被激活，黏集成堆构成血栓的起始点，随后凝血酶生成使纤维蛋白网罗血细胞而成为不可逆团块。"},{"q":"肝功能不全患者蜘蛛状血管痣好发于","o":["腹前壁","颈、面部、前臂及手掌","全身各部","上肢及下肢","背部及颈部"],"a":1,"e":"肝功能不全时雌激素灭活减少，小动脉末梢扩张形成蜘蛛痣，好发于颈、面部、前臂及手掌等处，压迫中心红点可使整个痣消退。"},{"q":"图为肺淤血镜下表现，箭头所指细胞为","o":["心力衰竭时某些形态特殊的心肌细胞","硅沉着病致右心衰竭时，肺内吞噬硅尘的巨噬细胞","褐色硬变肺内含有含铁血黄素的巨噬细胞","心力衰竭时肺内吞噬炭末的巨噬细胞","心力衰竭时肺泡腔内的泡沫细胞"],"a":2,"e":"慢性肺淤血时肺泡腔内巨噬细胞吞噬降解红细胞，胞质内形成含铁血黄素颗粒，即心衰细胞，肺呈棕褐色称肺褐色硬化。"},{"q":"脑出血最常见的原因是","o":["血液病","血管瘤破裂","高血压病脑内出血","脑内小动脉粥样硬化","外伤"],"a":2,"e":"脑内出血最常见的病因是高血压病，脑细小动脉硬化并形成微动脉瘤，血压骤升时破裂，好发于基底节、内囊区。"},{"q":"与癌前病变无关的描述是","o":["如不及时治愈有可能转变为癌","演变为癌的时间较长","细胞形态可有异型性","癌前病变可分为遗传性和获得性","适应性反应"],"a":4,"e":"癌前病变指本身不是癌但具有癌变潜能的病变，其演变为癌需较长时间，细胞可呈异型性，并可分为遗传性与获得性。适应性反应属细胞对刺激的调整性改变，与癌前病变无直接关系。"},{"q":"肝穿刺送检标本，镜下如图所示，箭头所指肝细胞出现何种病变","o":["细胞水肿","脂肪变性","玻璃样变性","嗜酸性变","点状坏死"],"a":3,"e":"官方题库缺失图片"},{"q":"下面疾病中属于癌前病变的是","o":["黏膜白斑","白塞综合征","Wegener肉芽肿","复发性阿弗他溃疡","牙龈瘤"],"a":0,"e":"黏膜白斑属癌前病变，口腔、外阴等处黏膜上皮长期受刺激后出现鳞状上皮增生和异型增生，可进一步发展为鳞状细胞癌；白塞综合征是血管炎，与癌变无关。"},{"q":"下列哪种肿瘤无血管及间质","o":["脂肪瘤","横纹肌肉瘤","纤维肉瘤","畸胎瘤","绒毛膜癌"],"a":4,"e":"绒毛膜癌由滋养层细胞增生形成，癌细胞排列成团或条索，无血管及间质，靠宿主血管获取营养。脂肪瘤、纤维肉瘤、横纹肌肉瘤及畸胎瘤均有间质和血管。"},{"q":"下列不是流行性脑脊髓膜炎的临床表现的是","o":["脑膜刺激征状","颅内压升高","偏瘫","脑脊髓液细胞数增加","脑神经麻痹"],"a":2,"e":"流脑为软脑膜及蛛网膜下腔的化脓性炎，表现为颅内压升高、脑膜刺激征和脑脊液细胞数增多；偏瘫属脑实质受累的局灶体征，见于乙脑等脑炎。"},{"q":"在淋巴结内有多核巨细胞、类上皮细胞形成的结节样反应，此时可排除","o":["猫抓病","结核","非典型分枝杆菌感染","性病性淋巴肉芽肿","窦组织细胞增生"],"a":0,"e":"结核、非典型分枝杆菌感染和性病性淋巴肉芽肿均形成上皮样细胞结节伴多核巨细胞；猫抓病以微脓肿和星状坏死为特点，不是结核样结节。"},{"q":"细动脉透明变性常见于下列哪项","o":["肾、心、脾、视网膜等处的细动脉","肺、胰、肠系膜等处的细动脉","肾、脑、肝、心等处的细动脉","心、肺、脾、视网膜等处的细动脉","肾、脑、脾、视网膜等处的细动脉"],"a":0,"e":"细动脉玻璃样变常见于缓进型高血压和糖尿病，最易累及肾入球动脉、视网膜动脉和脾中央动脉，脑细小动脉亦可受累。"},{"q":"亚急性感染性心内膜炎的赘生物脱落后最易引起栓塞的部位是","o":["皮肤","心脏","肾","脾","脑"],"a":4,"e":"亚急性感染性心内膜炎的赘生物松脆易脱落，栓子随体循环最易栓塞脑，也可至肾、脾和下肢，脑栓塞可引起偏瘫、失语甚至死亡。"},{"q":"槟榔肝是指","o":["肝细胞肿胀","肝细胞脂肪变性、淤血","慢性肝炎","肝硬化","肝细胞萎缩"],"a":1,"e":"槟榔肝是慢性肝淤血的表现，肝小叶中央区淤血呈暗红色，与周边肝细胞脂肪变性呈黄色相间，形似槟榔切面。"},{"q":"下列哪一项不符合肺动脉高压形成的机制","o":["缺氧引起肺小动脉痉挛","长期、反复痉挛导致肺小动脉玻璃样变","肺内无肌性细动脉肌化","肺纤维化及肺气肿可引起肺动脉高压","肌型小动脉中膜肥厚，内膜下出现纵形肌束"],"a":1,"e":"肺心病时肺小动脉构型重建表现为无肌型细动脉肌化、肌型小动脉中膜肥厚及内膜下纵行肌束形成；玻璃样变是高血压细动脉硬化的改变，不是肺血管重建机制。"},{"q":"阿米巴滋养体所引起的组织坏死是","o":["凝固性坏死","干酪样坏死","湿性坏疽","液化性坏死","纤维素样坏死"],"a":3,"e":"阿米巴滋养体释放溶组织酶，使组织溶解液化，形成液化性坏死。镜下呈无结构淡红色病灶，病灶周围炎症反应轻微。"},{"q":"可造成感染慢性化的肝炎病毒是","o":["肝炎病毒C","肝炎病毒A、E","肝炎病毒A、D","肝炎病毒B、C、D","肝炎病毒C、D、E"],"a":3,"e":"乙型、丙型和丁型肝炎病毒均可引起慢性感染，其中HBV和HCV易转为慢性并致肝硬化、肝癌；甲型和戊型肝炎经粪-口传播，多呈自限性急性经过。"},{"q":"炎症反应的最重要的指征是","o":["血管扩张","红细胞漏出","血浆渗出","白细胞游出","纤维素渗出"],"a":3,"e":"白细胞游出血管进入炎区是炎症反应最重要的特征和指征，血管扩张和血浆渗出只是早期的血管反应。"},{"q":"某患者白带增多，宫颈活检镜下见鳞状上皮层下部近2/3的细胞出现异型性，应诊断为","o":["宫颈上皮内瘤变Ⅰ级","宫颈上皮内瘤变Ⅱ级","宫颈上皮内瘤变Ⅲ级","宫颈原位癌","宫颈柱状上皮异位"],"a":1,"e":"异型增生细胞占据上皮下1/3以上、未超过2/3者为CINⅡ级。CINⅠ级异型细胞限于下1/3，CINⅢ级异型细胞超过2/3或累及全层。"},{"q":"高血压脑出血最易发生病变的动脉是","o":["基底动脉","豆纹动脉内侧动脉","大脑中动脉","豆纹动脉外侧动脉","Willis动脉"],"a":3,"e":"高血压脑出血多发生于基底节豆状核区，因豆纹动脉自大脑中动脉呈直角发出、直接承受较高压力冲击，其中外侧豆纹动脉最易破裂。"},{"q":"电镜下细胞凋亡的特征性改变是","o":["细胞皱缩","细胞质致密","染色质边集","核碎裂","凋亡小体形成"],"a":4,"e":"细胞凋亡时核染色质凝聚边集、胞膜内陷出芽，形成含核碎片和细胞器的膜包被小体，电镜下凋亡小体最具特征性。"},{"q":"子宫颈癌最常见的组织学类型为","o":["黏液癌","鳞状细胞癌","腺癌","未分化癌","大细胞癌"],"a":1,"e":"子宫颈癌组织学类型以鳞状细胞癌最多见，约占80%～90%，多起于鳞柱交界处；腺癌较少，约占20%且近年有上升趋势。"},{"q":"大叶性肺炎患者的铁锈色痰变成黏液脓痰是在","o":["充血水肿期","红色肝样变期","灰色肝样变期","溶解消散期","病变恢复期"],"a":2,"e":"红色肝样变期红细胞崩解形成含铁血黄素使痰呈铁锈色；至灰色肝样变期红细胞已溶解，渗出物以中性粒细胞和纤维蛋白为主，痰转为黏液脓性。"},{"q":"下列关于妊娠期子宫内膜的特征叙述，哪一个是错误的","o":["子宫内膜致密层形成蜕膜组织","海绵层腺体扩张，弯曲，分泌增强","腺体上皮细胞呈顶浆分泌，腺体弯曲呈锯齿状","部分腺体出现A-S现象","腺体可呈腺瘤样增生"],"a":2,"e":"顶浆分泌、腺体弯曲呈锯齿状是分泌期子宫内膜的特征，妊娠期子宫内膜呈蜕膜样改变而非此表现。妊娠期内膜致密层形成蜕膜组织，海绵层腺体扩张弯曲、分泌增强，部分腺体出现A-S现象。"},{"q":"诊断慢性浅表性胃炎最有意义的是","o":["黏膜浅层溃疡形成","黏膜浅层嗜酸性粒细胞和中性粒细胞浸润","黏膜浅层淋巴细胞浸润和上皮坏死脱落","黏膜浅层炎细胞浸润和腺体增生","黏膜浅层淋巴细胞、浆细胞浸润伴固有层腺体消失"],"a":2,"e":"慢性浅表性胃炎病变限于黏膜浅层，固有层内以淋巴细胞、浆细胞浸润为主，表面上皮可变性坏死脱落，腺体保持完整无萎缩。腺体消失和肠上皮化生见于萎缩性胃炎。"},{"q":"下列哪型肝炎的肝脏重量减轻最明显","o":["急性普通型肝炎","急性重型肝炎","亚急性重型肝炎","重度慢性肝炎","轻度慢性肝炎"],"a":1,"e":"急性重型肝炎肝细胞弥漫性大片坏死，肝体积明显缩小、重量显著减轻、包膜皱缩、质地柔软，故肝脏重量减轻最明显；亚急性重型因结节状再生而缩小较轻。"},{"q":"癌变率较高的大肠病变是","o":["绒毛状腺瘤","增生性息肉","锯齿状腺瘤","幼年性息肉","炎性息肉"],"a":0,"e":"绒毛状腺瘤的绒毛状结构表面积大、异型增生重，癌变率明显高于管状腺瘤，属大肠癌的癌前病变。增生性、炎性及幼年性息肉一般不发生癌变。"},{"q":"可以诊断为恶性肿瘤的是","o":["肿瘤有出血","肿瘤有坏死","肿瘤有火山口状溃疡形成","肿瘤的异型性明显","肿瘤呈浸润性生长"],"a":3,"e":"肿瘤的异型性明显是判断恶性最重要的形态学依据，表现为细胞大小不一、核大深染、核质比增高和病理性核分裂；出血坏死也可见于良性肿瘤。"},{"q":"下列都符合流行性乙型脑炎，除外","o":["病毒引起的急性传染病","也称日本夏季脑炎","以蚊虫为传播媒介","脑组织以渗出性病变为主","病变以大脑皮质、基底节、视丘最为严重"],"a":3,"e":"流行性乙型脑炎由乙脑病毒经蚊虫叮咬传播，夏秋季流行，又称日本夏季脑炎，病变以大脑皮质、基底核和视丘最重。其基本病变为神经细胞变性坏死，属变质性炎，不以渗出为主。"},{"q":"尸体解剖时血管中常见到的固体质块是","o":["透明血栓","白色血栓","红色血栓","混合血栓","血凝块"],"a":4,"e":"尸检时血管内所见固体质块为死后血液凝固形成的血凝块，新鲜时湿润有弹性，与血管壁无粘连。红色血栓经一定时间后变干燥、无弹性、质脆易碎，与血凝块不同。"},{"q":"急性胰腺炎时，下列哪项不可能出现","o":["胰腺坏死病变呈间隔性小叶周围分布，坏死灶外周有炎性细胞包绕","常见淋巴管炎、静脉炎、血栓形成","血清中碱性磷酸酶活性增高","部分病人可有心包积液、化学性腹水和胸腔积液","血清及尿中淀粉酶和脂酶含量增高"],"a":2,"e":"急性胰腺炎时血清及尿淀粉酶、脂酶升高，可伴化学性腹水、胸腔积液及心包积液。碱性磷酸酶活性增高见于骨软化症等骨病变，并非急性胰腺炎的表现。"},{"q":"革囊胃的形成是指","o":["范围较大的溃疡型胃癌","胃溃疡广泛瘢痕形成","胃癌癌细胞弥漫浸润胃壁","胃癌伴胃囊性扩张","胃黏液腺癌大量黏液潴留"],"a":2,"e":"弥漫浸润型胃癌的癌组织向胃壁内弥漫浸润，致胃壁普遍增厚、变硬，胃腔缩小，状如皮革，称革囊胃。"},{"q":"由肥大细胞释放的炎症介质有","o":["溶菌酶","血管活性胺","激肽","补体","缓激肽"],"a":1,"e":"血管活性胺包括组胺和5-羟色胺，储存于肥大细胞等细胞的分泌颗粒中，急性炎症时最先释放。"},{"q":"关于慢性支气管炎的说法，下列哪项是错误的","o":["40岁以上男性多见","可伴喘息症状","常见反复咳嗽、咳痰","可进展为肺心病","常伴发作性呼气性呼吸困难"],"a":4,"e":"发作性呼气性呼吸困难伴哮鸣音是支气管哮喘的表现；慢性支气管炎以长期反复咳嗽、咳痰为特征，可伴喘息，晚期并发肺气肿和肺心病。"},{"q":"良性肿瘤的异型性主要表现在","o":["瘤细胞的多形性","细胞核的多形性","组织结构的异型性","病理性核分裂","细胞异型性"],"a":2,"e":"良性肿瘤细胞异型性不明显，其异型性主要表现在组织结构的异型性，即组织排列方式与正常组织的差异；细胞多形性和病理性核分裂见于恶性肿瘤。"},{"q":"下列哪一种细胞器对缺氧最敏感","o":["线粒体","溶酶体","滑面内质网","高尔基体","粗面内质网"],"a":0,"e":"线粒体是有氧氧化的场所，缺氧时最先出现肿胀、嵴断裂、空泡化和钙沉积，ATP生成锐减，其损伤是细胞不可逆性损伤的早期标志。"},{"q":"引起急性感染性心内膜炎的常见病原体是","o":["草绿色链球菌","金黄色葡萄球菌","痢疾杆菌","柯萨奇B组病毒","朊病毒"],"a":1,"e":"急性感染性心内膜炎以金黄色葡萄球菌最多见，赘生物大而松软、易脱落形成含菌栓子；亚急性者以甲型溶血性链球菌最常见。"},{"q":"二尖瓣狭窄可继发以下改变，但除外哪项","o":["肺褐色硬化","槟榔肝及脾大","三尖瓣相对关闭不全","左心房附壁血栓形成","主动脉关闭不全"],"a":4,"e":"二尖瓣狭窄使左心房压升高、肺淤血，可致肺褐色硬化和左心房附壁血栓；继发右心衰竭后出现槟榔肝、脾大和三尖瓣相对关闭不全。"},{"q":"系统性红斑狼疮患者心脏典型病变为","o":["心瓣膜非细菌性疣状赘生物","心外膜纤维素性炎","心瓣膜闭锁缘菜花样赘生物","MeCallum斑","心瓣膜钙化"],"a":0,"e":"系统性红斑狼疮心脏受累以心包炎最常见，最典型的是心瓣膜非细菌性疣赘性心内膜炎，赘生物小、附着于瓣膜闭锁缘。"},{"q":"Krukenberg瘤是指","o":["胃黏液癌种植转移至膀胱上","肺癌种植转移至胸膜上","胃黏液癌种植转移至腹膜上","胃黏液癌种植转移至肠壁上","胃黏液癌种植转移至卵巢上"],"a":4,"e":"Krukenberg瘤指胃肠道黏液癌尤其胃印戒细胞癌种植转移至卵巢形成的转移性黏液腺癌，多为双侧卵巢肿大，镜下见富于黏液的印戒细胞弥漫浸润。"},{"q":"下列不属于肉芽肿性炎的是","o":["风湿病","伤寒","肺硅沉着病","乙型脑炎","麻风"],"a":3,"e":"乙型脑炎是病毒引起的脑实质变质性炎，以神经细胞变性坏死为主，不形成肉芽肿；风湿病、伤寒、硅沉着病和麻风均属肉芽肿性炎。"},{"q":"与慢性胃炎发病有关的细菌是","o":["大肠杆菌","葡萄球菌","链球菌","幽门螺杆菌","白假丝酵母菌"],"a":3,"e":"幽门螺杆菌定植于胃黏膜表面和胃小凹内，通过尿素酶、空泡毒素等损伤黏膜屏障并诱发炎症，是慢性胃炎最主要的病因，也与消化性溃疡和胃癌相关。"},{"q":"组织固定后脱水的顺序依次是","o":["70%乙醇，80%乙醇，95%乙醇，100%乙醇","70%乙醇，95%乙醇，80%乙醇，100%乙醇","100%乙醇，95%乙醇，80%乙醇，70%乙醇","95%乙醇，100%乙醇，70%乙醇，80%乙醇","80%乙醇，100%乙醇，70%乙醇，95%乙醇"],"a":0,"e":"组织固定后乙醇脱水须由低浓度向高浓度逐级进行，依次为70%、80%、95%、100%乙醇，以免组织骤然收缩变形。"},{"q":"毛细血管再生时在蛋白分解酶作用下基底膜分解，首先出现的变化是","o":["内皮细胞分裂增生形成幼芽","内皮细胞分泌层粘连蛋白","内皮细胞分泌Ⅳ型胶原","成纤维细胞分泌Ⅲ型胶原","出现毛细血管管腔"],"a":0,"e":"毛细血管再生时，基底膜在蛋白分解酶作用下分解后，内皮细胞分裂增生形成突起的幼芽，随后向前移动并形成管腔。管腔出现是较晚的变化。"},{"q":"与坏死后肝硬化相比，下列哪项是门脉性肝硬化常见的特点","o":["肝功能障碍","上消化道大出血","合并胆管上皮癌","合并肝细胞肝癌","结节大小相仿"],"a":4,"e":"门脉性肝硬化属小结节型，结节大小相仿、直径多小于3mm、纤维间隔较细；坏死后性肝硬化结节大小悬殊、间隔宽大，易合并肝细胞癌。"},{"q":"肝硬化患者出现颈部蜘蛛状血管痣，考虑肝脏对（ ）灭活作用减弱所致","o":["雌激素","雄激素","生长激素","甲状腺激素","甲状旁腺激素"],"a":0,"e":"肝硬化时肝细胞对雌激素的灭活减弱，血中雌激素水平升高，使小动脉末梢扩张形成蜘蛛痣和肝掌。"},{"q":"肺静脉血栓脱落致脑动脉阻塞的现象称为","o":["血栓再通","血栓机化","血栓软化","血栓钙化","血栓栓塞"],"a":4,"e":"血栓或血栓的一部分脱落成为栓子，随血流运行阻塞远端血管，称血栓栓塞，占全部栓塞的99%以上。"},{"q":"最常见的鼻咽癌组织学类型是","o":["去分化癌","泡状核细胞癌","腺癌","高分化鳞癌","低分化鳞癌"],"a":4,"e":"鼻咽癌以低分化鳞癌（非角化型）最常见，与EB病毒感染关系密切；高分化鳞癌癌巢内可见细胞间桥和角化珠。"},{"q":"急性、慢性（急性变）粒细胞白血病时，在骨内、骨膜下或其他器官内，可由白血细胞形成瘤结，瘤组织在新鲜时，外观呈某种颜色，可称为","o":["白色瘤","黄色瘤","绿色瘤","转移瘤","棕色瘤"],"a":2,"e":"粒细胞白血病时白血病细胞在骨内、骨膜下或其他器官形成瘤结，瘤组织含原卟啉或绿色过氧化物酶，新鲜时呈绿色，称绿色瘤。暴露日光后绿色消退，还原剂可使其重现。"},{"q":"引起心肌炎最常见的病毒是","o":["柯萨奇病毒","埃可病毒","腺病毒","风疹病毒","巨细胞病毒"],"a":0,"e":"病毒性心肌炎最常见的病原体是柯萨奇B组病毒，其次为柯萨奇A组病毒、埃可病毒和腺病毒。"},{"q":"绒毛心是指","o":["心外膜的纤维素性炎","心外膜的纤维素性化脓性炎","心外膜的化脓性炎","心外膜的浆液性炎","心外膜的纤维性增生的结果"],"a":0,"e":"绒毛心是风湿性心外膜炎时心外膜脏层纤维蛋白性渗出，渗出的纤维蛋白随心脏搏动牵拉呈绒毛状，属纤维素性炎。"},{"q":"可能发生恶变的是","o":["蓝痣","混合痣","表皮疣状痣","皮内痣","交界痣"],"a":4,"e":"交界痣的痣细胞位于表皮与真皮交界处，易受刺激而发生恶变，形成恶性黑色素瘤。皮内痣、混合痣恶变少见。"},{"q":"下列哪种细胞不是通过变形运动离开血管的","o":["中性粒细胞","红细胞","嗜酸性粒细胞","淋巴细胞","巨噬细胞"],"a":1,"e":"红细胞无运动能力，只随血流被动漏出或在血管壁损伤处溢出；中性粒细胞、嗜酸性粒细胞、淋巴细胞和巨噬细胞均以阿米巴样变形运动游出血管。"},{"q":"属于阻塞型先天性心脏病的是","o":["房间隔缺损","室间隔缺损","动脉导管开放","法洛四联症","主动脉缩窄"],"a":4,"e":"先天性心脏病按血流动力学分为非发绀型（房缺、室缺、动脉导管未闭）、发绀型（法洛四联症、大动脉转位）和阻塞型（主动脉缩窄），主动脉缩窄为主动脉局限性狭窄。"},{"q":"在触发凝血过程中起核心作用的是","o":["血小板的活化","胶原","凝血因子Ⅻ","纤维连接蛋白","凝血酶敏感蛋白"],"a":0,"e":"血管内膜损伤暴露胶原后，血小板黏附、活化和聚集，为凝血因子提供磷脂表面并释放颗粒内容物，在启动和放大凝血过程中起核心作用。"},{"q":"恶性高血压病病变特点是","o":["细动脉壁发生纤维素样坏死","细动脉壁发生炎症性改变","细动脉壁发生黏液变性","细动脉壁发生玻璃样变","细动脉壁发生痉挛"],"a":0,"e":"恶性高血压的基本病变是细小动脉壁发生纤维素样坏死，可并发血栓形成和微动脉瘤，主要累及肾、脑和视网膜。细动脉玻璃样变是良性高血压的特征。"},{"q":"软组织透明细胞肉瘤的起源是","o":["滑膜","神经外胚叶","纤维组织","平滑肌","上皮组织"],"a":1,"e":"软组织透明细胞肉瘤起源于神经外胚叶即神经嵴，瘤细胞胞质透亮，常伴t(12;22)EWSR1-ATF1融合基因，属高度恶性软组织肉瘤。"},{"q":"胰腺癌患者最常见的基因异常是","o":["c-erbB-2基因扩增","p53基因突变","c-myc基因转位","K-ras基因突变","c-kit基因突变"],"a":3,"e":"胰腺癌K-ras基因突变率高达90%左右，主要位于第12密码子，是胰腺癌最常见的基因异常。"},{"q":"关于甲状腺乳头状癌错误的说法是","o":["乳头状癌BRAF基因可以不突变","直径小于1cm的乳头状癌称为微小乳头状癌","恶性程度较低，但局部淋巴结转移较早","甲状腺乳头状癌细胞常呈磨玻璃样，有核沟及核内包涵体","甲状腺乳头状癌的乳头一般没有纤维血管间质"],"a":4,"e":"甲状腺乳头状癌的乳头分支复杂，乳头中心有纤维血管间质，间质内可见砂粒体；癌细胞核呈毛玻璃样，有核沟和核内包涵体，局部淋巴结转移早而恶性度低。"},{"q":"阑尾炎的基本病变是属于","o":["肉芽肿性炎","急性增生性炎","蜂窝织炎","纤维素性炎","变质性炎"],"a":2,"e":"阑尾炎的基本病变是阑尾壁的化脓性炎，炎症沿疏松结缔组织弥漫扩散，与周围组织界限不清，属蜂窝织炎，多由溶血性链球菌等引起。"},{"q":"肺转移性肝癌是指","o":["肝癌和肺癌互相转移","肝癌转移到肺","肝和肺同时发生转移性癌","肺癌转移到肝","肝癌和肺癌同期转移到其他地方"],"a":1,"e":"肺转移性肝癌指原发于肝的癌细胞经肝静脉、下腔静脉入右心，随肺动脉血流在肺内形成转移瘤；转移瘤按原发部位命名，故称肝癌肺转移。"},{"q":"左心房血栓脱落不会引起","o":["脑梗死","肺梗死","肾梗死","脾梗死","下肢梗死"],"a":1,"e":"左心房血栓脱落后随体循环动脉栓塞，可阻塞脑、肾、脾及下肢动脉引起相应梗死。肺动脉栓塞多源于体静脉或右心血栓，左心来源的栓子经动脉系统不会进入肺循环。"},{"q":"下列哪种癌较早经淋巴道转移","o":["甲状腺乳头状腺癌","食管鳞状细胞癌","子宫颈鳞状细胞癌","鼻咽低分化鳞状细胞癌","胃黏液腺癌"],"a":3,"e":"鼻咽低分化鳞状细胞癌恶性程度高，早期即可经淋巴道转移至颈部淋巴结。甲状腺乳头状腺癌、食管及子宫颈鳞癌淋巴道转移相对较晚。"},{"q":"胃溃疡镜下变化由内向外分别是","o":["炎性渗出、坏死、肉芽、瘢痕","坏死、炎性渗出、肉芽、瘢痕","瘢痕、肉芽、炎性渗出、坏死","瘢痕、肉芽、坏死、炎性渗出","坏死、肉芽、炎性渗出、瘢痕"],"a":0,"e":"胃溃疡底部由内向外依次为炎性渗出层、坏死组织层、肉芽组织层和瘢痕层。瘢痕层小动脉常有增殖性动脉内膜炎，影响愈合。"},{"q":"急性感染性心内膜炎中瓣膜赘生物中，不具有的成分是","o":["大量细菌","大量肉芽组织","大量中性粒细胞","坏死组织","大量血小板和纤维蛋白"],"a":1,"e":"急性感染性心内膜炎的赘生物由大量细菌、血小板与纤维蛋白、坏死组织及大量中性粒细胞构成，松脆易脱落。肉芽组织见于炎症修复期，不属急性期赘生物成分。"},{"q":"乳腺小叶原位癌的特点是","o":["癌细胞局限于小叶腺泡内","癌细胞局限于导管内","癌细胞丰富、间质少","纤维间质丰富，癌细胞少","癌细胞与间质大致相等"],"a":0,"e":"小叶原位癌的癌细胞充满膨胀的小叶末梢导管和腺泡，呈实体排列，小叶结构尚存，未突破基底膜；癌细胞局限于扩张导管内者为导管原位癌。"},{"q":"淋病属于","o":["化脓性炎症","假膜性炎","浆液性炎症","变质性炎症","肉芽肿性炎症"],"a":0,"e":"淋病由淋病奈瑟菌引起，为泌尿生殖道黏膜的急性化脓性炎症，大量中性粒细胞渗出并伴组织坏死。假膜性炎见于白喉和细菌性痢疾。"},{"q":"下列与肝硬化形成最为密切的是","o":["急性重型肝炎","轻度慢性肝炎","重度慢性肝炎","急性普通型肝炎","急性甲型肝炎"],"a":2,"e":"慢性肝炎时肝细胞反复变性坏死并伴纤维化，中重度者坏死重、纤维间隔形成，最易发展为肝硬化；急性肝炎病程短，一般不引起肝硬化。"},{"q":"系统性红斑狼疮患者皮肤损害具有病理学诊断意义的是","o":["表皮萎缩、角化过度","基底细胞液化","狼疮带","表皮真皮交界处水肿","血管周围淋巴细胞浸润"],"a":2,"e":"免疫荧光显示真皮与表皮交界处有IgG、IgM及补体C3呈颗粒或团块状沉积，形成狼疮带，对系统性红斑狼疮有诊断意义。"},{"q":"关于慢性支气管炎的描述错误的是","o":["黏膜腺体增生、肥大","支气管壁平滑肌断裂、萎缩","黏膜上皮可出现鳞状化生","典型临床表现为伴有哮鸣音的呼气性呼吸困难","支气管壁充血水肿，淋巴细胞、浆细胞浸润"],"a":3,"e":"伴哮鸣音的呼气性呼吸困难是支气管哮喘的典型表现，而非慢性支气管炎；后者以长期咳嗽、咳痰为主，病理见腺体增生肥大、平滑肌断裂萎缩和上皮鳞状化生。"},{"q":"下列疾病不可能发生纤维结缔组织玻璃样变的是","o":["结核性纤维素性胸膜炎","硅肺","慢性浅表性胃炎","肝硬化","心肌梗死"],"a":2,"e":"纤维结缔组织玻璃样变见于纤维组织增生老化的病灶，如结核性纤维素性胸膜炎、硅肺、肝硬化和心肌梗死瘢痕；慢性浅表性胃炎仅有黏膜炎症，无明显纤维组织增生。"},{"q":"急性炎症组织中最多的细胞浸润是","o":["浆细胞","淋巴细胞","嗜酸性粒细胞","中性粒细胞","巨噬细胞"],"a":3,"e":"急性炎症早期24小时内以中性粒细胞浸润为主，其趋化性强、吞噬活跃；24~48小时后单核巨噬细胞逐渐成为主要浸润细胞。"},{"q":"风湿病变累及全身结缔组织，其中最严重的器官是","o":["脑","血管","心脏","皮肤","关节"],"a":2,"e":"风湿病累及全身结缔组织，以心脏、关节和血管受累最常见，其中以心脏病变最为严重，可致瓣膜变形和心功能不全。"},{"q":"有关前列腺癌，下列说法错误的是","o":["90%以上是腺癌","PSA染色多为阴性","很少侵犯直肠","最常见的转移部位是骨","好发于50岁以上的老年人"],"a":1,"e":"PSA是前列腺上皮特异性标志物，前列腺癌免疫组化PSA染色多呈阳性，有助于确定肿瘤起源于前列腺。"},{"q":"下列哪一项是恶性肿瘤独有的特征","o":["局部肿块","恶病质","出血坏死","浸润性生长","转移"],"a":4,"e":"转移是恶性肿瘤独有的特征，指瘤细胞脱离原发灶，经淋巴道、血道或种植途径在远隔部位形成继发肿瘤。局部肿块、出血坏死和浸润性生长也可见于良性肿瘤或炎症。"},{"q":"下列对阑尾炎的描述哪一项是错误的","o":["临床主要表现为转移性右下腹疼痛","根据病程常分为急性和慢性","细菌和病毒是阑尾炎发病的主要因素","大部分阑尾炎伴有阑尾腔阻塞","常见并发症是阑尾周围脓肿和急性弥漫性腹膜炎"],"a":2,"e":"阑尾炎发病的两个主要因素是细菌感染和阑尾腔阻塞，无特定病原菌，病毒不是致病因素。临床以转移性右下腹痛为特点，并发症为穿孔所致腹膜炎和阑尾周围脓肿。"},{"q":"透明血栓多发生在","o":["毛细血管","动脉系统","静脉系统","心房","心室"],"a":0,"e":"透明血栓由嗜酸性同质性纤维蛋白构成，发生于微循环的毛细血管内，仅在显微镜下可见，故又称微血栓，最常见于DIC。"},{"q":"关于慢性胃溃疡，下列哪项是错误的","o":["溃疡多位于胃大弯近幽门侧","溃疡边缘整齐不隆起","溃疡一般较深","溃疡直径多在2cm以内","溃疡周围黏膜皱襞呈放射状"],"a":0,"e":"胃溃疡多位于胃小弯侧，愈近幽门愈多见，尤多见于胃窦部，大弯侧少见；边缘整齐、较深、直径多在2cm以内及周围黏膜皱襞放射状集中，均为良性溃疡的特点。"},{"q":"为提高阳性率，胸腹腔积液标本离心后取哪一层细胞涂片最好","o":["试管上层","红细胞层","交界层","红细胞之上的白膜层","底层"],"a":3,"e":"离心后积液中的细胞沉于管底，红细胞之上的白膜层富含有核细胞，涂片阳性率最高，故取该层细胞制片。"},{"q":"IgA肾病的最显著特点是","o":["血清IgA水平增高","复发性血尿","弥漫性系膜增多","系膜区IgA沉积","血清C3下降"],"a":3,"e":"IgA肾病的特点是免疫荧光显示系膜区有IgA颗粒状沉积，临床表现为反复发作的镜下或肉眼血尿；血清IgA水平可正常。"},{"q":"关于风湿病，下列哪一项是错误的","o":["与A组乙型溶血性链球菌感染有关","是一种结缔组织病","以形成风湿小体为病变特征","风湿性关节炎常可导致关节畸形","皮下结节和环形红斑对临床诊断风湿病有帮助"],"a":3,"e":"风湿性关节炎为浆液性炎，呈游走性、多发性，累及大关节，渗出物易吸收，不遗留关节畸形。导致关节畸形的是类风湿关节炎的血管翳和软骨破坏。"},{"q":"下列不属于坏死后性肝硬化的病变特点的是","o":["假小叶大小不等","纤维间隔较宽","炎细胞浸润明显","假小叶大小相仿","碎片状坏死"],"a":3,"e":"坏死后性肝硬化由大片状肝坏死引起，纤维间隔宽、炎细胞浸润明显，假小叶大小不等；假小叶大小相仿是小结节型即门脉性肝硬化的特点。"},{"q":"组织切片最常用的染色方法是","o":["苏丹Ⅲ染色","苏木素伊红染色","Masson三色染色","PAS染色","嗜银染色"],"a":1,"e":"苏木素-伊红染色是组织切片最常用的染色方法，能清晰显示组织结构和细胞形态，是病理诊断的基础。PAS、Masson三色及嗜银染色属特殊染色，仅在必要时辅助使用。"},{"q":"关于肺出血肾炎综合征的叙述，错误的是","o":["属于快速进行性肾炎1型","抗GBM的抗体与肺泡基底膜发生交叉反应，引起反复咯血","病理特征是肾小球内新月体形成","常继发于链球菌感染或系统性红斑狼疮","肾小球内IgG和C3沿毛细血管袢呈线状沉积"],"a":3,"e":"肺出血肾炎综合征属急进性肾炎Ⅰ型，抗GBM抗体与肺泡基膜交叉反应引起肺出血，免疫荧光呈线状，新月体形成为其病理特征；继发于链球菌感染或狼疮者为Ⅱ型。"},{"q":"脑膜瘤最好发于","o":["颅后凹","蝶骨嵴的侧面","窦汇周围","上矢状窦两侧","小脑脑桥角"],"a":3,"e":"脑膜瘤起源于蛛网膜帽状细胞，好发于上矢状窦两侧及大脑凸面、大脑镰旁，与该处蛛网膜颗粒分布一致，多为单发，女性多见。"},{"q":"符合腺泡中央型肺气肿的病变特点是","o":["细支气管和肺泡弥漫性扩张","呼吸性细支气管扩张","肺泡管和肺囊泡扩张","呼吸细支气管和肺囊泡扩张","呼吸细支气管和肺泡管扩张"],"a":1,"e":"腺泡中央型肺气肿最常见，病变位于腺泡中央的呼吸性细支气管，呈囊状扩张，而肺泡管和肺泡囊扩张不明显。"},{"q":"早期食管癌是指","o":["未发生转移的癌","局限于上皮层内的癌","局限于黏膜或黏膜下层，不论是否发生淋巴结转移","病变长度小于3cm，未发生淋巴结转移","局限于黏膜层，不论是否发生淋巴结转移"],"a":2,"e":"早期食管癌指癌组织局限于黏膜层或黏膜下层、未侵犯肌层，无论有无淋巴结转移，多为原位癌或黏膜内癌，临床无明显症状。"},{"q":"医院内肺炎常见的病原体是","o":["厌氧菌多见","支原体多见","革兰阴性杆菌多见","真菌多见","病毒多见"],"a":2,"e":"医院内肺炎多由革兰阴性杆菌引起，以铜绿假单胞菌、肺炎克雷伯菌和大肠埃希菌多见，与住院期间菌群定植及器械操作有关。"},{"q":"并发肺肉质变最主要的原因是","o":["含铁血黄素沉积","细菌毒力过强","单核细胞浸润过多","中性粒细胞渗出过少","纤维蛋白渗出过多"],"a":3,"e":"肺肉质变因肺泡内中性粒细胞渗出过少，释放的蛋白酶不足以溶解纤维蛋白，未被清除的纤维蛋白由肉芽组织取代而机化，使病变肺组织呈肉样外观。"},{"q":"下列哪种损伤不能发生完全再生","o":["骨折","肝细胞坏死但网状支架未塌陷","腺体及基膜都受损","腺体仅有腺上皮受损","子宫内膜脱落"],"a":2,"e":"腺体仅有腺上皮受损而基膜完整时可完全再生；若腺体与基膜均遭破坏，腺管不能重新形成，只能由肉芽组织机化形成瘢痕。"},{"q":"下列哪种疾病可导致心肌间质中出现大量淋巴单核细胞浸润","o":["风湿性心肌炎","病毒性心肌炎","心肌病","心肌梗死","细菌性心肌炎"],"a":1,"e":"病毒性心肌炎由嗜心肌病毒感染引起，表现为心肌间质弥漫性淋巴细胞和单核细胞浸润，伴心肌细胞变性坏死，属非特异性间质性炎症。"},{"q":"属于发绀型先天性心脏病的是","o":["房间隔缺损","室间隔缺损","动脉导管开放","法洛四联症","主动脉缩窄"],"a":3,"e":"法洛四联症由肺动脉狭窄、室间隔缺损、主动脉骑跨和右心室肥厚构成，属发绀型先天性心脏病；房间隔缺损、室间隔缺损和动脉导管未闭为非发绀型。"},{"q":"急性肺淤血时最典型的症状是","o":["心悸","胸闷","呼吸困难","粉红色泡沫痰","铁锈色痰"],"a":3,"e":"急性肺淤血伴严重肺水肿时，血浆与红细胞漏入肺泡，与气体混合形成大量粉红色泡沫痰，同时伴气促、发绀和濒死感。"},{"q":"慢性炎症病灶内浸润的炎细胞主要是","o":["中性粒细胞和单核细胞","单核细胞和淋巴细胞","浆细胞和嗜碱性粒细胞","淋巴细胞和嗜酸性粒细胞","嗜酸性粒细胞和嗜碱性粒细胞"],"a":1,"e":"慢性炎症灶内浸润的炎细胞主要为单核细胞、淋巴细胞和浆细胞，中性粒细胞多见于急性炎症和化脓性炎。"},{"q":"引起急性胰腺炎的原因，不包括","o":["营养不良","暴饮暴食","大量饮酒","胆石症","胆道蛔虫"],"a":0,"e":"急性胰腺炎多由胆道疾病如胆石症、胆道蛔虫以及大量饮酒、暴饮暴食诱发，胰液排出受阻或胰酶过早激活致胰腺自身消化。"},{"q":"动脉粥样硬化早期，哪种细胞最早迁入动脉内膜","o":["嗜酸性粒细胞","淋巴细胞","中性粒细胞","单核细胞","成纤维细胞"],"a":3,"e":"内皮损伤后，损伤内皮细胞分泌细胞因子吸引单核细胞黏附并迁入内皮下间隙，摄取氧化脂质形成泡沫细胞，故单核细胞最早迁入内膜。"},{"q":"早期发现胃癌最可靠的方法是","o":["X线钡餐检查","超声检查","胃液特异酶检测","胃液脱落细胞学检查","纤维胃镜活组织检查"],"a":4,"e":"纤维胃镜可直视胃黏膜病变并钳取活组织行病理检查，确定癌的组织学类型和浸润范围，是早期发现和确诊胃癌最可靠的方法。"},{"q":"在溃疡愈合期，填补溃疡的是","o":["肌细胞和结缔组织","淋巴细胞和淋巴组织","上皮细胞和肉芽组织","成纤维细胞和肌组织","不稳定细胞和组织"],"a":2,"e":"溃疡愈合时底部肉芽组织增生填补缺损，边缘黏膜上皮再生并覆盖表面，最终形成瘢痕，故由上皮细胞和肉芽组织共同完成修复。"},{"q":"下列能反映小叶性肺炎的本质的是","o":["支气管及肺泡的化脓性炎症","支气管及肺泡的纤维素性炎症","支气管及肺泡的卡他性炎症","支气管及肺泡的出血性炎症","支气管及肺泡结构的破坏"],"a":0,"e":"小叶性肺炎由化脓菌引起，病变以细支气管为中心并累及周围肺泡，本质是细支气管及其周围肺泡的化脓性炎症。"},{"q":"胃癌最主要的转移途径是","o":["直接扩散","淋巴道转移","血行转移","腹腔内种植","盆腔内种植"],"a":1,"e":"胃癌主要经淋巴道转移，首先转移至幽门下胃小弯局部淋巴结，再至腹主动脉旁、肝门或肠系膜根部淋巴结。"},{"q":"细小动脉壁玻璃样变最常发生于","o":["心、脾、肺、视网膜等处的细动脉","肾、脑、脾、视网膜等处的细动脉","心、肝、肾、脑等处的细动脉","肺、胰、脾、肠等处的细动脉","肺、脑、脾、视网膜等处的细动脉"],"a":1,"e":"细小动脉壁玻璃样变常见于缓进型高血压和糖尿病，最易累及肾入球动脉、脑和脾的细小动脉以及视网膜动脉。"},{"q":"化脓菌入血、生长繁殖、产生毒素、形成多发性脓肿，最合适的病名是","o":["脓毒败血症","毒血症","败血症","菌血症","噬血症"],"a":0,"e":"化脓菌入血后大量繁殖并产生毒素，同时在全身多个脏器形成多发性栓塞性脓肿，称脓毒败血症。败血症无多发性脓肿，毒血症仅有毒素入血。"},{"q":"慢性肾盂肾炎与慢性硬化性肾小球肾炎的肉眼区别主要是","o":["体积缩小","质地变硬","肾内小动脉硬化","颜色苍白","表面有不规则的凹陷性瘢痕"],"a":4,"e":"慢性肾盂肾炎的瘢痕宽大而不规则，多位于肾两极并伴肾盂肾盏变形，切面呈皮髓质界限不清；慢性硬化性肾小球肾炎则为弥漫均匀的细颗粒。"},{"q":"关于流行性乙型脑炎的叙述，下列哪项是正确的","o":["乙脑病毒属于DNA病毒","有较多的中性粒细胞围血管浸润","镂空筛状软化灶形成具有一定的诊断意义","小胶质细胞越多，预后越好","出现脑膜刺激征基本上可排除脑炎"],"a":2,"e":"乙脑病毒为RNA病毒，病变以神经细胞变性坏死、胶质细胞增生和血管周围淋巴细胞套为特点，灶性液化性坏死形成镂空筛网状软化灶，具诊断意义。"},{"q":"膜增生性肾小球肾炎可伴有下列哪种表现","o":["明显血尿","脂滴沉积","红细胞增多症","IgA沉积","低补体血症"],"a":4,"e":"膜增生性肾小球肾炎由循环免疫复合物沉积并激活补体，Ⅱ型常经替代途径持续激活补体，血清C3明显降低而C1、C4正常，故多伴低补体血症。"},{"q":"患者，男，58岁，进行性声嘶2个月，伴吞咽困难，临床检查示喉部新生物。活检镜下如图，正确的诊断是","o":["喉乳头状瘤","喉恶性淋巴瘤侵及固有腺体","喉低分化鳞状细胞癌侵及固有腺体","喉腺癌","喉高分化鳞状细胞癌侵及固有腺体"],"a":2,"e":"官方题库缺失图片"},{"q":"下列哪种出血不属于破裂性出血","o":["慢性纤维空洞型肺结核大咯血","肝硬化食管-胃底静脉曲张大呕血","十二指肠溃疡柏油样便","胃癌呕血","肺淤血性出血"],"a":4,"e":"破裂性出血由心脏或血管壁破裂引起，见于空洞型肺结核咯血、食管胃底静脉曲张破裂、消化性溃疡和胃癌出血。肺淤血性出血属漏出性出血，因毛细血管通透性增高致红细胞漏出。"},{"q":"下列哪种最支持恶性肿瘤的形态","o":["肿瘤与周围组织分界不清","囊性变","出血、坏死","病理性核分裂","质硬"],"a":3,"e":"病理性核分裂象如不对称核分裂、多极核分裂只见于恶性肿瘤，是细胞异型性的可靠标志；分界不清、出血坏死、质硬也可见于良性病变。"},{"q":"伤寒小结的组成主要是","o":["伤寒细胞、中性粒细胞","多核巨细胞、上皮样细胞","上皮样细胞、淋巴细胞","巨噬细胞、伤寒细胞","淋巴细胞、浆细胞"],"a":3,"e":"伤寒小结由吞噬伤寒沙门菌、红细胞和细胞碎片的巨噬细胞即伤寒细胞聚集而成，属伤寒肉芽肿，对诊断有重要价值，其中不含中性粒细胞。"},{"q":"有Ph1染色体标志的主要是","o":["急性粒细胞白血病","慢性粒细胞白血病","慢性淋巴细胞白血病","急性淋巴细胞白血病","急性单核细胞白血病"],"a":1,"e":"Ph染色体即t(9;22)易位形成的BCR::ABL1融合基因，是慢性粒细胞白血病标志性的细胞遗传学改变。"},{"q":"慢性硬化性肾小球肾炎的晚期发生高血压的最主要原因是","o":["肾小球滤过率减少","少尿","肾小管重吸收增加","肾素分泌增加","高脂血症"],"a":3,"e":"慢性硬化性肾小球肾炎晚期肾组织缺血、肾素分泌增加，激活肾素-血管紧张素系统使血压持续升高；水钠潴留也参与，但不是最主要原因。"},{"q":"革囊胃是指","o":["胃癌伴胃扩张","胃黏液癌","胃癌弥漫浸润型","胃溃疡广泛瘢痕形成","范围较大的溃疡型胃癌"],"a":2,"e":"胃癌弥漫浸润型时癌组织在胃壁内广泛浸润并伴纤维组织增生，胃壁增厚变硬、胃腔缩小，状如皮革，称革囊胃。"},{"q":"下列关于蜂窝织炎的叙述，正确的是","o":["常由草绿色链球菌感染引起","常见部位是内脏器官、肌肉和阑尾","病变特点与链球菌分泌的链激酶和透明质酸酶有关","细菌不容易经组织间隙、淋巴管和血道蔓延扩散","常有明显的组织坏死和脓肿形成"],"a":2,"e":"蜂窝织炎主要由溶血性链球菌引起，其透明质酸酶降解结缔组织基质、链激酶溶解纤维蛋白，故炎症沿组织间隙和淋巴管弥漫扩散，与周围界限不清。"},{"q":"如图，心肌梗死后很少出现下列哪种改变","o":["梗死灶呈地图形","梗死灶心肌细胞再生","贫血性梗死","梗死灶周围充血出血带","继发附壁血栓形成"],"a":1,"e":"官方题库缺失图片"},{"q":"同时累及脑膜、肾、肺、肠及骨的肉芽肿性病变常常是","o":["风湿小体","伤寒小体","麻风小结","矽结节","结核结节"],"a":4,"e":"结核结节是结核病的特征性肉芽肿，可发生于脑膜、肾、肺、肠及骨等多处，由上皮样细胞、朗汉斯巨细胞及外周淋巴细胞构成，中央常伴干酪样坏死。"},{"q":"左心室附壁血栓可引起","o":["心力衰竭","肺淤血","脑动脉栓塞","肺动脉栓塞","心壁穿孔"],"a":2,"e":"左心室附壁血栓脱落后栓子进入体循环，可栓塞脑动脉引起脑梗死，也可至下肢、肾、脾和肠。肺动脉栓塞的栓子来自右心和静脉系统。"},{"q":"风湿性心内膜炎，心瓣膜上的赘生物为","o":["透明血栓","白色血栓","红色血栓","混合血栓","微血栓"],"a":1,"e":"风湿性心内膜炎的赘生物为白色血栓，由血小板和纤维蛋白构成，多位于二尖瓣闭锁缘呈单行排列，与瓣膜紧密粘连而不易脱落。"},{"q":"下列哪项最能体现原位癌的特征","o":["发生于子宫颈黏膜上皮","是一种早期癌","癌变波及全层，但未突破基底膜","未发生转移","可长期保持原来结构，甚至消退"],"a":2,"e":"原位癌指异型增生细胞形态和生物学特性同癌细胞，累及上皮全层但未突破基底膜向下浸润，基底膜完整是其本质特征，属早期癌。"},{"q":"一期愈合的特点不包括","o":["创缘整齐，对合严密","无感染与异物","愈合时间较短","愈合后常遗留下较大瘢痕","肉芽组织第3天即可从伤口边缘长出"],"a":3,"e":"一期愈合见于缺损小、创缘整齐、无感染、对合严密的伤口，愈合时间短，仅留线状瘢痕；较大瘢痕是二期愈合的特点，因缺损大而需大量肉芽组织填充。"},{"q":"下列哪项属于早期食管癌的必要条件","o":["癌变面积小于1.0cm","浸润深度未超过黏膜下层","无明显临床症状","无淋巴结转移","钡餐检查可有局限性僵硬"],"a":1,"e":"早期食管癌指癌组织浸润深度未超过黏膜下层且无淋巴结转移者，与癌变面积大小和有无临床症状无关。"},{"q":"肺硅沉着病的特征性病变是","o":["玻璃样硅结节形成","肺间质纤维化","肺间质纤维化玻璃样变","硅肺性空洞形成","胸膜纤维化"],"a":0,"e":"硅肺的基本病变是硅结节形成和肺组织弥漫性纤维化，典型硅结节由同心圆排列的玻璃样变胶原纤维构成，触之有沙砾感。"},{"q":"肉芽组织转化为瘢痕组织的过程，下列哪项是错误的","o":["毛细血管闭塞、数目减少","胶原纤维增多","成纤维细胞减少","炎细胞增多","间质的水分逐渐吸收减少"],"a":3,"e":"肉芽组织成熟为瘢痕时水分吸收、胶原纤维增多、成纤维细胞和毛细血管减少、炎细胞逐渐消失，故炎细胞增多不成立。"},{"q":"关于肉芽组织的结局，下列叙述正确的是","o":["最终填补缺损","最终纤维化形成瘢痕","抗感染的过程","产生细胞外基质的过程","分泌大量生长因子，调控细胞增生的过程"],"a":1,"e":"肉芽组织逐渐成熟，血管减少、胶原增多、成纤维细胞转变为纤维细胞，最终纤维化形成瘢痕，这是肉芽组织的必然结局。"},{"q":"关于绒毛膜癌的叙述，下列哪项是错误的","o":["可见绒毛","侵袭血管是其生物学特性","引起组织出血、坏死","50%继发于葡萄胎","常浸润子宫肌层"],"a":0,"e":"绒毛膜癌由细胞滋养层和合体滋养层两种瘤细胞组成，肿瘤内无间质和血管，无绒毛结构；有无绒毛是与侵袭性葡萄胎鉴别的关键。"},{"q":"直肠癌最常见的症状是","o":["肠梗阻","体重减轻","贫血","大便习惯改变","黏液血便"],"a":4,"e":"直肠癌最常见的症状是黏液血便，由肿瘤表面坏死溃破、继发感染及黏液分泌增多所致；贫血、消瘦和肠梗阻多见于晚期。"},{"q":"关于鼻咽癌的转移，说法不正确的是","o":["约半数以上患者以颈部淋巴结肿大就诊","主要转移至颈部浅淋巴结","颈部淋巴结转移常为同侧","侵犯颅底骨主要破坏卵圆孔处","可侵犯耳咽管至中耳"],"a":1,"e":"鼻咽癌淋巴道转移主要至颈深上淋巴结而非颈部浅淋巴结，约半数以上患者以颈淋巴结肿大为首发症状且多为同侧，可破坏卵圆孔侵入颅内。"},{"q":"下列哪项不是肝细胞癌镜下表现的主要特点","o":["癌巢间有大量纤维组织分割，状似假小叶","癌细胞呈小梁状排列","癌组织间富于血窦","癌组织呈腺泡样，内可含胆汁","癌细胞与肝细胞较相似"],"a":3,"e":"肝细胞癌细胞多排列成梁索状或团块状，癌巢间血窦丰富，癌细胞与肝细胞相似；腺泡样结构内含胆汁并非其镜下主要特点。"},{"q":"下列哪项属于癌前疾病","o":["阑尾炎","乳腺纤维腺瘤","纤维囊性乳腺病","慢性肥厚性胃炎","韧带样瘤"],"a":2,"e":"纤维囊性乳腺病属乳腺增生性病变，导管及小叶上皮增生伴囊肿形成，有癌变倾向，属癌前疾病。乳腺纤维腺瘤为良性肿瘤，不属癌前疾病。"},{"q":"癌与肉瘤的最主要区别是","o":["瘤细胞的分布方式不同","组织来源不同","肿瘤内血管多少不同","转移的途径不同","发生的年龄不同"],"a":1,"e":"癌来源于上皮组织，肉瘤来源于间叶组织，二者发病率、大体形态和转移途径的差别均由此决定，故组织来源是最主要的区别。"},{"q":"关于结节性甲状腺肿的叙述，下列哪项是错误的","o":["甲状腺滤泡过度扩大，大小差别明显","结节内常有出血、坏死、纤维增生等改变","结节边界清楚，有完整包膜","结节常为多个，大小不等","病变后期滤泡上皮增生与复旧不一致，分布不均"],"a":2,"e":"结节性甲状腺肿为多发结节、大小不等，结节境界可清楚但常无完整包膜；单发、有完整包膜是甲状腺腺瘤的鉴别要点。"},{"q":"诊断肺心病主要诊断标准是","o":["肺动脉下2cm处，右室壁厚大于5mm","肺动脉圆锥膨隆","右心室扩张","心脏增大","心尖钝圆"],"a":0,"e":"肺心病以肺动脉瓣下2cm处右心室前壁肌层厚度超过5mm（正常3～4mm）作为病理形态诊断标准。"},{"q":"下列细胞中来源与巨噬细胞无关的是","o":["泡沫细胞","Aschoff细胞","伤寒细胞","印戒细胞","类上皮细胞"],"a":3,"e":"泡沫细胞、Aschoff细胞、伤寒细胞和类上皮细胞均由巨噬细胞转化而来；印戒细胞是含大量黏液并将核挤向一侧的腺癌细胞，与巨噬细胞无关。"},{"q":"关于胃癌的转移途径的叙述，下列哪项是错误的","o":["癌细胞脱落种植于盆腔器官","血行转移至肝脏","癌细胞脱落种植于十二指肠壁","淋巴道转移至所属局部淋巴结","淋巴道转移至大网膜淋巴结"],"a":2,"e":"胃癌种植性转移是癌细胞穿破浆膜脱落后种植于腹腔及盆腔器官浆膜，如卵巢；十二指肠壁与胃相邻且为腔内结构，不属种植部位。"},{"q":"肝穿刺活检，镜下可见弥漫性肝细胞细胞质疏松化，气球样变，点状坏死及嗜酸性小体形成，汇管区有轻度炎细胞浸润。应诊断为","o":["急性普通型肝炎","慢性中度肝炎","肝硬化","急性重型肝炎","亚急性重型肝炎"],"a":0,"e":"肝细胞弥漫性疏松化、气球样变伴点状坏死和嗜酸性小体，汇管区轻度炎细胞浸润，是急性普通型肝炎的典型改变；大片坏死见于重型肝炎，假小叶形成见于肝硬化。"},{"q":"金黄色葡萄球菌的层粘连蛋白受体能","o":["使病变易于局限","容易形成溃疡","容易形成窦道","容易形成转移性脓肿","使组织容易受损"],"a":3,"e":"金黄色葡萄球菌表面的层粘连蛋白受体使其易于黏附并穿过血管壁，在远隔部位形成迁徙性脓肿。其产生的凝血酶使纤维蛋白原转为纤维蛋白，反使原发灶较为局限。"},{"q":"下列哪种为癌基因","o":["ras基因","P53基因","Rb基因","APC基因","NF-1基因"],"a":0,"e":"ras基因是原癌基因，其激活（如12号密码子点突变）可促进细胞异常增殖而致癌。P53、Rb、APC、NF-1均为肿瘤抑制基因，失活后才参与肿瘤发生。"},{"q":"栓子最确切的定义是","o":["循环血液内的有形成分","循环血液内不溶于血液的异常物质","循环血液内脱落的血栓","循环血液内脱落的肿瘤团块","循环血液内的脂肪滴"],"a":1,"e":"栓塞是循环血液中出现不溶于血液的异常物质随血流运行阻塞血管腔的现象，该异常物质即栓子。栓子可为固体、液体或气体，最常见为脱落的血栓。"},{"q":"下列哪种肿瘤的发生与EB病毒感染密切相关","o":["胃癌","鼻咽癌","膀胱癌","肺癌","胰腺癌"],"a":1,"e":"鼻咽癌的发生与EB病毒感染密切相关，瘤细胞内可检出EB病毒DNA和核抗原，低分化鳞癌与EBV关系尤为密切；EBV还与Burkitt淋巴瘤相关。"},{"q":"对图示炎症细胞描述正确的是","o":["出现在炎症的早期","出现在炎症的晚期","出现在化脓性炎中","出现在脓肿中","出现在假膜性炎"],"a":1,"e":"官方题库缺失图片"},{"q":"按发病率递减的顺序，食管癌最常见的部位依次是","o":["食管上段、中段、下段","食管中段、下段、上段","食管上段、下段、中段","食管中段、上段、下段","各段分布相等"],"a":1,"e":"食管癌好发于三个生理性狭窄部，按发病率递减依次为中段、下段、上段，中段约占半数。"},{"q":"静脉血栓形成时，不易发生的结局是","o":["脱落","机化","血流完全恢复正常","钙化","再通"],"a":2,"e":"静脉血栓形成后经机化、再通、钙化或脱落等途径转归，血流不能完全恢复正常。血栓机化由肉芽组织取代并形成再通通道，管腔难以恢复原有通畅状态。"},{"q":"骨肉瘤是指","o":["骨原发性的恶性肿瘤，有反应性骨质增生","肉瘤细胞直接形成肿瘤性骨样组织或骨组织的肿瘤","骨组织起源的肉瘤","骨组织中肉瘤的总称","骨组织来源的未分化肿瘤"],"a":1,"e":"骨肉瘤的瘤细胞异型性明显，直接形成肿瘤性骨样组织或骨组织，这是诊断最重要的组织学依据。骨膜反应形成的放射状新生骨小梁属反应性骨，不是肿瘤性骨。"},{"q":"早期大肠癌是","o":["局限于黏膜层及黏膜下层的癌","侵及黏膜下层的癌","侵及浅肌层的癌","无淋巴结转移的癌","直径小于2cm的癌"],"a":0,"e":"早期大肠癌指癌组织浸润仅限于黏膜层或黏膜下层，无论有无淋巴结转移；侵及肌层者属进展期癌。"},{"q":"地方性甲状腺肿的主要病因是","o":["遗传因素","机体对碘或甲状腺素需求量增加","长期摄入大量钙","缺碘","吃海产品过多"],"a":3,"e":"地方性甲状腺肿的主要病因是水土和食物中缺碘，甲状腺素合成减少，反馈性TSH分泌增多，滤泡上皮增生、胶质贮积而致甲状腺肿大。"},{"q":"流行性脑脊髓膜炎中，病原菌主要侵犯","o":["大脑皮质","额、顶叶及脑干","硬脑膜","蛛网膜下腔","丘脑及基底神经核"],"a":3,"e":"流行性脑脊髓膜炎的特征性病变是脑脊髓膜的化脓性炎症，病原菌主要侵犯蛛网膜下腔，使蛛网膜下腔充满灰黄色脓性渗出物。脑实质一般受累较轻，硬脑膜非主要侵犯部位。"},{"q":"关于胰腺癌的叙述，错误的是","o":["以胰尾部最多见","患者年龄多在60~80岁","可发生于胰头、体、尾部或累及整个胰腺","男性多于女性","大部分病例有K-ras基因突变"],"a":0,"e":"胰腺癌约60%发生于胰头，体部约15%、尾部约5%，故以胰头最多见而非胰尾。胰头癌主要症状为无痛性黄疸。"},{"q":"在月经周期中子宫内膜腺体和间质明显增生，腺体数目增多，上皮呈高柱状，呈假复层排列，核椭圆形，由底部移向细胞中央，间质中可见有丝分裂，此时月经周期是","o":["增生晚期","分泌早期","增生早期","分泌晚期","月经前期"],"a":0,"e":"增生晚期子宫内膜腺体数目增多、腔大而弯曲，上皮呈高柱状假复层排列，核椭圆形由基底部移向细胞中央，间质细胞有丝分裂活跃。"},{"q":"关于乳腺纤维腺瘤的叙述，错误的是","o":["是最常见的乳腺良性肿瘤","好发于20～30岁的青年女性","多为单侧","恶变率较高","分为管内型和管周型"],"a":3,"e":"乳腺纤维腺瘤是乳腺最常见的良性肿瘤，好发于20～35岁，多单发，分为管内型和管周型，恶变率低。"},{"q":"霍奇金淋巴瘤按预后好坏，排列顺序为","o":["混合细胞型，淋巴细胞减少型，结节硬化型，淋巴细胞为主型","淋巴细胞为主型，结节硬化型，淋巴细胞减少型，混合细胞型","淋巴细胞减少型，混合细胞型，结节硬化型，淋巴细胞为主型","淋巴细胞为主型，结节硬化型，混合细胞型，淋巴细胞减少型","淋巴细胞减少型，淋巴细胞为主型，结节硬化型，混合细胞型"],"a":3,"e":"霍奇金淋巴瘤预后由好至差依次为淋巴细胞为主型、结节硬化型、混合细胞型、淋巴细胞减少型，淋巴细胞越少、异型瘤细胞越多则预后越差。"},{"q":"膀胱癌的最好发部位是","o":["膀胱后壁","任何部位均可发生","膀胱前壁","膀胱侧壁和三角区","膀胱顶"],"a":3,"e":"膀胱癌好发于膀胱侧壁和膀胱三角区近输尿管开口处，该处黏膜与尿中致癌物接触时间长，肿瘤可呈乳头状、息肉状或扁平斑块状。"},{"q":"病毒性肝炎时最常见的肝细胞变性是","o":["嗜酸性变","脂肪变性","细胞水肿","玻璃样变","黏液样变"],"a":2,"e":"病毒性肝炎时最常见、最早出现的肝细胞变性是细胞水肿即气球样变，因细胞膜钠泵功能受损、水钠潴留而胞质疏松淡染。"},{"q":"在葡萄球菌感染的炎症反应中所见到的炎细胞主要是","o":["淋巴细胞","单核细胞","嗜酸性粒细胞","肥大细胞","中性粒细胞"],"a":4,"e":"化脓性炎尤其葡萄球菌、链球菌感染时渗出以中性粒细胞为主，其吞噬和杀菌能力强，变性坏死后成为脓细胞的主要成分。"},{"q":"下列哪项是变质性炎","o":["流行性脑脊髓膜炎","细菌性痢疾","大叶性肺炎","阿米巴肝脓肿","化脓性胆囊炎"],"a":3,"e":"变质性炎以组织细胞变性、坏死为主，渗出和增生轻微。阿米巴肝脓肿为阿米巴滋养体引起的肝组织液化性坏死。流行性脑脊髓膜炎、细菌性痢疾、大叶性肺炎和化脓性胆囊炎均以渗出性炎为主。"},{"q":"白色血栓主要由下列哪些成分构成","o":["白细胞、纤维素和血小板","血小板和纤维素","红细胞和白细胞","红细胞和纤维素","血小板和红细胞"],"a":1,"e":"白色血栓主要由血小板和少量纤维蛋白构成，肉眼呈灰白色小结节，与血管壁紧密黏着，多见于心瓣膜和动脉内。"},{"q":"下列配对哪项是错误的","o":["皮肤表层水疱－化脓性炎","大叶性肺炎－纤维素性炎","风湿性关节炎－浆液性炎","结核病－肉芽肿性炎","皮肤疖－化脓性炎"],"a":0,"e":"皮肤表层水疱是浆液性炎，渗出的浆液在表皮内或表皮下积聚所致，并非化脓性炎。大叶性肺炎为纤维素性炎，风湿性关节炎为浆液性炎，结核病为肉芽肿性炎。"},{"q":"下列属于肿瘤的是","o":["错构瘤","动脉瘤","室壁瘤","创伤性神经瘤","骨软骨瘤"],"a":4,"e":"骨软骨瘤是最常见的良性骨肿瘤，属真性肿瘤；错构瘤为组织排列异常的瘤样畸形，动脉瘤与室壁瘤是血管壁膨出，创伤性神经瘤为修复性增生。"},{"q":"下面叙述中不符合2型糖尿病的是","o":["成年发病，起病较轻，发展缓慢","无抗胰岛细胞抗体","胰岛数目正常或轻度减少","血胰岛素水平明显降低","肥胖者多见"],"a":3,"e":"2型糖尿病血中胰岛素可正常、增多或降低，并非明显降低；明显降低见于1型糖尿病，因其胰岛B细胞严重受损、胰岛素绝对不足。"},{"q":"下述关于脑动脉粥样硬化的叙述中，哪项是错误的","o":["大脑前动脉病变最重","脑动脉粥样硬化的发生比冠状动脉晚","继发脑动脉血栓形成","可引起脑软化","可引起小动脉瘤"],"a":0,"e":"脑动脉粥样硬化以大脑中动脉和基底动脉病变最重，大脑前动脉较轻；可致管腔狭窄、脑萎缩和脑软化，并形成小动脉瘤破裂出血。"},{"q":"乳腺癌表面皮肤橘皮样变是因为","o":["肿瘤细胞直接浸润表皮","肿瘤体积过大，压迫皮肤","肿瘤压迫静脉导致血液回流受阻","肿瘤细胞阻塞淋巴管导致淋巴液回流受阻而使皮肤水肿","肿瘤侵犯Cooper韧带所致"],"a":3,"e":"癌细胞阻塞真皮内淋巴管，淋巴液回流受阻致皮肤水肿，而毛囊汗腺处皮肤相对下陷，形成橘皮样外观。"},{"q":"不属于特异性心肌病的是","o":["致心律失常性右室心肌病","克山病","酒精性心肌病","围生期心肌病","药物性心肌病"],"a":0,"e":"心肌病分为扩张型、肥厚型、限制型、致心律失常性右室心肌病及未分类心肌病，克山病、酒精性、围生期和药物性心肌病均归入特异性心肌病。"},{"q":"髓母细胞瘤最常见的发生部位在","o":["大脑皮质","垂体","脑桥","小脑蚓部","延髓"],"a":3,"e":"髓母细胞瘤起源于小脑胚胎性外颗粒层细胞或室管膜下基质细胞，约75%的儿童病例位于小脑蚓部并突入第四脑室。"},{"q":"关于动脉性充血，下列哪项叙述是错误的","o":["细动脉扩张","见于心力衰竭","温度增高","见于减压后","局部呈鲜红色"],"a":1,"e":"动脉性充血表现为细动脉扩张、局部鲜红、温度升高，见于炎性充血和减压后充血；心力衰竭时静脉回流受阻，引起的是静脉性淤血。"},{"q":"急性风湿热皮肤表现为","o":["Osler结节","Negri小体","Aschoff小体","环形红斑","McCallum斑"],"a":3,"e":"急性风湿病时皮肤出现环形红斑和皮下结节，具诊断意义；环形红斑为渗出性病变，多见于躯干和四肢，呈淡红色环状红晕。Aschoff小体位于心肌间质。"},{"q":"动脉血栓形成的最重要和最常见的原因是","o":["血流缓慢及涡流形成","血液成分改变","血管内膜损伤","血流速度变快","血液凝固性减低"],"a":2,"e":"心血管内膜损伤后暴露内皮下胶原，激活血小板和凝血因子Ⅻ，同时损伤内皮释放组织因子启动外源凝血，是动脉血栓形成最重要最常见的原因。"},{"q":"引起胆囊炎或胆管炎的最常见致病菌是","o":["大肠杆菌","链球菌","真菌","葡萄球菌","伤寒杆菌"],"a":0,"e":"胆道感染多为肠道细菌经胆道逆行侵入所致，致病菌以大肠埃希菌最常见，其次为葡萄球菌和肠球菌等。"},{"q":"卵巢Krukenberg瘤的原发病灶常在","o":["肺","胃肠道","乳腺","肝脏","子宫内膜"],"a":1,"e":"Krukenberg瘤是胃等胃肠道黏液癌（尤其印戒细胞癌）种植转移至卵巢形成的黏液腺癌。教材明确其多由胃肠道黏液癌转移而来，故原发灶常在胃肠道。"},{"q":"胆囊炎最常见于","o":["男性","肥胖的妇女","肝硬化患者","酒精中毒者","Oddi（肝胰壶腹）括约肌慢性痉挛者"],"a":1,"e":"胆囊炎与胆石症关系密切，肥胖的妇女发病率高，与胆汁胆固醇过饱和、胆囊排空障碍及细菌感染有关。"},{"q":"导致肾脏体积明显缩小的疾病是","o":["糖尿病肾病","肾脓肿","肾盂积水","慢性硬化性肾小球肾炎","肾梗死"],"a":3,"e":"慢性硬化性肾小球肾炎双肾对称性缩小、质硬、表面呈细颗粒状，单侧重量可小于100g；肾盂积水、肾脓肿及糖尿病肾病早期均使肾体积增大。"},{"q":"心内膜下心肌梗死的并发症是","o":["心脏破裂","附壁血栓形成","室壁瘤","无菌性纤维素性心包炎","心律失常"],"a":1,"e":"心内膜下心肌梗死累及心内膜使其表面粗糙，局部血流形成涡流，易在左心室形成附壁血栓，脱落后引起体循环栓塞。"},{"q":"急性肾盂肾炎的主要病变特点是","o":["以肾盂为主的急性化脓性炎","以肾间质为主的化脓性炎、脓肿形成和肾小管坏死","以肾间质为主的增生性炎","单发性肾脓肿","以肾间质为主的过敏性炎"],"a":1,"e":"急性肾盂肾炎是肾盂、肾间质和肾小管的化脓性炎，镜下为灶状间质性化脓性炎或脓肿形成、肾小管腔内中性粒细胞集聚及肾小管坏死，病变常为多发灶性。"},{"q":"酒精性肝病的发病机制中，酒精可以影响脂肪酸的氧化，主要是因为在肝解毒过程中消耗了大量的","o":["二磷酸吡啶核苷酸（NAD）","三磷酸吡啶核苷酸（TPN）","一磷酸腺苷（AMP）","二磷酸腺苷（ADP）","三磷酸腺苷（ATP）"],"a":0,"e":"乙醇在肝内氧化为乙醛和乙酸的过程中大量消耗NAD，使NAD/NADH比值下降，抑制脂肪酸β氧化和三羧酸循环，脂肪酸酯化增强而形成脂肪肝。"},{"q":"血栓的结局不包括","o":["溶解吸收","机化、再通","钙化","脱落形成栓子","肉芽肿形成"],"a":4,"e":"血栓结局包括溶解吸收、机化再通、钙化和脱落形成栓子；肉芽肿是巨噬细胞增生形成的结节状炎症病灶，与血栓结局无关。"},{"q":"属于特异性心肌病的是","o":["扩张型心肌病","肥厚性心肌病","限制性心肌病","致心律失常性右室心肌病","克山病"],"a":4,"e":"克山病是我国的地方性心肌病，被列入特异性心肌病；扩张型、肥厚型、限制型和致心律失常性右室心肌病均属原发性心肌病。"},{"q":"下列哪项是Goodpasture综合征的主要病变","o":["肺出血合并肾盂肾炎","肺出血合并肾小管坏死","肺出血合并肾小球肾炎","肺水肿合并肾小球肾炎","肺出血合并肾衰竭"],"a":2,"e":"抗GBM抗体与肾小球基膜及肺泡基膜交叉反应，引起肺出血合并肾小球肾炎，后者以新月体形成为特征，临床出现咯血、血尿及肾衰竭。"},{"q":"肺癌的临床表现为","o":["咳嗽，咳铁锈色痰","刺激性干咳，无痰","长期咳嗽，咳白色泡沫痰","咳嗽，咯血，咳大量脓痰","刺激性呛咳，痰中带血"],"a":4,"e":"肺癌早期多为刺激性干咳或呛咳，癌组织溃破血管则痰中带血，为最有提示意义的症状；咳铁锈色痰见于大叶性肺炎。"},{"q":"Behcet（白塞）综合征的临床表现不包括","o":["皮肤结节性红斑","复发性口腔溃疡","生殖器溃疡","消化道溃疡","眼葡萄膜炎"],"a":3,"e":"白塞综合征以复发性口腔溃疡、生殖器溃疡、眼葡萄膜炎及皮肤结节性红斑为特征，属血管炎性病变；消化道溃疡是其可累及的表现，不列入诊断要点。"},{"q":"下列对诊断肥厚性胃炎最有诊断意义的是","o":["腺体萎缩","固有层结缔组织增生","黏膜肥厚，腺体增生肥大，腺体间有慢性炎细胞浸润","胃黏膜上皮细胞异型性增生","腺体肠上皮化生"],"a":2,"e":"肥厚性胃炎以胃黏膜肥厚、腺体增生肥大、腺体间慢性炎细胞浸润为特征，黏膜皱襞粗大。腺体萎缩和肠上皮化生是萎缩性胃炎的表现。"},{"q":"卡他性炎指的是","o":["皮肤的浆液性炎","浆膜的浆液性炎","黏膜的浆液性炎","关节的浆液性炎","脑膜的浆液性炎"],"a":2,"e":"卡他性炎指黏膜的渗出性炎，渗出物稀薄并沿黏膜表面下流，以浆液性卡他最常见，如感冒初期鼻黏膜排出大量浆液性分泌物。"},{"q":"胰腺最常见的恶性肿瘤是","o":["导管腺癌","鳞状细胞癌","腺鳞癌","印戒细胞癌","肉瘤样癌"],"a":0,"e":"胰腺癌中导管腺癌占85%以上，是最常见的组织学类型，多见于胰头，早期即可压迫胆总管引起梗阻性黄疸。"},{"q":"下列肿瘤中最容易经血行转移的是","o":["宫颈鳞状细胞癌","肠黏液腺癌","乳腺浸润性导管癌","绒毛膜癌","肺大细胞癌"],"a":3,"e":"绒毛膜癌侵袭破坏血管的能力极强，极易经血道转移，以肺最常见，其次为脑、肝和阴道，故血行转移是其显著特点。"},{"q":"病理诊断慢性支气管炎的主要病变指标是","o":["支气管黏膜上皮细胞变性、坏死脱落","支气管壁黏液腺体增生、肥大","支气管壁充血、水肿、炎细胞浸润","支气管黏膜鳞状上皮化生","支气管壁平滑肌、软骨破坏"],"a":1,"e":"慢性支气管炎的诊断性病变是黏膜下黏液腺体增生肥大、黏液分泌增多，腺体厚度与管壁厚度之比增大，可伴杯状细胞增多和鳞状上皮化生。"},{"q":"关于动物实验，下列描述中哪项是错误的","o":["在适宜的动物身上可以复制某种疾病的动物模型","动物实验的结果可以直接应用于人体","可以了解疾病的病理发展过程","可在一定程度上了解药物或其他因素对某种疾病的疗效和影响","可利用动物研究疾病的病因、发病机制"],"a":1,"e":"动物实验可复制人类疾病模型、研究病因发病机制及药物疗效，但动物与人存在物种差异，结果仅可作参考，不能不加分析地直接套用于人体。"},{"q":"漏出性出血的发生机制是由于","o":["组织的渗透压增高","毛细血管壁通透性增加","血管壁周围病变侵犯","血浆胶体渗透压降低","血管机械性损伤"],"a":1,"e":"漏出性出血因毛细血管和毛细血管后静脉通透性增高，血液经扩大的内皮细胞间隙和受损基底膜漏出，常见于缺氧、感染、中毒及维生素C缺乏。"},{"q":"急性重型肝炎的病变，哪项是不正确的","o":["肝细胞大片坏死","肝窦扩张充血","网状支架塌陷","坏死灶及周围有炎细胞浸润","肝细胞再生结节形成"],"a":4,"e":"急性重型肝炎肝细胞弥漫性大片坏死，仅残留网状支架，肝体积明显缩小、被膜皱缩，库普弗细胞增生，坏死区炎症细胞浸润，但无肝细胞结节状再生。"},{"q":"有关溃疡的并发症，下列哪项错误","o":["恶变","出血","幽门狭窄","穿孔","卒中"],"a":4,"e":"消化性溃疡的并发症为出血、穿孔、幽门梗阻和癌变。卒中由脑血管病变引起，与溃疡本身无关。"},{"q":"腹股沟疝嵌顿后，疝囊内的肠壁可发生","o":["凝固性坏死","湿性坏疽","干性坏疽","液化性坏死","气性坏疽"],"a":1,"e":"嵌顿疝肠壁静脉回流受阻而动脉仍通畅，肠管淤血水肿、水分多，易继发腐败菌感染，形成湿性坏疽。干性坏疽发生于动脉阻塞而静脉回流通畅的肢体。"},{"q":"不符合大叶性肺炎红色肝样变期病理变化的是","o":["肺泡壁血管贫血状态","肺泡腔内纤维素渗出","患者缺氧严重","肺泡腔内中性粒细胞渗出","肉眼实变，有如肝脏切面"],"a":0,"e":"红色肝样变期肺泡间隔毛细血管仍扩张充血，肺泡腔内充满纤维蛋白及大量红细胞，并夹杂中性粒细胞和巨噬细胞，故血管并非贫血状态。"},{"q":"获得性免疫缺陷综合征患者常见的恶性肿瘤是","o":["尤文氏肉瘤","Kaposi肉瘤","纤维肉瘤","膀胱移行细胞癌","直肠癌"],"a":1,"e":"艾滋病患者约30%发生卡波西肉瘤，由HHV-8感染引起，表现为皮肤多发紫红色斑块或结节；非霍奇金淋巴瘤也较常见。"},{"q":"下列所有的临床特征中不符合肾病综合征的是","o":["蛋白尿","低蛋白血症","血尿","高脂血症","水肿"],"a":2,"e":"肾病综合征的诊断依据为大量蛋白尿、低蛋白血症、明显水肿和高脂血症，血尿属肾炎综合征的表现，不是其必备条件。"},{"q":"绝大多数肺癌起源于","o":["支气管腺体","支气管黏膜上皮","Clara细胞","肺泡上皮","细支气管黏膜腺体"],"a":1,"e":"肺癌绝大多数起源于支气管黏膜上皮，包括鳞癌、腺癌和小细胞癌等；小细胞癌起源于黏膜上皮的Kulchitsky细胞，属神经内分泌肿瘤，而非肺泡上皮或腺体。"},{"q":"炎症反应的最重要的特征是","o":["血清渗出","血浆渗出","纤维素渗出","白细胞渗出","红细胞渗出"],"a":3,"e":"白细胞渗出血管并聚集于损伤部位，是炎症反应最重要的特征，也是防御与损伤的核心环节。液体渗出虽常见，但缺乏特异性。"},{"q":"肿瘤细胞分化程度越低","o":["恶性程度越高","异型性越小","转移越晚","预后越好","对放射治疗越不敏感"],"a":0,"e":"肿瘤分化程度越低，与正常组织差异越大，异型性越明显，生长快、转移早，恶性程度越高，预后越差，对放射治疗也多不敏感。"},{"q":"胃黏膜肠上皮化生最常见于","o":["慢性萎缩性胃炎","慢性胃溃疡","慢性浅表性胃炎","急性刺激性胃炎","先天性肠黏膜异位"],"a":0,"e":"慢性萎缩性胃炎时胃黏膜变薄、腺体减少或消失，常伴肠上皮化生，化生程度随萎缩加重而增多，并与肠型胃癌发生相关。浅表性胃炎腺体完整，一般无化生。"},{"q":"关于甲状腺乳头状癌的叙述，下列不正确的是","o":["本癌发现时约50%已有颈淋巴结转移，因此预后很差","青少年女性多见","为最多见的甲状腺癌","生长较慢，预后较好","肿瘤间质中常见砂粒体"],"a":0,"e":"原发性高血压是脑出血最常见的病因，脑内细小动脉硬化并形成微动脉瘤，血压骤升时破裂出血，好发于基底节、内囊区。"},{"q":"下列哪项决定肿瘤的生长速度","o":["肿瘤的生长方式","肿瘤的异型性","机体的免疫力","肿瘤的起源组织","肿瘤的发生部位"],"a":1,"e":"肿瘤生长速度取决于瘤细胞的分化程度和异型性，分化差、异型性大者倍增时间短、生长快，短期内即可形成明显肿块；生长方式主要影响其形态和边界。"},{"q":"下列哪项因素与动脉粥样硬化发生关系最为密切","o":["吸烟","高脂血症","高血压","肥胖","遗传因素"],"a":1,"e":"高脂血症尤其是LDL升高是动脉粥样硬化最重要的危险因素，脂质在内膜下沉积并被氧化，促进泡沫细胞形成和斑块发生，其关系较吸烟、高血压、肥胖更为密切。"},{"q":"风湿性心内膜炎最常累及","o":["二尖瓣及主动脉瓣","三尖瓣及肺动脉瓣","三尖瓣","二尖瓣","主动脉瓣"],"a":3,"e":"风湿性心内膜炎病变主要侵犯心瓣膜，其中二尖瓣最常受累，其次为二尖瓣和主动脉瓣同时受累。"},{"q":"肥厚型心肌病的病变特点是","o":["两侧心室肥大，四个心腔扩张","常伴有附壁血栓形成","心肌细胞异常肥大，排列方向紊乱","弥漫性心肌间质纤维化","心肌细胞数量增多"],"a":2,"e":"肥厚型心肌病以室间隔非对称性肥厚、心室腔变小为特征，光镜下心肌细胞弥漫性肥大、核大畸形深染，心肌纤维走行紊乱。"},{"q":"肿瘤是局部细胞的","o":["多克隆性增生所致","不典型增生所致","组织转化所致","克隆性增生所致","炎性增生所致"],"a":3,"e":"肿瘤是局部细胞克隆性增生所致，肿瘤性增生的淋巴细胞可视为被阻断在分化某一阶段的淋巴细胞克隆性增生。"},{"q":"混合血栓见于","o":["毛细血管内","静脉血栓的头部","动脉血栓的起始部","心瓣膜上的赘生物","静脉血栓的体部"],"a":4,"e":"静脉血流缓慢并出现漩涡时，血小板小梁与纤维蛋白网交替构成混合血栓，位于静脉血栓体部；白色血栓构成血栓头部，红色血栓构成尾部。"},{"q":"Ph1染色体主要出现在哪种白血病","o":["急性淋巴细胞白血病","慢性淋巴细胞白血病","急性粒细胞白血病","慢性粒细胞白血病","单核细胞白血病"],"a":3,"e":"Ph染色体即t(9;22)形成的BCR::ABL1融合基因，编码的融合蛋白使细胞持续增殖，是慢性粒细胞白血病即慢性髓系白血病的标记。"},{"q":"AIDS患者继发的Kaposi肉瘤来源于","o":["滑膜细胞","血管内皮细胞","平滑肌细胞","淋巴细胞","血管周细胞"],"a":1,"e":"Kaposi肉瘤起源于血管内皮细胞，AIDS患者因免疫缺陷在HHV-8作用下发生，表现为皮肤多发紫红色斑块或结节，可累及内脏和淋巴结。"},{"q":"下列哪项对中性粒细胞无趋化作用","o":["细菌代谢产物","坏死组织","阳离子蛋白","C3a","激肽原酶"],"a":2,"e":"嗜酸性粒细胞颗粒中的主要嗜碱性蛋白为阳离子蛋白，对寄生虫有毒性，对中性粒细胞无趋化作用。C3a、细菌产物、坏死组织及激肽原酶均能趋化和吸引中性粒细胞。"},{"q":"肾小球肾炎的基本病理改变不包括","o":["肾小球细胞增多","肾小球炎性渗出和坏死","肾间质内脓肿形成","基膜增厚、系膜基质增多","玻璃样变和硬化"],"a":2,"e":"肾小球肾炎的基本病变为细胞增多、炎性渗出和坏死、基膜增厚及系膜基质增多、玻璃样变和硬化；肾间质脓肿形成是急性肾盂肾炎的特点。"},{"q":"萎缩的心肌细胞内常可出现","o":["橙色血质","含缺血黄素","脂褐素","疟色素","黑色素"],"a":2,"e":"萎缩的心肌细胞和肝细胞胞质内可出现脂褐素颗粒，其是未被彻底消化的富含磷脂的细胞器残体，源于溶酶体，又称消耗性色素。"},{"q":"心肌脂肪变性时出现以下哪种病理改变","o":["心肌间质淋巴细胞浸润","心肌细胞脂肪组织浸润","心肌肉眼呈红、黄相间的条纹","心肌细胞空泡变性","心肌组织凝固性坏死"],"a":2,"e":"慢性酒精中毒或缺氧引起左心室内膜下及乳头肌心肌脂肪变，脂肪变心肌呈黄色，与正常心肌暗红色相间，形成虎斑心。"},{"q":"免疫荧光法显示IgG和C3沿毛细血管壁呈线形荧光者主要是","o":["脂性肾病","抗肾小球基底膜肾炎","膜性肾小球肾炎","膜增生性肾小球肾炎","局灶性节段性肾小球硬化"],"a":1,"e":"抗肾小球基膜肾炎由抗GBM抗体沿基膜连续沉积，免疫荧光呈特征性线形；膜性、膜增生性和链球菌感染后肾炎均呈颗粒状沉积。"},{"q":"慢性溃疡性结肠炎的病变特点不包括","o":["病变可累及结肠各段","临床上呈慢性经过","肠壁形成较大溃疡","易修复，不易癌变","常伴有肠外免疫性疾病"],"a":3,"e":"溃疡性结肠炎为原因不明的慢性结肠炎，病变连续性弥漫分布、可累及各段结肠，常伴肠外免疫性疾病；病程越长癌变风险越高，并非不易癌变。"},{"q":"口眼干燥综合征的组织学表现主要是","o":["受累腺体萎缩，不伴有淋巴浆细胞浸润","受累腺体间淋巴浆细胞浸润，伴有腺体结构破坏","受累腺体间常见上皮样肉芽肿","大量泡沫细胞浸润","有化脓性肉芽肿形成"],"a":1,"e":"干燥综合征病变主要累及唾液腺和泪腺，表现为大量淋巴细胞浸润并形成淋巴滤泡，同时伴腺泡结构破坏。腺体萎缩不伴淋巴浆细胞浸润不符合本病。"},{"q":"如图，可能的肾炎类型是","o":["急性肾小球肾炎","急进性肾小球肾炎","慢性肾小球肾炎","慢性肾盂肾炎","急性肾盂肾炎"],"a":2,"e":"官方题库缺失图片"},{"q":"鼻咽癌最常见于鼻咽的哪个部位","o":["外侧壁","前壁","前壁和咽隐窝","咽隐窝","顶部"],"a":4,"e":"鼻咽癌最常发生于鼻咽顶部，其次为外侧壁和咽隐窝，前壁最少见，顶部与侧壁也可同时受累。"},{"q":"关于萎缩性胃炎的病因，下列错误的是","o":["B型血中有内因子抗体","A型与自身免疫有关","B型与自身免疫无关","肠上皮化生","A型血中有壁细胞抗体"],"a":0,"e":"内因子抗体和壁细胞抗体见于A型萎缩性胃炎，属自身免疫性，病变位于胃体和胃底并伴恶性贫血；B型与幽门螺杆菌感染有关，自身抗体阴性。"},{"q":"神经细胞卫星现象指","o":["淋巴细胞、单核细胞围绕血管","神经元被5个以下少突胶质细胞环绕","神经元被5个以上淋巴细胞环绕","神经节细胞周围被鞘膜细胞环绕","神经元被5个以上少突胶质细胞环绕"],"a":4,"e":"灰质中一个神经元被5个或以上少突胶质细胞环绕，称卫星现象，见于神经元受损时；噬神经细胞现象则是小胶质细胞吞噬坏死神经元。"},{"q":"急性病毒性肝炎的病变性质为","o":["急性增生性炎","急性出血性炎","急性浆液性炎","急性变质性炎","急性纤维素性炎"],"a":3,"e":"急性病毒性肝炎以肝细胞变性、坏死为主，渗出和增生改变轻微，属变质性炎，临床以肝细胞功能障碍为主要表现。"},{"q":"微循环血管壁通透性增高引起的出血是","o":["破裂性出血","体腔积血","外出血","漏出性出血","渗出性出血"],"a":3,"e":"微循环的毛细血管和毛细血管后静脉通透性增高，红细胞通过增宽的内皮细胞间隙和受损基底膜漏出，称漏出性出血。"},{"q":"对于喉癌的描述，下列哪项是错误的","o":["浸润性鳞癌最常见","声嘶是喉癌患者最常见的早期症状","常经淋巴道转移至颈总动脉分叉处淋巴结","更易早期转移到肺","常发生于声带"],"a":3,"e":"喉癌以浸润性鳞状细胞癌最常见，好发于声带，声嘶为最常见的早期症状，主要经淋巴道转移至颈总动脉分叉处淋巴结；早期血行转移至肺少见。"},{"q":"下述哪种疾病属出血性炎","o":["病毒性肝炎","肠阿米巴病","流行性脑脊髓膜炎","钩端螺旋体病","丹毒"],"a":3,"e":"钩端螺旋体病属急性全身中毒性损害，主要累及全身毛细血管，引起循环障碍和出血，炎症反应轻微，故为出血性炎。"},{"q":"下列哪种激素具有抑制炎症的作用","o":["甲状腺素","生长激素","垂体促甲状腺素","促肾上腺皮质激素","糖皮质激素"],"a":4,"e":"糖皮质激素可抑制磷脂酶A2和环氧合酶-2的转录，减少前列腺素、白三烯及炎性细胞因子生成，具有较强的抗炎作用。"},{"q":"下列肿瘤中，有明显家族发病倾向者为","o":["胶质瘤","结肠息肉性腺瘤","骨软骨瘤","畸胎瘤","淋巴瘤"],"a":1,"e":"家族性腺瘤性息肉病为常染色体显性遗传，结肠内腺瘤数目众多，40岁前几乎均癌变，故结肠息肉性腺瘤呈明显家族发病倾向。"},{"q":"早期确诊肺癌简单、有效的检查方法为","o":["痰脱落细胞检查","胸部X线检查","放射性核素肺扫描","支气管镜检查","活组织检查"],"a":1,"e":"胸部X线检查简便、经济、无创，能显示肺部肿块或结节影，是肺癌早期发现和筛查最常用的方法，确诊仍靠痰细胞学或活组织检查。"},{"q":"食管癌中，最少见的肉眼类型是","o":["髓质型","蕈伞型","胶样型","溃疡型","缩窄型"],"a":2,"e":"食管癌肉眼类型分髓质型、蕈伞型、溃疡型和缩窄型，胶样型不属于食管癌的肉眼分型，故为最少见（实为不存在）的类型。"},{"q":"食管癌最常见的组织学类型是","o":["鳞状细胞癌","小细胞癌","腺癌","腺鳞癌","黏液癌"],"a":0,"e":"中国人食管癌最常见的组织学类型为鳞状细胞癌，约占90%以上，腺癌次之且多来自贲门。"},{"q":"吞噬作用最为活跃的炎症细胞是","o":["淋巴细胞","中性粒细胞","浆细胞","嗜酸性粒细胞","肥大细胞"],"a":1,"e":"中性粒细胞吞噬能力最强，胞质颗粒含髓过氧化物酶和溶酶体酶，能有效杀伤降解病原微生物，是急性炎症早期主要的吞噬细胞。"},{"q":"子宫内膜腺上皮的核下空泡出现在月经周期的","o":["11～14天","24～28天","20～23天","16～17天","17～19天"],"a":3,"e":"分泌期早期在孕激素作用下腺上皮基底部出现核下空泡，约于周期第16~17天最明显，随后空泡移至核上并将糖原分泌入腺腔。"},{"q":"硅肺的特征性病变是","o":["类上皮肉芽肿","肺间质纤维化","硅肺空洞","硅结节","胸膜变厚"],"a":3,"e":"硅肺的基本病变是硅结节形成和肺组织弥漫性纤维化，硅结节为境界清楚、触之有沙砾感的灰白结节，由吞噬硅尘的巨噬细胞聚集演变而成。"},{"q":"急进型高血压时，细动脉壁内有细丝、颗粒状或凝集成片块状的嗜酸物质，其改变可能是","o":["玻璃样变","淀粉样变","黏液样变性","纤维素样坏死","干酪样坏死"],"a":3,"e":"急进型高血压时细动脉壁发生纤维素样坏死，镜下呈细丝状、颗粒状或片块状强嗜酸性无结构物质；缓进型高血压则为细动脉玻璃样变。"},{"q":"关于大肠癌的描述，下列正确的是","o":["盲肠癌最多见","类癌由腺瘤癌变而来","少数癌瘤产生CEA","Dukes后期向远隔器官远移","未分化癌多见"],"a":3,"e":"Dukes分期依据癌的浸润深度、淋巴结转移和远隔器官转移，C、D期提示已有淋巴结或远处转移；大肠癌以直肠最多见，多数可产生CEA，组织学以腺癌为主。"},{"q":"关于栓子的运行途径，下列说法错误的是","o":["静脉系统及右心栓子常引起肺栓塞","动脉系统及左心栓子常引起脑、脾、肾等器官的栓塞","栓子运行一般逆压力差运行","下腔静脉内的血栓在胸、腹压突然升高时可发生逆行性栓塞","交叉性栓塞又称反常性栓塞"],"a":2,"e":"栓子一般随血流方向运行，停留在口径与其相当的血管并阻断血流；仅下腔静脉血栓在胸腹压骤升时可逆行至其所属分支，交叉性栓塞须经房间隔缺损才发生。"},{"q":"最容易发生脑转移的恶性肿瘤是","o":["肾癌","肺癌","绒癌","恶性黑色素瘤","胃癌"],"a":1,"e":"肺癌易经血道转移至脑、骨、肝和肾上腺，是脑转移瘤最常见的原发灶；绒毛膜癌和恶性黑色素瘤也可转移至脑。"},{"q":"风湿性肉芽肿中的坏死为","o":["固缩性坏死","干酪样坏死","纤维素样坏死","坏疽","液化性坏死"],"a":2,"e":"风湿小体中央为纤维蛋白样坏死，周围为成群的风湿细胞及少量淋巴细胞、浆细胞。纤维蛋白样坏死是结缔组织和小血管壁的坏死形式，并非干酪样坏死。"},{"q":"流行性乙型脑炎的病原体是","o":["乙型链球菌","α-溶血性链球菌","脑膜炎双球菌","乙型脑炎病毒","柯萨奇病毒"],"a":3,"e":"流行性乙型脑炎的病原体是嗜神经性乙型脑炎病毒，为有膜RNA病毒，经蚊虫叮咬传播。"},{"q":"常发生机化的病灶，下列哪项除外","o":["风湿性小体","心肌梗死","脑梗死","肠上皮细胞化生","干酪样坏死"],"a":3,"e":"机化是新生肉芽组织取代坏死组织、血栓、渗出物或异物的过程，心肌梗死、脑梗死、干酪样坏死及风湿小体均可机化；肠上皮化生属上皮的适应性改变，不经历机化。"},{"q":"溶组织内阿米巴具有致病性的阶段主要是","o":["大滋养体","小滋养体","包囊","幼虫","成虫"],"a":0,"e":"溶组织内阿米巴成熟四核包囊为传染阶段，滋养体为致病阶段，其中大滋养体（组织型）分泌溶组织酶并吞噬组织细胞，引起肠壁溃疡。"},{"q":"下列关于栓塞的叙述，哪项是正确的","o":["进入血液的癌细胞均可形成栓塞","脂肪栓塞均由创伤引起","羊水栓塞不会引起死亡","肺动脉血栓栓塞的栓子多来自于下肢深静脉","减压病是氧气栓塞"],"a":3,"e":"肺动脉血栓栓塞的栓子95%以上来自膝以上的下肢深静脉；脂肪栓塞也见于骨折和脂肪组织挫伤，羊水栓塞可迅速致死，减压病为氮气栓塞。"},{"q":"脂性肾病的临床特点是","o":["成年人多见","高血压","明显血尿","无水肿","选择性蛋白尿"],"a":4,"e":"脂性肾病即微小病变性肾小球病，临床表现为肾病综合征，蛋白尿以白蛋白为主，属选择性蛋白尿，提示滤过膜损伤较轻。该病多见于儿童，对糖皮质激素治疗敏感。"},{"q":"慢性支气管炎患者通气障碍是由于","o":["黏液腺肥大、增生","上皮纤毛倒伏、脱落","软骨变性萎缩","小气道阻塞","管壁平滑肌萎缩"],"a":3,"e":"慢性支气管炎时小支气管和细支气管管壁增厚、管腔狭窄，黏液栓形成，导致小气道阻塞，引起阻塞性通气障碍，呼气阻力增加，残气量增多。"},{"q":"对炎症病变痊愈来说，下列哪项是错误的","o":["致炎因子被清除","坏死组织被溶解吸收","由肉芽组织修复","损伤的组织结构和功能完全恢复","有肉芽肿形成"],"a":4,"e":"炎症痊愈需致炎因子清除、坏死组织溶解吸收、由肉芽组织修复并恢复原有结构与功能；肉芽肿是慢性炎症的特殊类型，不是痊愈的表现。"},{"q":"下列不符合阿尔兹海默病的特点的是","o":["老年斑","神经元纤维缠结","萎缩区皮质神经元丧失","弥漫性脑萎缩","与脑动脉硬化有密切关系"],"a":4,"e":"阿尔茨海默病以弥漫性脑萎缩、皮质神经元丧失、老年斑和神经元纤维缠结为特征，与Aβ沉积和tau蛋白过度磷酸化相关；其并非由脑动脉硬化引起，二者为独立疾病。"},{"q":"膀胱上皮发生鳞状上皮化生后恶性变，这时所形成的恶性肿瘤称为","o":["膀胱移行细胞癌","膀胱癌肉瘤","膀胱鳞状细胞癌","膀胱腺棘皮癌","膀胱腺鳞癌"],"a":2,"e":"膀胱黏膜发生鳞状上皮化生后恶变即形成鳞状细胞癌，镜下可见角化珠和细胞间桥，占膀胱癌的3%～7%。"},{"q":"膜性肾小球肾炎电镜下常见","o":["基底膜外侧许多颗粒状电子致密物沉积","基底膜外侧有驼峰状电子致密物沉积","基底膜呈“双轨状”","脏层上皮细胞足突融合","基底膜内侧电子致密物散在沉积"],"a":0,"e":"膜性肾小球病电镜下见基膜上皮侧弥漫分布的颗粒状电子致密物，伴基膜增厚和足突融合；驼峰状沉积见于急性弥漫性增生性肾炎，双轨状见于膜增生性肾炎。"},{"q":"构成胆道结石的化学成分不包括","o":["黏液物质","尿酸盐","钙盐","胆固醇","胆色素"],"a":1,"e":"胆道结石主要由胆固醇、胆色素、钙盐和黏液物质构成，可混合存在；尿酸盐结石见于痛风和尿路结石。"},{"q":"关于浆细胞下列错误的是","o":["正常时不存在于血液中","无吞噬功能","来源于T淋巴细胞","椭圆形，核位于胞质一端，核染色呈车轮状分布","胞质内有丰富的粗面内质网"],"a":2,"e":"浆细胞由B淋巴细胞受抗原刺激后转化而来，无吞噬功能，核偏位呈车轮状，胞质含丰富粗面内质网，正常不出现在外周血中。"},{"q":"宫颈癌的好发部位","o":["宫颈外口鳞状上皮侧","宫颈外口鳞状上皮与柱状上皮交界处","宫颈内口","宫颈管","宫颈外口柱状上皮侧"],"a":1,"e":"子宫颈癌好发于宫颈外口鳞状上皮与柱状上皮交界处的移行带，该处上皮更替活跃、易受HPV感染；癌变多起于鳞柱交界并向宫颈管方向延伸。"},{"q":"病毒性肝炎时，下列哪项罕见","o":["溶解坏死","脂肪变性","嗜酸性变","胞质疏松化和气球样变","肝细胞再生"],"a":1,"e":"病毒性肝炎以肝细胞胞质疏松化、气球样变、嗜酸性变及溶解性坏死为主，坏死区伴炎症细胞浸润和肝细胞再生。脂肪变性多见于酒精性肝病和代谢性疾病，在病毒性肝炎中罕见。"},{"q":"青壮年患者骤然畏寒、高热、胸痛、咳铁锈色痰，最有可能是","o":["急性支气管炎","慢性支气管炎急性发作","大叶性肺炎","小叶性肺炎","病毒性肺炎"],"a":2,"e":"青壮年骤起寒战高热、胸痛、咳嗽并咳铁锈色痰，是大叶性肺炎的典型表现，由肺泡内弥漫性纤维蛋白渗出实变所致。"},{"q":"下列哪种癌较早经血行转移","o":["移行细胞癌","绒毛膜癌","肺大细胞癌","胃癌","乳腺浸润性导管癌"],"a":1,"e":"绒毛膜癌侵袭破坏血管的能力强，早期即可经血道转移至肺、脑和肝，故较早发生血行转移；移行细胞癌和胃癌以淋巴道转移为主。"},{"q":"关于局限性肠炎下列哪项是错误的","o":["又称克罗恩病","主要累及回肠末端","临床出现腹痛、腹泻、肠穿孔和肠梗阻","病变呈节段性，由正常黏膜分隔","横行溃疡发展为裂隙，炎症浅表"],"a":4,"e":"克罗恩病黏膜面为纵行溃疡并可发展为裂隙，炎症累及肠壁全层，常并发穿孔、瘘管和肠梗阻。横行溃疡、炎症浅表是肠结核的特点。"},{"q":"在免疫组化染色过程中，“血清封闭”的目的是","o":["抗原修复作用","增加反应敏感性","消除非特异性反应，降低背景染色","防止脱片","加强特异性反应，提高阳性率"],"a":2,"e":"血清封闭用正常血清或牛血清白蛋白封闭组织中的非特异性结合位点，减少二抗等与组织的非特异性结合，降低背景染色。"},{"q":"下列哪种栓塞不会引起猝死","o":["颈内动脉栓塞","冠状动脉栓塞","肺动脉口栓塞","肺动脉较大分支栓塞","肾动脉栓塞"],"a":4,"e":"肾动脉栓塞仅引起所属肾组织梗死，不直接危及生命。颈内动脉、冠状动脉及肺动脉主干或大分支栓塞可致脑、心急性缺血或急性右心衰竭而猝死。"},{"q":"关于化脓性炎的叙述，下列不正确的是","o":["表面化脓是指发生在浆膜、黏膜的化脓性炎","黏膜的化脓性炎又可称为脓性卡他","化脓性炎可不伴有坏死","蜂窝织炎是指弥漫性化脓性炎","当脓液在组织间隙或体腔、自然管腔中积聚时称为积脓"],"a":2,"e":"化脓性炎以中性粒细胞渗出为主，伴组织坏死和脓液形成，坏死是化脓性炎的基本特征之一。"},{"q":"肝细胞碎片状坏死和桥接坏死最常见于","o":["急性普通型肝炎","重度慢性肝炎","急性普通型黄疸性肝炎","急性重型肝炎","亚急性重型肝炎"],"a":1,"e":"碎片状坏死指肝小叶周边界板肝细胞灶性坏死崩解，桥接坏死为相邻肝小叶间连续的坏死带；二者见于中、重度慢性肝炎，提示炎症活动度高。"},{"q":"下列不是恶性肿瘤可以出现的情况的是","o":["转移","可出血、坏死、囊性变","可呈膨胀性生长或外生性生长","生长快，不浸润","浸润性生长"],"a":3,"e":"恶性肿瘤呈浸润性生长并发生转移，生长迅速者同样浸润破坏周围组织；膨胀性和外生性生长可见于良性肿瘤，也可是恶性肿瘤的局部表现。"},{"q":"系统性红斑狼疮引起组织病理损害最重要的因素是","o":["CD8+细胞","CD4+细胞","自身抗体","苏木素小体","狼疮细胞"],"a":2,"e":"系统性红斑狼疮的组织损伤主要由自身抗体介导，抗原抗体复合物沉积于血管壁、肾小球和皮肤基底膜，激活补体引起Ⅱ、Ⅲ型变态反应性炎症。"},{"q":"肠伤寒溃疡的形态学特点是","o":["表浅不规则","烧瓶样","与肠轴平行","与肠轴垂直","边缘隆起火山口样"],"a":2,"e":"肠伤寒溃疡发生于集合淋巴小结，其长轴与肠管长轴平行；孤立淋巴小结处溃疡小而圆。烧瓶样溃疡为肠阿米巴病特点，与肠轴垂直为肠结核溃疡特点。"},{"q":"伤寒小结的主要构成成分是","o":["类上皮细胞","淋病细胞","多核巨细胞","浆细胞","巨噬细胞"],"a":4,"e":"伤寒小结由吞噬伤寒沙门菌、红细胞和细胞碎片的巨噬细胞（伤寒细胞）聚集形成，具病理诊断价值。上皮样细胞和多核巨细胞是结核等肉芽肿的成分。"},{"q":"下列不是神经鞘瘤的特点的是","o":["易于复发，易于恶变","有完整的包膜","Antoni A型结构","Antoni B型结构","椎管内最常见的肿瘤"],"a":0,"e":"神经鞘瘤有完整包膜，镜下见细胞密集、栅栏状排列的Antoni A区和疏松网状的Antoni B区，生长缓慢、极少恶变，是椎管内最常见的良性肿瘤。"},{"q":"坏死的结局不包括","o":["溶解吸收","分离排出","化生","钙化","机化包裹"],"a":2,"e":"坏死的结局为溶解吸收、分离排出、机化和包裹、钙化；化生是已分化细胞转变为另一种分化细胞的适应性改变，不属于坏死结局。"},{"q":"关于溃疡底部的结构，下列不正确的是","o":["渗出层","坏死层","肉芽肿层","瘢痕层","肉芽组织层"],"a":2,"e":"慢性消化性溃疡底部由内向外依次为渗出层、坏死层、肉芽组织层和瘢痕层，无肉芽肿层。肉芽肿是结核等特殊炎症的病变，不属溃疡结构。"},{"q":"细胞内出现Mallory小体常见于","o":["门脉性肝硬化","坏死后性肝硬化","淤血性肝硬化","酒精性肝硬化","胆汁性肝硬化"],"a":3,"e":"Mallory小体是变性肝细胞胞质内的嗜酸性凝集小体，由缠绕的细胞角蛋白中间丝构成，结合酗酒史和肝功能异常可诊断酒精性肝病。酒精性肝硬化属小结节型肝硬化，为酒精性肝病最严重病变。"},{"q":"肝癌一般不转移至","o":["淋巴结","脾","腹膜","肺","脑"],"a":1,"e":"肝癌经淋巴道转移至肝门及腹膜后淋巴结，经血道转移至肺、肾上腺和脑，侵及肝表面时可行种植转移；脾因门静脉血流滤过极少成为转移部位。"},{"q":"肺肉质变指的是","o":["胸膜渗出物纤维化","支气管壁纤维化","肺泡壁纤维化","肺泡壁平滑肌增生","肺泡腔内渗出物机化"],"a":4,"e":"大叶性肺炎时肺泡腔内纤维蛋白渗出物因中性粒细胞过少、蛋白酶不足而未被溶解，由肉芽组织取代机化，肺组织呈褐色肉样，称肺肉质变。"},{"q":"继发性肺结核的早期病灶多出现在","o":["肺尖下2～4cm处","肺门","肺底部","右肺上叶背部","右肺上叶下部或下叶上部近脏胸膜处"],"a":0,"e":"继发性肺结核的早期病变为局灶型肺结核，病灶定位于肺尖下2～4cm处，直径0.5～1.0cm，境界清楚有纤维包裹。原发性肺结核原发灶多位于上叶下部或下叶上部近胸膜处。"},{"q":"心冠状动脉粥样硬化最常受累的动脉分枝是","o":["右冠状动脉主干","左冠状动脉主干","右冠状动脉后降支","左冠状动脉回旋支","左冠状动脉前降支"],"a":4,"e":"冠状动脉粥样硬化以左冠状动脉前降支检出率最高，其后依次为右主干、左主干或左旋支、后降支。"},{"q":"与亚急性感染性心内膜炎无关的病变是","o":["肾梗死","皮肤黏膜出血点","皮肤环形红斑","心瓣膜赘生物","脾大"],"a":2,"e":"亚急性感染性心内膜炎可引起心瓣膜赘生物、脾大、皮肤黏膜出血点、肾梗死等。皮肤环形红斑是风湿病的特征性皮肤病变，由免疫复合物性血管炎所致。"},{"q":"十二指肠溃疡病最好发于","o":["十二指肠各段","十二指肠降部","十二指肠球部","十二指肠降部和球部","十二指肠下段后壁"],"a":2,"e":"十二指肠溃疡多发生在球部的前壁或后壁，溃疡一般较小，直径常在1cm以内，较浅且易愈合。空肠与回肠内为碱性环境，极少发生消化性溃疡。"},{"q":"不符合小叶性肺炎的是","o":["属化脓性炎症","病变从细支气管开始","常咳黏液脓性痰","肺组织化脓性炎","常见于青壮年"],"a":4,"e":"小叶性肺炎是以细支气管为中心的化脓性炎，多见于儿童、体弱老人和久病卧床者；青壮年多发的肺炎是大叶性肺炎。"},{"q":"骨化性纤维瘤不具有的特征是","o":["多见于上颌骨","女性发病率高","肿瘤中常见编织骨","常见成堆的多核巨细胞","多见于股骨、胫骨"],"a":4,"e":"骨化性纤维瘤多见于颌骨，以上颌骨最常见，女性多于男性，镜下见纤维组织内散在编织骨小梁和成堆多核巨细胞；股骨、胫骨是好发骨巨细胞瘤等肿瘤的部位。"},{"q":"肺癌最常见的类型是","o":["腺癌","鳞状细胞癌","胶样癌","黏液癌","未分化癌"],"a":0,"e":"肺腺癌发生率近年明显上升，已成为肺癌最常见的类型，多为非吸烟者，且大多数为周围型肺癌。鳞状细胞癌以中央型为主。"},{"q":"高血压时心脏产生的病变如图所示指的是","o":["左心室心肌肥厚而心腔不扩张","左心室心肌肥厚而心腔扩张","左心室壁厚度正常而心腔明显扩张","左心室、左心房心肌明显增厚","左心室、左心房心肌正常"],"a":0,"e":"官方题库缺失图片"},{"q":"深达肌肉的开放性创伤组织合并厌氧菌感染所致的坏死属于","o":["液化性坏死","凝固性坏死","干性坏疽","湿性坏疽","气性坏疽"],"a":4,"e":"深达肌肉的开放性创伤合并产气荚膜杆菌等厌氧菌感染，坏死组织产生大量气体，按压有捻发感，称气性坏疽，属湿性坏疽。"},{"q":"脂性肾病在电镜下最主要的变化是","o":["肾小球壁层上皮细胞内见大量脂质沉积","肾小球脏层上皮细胞足突广泛消失","肾小球毛细血管内皮细胞和系膜细胞增生","肾小球系膜基质增多","肾小球毛细血管基底膜外驼峰状沉积物"],"a":1,"e":"脂性肾病即微小病变性肾小球病，电镜下基膜正常、无电子致密物，主要改变为弥漫性脏层上皮细胞足突消失；光镜下仅见肾小管上皮细胞内脂质沉积。"},{"q":"与Burkitt淋巴瘤有关的病毒是","o":["EB病毒","麻疹病毒","疱疹病毒","腺病毒","HTLV-1"],"a":0,"e":"EB病毒与Burkitt淋巴瘤和鼻咽癌有关，能使B淋巴细胞多克隆性增殖并进一步发展为单克隆增殖形成淋巴瘤。"},{"q":"下列哪种肝硬化可出现肝细胞的羽毛状坏死","o":["坏死后性肝硬化","血吸虫性肝硬化","胆汁性肝硬化","门脉性肝硬化","淤血性肝硬化"],"a":2,"e":"胆汁淤积时胆盐损伤肝细胞，胞质内胆色素蓄积、细胞肿胀疏松呈羽毛状，形成羽毛状坏死，见于胆汁性肝硬化。"},{"q":"对于慢性胆囊炎的描述，错误的是","o":["可以发生癌变","黏膜多发性萎缩","常伴有明显纤维化","可由急性胆囊炎反复发作迁延所致","各层组织中均有中性粒细胞浸润"],"a":4,"e":"慢性胆囊炎镜下黏膜多萎缩，各层组织以淋巴细胞、单核细胞浸润为主并伴明显纤维化，而非中性粒细胞浸润。慢性炎症反复发作可致纤维化并存在癌变风险。"},{"q":"下列哪项不是胰岛素依赖型糖尿病的特点","o":["多发生于成年，发病缓慢","胰岛B细胞明显减少","是自身免疫性疾病","血中胰岛素明显降低","治疗依赖胰岛素"],"a":0,"e":"胰岛素依赖型糖尿病多见于青少年，起病急、病情重，胰岛B细胞严重受损致胰岛素绝对不足，治疗依赖胰岛素；成年发病、起病缓慢属非胰岛素依赖型的特点。"},{"q":"最有防御意义的炎症改变过程是","o":["炎症介质形成","分解代谢亢进","局部酸中毒","分子浓度增高","白细胞渗出"],"a":4,"e":"白细胞渗出并游出至炎症灶，通过吞噬和释放杀菌物质清除病原体，是炎症反应最重要的特征和最有防御意义的环节；血管反应和炎症介质为其提供条件。"},{"q":"脑动脉粥样硬化时下列哪项不易发生","o":["引起脑萎缩","动脉瘤形成","引起延髓性麻痹","继发脑血栓形成","大脑中动脉病变最重"],"a":2,"e":"脑动脉粥样硬化使脑组织长期缺血而萎缩，斑块可继发血栓形成致脑梗死，也常形成动脉瘤并破裂出血，病变以大脑中动脉和基底动脉环最重。延髓性麻痹由延髓运动神经核及其神经损害引起，非本病表现。"},{"q":"下列哪种因素对再生修复不利","o":["局部感染已被控制","患者无血管硬化性疾病","局部有较明显的瘢痕组织","创口缝合良好","充足维生素C的供给"],"a":2,"e":"局部瘢痕组织血供差、缺乏再生所需的细胞与基质，明显不利于再生修复；控制感染、良好缝合和充足维生素C则有利于愈合。"},{"q":"目前临床主要应用的国际肿瘤分期方法是","o":["WHO系统","TNM系统","NIH系统","CDC系统","AJCS系统"],"a":1,"e":"国际上广泛采用TNM分期系统，T表示原发灶大小及浸润范围，N为区域淋巴结受累情况，M为远处转移，据此综合判定临床分期。"},{"q":"慢性肺源性心脏病的主要发病因素不包括","o":["肺循环阻力增加","体循环阻力增加","肺动脉高压","肺组织减少","气道阻塞"],"a":1,"e":"慢性肺源性心脏病由肺循环阻力增加、肺动脉高压引起右心室肥大扩张，常见于慢支并发肺气肿等肺疾病；体循环阻力增加是高血压左心后负荷增高的机制。"},{"q":"妇女最常见的乳腺良性肿瘤是","o":["乳腺纤维腺瘤","乳腺平滑肌瘤","乳腺错构瘤","乳管内乳头状瘤","脂肪瘤"],"a":0,"e":"乳腺纤维腺瘤是乳腺最常见的良性肿瘤，由增生的腺管和纤维间质构成，多见于20～35岁，边界清楚、活动度好，切面灰白分叶状并见裂隙。"},{"q":"关于反流性食管炎的描述错误的是","o":["由胃内容物及十二指肠液反流引起","胃食管连接处以下出现Barrett食管改变","局部黏膜糜烂及溃疡","食管鳞状上皮增生","可导致食管环状纤维化和狭窄"],"a":1,"e":"Barrett食管指食管远端鳞状上皮被柱状上皮取代，位于胃食管连接处以上，是反流性食管炎的后果；反流性食管炎还可有黏膜糜烂溃疡、鳞状上皮增生及纤维化狭窄。"},{"q":"下列哪项属于静脉性充血","o":["减压后充血","妊娠子宫充血","炎性充血","进食后胃肠道的充血","静脉阻塞引起的充血"],"a":4,"e":"静脉阻塞使局部血流停滞、组织缺氧，属静脉性充血。进食后胃肠道充血、妊娠子宫充血、运动时骨骼肌充血及减压后充血均为生理性或动脉性充血。"},{"q":"下述流行性脑脊髓膜炎的临床表现错误的是","o":["脑膜刺激征","颅内压升高症状","混浊或脓样脑脊液","血性脑脊液","皮肤瘀点及瘀斑"],"a":3,"e":"流脑时脑脊液压力升高、外观混浊或呈脓性，蛋白增多、糖降低，涂片可找到脑膜炎双球菌；血性脑脊液见于蛛网膜下腔出血。"},{"q":"下述哪种病变不会引起远隔器官梗死","o":["风湿性二尖瓣狭窄","心肌梗死","心脏室壁瘤","亚急性感染性心内膜炎","高血压性心脏病"],"a":4,"e":"风湿性二尖瓣狭窄、心肌梗死、室壁瘤和亚急性感染性心内膜炎均可在心腔内形成血栓，脱落后栓塞远隔器官；高血压性心脏病仅致心室肥大和心力衰竭。"},{"q":"光镜下判断细胞是否坏死，主要观察","o":["染色质形态的改变","核仁形态的改变","细胞质形态的改变","细胞核形态的改变","细胞形态的改变"],"a":3,"e":"细胞坏死最可靠的形态学标志是核的改变，即核固缩、核碎裂和核溶解；胞质和细胞整体形态改变特异性差，核仁变化不能单独作为坏死判断依据。"},{"q":"引起脑梗死最常见的原因是","o":["脑动脉栓塞","脑血管畸形","脑动脉硬化伴血栓形成","脑动脉粥样硬化斑块内出血","脑血管炎症"],"a":0,"e":"官方答案为【脑动脉栓塞】，但依据教材，正确答案为【脑动脉硬化伴血栓形成】。血栓形成是梗死形成最常见的原因，脑动脉粥样硬化合并血栓形成是脑梗死最主要的发病机制。"},{"q":"发生DIC死亡的病人尸体解剖后，在肺、肾、脑等组织切片中可见到","o":["白色血栓","红色血栓","混合血栓","透明血栓","静脉血栓"],"a":3,"e":"DIC时全身微循环内形成纤维蛋白性微血栓，即透明血栓，需镜下观察；其主要成分为嗜酸性同质性纤维蛋白，见于肺、肾、脑等器官的毛细血管。"},{"q":"组胺类介质引起血管通透性升高的机制是","o":["引起内皮细胞收缩","引起内皮细胞损伤","介导白细胞对内皮细胞的损伤","使内皮细胞的穿胞作用增强","新生毛细血管的高通透性"],"a":0,"e":"组胺、缓激肽和白细胞三烯作用于毛细血管后微静脉内皮细胞，使其迅速收缩，细胞间出现缝隙，血管通透性升高，持续时间较短。"},{"q":"下述关于动脉粥样硬化的危险因素中，哪项是错误的","o":["高脂血症，特别是血浆低密度脂蛋白（LDL）、极低密度脂蛋白（VLDL）水平与动脉粥样硬化的发病率呈正相关","吸烟是引起动脉粥样硬化的因素之一","高血压患者，动脉粥样硬化发病较早，病变较重","遗传因素是动脉粥样硬化的危险因素","雌激素可降低血浆胆固醇水平，因此，女性比同年龄男性动脉粥样硬化发病率低"],"a":4,"e":"雌激素可改善血管内皮功能、降低血浆胆固醇水平，故绝经期前女性动脉粥样硬化发病率低于同龄男性，该表述本身正确。绝经期后此差别消失。"},{"q":"流行性乙型脑炎病变最明显的部位在","o":["脑桥","小脑","大脑皮质及基底核","脊髓","丘脑"],"a":2,"e":"流行性乙型脑炎病变以大脑皮质、基底核和视丘最为严重，小脑皮质、丘脑和脑桥次之，脊髓病变最轻。"},{"q":"确诊淀粉样变常用的染色法是","o":["刚果红染色","苏丹Ⅲ染色","普鲁士蓝染色","PAS染色","HE染色"],"a":0,"e":"淀粉样物质HE染色呈淡红色均质状，刚果红染色呈橘红色，偏振光显微镜下显示苹果绿色双折光，是确诊淀粉样变的常用方法。苏丹Ⅲ染脂肪，普鲁士蓝染铁。"},{"q":"对狼疮性肾炎具有诊断价值的形态特征是","o":["狼疮小体","肾小球系膜细胞增生","补体沉积","电子致密物沉积","免疫球蛋白"],"a":0,"e":"狼疮小体即苏木素小体，为抗核抗体作用于受损细胞核形成的均质状团块，对系统性红斑狼疮有明确诊断价值，被吞噬后形成狼疮细胞。"},{"q":"关于主动脉粥样硬化的叙述中下列错误的是","o":["病变多位于主动脉后壁和各分支开口处","可引起动脉血流障碍","可引起主动脉瓣膜病","可引起夹层动脉瘤","可继发溃疡及血栓形成"],"a":2,"e":"主动脉粥样硬化好发于后壁及分支开口处，可致管腔狭窄、继发溃疡和血栓，也可破坏中膜形成夹层动脉瘤。主动脉瓣膜病多由风湿性主动脉炎引起，不是主动脉粥样硬化的直接后果。"},{"q":"下列不符合肿瘤性增生的是","o":["与整个机体不协调","生长旺盛","增生过程中致瘤因子持续存在","具有相对自主性","不同程度的丧失了分化成熟的能力"],"a":2,"e":"肿瘤性增生由致瘤因子引起基因改变后自主持续生长，去除致瘤因子仍继续增生；增生过程中致瘤因子持续存在是炎症性增生的特点。"},{"q":"流行性乙型脑炎最具特征性的病变是","o":["噬神经细胞现象","卫星现象","筛网状软化灶","淋巴细胞袖口状浸润","胶质结节"],"a":2,"e":"流行性乙型脑炎时神经组织发生灶性液化性坏死，形成质地疏松、染色浅淡的镂空筛网状软化灶，对本病诊断有特征性意义，其他胶质反应特异性较低。"},{"q":"良性高血压病时，左心室向心性肥大属于","o":["肥大","增生","化生","再生","变性"],"a":0,"e":"良性高血压时左心室因压力负荷增加发生代偿性肥大，表现为左心室壁增厚、心腔相对缩小，即向心性肥大。肥大是细胞体积增大，而非细胞数目增多。"},{"q":"急性重型肝炎大量肝细胞溶解性坏死可导致以下各项，除了","o":["胆红素大量入血","肝细胞性黄疸","凝血因子合成障碍","肝细胞再生","肝性脑病"],"a":3,"e":"急性重型肝炎肝细胞广泛大片溶解性坏死，致胆红素大量入血出现肝细胞性黄疸、凝血因子合成障碍而出血、解毒功能丧失而发生肝性脑病。"},{"q":"引起肺褐色硬化的常见病变为","o":["二尖瓣狭窄","三尖瓣狭窄","肺动脉栓塞","急性肺淤血","右心衰竭"],"a":0,"e":"二尖瓣狭窄使左心房压升高、肺静脉回流受阻，长期慢性肺淤血致肺泡壁纤维化并大量含铁血黄素沉积，形成肺褐色硬化。"},{"q":"霍奇金淋巴瘤最常发生的部位是","o":["纵隔淋巴结","腋窝淋巴结","颈部淋巴结","肠系膜淋巴结","腹膜后淋巴结"],"a":2,"e":"霍奇金淋巴瘤原发部位以颈部淋巴结和中纵隔多见，颈部淋巴结为最常受累部位。非霍奇金淋巴瘤则多见于前纵隔、回盲部及腹腔淋巴结。"},{"q":"萎缩的心肌细胞内最易出现的色素是","o":["含铁血黄素","疟色素","胆色素","脂褐素","黑色素"],"a":3,"e":"脂褐素是细胞器残体未被彻底消化形成的富含磷脂的色素，萎缩的心肌细胞和肝细胞核周大量出现，故有消耗性色素之称。"},{"q":"关于肾小球肾炎的发病机制，目前认为关系最密切的是","o":["抗原抗体复合物形成","T淋巴细胞致敏","机体免疫功能低下","抗体直接损伤","B淋巴细胞致敏"],"a":0,"e":"大部分原发性肾小球疾病由免疫机制介导，循环免疫复合物在肾小球内沉积或抗体与肾小球内抗原原位反应形成免疫复合物，是肾小球损伤最主要的发病机制。"},{"q":"高血压病时，细小动脉硬化的主要病理改变是","o":["内膜结缔组织增生","内膜弹力纤维增生","内膜胆固醇沉着","管壁玻璃样变","内膜下有粥样物质沉着"],"a":3,"e":"缓进型高血压的细动脉硬化表现为管壁玻璃样变，由内皮受损后血浆蛋白渗入并沉积于管壁所致，最易累及肾入球动脉、视网膜动脉和脾中央动脉。"},{"q":"早期动脉粥样硬化的肉眼病变是","o":["脂纹","纤维斑块","粥样坏死","出血","玻璃样变"],"a":0,"e":"脂纹是动脉粥样硬化肉眼可见的最早病变，为内膜上黄色点状或条纹状病灶，由泡沫细胞聚集形成，不隆起或仅微隆起。"},{"q":"表达AFP最强的癌是","o":["卵巢癌","肝癌","结肠癌","子宫内膜癌","胃癌"],"a":1,"e":"原发性肝癌起源于肝细胞或肝内胆管上皮细胞，甲胎蛋白（AFP）明显升高，是表达AFP最强的癌。AFP和影像学检查可提高早期肝癌检出率。"},{"q":"关于慢性萎缩性胃炎的病理特点，下列哪项是错误的","o":["胃黏膜萎缩变薄","腺体变小，并可有囊性扩张","肠上皮化生","胃黏膜表面有很多结节状突起，中心凹陷似痘疹","壁细胞和主细胞消失"],"a":3,"e":"胃黏膜表面出现多个中心凹陷的疣状突起是疣状胃炎的特征；慢性萎缩性胃炎表现为黏膜变薄、腺体减少或囊性扩张、肠上皮化生及壁细胞主细胞消失。"},{"q":"晚期胃癌，最常发生转移的远处淋巴结为","o":["颈部","腋窝","腹股沟","左锁骨上","胃窦部小弯处"],"a":3,"e":"胃癌晚期癌细胞经淋巴管至胸导管，转移至左锁骨上淋巴结，即Virchow淋巴结；体检触及该结节约提示腹腔脏器恶性肿瘤。"},{"q":"前列腺增生的发生和（ ）有关","o":["雌激素","雄激素","HPV感染","HBV感染","HHV8感染"],"a":1,"e":"良性前列腺增生以前列腺上皮和间质增生为特征，其发生和雄激素有关。雌激素对前列腺癌生长有抑制作用，去势手术可抑制肿瘤生长。"},{"q":"人类免疫缺陷病毒可感染组织中的","o":["单核巨噬细胞","中性粒细胞","K细胞","NK细胞","B细胞"],"a":0,"e":"HIV除感染CD4+T细胞外，还可感染脑、淋巴结和肺等组织中的单核巨噬细胞；后者CD4表达水平低，病毒可在其中长期存留成为储存库。"},{"q":"下列疾病的出血不属于漏出性出血","o":["维生素C缺乏","食管下段静脉曲张","流行性出血热","原发免疫性血小板减少症","血友病"],"a":1,"e":"食管下段静脉曲张破裂属破裂性出血，血液由破裂口直接溢出；维生素C缺乏、出血热、血小板减少和血友病均因血管壁通透性增高或凝血障碍致漏出性出血。"},{"q":"良性高血压最具特征性的动脉病变是","o":["细动脉的玻璃样变","细动脉的纤维素样坏死","细小动脉内膜炎","动脉粥样硬化","动脉中层钙化"],"a":0,"e":"细动脉玻璃样变是良性高血压的主要病变特征，最易累及肾入球动脉、视网膜动脉和脾中央动脉。细动脉纤维素样坏死见于恶性高血压，动脉粥样硬化与高血压病分属不同疾病。"},{"q":"浆液性炎症中，其渗出的浆液内蛋白质含量为","o":["1%～3%","3%～5%","5%～7%","7%～9%","＞10%"],"a":1,"e":"浆液性炎渗出的浆液主要来自血浆，蛋白质含量为3%~5%，以白蛋白为主，同时混有少量中性粒细胞和纤维蛋白。"},{"q":"急性细菌性痢疾的假膜成分除外","o":["细菌","大量纤维蛋白","淋巴细胞","坏死上皮","中性粒细胞"],"a":2,"e":"急性细菌性痢疾的假膜由纤维蛋白、坏死脱落的黏膜上皮、中性粒细胞、红细胞及细菌共同构成。淋巴细胞主要参与慢性炎症，不是假膜的组成成分。"},{"q":"干性坏疽与湿性坏疽的区别在于前者","o":["好发生于四肢末端","与正常组织分界清楚","全身中毒症状严重","静脉回流通畅","有明显的臭味"],"a":3,"e":"干性坏疽发生于动脉阻塞而静脉回流仍通畅的四肢末端，坏死区干燥皱缩呈黑色，与正常组织界限清楚，全身中毒症状轻。湿性坏疽静脉回流受阻，肿胀恶臭、界限不清。"},{"q":"流行性脑脊髓膜炎是","o":["化脓性炎","变质性炎","出血性炎","纤维素性炎","肉芽肿性炎"],"a":0,"e":"流行性脑脊髓膜炎由脑膜炎双球菌引起，是脑脊髓膜的急性化脓性炎症，蛛网膜下腔充满灰黄色脓性渗出物，覆盖脑沟脑回。"},{"q":"最常出现砂粒体的甲状腺癌是","o":["髓样癌","滤泡性癌","未分化癌","乳头状癌","鳞状细胞癌"],"a":3,"e":"砂粒体为同心圆状钙化小体，位于乳头轴心的纤维血管间质内，是甲状腺乳头状癌的重要形态学标志，见于多数病例。"},{"q":"慢性萎缩性胃炎B型的表现有","o":["胃体部黏膜弥漫性病变","胃窦部黏膜病变严重","血清自身抗体阳性","维生素B吸收障碍","常伴有恶性贫血"],"a":1,"e":"慢性萎缩性胃炎B型与幽门螺杆菌感染有关，病变主要位于胃窦部，自身抗体阴性、血清胃泌素正常或降低，不伴恶性贫血。"},{"q":"结核结节中的Langhans巨细胞来源于","o":["支气管上皮细胞","上皮样细胞","肺泡上皮细胞","间叶细胞","成纤维细胞"],"a":1,"e":"朗汉斯巨细胞由上皮样细胞互相融合或核分裂而胞质不分裂形成，其核排列于胞质周边呈马蹄形或环形，见于结核结节。"},{"q":"HIV选择性破坏","o":["Ts细胞","Th细胞","TI细胞","Tc细胞","树突状细胞"],"a":1,"e":"HIV通过gp120与CD4分子结合，主要侵犯CD4阳性的辅助性T细胞，使其大量破坏、数量减少，导致细胞免疫功能严重缺陷。"},{"q":"慢性支气管炎的病变性质是","o":["慢性特异性炎症","慢性非特异性炎症","急性浆液性炎症","急性出血性炎症","急性化脓性炎症"],"a":1,"e":"慢性支气管炎是发生于支气管黏膜及其周围组织的慢性非特异性炎性疾病，以反复咳嗽、咳痰或伴喘息为临床特征。特异性炎症指肉芽肿性炎等有特定病因者。"},{"q":"弥漫性腱鞘巨细胞瘤组织学可见","o":["滑膜细胞变性、坏死、脱落","滑膜细胞增生并吞噬大量含铁血黄素","滑膜细胞增生并吞噬大量脂褐素","滑膜细胞增生并吞噬大量黑色素","间质细胞无改变"],"a":1,"e":"弥漫性腱鞘巨细胞瘤由滑膜样单核细胞增生构成，并见多核巨细胞，胞质内吞噬大量含铁血黄素而呈黄褐色，易浸润周围软组织。"},{"q":"弥散性血管内凝血（DIC）时引起的出血，与其关系最为密切的因素是","o":["肝脏合成凝血因子障碍","凝血因子Ⅻ被激活","凝血因子被大量消耗","血管通透性增高","血小板被激活"],"a":2,"e":"弥散性血管内凝血时微血管内广泛形成纤维蛋白微血栓，凝血因子和血小板被大量消耗，继发纤溶亢进，导致全身广泛出血。"},{"q":"不属于类风湿性关节炎病变特点的是","o":["急性坏死性动脉炎","滑膜下淋巴滤泡的形成","关节软骨表面血管翳的形成","Aschoff小体的生成","晚期关节的畸形"],"a":3,"e":"Aschoff小体是风湿病的特征性病变，由风湿细胞及淋巴细胞、浆细胞构成，见于风湿性心肌炎，而非类风湿性关节炎。类风湿性关节炎可见滑膜淋巴滤泡形成、血管翳及晚期关节畸形。"},{"q":"下列病变中癌变可能性较大的是","o":["十二指肠溃疡","慢性萎缩性胃炎","浅表性胃炎","肥厚性胃炎","疣状胃炎"],"a":1,"e":"慢性萎缩性胃炎伴肠上皮化生和异型增生，是胃癌重要的癌前病变；浅表性胃炎、疣状胃炎和消化性溃疡的癌变率均低。"},{"q":"大结节性肝硬化，结节粗大且大小不均，多数结节直径大于（ ），纤维间隔较宽，且宽窄不一","o":["5cm","3cm","5mm","4mm","3mm"],"a":4,"e":"小结节型肝硬化结节直径一般小于3mm，纤维间隔细；大结节型结节粗大不均、多数直径大于3mm，纤维间隔宽窄不一，多由重型肝炎引起。"},{"q":"与EB病毒感染密切相关的淋巴瘤类型是","o":["蕈样肉芽肿（蕈样霉菌病）","霍奇金淋巴瘤","外周T细胞淋巴瘤","滤泡性淋巴瘤","弥漫性大B细胞淋巴瘤"],"a":1,"e":"EB病毒感染与霍奇金淋巴瘤关系密切，瘤组织中EB病毒检出率可高达75%，经典型霍奇金淋巴瘤尤为明显。"},{"q":"在结核病的基本病变以增生为主时，常形成","o":["增生性息肉","结核性肉芽肿","结核球","假结核结节","炎性假瘤"],"a":1,"e":"菌量少、毒力低而机体免疫反应较强时，病变以增生为主，形成结核结节即结核性肉芽肿，由上皮样细胞、朗汉斯巨细胞及外周淋巴细胞和成纤维细胞构成。"},{"q":"如图显示肿瘤的转移方式是","o":["淋巴道转移","血行转移","种植转移","直接蔓延","广泛转移"],"a":2,"e":"肿瘤细胞侵及器官表面后脱落，种植于体腔其他器官表面形成多个转移灶，为种植性转移。淋巴道转移经淋巴管至局部淋巴结，血行转移经血管播散，均与图示腔面播散方式不同。"},{"q":"动脉粥样硬化脂纹病变中主要的细胞成分是","o":["单核细胞","T淋巴细胞","泡沫细胞","平滑肌细胞","中性粒细胞"],"a":2,"e":"脂纹由内膜下大量泡沫细胞聚集形成，泡沫细胞源于巨噬细胞和迁入内膜的平滑肌细胞；其为动脉粥样硬化最早病变，尚无纤维帽和坏死核心。"},{"q":"下列哪项最符合转移性肿瘤的概念","o":["远隔器官发生的另一种肿瘤","血行转移的结果","可形成“癌脐”","与原发瘤属同一类型","可进一步发生转移"],"a":3,"e":"转移是瘤细胞从原发部位经淋巴道、血道或体腔迁徙至他处继续生长，形成与原发瘤同样类型的肿瘤，这是转移的本质特征。"},{"q":"慢性风湿性心瓣膜病最常见的联合瓣膜病变是","o":["主动脉瓣和肺动脉瓣","二尖瓣和三尖瓣","三尖瓣和肺动脉瓣","二尖瓣和主动脉瓣","三尖瓣和主动脉瓣"],"a":3,"e":"慢性风湿性心瓣膜病以二尖瓣受累最常见，二尖瓣合并主动脉瓣病变为20%～30%，是最常见的联合瓣膜病变。三尖瓣和肺动脉瓣病变者少见。"},{"q":"下列哪些病变的出血是属于漏出性出血","o":["脑动脉瘤","肺结核","肺淤血","胃溃疡","子宫颈癌"],"a":2,"e":"肺淤血时肺静脉和毛细血管内压升高、通透性增高，红细胞漏出至肺泡腔，属漏出性出血；脑动脉瘤、胃溃疡、肺结核和宫颈癌出血为破裂性出血。"},{"q":"二尖瓣狭窄不会引起","o":["右心房增大","左心房增大","右心室增大","左心室增大","肺动脉高压"],"a":3,"e":"二尖瓣狭窄使左心房压升高，继而肺静脉压、肺动脉压升高，引起左心房、右心室和右心房增大。单纯二尖瓣狭窄不累及左心室，晚期左心室反而缩小。"},{"q":"下列哪一项最能体现宫颈原位癌的特征","o":["发生于子宫颈黏膜的柱状上皮","未发生转移","是一种早期癌","是一种基底细胞癌","癌组织波及上皮全层，但未突破基底膜"],"a":4,"e":"原位癌指异型细胞累及上皮全层，细胞形态与癌细胞相同，但基底膜完整、无间质浸润，故不发生转移。"},{"q":"与免疫复合物无关的肾小球肾炎是","o":["膜性肾炎","急性肾炎","微小病变性肾小球病","膜增生性肾小球肾炎","新月体性肾小球肾炎"],"a":2,"e":"微小病变性肾小球病肾小球正常，免疫荧光阴性，无沉积物，足细胞足突消失，与免疫复合物无关。其余各型均有免疫复合物沉积。"},{"q":"高血压的血管壁玻璃样变主要发生于","o":["细小动脉","毛细血管","大动脉","中动脉","细小静脉"],"a":0,"e":"高血压时血浆蛋白渗入细小动脉内膜下并沉积，形成玻璃样变，使管壁增厚、管腔狭窄，是缓进型高血压的基本血管病变。"},{"q":"引起慢性肺源性心脏病最常见的原因是","o":["支气管哮喘","支气管扩张症","慢性支气管炎并发阻塞性肺气肿","肺尘埃沉着病","慢性纤维空洞型肺结核"],"a":2,"e":"慢性阻塞性肺疾病是肺心病最常见的原因，其中以慢性支气管炎并发阻塞性肺气肿最常见，占80%～90%。"},{"q":"下列哪项叙述是更年期子宫内膜的组织学表现","o":["内膜薄，腔狭而直，腺上皮立方","内膜增厚，腺上皮增生，间质致密","内膜腺体形态不规则、排列紊乱，腺腔扩张，腺上皮高低不一，缺少分泌现象","内膜的间质细胞分化成为蜕膜细胞和内膜颗粒细胞","腺体上皮细胞质内出现空泡"],"a":2,"e":"更年期卵巢功能衰退、无排卵，子宫内膜在雌激素持续作用下呈增生改变，腺体形态不规则、排列紊乱、腺腔扩张，腺上皮高低不一且缺少分泌现象。"},{"q":"下列属于病理性再生的是","o":["消化道黏膜上皮细胞的更新","子宫内膜周期性脱落、增生、修复","鳞状上皮表层角化细胞脱落、基底细胞增生","血细胞的更新","皮肤缺损后由周围的被覆上皮增生、修复"],"a":4,"e":"病理性再生指病理状态下组织缺损后的再生修复，皮肤缺损由创缘基底细胞增生覆盖即属此类；消化道黏膜、子宫内膜和血细胞的更新属生理性再生。"},{"q":"既有肝细胞的大片坏死，又有肝细胞的结节状再生，是哪种肝炎","o":["慢性轻度肝炎","急性重型肝炎","亚急性重型肝炎","急性普通型肝炎","慢性中度肝炎"],"a":2,"e":"亚急性重型肝炎既有肝细胞亚大块坏死，又有结节状肝细胞再生，并伴小胆管增生和炎细胞浸润；急性重型肝炎以弥漫性大片坏死为主，再生不明显。"},{"q":"下列关于软骨瘤的叙述不正确的是","o":["多位于手、足各骨","男性发病率高","外生性软骨瘤位于骨皮质外侧","生长快，局部症状明显","内生性软骨瘤位于骨髓腔"],"a":3,"e":"软骨瘤生长缓慢，多无症状或仅有轻微疼痛，好发于手足短骨，男性略多；内生性者位于骨髓腔，外生性者位于骨皮质外。生长快、局部症状明显提示恶变或为其他肿瘤。"},{"q":"下述均为急性链球菌感染后肾小球肾炎的特点，但除外","o":["多见于儿童","明显血尿","肾小球呈缺血状","上皮下驼峰状电子致密物","肾小球毛细血管内有链球菌菌栓"],"a":4,"e":"急性链球菌感染后肾炎由免疫复合物介导，肾小球内并无链球菌菌栓；病变以系膜细胞和内皮细胞增生、上皮下驼峰状沉积为特点。"},{"q":"病毒性肝炎肝硬化最显著的特征是","o":["灶性肝细胞坏死","大量中性粒细胞浸润","大量嗜酸性粒细胞浸润","肝细胞脂肪变性","假小叶形成"],"a":4,"e":"肝硬化最具特征性的病变是假小叶形成，即纤维组织分割包绕肝细胞团，中央静脉缺如或偏位，并伴肝内血液循环改建。"},{"q":"下列属病理性再生的是","o":["血细胞的更新","肠道黏膜上皮的更新","子宫内膜的周期性再生","皮肤缺损由周围的被覆上皮增生修复","口腔黏膜上皮脱落更新"],"a":3,"e":"病理性再生指组织损伤后通过再生修复，皮肤缺损由创缘基底层细胞增生迁移覆盖即属此例；血细胞更新、子宫内膜周期再生和黏膜上皮更新均为生理性再生。"},{"q":"肿瘤细胞核染色体多呈","o":["单倍体","双倍体","三倍体","四倍体","多倍体"],"a":4,"e":"恶性肿瘤细胞染色体多呈非整倍体即多倍体，出现超二倍体、多倍体及染色体结构畸变，是核异型性的重要基础。"},{"q":"下述关于动脉粥样硬化性固缩肾的描述中，哪项是错误的","o":["可引起肾血管性高血压","肾动脉开口处或主干近侧端狭窄","肾动脉粥样硬化可并发血栓形成","受累的肾脏出现较大块的凹陷瘢痕","常引起肾功能不全"],"a":4,"e":"动脉粥样硬化性固缩肾因斑块多位于肾动脉开口及主干近端，可致肾血管性高血压，梗死机化形成较大凹陷瘢痕；受累范围有限，一般不引起肾功能不全。"},{"q":"急性肾小球肾炎的病变是","o":["纤维素性炎","变态反应性炎","变质性炎","化脓性炎","增生性炎"],"a":1,"e":"急性肾小球肾炎由链球菌感染后免疫复合物沉积致病，属变态反应性炎症，光镜下以肾小球内皮细胞和系膜细胞弥漫增生为特点。"},{"q":"间质性肺炎的特点不包括","o":["好发于儿童和青年","主要由肺炎支原体和病毒引起","一般无肺实变体征","预后大多较差","肺间质淋巴细胞和单核细胞浸润"],"a":3,"e":"间质性肺炎多由肺炎支原体和病毒引起，好发于儿童和青年，病变位于肺间质，无肺实变体征，预后大多良好。"},{"q":"侵蚀性葡萄胎与绒毛膜癌的主要区别是","o":["细胞有明显的增生和异型性","浸润肌层","有出血坏死","转移的阴道结节","有绒毛结构"],"a":4,"e":"侵蚀性葡萄胎与绒毛膜癌均可浸润肌层、出血坏死并发生转移，鉴别关键是前者仍可见水泡状绒毛结构，后者由分化不良的滋养细胞组成，无绒毛和间质血管。"},{"q":"下列哪项不符合凝固性坏死的特点","o":["坏死灶的质地较坚实","坏死灶体积可明显肿胀","坏死灶色泽灰白或黄白","坏死灶的水分含量减少","坏死灶的结构轮廓可保存"],"a":1,"e":"凝固性坏死时组织水分减少，坏死灶呈灰白或黄白色，质实而干燥，镜下组织轮廓可保存一段时间，体积不出现明显肿胀。"},{"q":"FISH主要检测细胞内哪项指标的变化","o":["基因拷贝数","DNA含量","mRNA含量","蛋白质含量","基因突变位点"],"a":0,"e":"FISH以荧光标记探针与染色体DNA原位杂交，主要用于检测基因拷贝数扩增或缺失以及染色体易位，不用于测定mRNA和蛋白质含量。"},{"q":"下述关于风湿性心内膜炎的叙述中，哪项是正确的","o":["瓣膜赘生物内有细菌","瓣膜赘生物牢固粘连","受累瓣膜容易发生穿孔、破裂","受累瓣膜以三尖瓣多见","赘生物位于房室瓣心室面"],"a":1,"e":"风湿性心内膜炎的疣状赘生物由血小板和纤维蛋白构成，附着牢固、不易脱落，且不含细菌；多位于二尖瓣心房面闭锁缘，一般不引起瓣膜穿孔。"},{"q":"如图，下列脾梗死的形态特征哪项是错误的","o":["组织轮廓尚保存","镜下呈凝固性坏死","梗死区呈锥形","梗死灶周围无炎症反应","梗死灶呈灰白色"],"a":3,"e":"脾梗死早期梗死灶与正常组织交界处因炎症反应出现充血出血带，并非无炎症反应。脾梗死为凝固性坏死，组织轮廓保存，切面呈灰白色锥形。"},{"q":"皮肤纤维组织细胞瘤的病变特点中，不包括","o":["病变呈漩涡状排列","病变多位于真皮和皮下","常见图顿巨细胞","瘤周呈高度浸润性生长，呈长条索状向周围脂肪伸展","有时可见泡沫样细胞"],"a":3,"e":"皮肤纤维组织细胞瘤位于真皮及皮下，由梭形纤维细胞和组织细胞构成，呈漩涡状或席纹状排列，可见图顿巨细胞和泡沫细胞；其边界较清，不呈高度浸润性生长。"},{"q":"下列不属于门脉高压症的表现的是","o":["脾大","肝大","食管-胃底静脉曲张","痔核形成","腹水"],"a":1,"e":"门静脉高压表现为脾大、食管胃底静脉曲张、痔核形成、腹水和腹壁静脉曲张；肝大是肝淤血或肝癌本身的表现，不属门脉高压症。"},{"q":"伤寒的传染途径是","o":["经口传染","呼吸传染","血液传染","接触传染","以上途径都可以"],"a":0,"e":"伤寒杆菌随患者粪便、尿排出，污染食物、饮水和牛奶，经口进入消化道而感染，属粪-口途径传播。"},{"q":"食管癌最好发的部位是","o":["上段","下段","中段","起始部","末端"],"a":2,"e":"食管癌好发于三个生理性狭窄部，以中段最多见，其次为下段，上段最少；中段癌常转移至食管旁及肺门淋巴结。"},{"q":"梗死灶的形状取决于","o":["坏死灶的大小","坏死的类型","梗死灶内的含血量","该器官的血管分布","侧支循环的建立"],"a":3,"e":"梗死灶的形状取决于该器官血管的分布方式：脾、肾、肺血管呈锥形分支，梗死灶呈锥形；肠梗死呈节段形，心肌梗死呈地图状。"},{"q":"流行性乙型脑炎的病变性质属于","o":["变质性炎","渗出性炎","增生性炎","肉芽肿性炎","化脓性炎"],"a":0,"e":"流行性乙型脑炎以神经细胞变性坏死、胶质细胞增生和血管周围淋巴细胞浸润为主，属变质性炎症。"},{"q":"早期胃癌是指","o":["仅限于黏膜下层以内","仅限于肌层以内","仅限于浆膜以内","仅限于局部淋巴结转移","仅限于扩散至邻近器官"],"a":0,"e":"早期胃癌指癌组织浸润仅限黏膜层或黏膜下层，无论有无淋巴结转移；浸润超过黏膜下层即属中晚期癌，直径小于0.5cm者称微小癌。"},{"q":"阴茎癌最常见的类型是","o":["腺癌","鳞状细胞癌","髓样癌","小管癌","黏液癌"],"a":1,"e":"阴茎鳞状细胞癌是起源于阴茎鳞状上皮的恶性肿瘤，为阴茎癌最常见的组织学类型。腺癌、髓样癌、黏液癌均少见。"},{"q":"高血压患者肾脏，其大体如图所示，该肾脏又称为","o":["继发性颗粒性固缩肾","大红肾","原发性颗粒性固缩肾","大白肾","蚤咬肾"],"a":2,"e":"官方题库缺失图片"},{"q":"慢性浅表性胃炎肉眼所见主要是","o":["胃黏膜失去正常光泽","胃黏膜皱襞变浅或消失","胃黏膜薄而光滑","可见黏膜充血、水肿","黏膜下小血管清晰可见"],"a":3,"e":"慢性浅表性胃炎肉眼见胃黏膜充血、水肿，呈淡红色，可伴点状出血和糜烂，黏膜皱襞及腺体保持完整，不出现变薄和皱襞消失。"},{"q":"下列哪项不是慢性肾盂肾炎的主要病变特点","o":["病变可单侧也可双侧发生，且两侧改变不对称","肉眼观表现为肾体积缩小，有瘢痕","均由急性肾盂肾炎转变而来","代偿扩张的肾小管内可出现甲状腺滤泡样管型","肾盂、肾盏变形，黏膜粗糙"],"a":2,"e":"慢性肾盂肾炎可单侧或双侧、两侧不对称，肾缩小并有瘢痕、肾盂肾盏变形，扩张的肾小管内可见甲状腺滤泡样管型；部分病例无急性期病史，可隐匿起病。"},{"q":"慢性胃溃疡最多见的部位是","o":["大弯近幽门部","小弯近幽门部","近贲门部","小弯角切迹部","小弯近胃窦部"],"a":4,"e":"胃溃疡多位于胃小弯近胃窦部，该处黏膜与胃酸和胃蛋白酶接触时间长，血供及再生能力较弱，易被消化形成溃疡。"},{"q":"下列哪项是发生干性坏疽的条件","o":["发生于肺或子宫等内脏","有明显的腐败菌感染","全身中毒症状严重","病变部分较干燥，腐败菌感染较轻","病灶内坏死组织分界，产生大量气体"],"a":3,"e":"干性坏疽见于动脉阻塞而静脉回流仍通畅的四肢末端，水分蒸发多使坏死组织干燥皱缩、呈黑色，与正常组织界限清楚，腐败菌感染较轻。"},{"q":"冠状动脉粥样硬化最常受累的动脉分支是","o":["右冠状动脉主干","左冠状动脉主干","左冠状动脉回旋支","右冠状动脉后降支","左冠状动脉前降支"],"a":4,"e":"冠状动脉粥样硬化以左冠状动脉前降支受累最多，其后依次为右主干、左主干或左旋支、后降支；前降支供血区约占全部心肌梗死的一半。"},{"q":"下列哪项不是慢性阻塞性肺病的共同特征","o":["呼气阻力增加","肺组织实变","肺实质受损害","小气道受损害","肺功能不全"],"a":1,"e":"COPD的共同特点是肺实质与小气道受损，导致气道阻塞、呼气阻力增加和肺功能不全；肺组织实变是肺炎的渗出性病变，不属于COPD。"},{"q":"亚急性细菌性心内膜炎的特点除外下列哪项","o":["赘生物单个或多个，呈息肉状或菜花状","多发生于原有病变的瓣膜上","镜下表面有细菌团","赘生物脱落引起动脉栓塞和血管炎","外观污秽、质松软、灰黄、易脱落"],"a":2,"e":"亚急性感染性心内膜炎的赘生物由纤维蛋白、血小板和坏死组织构成，细菌被包裹于赘生物内部，表面无细菌团，赘生物松软易脱落引起动脉栓塞。"},{"q":"小叶性肺炎的病变性质是","o":["浆液性炎","卡他性炎","肉芽肿性炎","化脓性炎","纤维素性炎"],"a":3,"e":"小叶性肺炎由化脓性细菌引起，以细支气管为中心形成肺小叶的化脓性炎，病灶散在分布于双肺下叶和背侧。"},{"q":"下列不是扩张型心肌病心肌组织的镜下特点的是","o":["心肌细胞呈均匀性肥大","核大、深染","核形不整，出现沟裂","胞质空泡变性、嗜酸性变","小灶性液化性肌溶解"],"a":0,"e":"扩张型心肌病镜下心肌细胞呈不均匀性肥大与萎缩交错，核大深染、核形不整，胞质空泡变性，可见小灶性肌溶解；均匀性肥大见于压力负荷过重者。"},{"q":"下列关于乙型脑炎病理改变的描述错误的是","o":["小血管周围有“血管套”形成","神经细胞变性坏死","筛状软化灶形成","胶质结节形成","蛛网膜下腔有较多的中性粒细胞"],"a":4,"e":"乙脑病变在脑实质，可见神经细胞变性坏死、血管淋巴套、筛状软化灶和胶质结节；脑膜病变轻微，为淋巴细胞浸润，蛛网膜下腔大量中性粒细胞是流脑的表现。"},{"q":"微小病变病电镜下特征性病变是","o":["肾小球系膜内见致密沉积物","系膜细胞增生","肾小球毛细血管壁增厚","脏层上皮细胞足突广泛消失","肾小球毛细血管基膜上皮细胞侧见致密沉积物"],"a":3,"e":"微小病变性肾小球病的特征性电镜改变为弥漫性脏层上皮细胞足突消失，基膜正常、无电子致密物沉积；光镜下肾小球基本正常，免疫荧光阴性。"},{"q":"二尖瓣关闭不全与狭窄的病变不同之处是","o":["左心房肥大","右心房肥大","左心室肥大","右心室肥大","体循环淤血"],"a":2,"e":"二尖瓣狭窄时左心室舒张期充盈减少，左心室不肥大；关闭不全时舒张期左心室同时接受左心房回流血，容量负荷增加引起左心室肥大，为本病与狭窄的重要不同。"},{"q":"纤维素样坏死常发生于","o":["骨组织、细动脉壁","结缔组织、平滑肌组织","神经组织、细动脉壁","鳞状上皮组织、移行上皮组织","结缔组织、细动脉壁"],"a":4,"e":"纤维素样坏死是结缔组织及细小动脉壁的常见坏死类型，表现为红染无结构的纤维素样物质。细小动脉壁玻璃样变见于缓进型高血压和糖尿病，与纤维素样坏死不同。"},{"q":"肾细胞癌最常发生于","o":["随机发生","肾中部","肾下极","肾上极","肾门"],"a":3,"e":"肾细胞癌多发生于肾脏上、下两极，以上极更为常见，常为单侧单发，切面淡黄或灰白，可有出血坏死，转移最常至肺和骨。"},{"q":"肺气肿大体表现的描述不正确的是","o":["肺体积膨大","指压后压痕不易消退","肺边缘锐利","柔软，缺乏弹性","入水漂浮"],"a":2,"e":"肺气肿时肺体积显著膨大、色灰白、边缘钝圆而非锐利，柔软缺乏弹性，指压后压痕不易消退，因含气量多而浮于水。"},{"q":"肝细胞大片崩解坏死并有肝细胞结节状再生者见于","o":["慢性持续性肝炎","慢性活动性肝炎","亚急性重型肝炎","急性普通型肝炎","急性重型肝炎"],"a":2,"e":"亚急性重型肝炎在肝细胞大片坏死的同时，残存肝细胞呈结节状再生，形成大小不等的再生结节并伴纤维组织增生。急性重型肝炎无结节状再生，肝体积明显缩小。"},{"q":"前列腺癌常见的类型为","o":["鳞状细胞癌","移行细胞癌","腺癌","透明细胞癌","腺鳞癌"],"a":2,"e":"前列腺癌源自前列腺上皮，组织学类型以腺癌最常见。骨转移为前列腺癌常见转移部位。"},{"q":"中晚期食管癌最常见的肉眼类型是","o":["髓质型","缩窄型","溃疡型","蕈伞型","隆起型"],"a":2,"e":"官方答案为【溃疡型】，但依据教材，正确答案为【髓质型】。中晚期食管癌分髓质型、蕈伞型、溃疡型和缩窄型，髓质型癌组织在壁内浸润生长、管壁均匀增厚，最多见，约占60%。"},{"q":"大叶性肺炎合并肺肉质变的机制是","o":["病变范围太广","纤维素渗出太多","吞噬细胞渗出太少","肺组织结构被炎症破坏","病程太长"],"a":2,"e":"大叶性肺炎时肺泡内纤维蛋白渗出过多，而中性粒细胞渗出少、释放的蛋白水解酶不足，纤维蛋白不能被溶解吸收，由肉芽组织机化而形成肺肉质变。"},{"q":"动脉粥样硬化的早期病变中，最早迁入内膜的细胞是","o":["单核细胞","淋巴细胞","平滑肌细胞","成纤维细胞","中性粒细胞"],"a":0,"e":"内皮损伤后分泌趋化因子，最先吸引单核细胞黏附并迁入内皮下间隙，摄取氧化型LDL转变为泡沫细胞；平滑肌细胞迁入较晚，T淋巴细胞随后参与。"},{"q":"关于血管瘤的叙述，下列哪项是错误的","o":["无包膜，呈浸润性生长","多为先天性","随身体发育而长大，可自然消退","对放射治疗和化疗敏感","多发生于皮肤"],"a":3,"e":"血管瘤多为先天性，无包膜呈浸润性生长，随身体发育而长大并可自然消退，对放射治疗和化学治疗不敏感，此点与血管肉瘤不同。"},{"q":"主动脉关闭不全的患者有以下临床表现，除外","o":["股动脉枪击音","X线示心脏增大","主动脉瓣区收缩期杂音","水冲脉","脉压增大"],"a":2,"e":"主动脉瓣关闭不全时舒张期血液反流，脉压增大，出现水冲脉、股动脉枪击音及左心室增大；收缩期喷射性杂音是主动脉瓣狭窄的体征。"},{"q":"慢性胃炎是","o":["细菌引起的胃黏膜的一种特异性炎症","病毒引起的胃黏膜的一种特异性炎症","支原体引起的胃黏膜的一种特异性炎症","病原微生物引起的胃黏膜的一种非特异性炎症","不同原因引起的胃黏膜的一种非特异性炎症"],"a":4,"e":"慢性胃炎是胃黏膜的慢性非特异性炎症，由幽门螺杆菌感染、胆汁反流、药物、酒精等多种不同原因引起，并非某种病原体所致的特异性炎症。"},{"q":"慢性风湿性瓣膜病常见的联合瓣膜病变是","o":["二尖瓣和三尖瓣病变","二尖瓣、主动脉瓣和三尖瓣病变","主动脉瓣和三尖瓣病变","二尖瓣和主动脉瓣病变","主动脉瓣和肺动脉瓣病变"],"a":3,"e":"慢性风湿性瓣膜病以二尖瓣受累最多，约占70%，其次为二尖瓣合并主动脉瓣病变，占20%～30%，三尖瓣和肺动脉瓣极少受累。"},{"q":"血栓转归中不会发生的是","o":["钙化","溶解","化生","机化","再通"],"a":2,"e":"血栓的结局为溶解吸收、机化再通、钙化和脱落栓塞，不会发生化生。化生是已分化成熟的组织转变为另一种分化成熟组织的过程。"},{"q":"不是急性胆囊炎的临床转归的是","o":["急性化脓性胆囊炎","慢性胆囊炎","蜂窝织炎性胆囊炎","胆囊癌","坏疽性胆囊炎"],"a":3,"e":"急性胆囊炎可发展为蜂窝织炎性胆囊炎、坏疽性胆囊炎，也可转为慢性胆囊炎；胆囊癌是独立恶性肿瘤，与胆囊结石长期刺激有关，不属急性炎症的转归。"},{"q":"如图所示，在慢性炎症灶中以下列哪种细胞最常见","o":["嗜酸性粒细胞","肥大细胞","淋巴细胞","嗜碱性粒细胞","中性粒细胞"],"a":2,"e":"官方题库缺失图片"},{"q":"急性感染性心内膜炎不存在的特点是","o":["常发生于原来已有病变的心瓣膜上","常是致病力强的化脓菌引起的脓毒血症的并发症之一","可致瓣膜糜烂、穿孔或破裂","主要侵犯二尖瓣或主动脉瓣","瓣膜表面常形成巨大的、松脆的含细菌的赘生物"],"a":0,"e":"急性感染性心内膜炎多发生于正常瓣膜，在已有病变瓣膜上形成赘生物是亚急性感染性心内膜炎的特点；前者由化脓菌引起脓毒败血症所致，赘生物巨大松脆含菌，可致瓣膜糜烂穿孔。"},{"q":"大肠癌的好发部位是","o":["升结肠","横结肠","降结肠","乙状结肠","直肠"],"a":4,"e":"结直肠癌好发部位以直肠最多见，约占50%，其余依次为乙状结肠、升结肠、横结肠、降结肠。"},{"q":"下列关于Barrett食管的叙述错误的是","o":["胃食管反流是Barrett食管形成的主要原因","Barrett食管发生食管腺癌的危险性与病灶大小有关","内镜下可表现为齿状线上方数厘米处食管黏膜呈橘红色","Barrett食管容易发生鳞状细胞癌","组织学上可见鳞状上皮被柱状上皮所取代，若出现杯状细胞便可确诊"],"a":3,"e":"Barrett食管是食管远端鳞状上皮被柱状上皮取代，出现杯状细胞即可确诊，属食管腺癌的癌前病变，癌变危险性与病灶范围有关。"},{"q":"淋巴结转移性肿瘤首先出现于淋巴结的","o":["副皮质区","髓质","边缘窦","髓窦","淋巴滤泡"],"a":2,"e":"瘤细胞经输入淋巴管进入淋巴结后，先滞留于被膜下的边缘窦，再累及皮质和髓质，使淋巴结肿大、质地变硬。"},{"q":"甲状腺恶性肿瘤中生长慢，恶性程度低，发病率最高的是","o":["滤泡癌","乳头状癌","髓样癌","未分化癌","肉瘤"],"a":1,"e":"甲状腺乳头状癌占甲状腺癌的60%，青少年女性多见，肿瘤生长缓慢、恶性程度低、预后好，10年生存率达80%以上。"},{"q":"对原发性胰腺癌的诊断最有价值的检查是","o":["血清酸性磷酸酶活性升高","血清甲胎蛋白（AFP）升高","血清癌胚抗原（CEA）升高","血清谷丙转氨酶活性升高","血清糖类抗原19-9（CA19-9）升高"],"a":4,"e":"CA19-9是胰腺癌最常用的血清标志物，对原发性胰腺癌的诊断、疗效监测和复发判断价值最高；AFP用于肝癌，CEA特异性差，酸性磷酸酶与前列腺癌相关。"},{"q":"双侧卵巢Krukenberg瘤最常来源于","o":["卵巢","肠","胆囊","胃","乳房"],"a":3,"e":"Krukenberg瘤是双侧卵巢的转移性黏液腺癌，多由胃的印戒细胞癌经腹膜种植转移而来。"},{"q":"鼻咽癌最常转移到","o":["左锁骨上淋巴结","右锁骨上淋巴结","纵隔淋巴结","中央区淋巴结","颈上深淋巴结"],"a":4,"e":"鼻咽癌经咽后壁淋巴结转移至颈上深淋巴结，常在胸锁乳突肌后缘上1/3与2/3交界处出现无痛性结节，且常为首发症状而就诊。"},{"q":"毛玻璃样肝细胞内嗜酸性颗粒的成分是","o":["包涵体","凋亡小体","细胞内玻璃样变性","内质网池","HBsAg"],"a":4,"e":"毛玻璃样肝细胞胞质内充满嗜酸性细颗粒，免疫组化及免疫荧光示HBsAg阳性，电镜下为滑面内质网池内堆积的HBsAg颗粒。"},{"q":"患者颈部淋巴结肿大，病理检查发现有泡状核细胞癌转移，其来源为","o":["肺部","鼻咽部","气管","喉","胸膜"],"a":1,"e":"泡状核细胞癌是鼻咽癌未分化型的一种，癌细胞核大呈空泡状、核仁明显，呈合体状排列，常以颈部淋巴结转移为首发表现。"},{"q":"最容易引起皮肤潮红、水样腹泻、心动过速、支气管哮喘等症状的肺癌类型是","o":["大细胞癌","黏液癌","类癌","未分化腺癌","低分化鳞状细胞癌"],"a":2,"e":"肺类癌起源于神经内分泌细胞，可分泌5-羟色胺等活性物质，引起皮肤潮红、水样腹泻、心动过速和支气管痉挛等类癌综合征表现。"},{"q":"下列哪项是变质性炎症","o":["肾盂肾炎","菌痢","大叶性肺炎","阿米巴肝脓肿","阑尾炎"],"a":3,"e":"阿米巴肝脓肿由溶组织内阿米巴滋养体溶解破坏肝组织形成，以组织液化性坏死为主，属变质性炎；菌痢、大叶性肺炎分别为纤维蛋白性炎，阑尾炎为化脓性炎。"},{"q":"关于浸润性生长，正确的是","o":["是恶性肿瘤所独有的生长方式","是良性肿瘤所独有的生长方式","良、恶性肿瘤均可以呈浸润性生长","良、恶性肿瘤均不可以呈浸润性生长","多数良性肿瘤的主要生长方式"],"a":2,"e":"浸润性生长并非恶性肿瘤独有，血管瘤、淋巴管瘤等良性肿瘤亦可呈浸润性生长；但恶性肿瘤以此为常见生长方式，且伴明显异型性和转移能力。"},{"q":"引起出血性炎的主要原因是","o":["血管破裂","血管壁损伤较重","组织缺血缺氧","组织内胶体渗透压升高","血浆晶体渗透压升高"],"a":1,"e":"出血性炎因血管壁损伤较重、通透性显著增高，红细胞大量漏出，常见于流行性出血热、钩端螺旋体病和鼠疫等烈性传染病。"},{"q":"关于肺硅沉着病，错误的说法是","o":["是一种常见职业病","脱离硅尘作业环境后病变不再进一步发展","硅结节中央常形成空洞","基本病变为硅结节和肺组织弥漫性纤维化","是一种慢性疾病"],"a":1,"e":"硅肺由长期吸入游离二氧化硅粉尘引起，基本病变为硅结节和肺组织弥漫性纤维化，病程慢性；巨噬细胞破裂后硅尘再释放，即使脱离作业环境病变仍持续进展。"},{"q":"引起支气管哮喘典型症状的主要机制是","o":["管壁大量炎性细胞浸润","支气管壁平滑肌痉挛","腔内黏液栓阻塞","黏膜水肿、基膜增厚","黏膜上皮杯状细胞增多、黏液腺增生"],"a":1,"e":"支气管哮喘发作时支气管壁平滑肌痉挛使管腔狭窄，引起呼气性呼吸困难伴哮鸣音，是典型症状的主要机制；黏膜水肿和黏液栓为辅助因素。"},{"q":"不属于法洛四联症的是","o":["肺动脉狭窄","房间隔缺损","室间隔缺损","主动脉骑跨","右心室肥厚"],"a":1,"e":"法洛四联症由肺动脉狭窄、室间隔缺损、主动脉骑跨和右心室肥厚四种畸形构成，属发绀型先天性心脏病；房间隔缺损为独立畸形。"},{"q":"亚急性甲状腺炎较特征性的病理学改变是甲状腺","o":["体积增大、不对称","切面见斑片状坏死","滤泡被破坏","肉芽肿性炎","纤维化"],"a":3,"e":"亚急性甲状腺炎时滤泡破坏、胶质外溢，引起异物巨细胞和上皮样细胞增生，形成类似结核结节的肉芽肿，故属肉芽肿性炎。"},{"q":"慢性萎缩性胃炎A型患者病变主要在","o":["胃窦","胃体","胃体和胃底","胃小弯","胃大弯"],"a":2,"e":"A型慢性萎缩性胃炎属自身免疫性，病变位于胃体和胃底，壁细胞抗体和内因子抗体阳性，胃酸显著降低，可因维生素B12吸收障碍并发恶性贫血。"},{"q":"虫媒病毒性脑炎病变部位最常见于","o":["颞叶","海马及小脑","大脑白质","脊髓","大脑皮质、基底节及视丘"],"a":4,"e":"流行性乙型脑炎病变广泛累及脑脊髓实质，以大脑皮质、基底核和视丘最严重，小脑皮质、丘脑和脑桥次之，脊髓病变最轻。"},{"q":"慢性支气管炎的描述，正确的是","o":["黏液脓性痰","咳铁锈色痰","黏液泡沫痰","呼吸困难","桶状胸"],"a":2,"e":"慢性支气管炎因黏液腺增生、分泌亢进，咳白色黏液泡沫痰，急性发作时转为黏液脓痰；铁锈色痰见于大叶性肺炎。"},{"q":"关于反流性食管炎的表述错误的是","o":["可见基底细胞增生","反流性食管炎的改变与病因、持续时间和病程的长短有关","长期病变可形成Barrett食管","上皮层嗜酸性粒细胞浸润是反流性食管炎的早期病变","组织学上表现为鳞状上皮的重度异型增生"],"a":4,"e":"反流性食管炎早期见上皮基底层增厚、乳头延长及嗜酸性粒细胞浸润，长期反流可形成Barrett食管；鳞状上皮重度异型增生属癌前病变，不是其组织学表现。"},{"q":"下列与肝细胞癌发生无关的因素是","o":["HBV，HCV","亚硝胺类化合物","黄曲霉毒素","某些藻类毒素","华支睾吸虫"],"a":4,"e":"华支睾吸虫感染与肝内胆管癌有关；肝细胞癌的主要相关因素为HBV、HCV感染、黄曲霉毒素、亚硝胺类化合物及藻类毒素。"},{"q":"减压病的发生主要是由于","o":["氧气栓塞","氮气栓塞","二氧化碳栓塞","氢气栓塞","混合气体栓塞"],"a":1,"e":"减压病是气体栓塞的一种：从高压环境迅速转入常压时，血中溶解的气体析出形成气泡，氮气在体液内溶解迟缓，故栓塞主要由氮气引起。"},{"q":"下列哪个器官的梗死灶为节段性","o":["脑","肝","心脏","小肠","脾"],"a":3,"e":"肠系膜血管呈扇形分支支配某一肠段，故肠梗死灶呈节段形；心冠状动脉分支不规则，心肌梗死灶呈地图状，脾、肾梗死灶则为楔形。"},{"q":"下述支持胃的恶性溃疡的是","o":["溃疡呈圆形，椭圆形","边缘整齐，不隆起","底部较平坦","火山口状，底部凹凸不平","皱襞向溃疡集中"],"a":3,"e":"恶性溃疡大体呈皿状或不规则火山口状，直径常大于2cm，边缘隆起不整齐，底部凹凸不平并有坏死出血；圆形、边缘整齐、皱襞集中是良性溃疡的表现。"},{"q":"阑尾系膜静脉血栓形成易见于下列哪种阑尾炎","o":["急性坏疽性阑尾炎","慢性阑尾炎急性发作","急性单纯性阑尾炎","慢性阑尾炎","急性蜂窝织炎性阑尾炎"],"a":0,"e":"急性坏疽性阑尾炎时炎症波及阑尾系膜静脉，引起血栓性静脉炎，加之阑尾腔阻塞积脓、腔内压升高，导致阑尾壁血液循环障碍而发生坏死。"},{"q":"慢性萎缩性胃炎的特征性病变是","o":["黏膜固有层淋巴细胞和浆细胞浸润","黏膜层有水肿、点状出血和上皮坏死","腺上皮萎缩伴淋巴细胞和浆细胞浸润","腺体萎缩伴肠上皮化生","腺上皮增生伴肠上皮化生"],"a":3,"e":"慢性萎缩性胃炎的特征是胃黏膜变薄、腺体减少或消失，伴肠上皮化生以及固有层内多量淋巴细胞、浆细胞浸润。"},{"q":"关于肺硅沉着病的叙述错误的是","o":["长期吸入游离的二氧化硅引起","及时脱离硅尘环境可防止病情发展","基本病变是硅结节形成和肺广泛纤维化","易激发肺的细菌和病毒感染","晚期常并发肺源性心脏病"],"a":1,"e":"硅肺即使脱离硅尘接触，肺部病变仍继续发展，故脱离环境不能防止病情进展。吸入游离二氧化硅粉尘是其主要病因，基本病变为硅结节和肺纤维化。"},{"q":"慢性胰腺炎患者，最不可能出现的情况是","o":["胰腺假囊肿","糖尿病","肥胖","胰腺癌","脂肪泻"],"a":2,"e":"慢性胰腺炎因胰酶分泌不足致脂肪和蛋白质消化吸收障碍，出现脂肪泻和消瘦，可并发假性囊肿、糖尿病及胰腺癌，肥胖不是其表现。"},{"q":"慢性胃溃疡最好发的部位是","o":["胃大弯近幽门部","胃大弯近贲门部","胃小弯近幽门部","胃小弯近贲门部","胃体小弯侧"],"a":2,"e":"胃溃疡多位于胃小弯侧，愈近幽门愈多见，尤多见于胃窦部，少见于胃底及大弯侧。溃疡常单发，呈圆形或椭圆形，直径多在2cm以内。"},{"q":"下述哪种因素与血栓形成无关","o":["血管内膜损伤","血小板数量增多","血流缓慢","癌细胞崩解产物","纤溶酶增加"],"a":4,"e":"血栓形成的条件为心血管内膜损伤、血流状态改变和血液凝固性增高；纤溶酶增加促进血栓溶解，属抗血栓因素，与血栓形成无关。"},{"q":"下列哪项不是引起肾盂肾炎的主要诱因","o":["感染","机体抵抗力下降","尿路阻塞","抗原抗体反应","膀胱输尿管反流"],"a":3,"e":"肾盂肾炎由细菌感染引起，常见诱因为尿路阻塞、膀胱输尿管反流和机体抵抗力下降；抗原抗体反应是肾小球肾炎的发病机制。"},{"q":"血源性感染性肾盂肾炎的最常见病原菌是","o":["大肠杆菌","链球菌","金黄色葡萄球菌","真菌","肠球菌"],"a":2,"e":"血源性感染性肾盂肾炎的病原菌以金黄色葡萄球菌最常见，细菌经血流至肾；上行性感染则以大肠杆菌最多见，二者感染途径与致病菌不同。"},{"q":"细菌性痢疾病变的最好发部位是","o":["空肠","回肠下段","回盲部","横结肠","乙状结肠和直肠"],"a":4,"e":"细菌性痢疾病变主要发生于大肠，尤以乙状结肠和直肠最重。阿米巴病则好发于盲肠和升结肠，可资鉴别。"},{"q":"流行性乙型脑炎时，病变的主要部位是","o":["大脑皮质","大脑灰质","小脑","大脑皮质及基底节、丘脑","软脑膜"],"a":3,"e":"流行性乙型脑炎病变以大脑皮质、基底核和视丘最为严重，小脑皮质、丘脑和脑桥次之，脊髓病变最轻。肉眼可见脑实质散在点状出血及半透明软化灶。"},{"q":"动脉性充血的主要病理变化是","o":["器官体积肿大","器官重量增加","局部呈红色","小动脉和毛细血管扩张，充满红细胞","局部温度升高"],"a":3,"e":"动脉性充血属主动性充血，镜下主要变化为局部细动脉和毛细血管扩张、充满红细胞，血液输入量增多，致局部鲜红、温度升高。"},{"q":"下列哪项病变不是假小叶的特点","o":["中央静脉缺失","肝细胞广泛凋亡，大量凋亡小体形成","可有2个以上中央静脉","肝细胞排列紊乱，有不同程度的坏死或脂肪变性","出现门管区"],"a":1,"e":"假小叶特点为中央静脉缺如或偏位、可有2个以上中央静脉、肝细胞排列紊乱伴变性坏死，并含门管区；大量凋亡小体形成不是其形态特征。"},{"q":"头皮血肿被肉芽组织所取代，这种现象称为","o":["肉芽组织形成","肉芽肿形成","机化","纤维化","血栓机化"],"a":2,"e":"坏死组织、血栓、血肿或异物被新生肉芽组织取代并最终形成瘢痕的过程称机化，头皮血肿被肉芽组织取代后纤维化正属机化。"},{"q":"下列哪项不是化生","o":["成纤维细胞变为纤维细胞","成纤维细胞变为成骨细胞","膀胱黏膜出现了鳞状上皮","柱状上皮转变为移行上皮","胃黏膜上皮转变为肠上皮"],"a":0,"e":"化生是分化成熟的细胞由一种类型转变为另一种类型，如柱状上皮转为鳞状上皮；成纤维细胞成熟为纤维细胞只是功能与形态状态的改变，不属化生。"},{"q":"关于慢性硬化性肾小球肾炎的叙述，下列正确的是","o":["无肾小球肾炎的病史","可形成原发性颗粒性固缩肾","蛋白尿、管型尿进行性加重","常有贫血、持续性高血压和肾功能不全","最常见的死亡原因是冠心病"],"a":3,"e":"慢性硬化性肾小球肾炎是各型肾炎的终末阶段，肾单位大量破坏使促红细胞生成素减少、水钠潴留，出现贫血、持续性高血压和肾功能不全。双肾对称缩小、表面细颗粒状，为继发性颗粒性固缩肾。"},{"q":"大叶性肺炎患者灰色肝样变期与红色肝样变期的临床表现不同在于","o":["胸痛消失","咳铁锈色痰","缺氧状况有所好转","重新出现啰音","开始出现肺实变体征"],"a":2,"e":"灰色肝样变期肺泡间隔毛细血管受压、血流量减少，静脉血氧含量不足减轻，缺氧症状因而好转；红色肝样变期因肺泡通气受阻、大量红细胞渗出，发绀明显。"},{"q":"淤血不会引起","o":["水肿","脂肪变","实质细胞增生","局部缺氧","胶原纤维增生"],"a":2,"e":"淤血使局部缺氧、毛细血管内压升高，可致水肿、出血、实质细胞萎缩和脂肪变，长期淤血还引起间质纤维组织增生。实质细胞增生属炎症或代偿反应，不是淤血的后果。"},{"q":"子宫内膜非典型增生与高分化子宫内膜癌鉴别的基本要点是","o":["细胞乳头状增生","宫内膜鳞状上皮化生","间质浸润","间质纤维组织增生","宫内膜细胞嗜酸性变"],"a":2,"e":"子宫内膜不典型增生为子宫内膜样癌的前驱病变，无间质浸润；高分化子宫内膜癌则癌细胞侵破基底膜浸润间质。间质浸润是二者鉴别的根本要点。"},{"q":"下列关于肾细胞癌的主要特点正确的是","o":["无血尿","不发生出血","肿瘤间质丰富，血管少","肿瘤组织内可见软骨、肌肉","侵犯肾静脉，有血管内生长倾向"],"a":4,"e":"肾细胞癌易侵犯肾静脉形成柱状瘤栓，并延伸至下腔静脉甚至右心；肿瘤间质少而血管丰富，常伴血尿，故间质丰富、血管少的描述不符。"},{"q":"门脉性肝硬化形成过程中的基本病理变化为","o":["肝细胞变性、坏死，肝纤维化","肝内胆管上皮增生，肝纤维化","肝细胞变性、坏死，肝细胞再生，肝弥漫性纤维化","肝细胞再生，肝纤维化","肝细胞变性、坏死，Kupffer细胞增生"],"a":2,"e":"肝硬化基本病理特征为慢性进行性、弥漫性肝细胞变性坏死、纤维组织增生和肝细胞结节状再生，三者共同构成假小叶形成的基础。"},{"q":"如图所示，下列哪种细胞参与形成卫星现象","o":["小胶质细胞","淋巴细胞","星形细胞","中性粒细胞","少突胶质细胞"],"a":4,"e":"官方题库缺失图片"},{"q":"下列关于风湿病的病因和发病机制的叙述错误的是","o":["本病多始发于儿童","患者血清抗链球菌抗体滴度明显升高","多见于热带地区","发病前多先有急性扁桃体炎和咽峡炎","抗生素的广泛应用，降低了风湿病的发病率"],"a":2,"e":"风湿病多发于寒冷潮湿的温带地区，我国以东北、华北较多，与A组乙型溶血性链球菌感染后的变态反应有关，热带地区少见。"},{"q":"有关血栓形成规律的说法中，不正确的是","o":["静脉血栓多于动脉血栓","下肢血栓多于上肢血栓","心腔内多形成附壁血栓","静脉血栓多为红色血栓","透明血栓多发生于微循环内"],"a":3,"e":"静脉血栓多为混合血栓，仅其尾部在血流停滞处形成红色血栓；静脉血栓多于动脉、下肢多于上肢，心腔内多为附壁血栓，透明血栓见于微循环。"},{"q":"下述炎症改变中，最有防御意义的是","o":["渗出液的产生","氧自由基释放","白细胞渗出","血液停滞","炎症介质形成"],"a":2,"e":"白细胞渗出是炎症反应最重要的特征，白细胞游出后沿趋化因子浓度梯度到达炎症灶，发挥吞噬和免疫防御作用。"},{"q":"下肢静脉内血栓形成后，对机体的最为严重的后果是","o":["血栓脱落后引起冠状动脉栓塞","阻塞血管，引起下肢急性梗死","血栓被机化后永久阻塞下肢血管","血栓脱落后引起肺动脉栓塞","形成静脉石后造成下肢静脉的永久性阻塞"],"a":3,"e":"下肢深静脉血栓脱落后随静脉血经右心进入肺动脉，引起肺动脉栓塞，大栓子嵌顿肺动脉主干可致猝死，是最严重的后果，一般不引起体循环动脉栓塞。"},{"q":"血栓形成是指","o":["在活体的心脏和血管内血液成分形成固体质块的过程","血液发生凝固形成固体质块的过程","在活体组织内血液发生凝固形成固体质块的过程","血液在静止状态中发生的异常凝固","活体组织内红细胞发生凝固形成固体质块的过程"],"a":0,"e":"血栓形成指在活体的心脏和血管内，血液发生凝固或某些有形成分凝集形成固体质块的过程，所成质块称血栓，须与死后血凝块相区别。"},{"q":"血吸虫病时，引起机体损害最为严重的是","o":["尾蚴","童虫","死亡童虫","虫卵","成虫"],"a":3,"e":"血吸虫各虫期均可损伤宿主，但以虫卵引起的病变最严重：虫卵沉积于肝、肠形成虫卵结节，导致纤维化、门静脉高压和肠壁溃疡，是本病的主要危害。"},{"q":"脱落细胞涂片最常用的固定液是","o":["95%的乙醇","乙醚-乙醇混合液","Carnoy氏液","甲醇","甲醛"],"a":0,"e":"脱落细胞涂片最常用的固定液是95%的乙醇，其渗透力强，能迅速固定细胞并保持细胞形态结构。甲醇、甲醛及Carnoy液等虽也可用于固定，但常规首选95%乙醇。"},{"q":"上消化道大量出血最常见的原因是","o":["慢性浅表性胃炎","慢性萎缩性胃炎","革囊胃","溃疡病","巨大肥厚性胃炎"],"a":3,"e":"消化性溃疡侵蚀溃疡底部血管是上消化道大量出血最常见的原因，占半数以上；慢性胃炎和胃癌引起的大出血相对少见。"},{"q":"下列肺部炎症中属纤维素性炎的是","o":["肺结核","病毒性肺炎","大叶性肺炎","小叶性肺炎","支原体肺炎"],"a":2,"e":"大叶性肺炎以肺泡内弥漫性纤维蛋白渗出为特点，属纤维蛋白性炎；小叶性肺炎为化脓性炎，病毒性肺炎和支原体肺炎为间质性炎。"},{"q":"富于淋巴细胞的经典型霍奇金淋巴瘤常见的肿瘤细胞是","o":["双核RS细胞","LP细胞","陷窝细胞","干尸细胞","多形性细胞"],"a":0,"e":"富于淋巴细胞型经典型霍奇金淋巴瘤背景为大量小淋巴细胞，肿瘤细胞为典型R-S细胞，多呈双核；陷窝细胞见于结节硬化型。"},{"q":"大肠癌的病因与下列哪些因素无关","o":["家族高发的遗传因素","p53基因点突变","富于刺激性纤维质多的食物","MSH2基因点突变","高营养低纤维质的食物"],"a":2,"e":"高脂低纤维饮食、家族遗传倾向及p53、MSH2等基因突变均与大肠癌发生有关。膳食纤维可稀释致癌物、促进排便，纤维质多的食物属保护因素而非病因。"},{"q":"风湿小体发生于","o":["心瓣膜","心肌细胞","心肌间质","关节滑膜","心外膜"],"a":2,"e":"风湿小体位于心肌间质、心内膜下和皮下结缔组织，由纤维蛋白样坏死灶内的风湿细胞及少量淋巴细胞、浆细胞构成，常位于小血管旁，是风湿病的特征性肉芽肿。"},{"q":"坏死和坏疽的主要区别是","o":["发生部位不同","发生原因不同","有无腐败菌感染","是否存在淤血","动脉阻塞程度不同"],"a":2,"e":"坏疽是局部组织大块坏死并继发腐败菌感染，腐败菌分解血红蛋白产生硫化氢，使组织呈黑色；坏死则无腐败菌参与。"},{"q":"假小叶的特征性病变不包括","o":["纤维组织增生，分割包绕肝小叶形成肝细胞团","肝细胞紊乱、脂肪变性","肝细胞团内出现汇管区","肝细胞团内缺少中央静脉","肝细胞团内中央静脉数量偏位或有2个以上"],"a":1,"e":"假小叶内中央静脉缺如、偏位或有两个以上，可见汇管区被包入、纤维组织增生及慢性炎细胞浸润；肝细胞脂肪变性属肝细胞损伤，不是假小叶的特征。"},{"q":"下列哪项对大肠癌诊断有意义","o":["血清酸性磷酸酶活性增加","癌胚抗原（CEA）高度阳性","甲胎蛋白（AFP）阳性","转肽酶活性增高","谷丙转氨酶活性增高"],"a":1,"e":"癌胚抗原（CEA）水平升高常见于消化道癌，对大肠癌诊断有意义。甲胎蛋白主要见于肝细胞癌。"},{"q":"属于癌前病变的是","o":["大肠腺瘤","皮下脂肪瘤","皮肤纤维瘤","子宫平滑肌瘤","乳腺纤维腺瘤"],"a":0,"e":"大肠腺瘤属获得性癌前病变，经“腺瘤-癌序贯”通路可癌变。脂肪瘤、纤维瘤、平滑肌瘤、纤维腺瘤均为良性肿瘤。"},{"q":"最常引起卵巢Krukenberg瘤的为","o":["宫颈癌","乳腺癌","胃癌","肺癌","肝癌"],"a":2,"e":"Krukenberg瘤多由胃的印戒细胞癌经种植性转移至双侧卵巢形成，也可来自结肠癌等胃肠道黏液癌。"},{"q":"形成肉芽肿的心肌炎是","o":["白喉心肌炎","埃可病毒性心肌炎","柯萨奇病毒性心肌炎","特发性巨细胞性心肌炎","葡萄球菌性心肌炎"],"a":3,"e":"特发性巨细胞性心肌炎病灶内可见心肌灶状坏死和肉芽肿形成，中央为红染无结构坏死物，周围有淋巴细胞、单核细胞及多核巨细胞浸润。"},{"q":"乙型肝炎病毒的主要传播途径是","o":["经飞沫传播","昆虫媒介传播","经口传播","皮肤黏膜接触传播","经血行传播"],"a":4,"e":"乙型肝炎病毒主要经输血、血制品等血行途径传播，也可经密切接触和垂直传播。粪-口途径是甲型和戊型肝炎的传播方式，飞沫与昆虫媒介不传播HBV。"},{"q":"鼻咽癌最早侵犯的淋巴结是","o":["颈浅淋巴结","颈上深淋巴结","锁骨上淋巴结","咽后壁淋巴结","咽外侧壁淋巴结"],"a":3,"e":"鼻咽癌细胞先经咽后壁淋巴结转移至颈上深淋巴结，故最早受累者为咽后壁淋巴结；患者常以胸锁乳突肌后缘上段无痛性肿块首诊，此时原发灶症状可不明显。"},{"q":"除外下列哪项均为乙型脑炎的病变","o":["“血管套”形成","小脓肿形成","神经细胞变性坏死","软化灶形成","胶质细胞增生"],"a":1,"e":"乙型脑炎的病变为神经细胞变性坏死、淋巴细胞血管套、筛状软化灶和胶质细胞增生；小脓肿形成是流行性脑脊髓膜炎等化脓性炎的表现。"},{"q":"易发生癌变的食管炎是","o":["急性食管炎","慢性食管炎","Barrett食管","反流性食管炎","感染性食管炎"],"a":2,"e":"Barrett食管指食管远端鳞状上皮被柱状上皮取代，是胃食管反流的结果，也是大多数食管腺癌的癌前病变，可经异型增生进展为腺癌。"},{"q":"以下为乙脑基本病理变化，但除外","o":["脑脊髓膜化脓性炎","脑实质细胞变性坏死","脑实质内血管袖套样改变","脑内筛状软化灶形成","脑质小结形成"],"a":0,"e":"乙脑的基本病变位于脑实质，包括神经细胞变性坏死、血管淋巴套形成、筛状软化灶和胶质结节；脑脊髓膜化脓性炎是流脑的特征。"},{"q":"下列哪种疾病不会引起肺气肿","o":["慢性支气管炎","支气管扩张症","支气管哮喘","大叶性肺炎","小叶性肺炎"],"a":3,"e":"大叶性肺炎为肺泡内弥漫性纤维蛋白渗出性炎，病变经抗生素干预后多局限吸收，一般不破坏支气管壁，不引起肺气肿。慢性支气管炎、支气管扩张症、支气管哮喘和小叶性肺炎均可致气道阻塞而继发肺气肿。"},{"q":"下列哪项属于门脉性肝硬化的病变特点","o":["假小叶大小不等","纤维间隔较宽","炎细胞浸润明显","假小叶大小相仿","碎片状坏死"],"a":3,"e":"门脉性肝硬化相当于小结节型，假小叶大小相仿、直径多小于3mm，纤维间隔较细、炎细胞浸润较轻；假小叶大小不等、间隔宽大者见于坏死后性肝硬化。"},{"q":"下列器官很少发生梗死的是","o":["心","脾","肾","肝","肠"],"a":3,"e":"肝有肝动脉和门静脉双重供血，侧支循环丰富，故很少发生梗死；心、脾、肾和肠的动脉属终末支，阻塞后易发生梗死。"},{"q":"病毒性肺炎的可靠诊断依据是","o":["间质性肺炎","淋巴细胞、单核细胞为主的炎细胞浸润","上皮细胞内病毒包涵体","肺泡上皮细胞增生","肺泡腔变大"],"a":2,"e":"病毒性肺炎时增生的支气管、肺泡上皮细胞及多核巨细胞内可见病毒包涵体，检出包涵体是病理组织学诊断的可靠依据；间质炎症和淋巴细胞浸润缺乏特异性。"},{"q":"结核病的基本病变不包括","o":["渗出性病变","化脓性病变","变质性病变","增生性病变","肉芽肿性病变"],"a":1,"e":"结核病的基本病变为渗出、变质和增生三类，可相互转化；其中变质性病变为干酪样坏死，化脓性病变由化脓菌感染引起，不属结核基本病变。"},{"q":"炎症时白细胞游出后定向移动的主要原因是","o":["炎症部位的化学趋向性","白细胞的阿米巴样运动","血管内压升高","轴流消失白细胞边集","血管壁的通透性增高"],"a":0,"e":"白细胞游出后沿化学物质浓度梯度向化学刺激物作定向移动，即趋化作用，由炎症病灶产生的趋化性细胞因子介导。阿米巴样运动是游出的运动方式，并非定向移动的原因。"},{"q":"下列关于肝癌肉眼类型及组织类型均为多见的叙述中，哪项是正确的","o":["多结节型与胆管上皮癌多见","巨块型与肝细胞癌多见","多结节型与肝细胞癌多见","巨块型与混合性肝癌多见","弥漫型与混合性肝癌多见"],"a":2,"e":"原发性肝癌肉眼以多结节型最常见，组织学以肝细胞癌最多见，约占75%～85%；巨块型、弥漫型和肝内胆管癌均相对少见。"},{"q":"不能促进血小板聚集的是","o":["胶原纤维","凝血酶","血栓素A","ADP","前列环素"],"a":4,"e":"前列环素（PGI2）由内皮细胞合成，具有抑制血小板黏集的作用。胶原纤维、凝血酶、血栓素A2和ADP均促进血小板聚集。"},{"q":"噬神经细胞现象是指","o":["少突胶质细胞环绕神经元","神经细胞吞噬崩解的脂质","胶质细胞增生取代死亡的神经元","小胶质细胞、巨噬细胞包围吞噬死亡的神经元","中性粒细胞吞噬死亡的神经元"],"a":3,"e":"坏死的神经元被增生的小胶质细胞或血源性巨噬细胞包围吞噬，称噬神经细胞现象，是小胶质细胞对坏死神经元的一种反应。"},{"q":"大量空气迅速进入血液循环引起死亡的原因是","o":["心肌梗死","急性心力衰竭和呼吸衰竭","脑栓塞","肺梗死","心脏破裂"],"a":1,"e":"大量空气迅速入血，随血流进入右心并阻塞肺动脉出口，肺循环受阻，引起急性呼吸衰竭和急性右心衰竭而迅速死亡；少量气体可被吸收而无严重后果。"},{"q":"结节性淋巴细胞为主型霍奇金淋巴瘤，肿瘤细胞免疫表型","o":["CD20+","CD3+","CD56+","CD68+","CD21+"],"a":0,"e":"结节性淋巴细胞为主型霍奇金淋巴瘤的肿瘤细胞为LP细胞，表达成熟B细胞标记CD20，不表达CD15和CD30。"},{"q":"肿瘤的演进是指","o":["细胞的恶性转化","恶性肿瘤的浸润能力","恶性肿瘤的转移现象","恶性肿瘤的生长速度","恶性肿瘤在生长过程中变得越来越富有侵袭性的现象"],"a":4,"e":"肿瘤演进指恶性肿瘤在生长过程中侵袭性不断增强的现象，表现为生长加快、浸润周围组织和发生远处转移，其基础是瘤细胞不断获得基因改变而形成异质性。"},{"q":"关于肥厚型心肌病特征的叙述，下列错误的是","o":["心脏肥大","心腔扩张","左心室流出道受阻","室间隔不匀称肥厚","舒张期充盈异常"],"a":1,"e":"肥厚型心肌病以室间隔不匀称肥厚、心室腔变小、左心室流出道受阻和舒张期充盈异常为特征，心腔扩张见于扩张型心肌病。"},{"q":"原位癌与浸润癌的主要区别是","o":["肿瘤大小","基膜是否完整","边界是否清楚","有无血管浸润","有无淋巴管浸润"],"a":1,"e":"原位癌癌细胞累及上皮全层但未突破基底膜，基底膜完整；浸润癌已突破基底膜侵入间质，故二者区别的关键是基底膜是否完整。"},{"q":"肺癌一般不转移至","o":["脑","骨","肾","肝","心"],"a":4,"e":"肺癌经血道常转移至脑、骨、肝和肾上腺，心脏转移罕见；淋巴道转移首先至肺门及纵隔淋巴结。"},{"q":"潜水员从深水中过快地升向水面，容易发生","o":["肺水肿","氮气栓塞","二氧化碳栓塞","肺不张","氧气栓塞"],"a":1,"e":"从高气压环境迅速升向水面时，原溶于血液和组织的气体迅速游离，其中氮气溶解迟缓，形成大量气泡引起氮气栓塞，即减压病。"},{"q":"风湿性心内膜炎心内膜之赘生物的实质是","o":["增生的肉芽组织","风湿性肉芽肿","机化的瘢痕","混合血栓","白色血栓"],"a":4,"e":"急性风湿性心内膜炎时二尖瓣闭锁缘形成的赘生物为白色血栓，主要由血小板及少量纤维蛋白构成，与瓣膜紧密黏着不易脱落。"},{"q":"下列哪项符合支原体肺炎的病变特点","o":["包涵体形成","可引起干酪性肺炎","病灶呈节段性分布","肺的纤维素性炎症","以细支气管为中心的化脓性炎症"],"a":2,"e":"支原体肺炎病变主要位于肺间质，肺泡内渗出少、实变不明显，病灶常呈节段性分布，以下叶多见。"},{"q":"不是胰腺癌的临床表现是","o":["腹水","黄疸进行性加重","疼痛","CA19-9升高","血清碱性磷酸酶活性升高"],"a":4,"e":"胰腺癌常见表现为腹痛、进行性加重的黄疸、腹水和CA19-9升高；血清碱性磷酸酶升高主要见于骨病和肝胆疾病，不是胰腺癌的特征性表现。"},{"q":"关于大肠多发性息肉病，下列哪项是错误的","o":["是一种显性遗传病","肠黏膜上有多个息肉","息肉为腺瘤性","息肉带有错构瘤性质","息肉易发生癌变"],"a":3,"e":"家族性腺瘤性息肉病为常染色体显性遗传，因APC基因突变致肠黏膜布满腺瘤性息肉，癌变率极高，其性质为腺瘤而非错构瘤。"},{"q":"主动脉粥样硬化大体检查如图，镜下观如图所示，该病变最佳名称为","o":["脂纹","纤维斑块","粥样斑块","粥瘤性溃疡","动脉瘤形成"],"a":3,"e":"官方题库缺失图片"},{"q":"流行性乙型脑炎的传播途径","o":["呼吸道","消化道","神经","虫媒传染","皮肤接触传染"],"a":3,"e":"流行性乙型脑炎经虫媒传播，三节吻库蚊为主要传播媒介，带毒蚊叮咬吸血时病毒侵入人体，经病毒血症侵犯中枢神经系统。"},{"q":"肉芽组织和肉芽肿的区别点在于","o":["是否为慢性炎症","是否导致局部纤维化","是否由急性转化而来","组成成分不同","最后结局不同"],"a":3,"e":"肉芽组织由新生毛细血管、成纤维细胞和炎细胞构成，肉芽肿由巨噬细胞及其衍生的上皮样细胞、多核巨细胞局限性增生构成，二者组成成分不同。"},{"q":"沃-弗综合征（Waterhouse-Friderichsen syndrome）主要发生于","o":["中毒性菌痢","大叶性肺炎","间质性肺炎","流行性脑脊髓膜炎","流行性乙型脑炎"],"a":3,"e":"沃-弗综合征见于暴发型流行性脑脊髓膜炎，因双侧肾上腺广泛出血坏死，导致急性肾上腺皮质功能衰竭和休克。"},{"q":"门脉性肝硬化脾肿大的主要原因是","o":["脾脏内单核巨噬细胞增生","门静脉压力增高","肝静脉血栓形成","腹水压迫使脾静脉回流障碍","脾脏内纤维结缔组织增生"],"a":1,"e":"门静脉高压使脾静脉回流受阻，脾长期淤血而肿大并伴脾功能亢进；脾内单核巨噬细胞增生和纤维化只是继发改变。"},{"q":"痰涂片阳性检出率最高的肺癌是","o":["大细胞癌","小细胞癌","腺癌","鳞状细胞癌","细支气管肺泡癌"],"a":3,"e":"鳞状细胞癌多位于肺门附近，癌巢中央角化珠易脱落，痰液中容易查到脱落的癌细胞，故痰涂片阳性检出率最高。"},{"q":"炎症时，引起白细胞渗出最重要的因素是","o":["血管壁通透性升高","白细胞附壁","炎症介质起作用","白细胞的阿米巴运动","血管内压力升高"],"a":2,"e":"炎症的血管反应和白细胞反应均通过化学因子实现，白细胞渗出由炎症介质（趋化性细胞因子等）介导。血管壁通透性升高和白细胞附壁是渗出过程中的环节，并非引起渗出的最重要因素。"},{"q":"急性重型肝炎发生肝萎缩的主要原因是","o":["肝细胞大片坏死，仅周边残留少数变性的肝细胞","肝细胞发生大片坏死，少数残留肝细胞又能再生","肝细胞大片萎缩","肝细胞发生碎片状坏死","肝细胞发生桥接坏死"],"a":0,"e":"急性重型肝炎肝细胞发生大块坏死并被迅速清除，仅小叶周边残留少许变性肝细胞，肝体积显著缩小，重量可减至600～800g。"},{"q":"病毒性肝炎时最常见的肝细胞坏死是","o":["嗜酸性坏死","点状坏死","溶解性坏死","碎片状坏死","桥接坏死"],"a":2,"e":"病毒性肝炎时肝细胞严重气球样变后胞膜破裂、核溶解消失、细胞解体，称溶解性坏死，是最常见的坏死类型。嗜酸性坏死及点状、碎片状坏死范围较小。"},{"q":"下列选项中，不是侵袭性血管黏液瘤的特征的是","o":["好发于女性盆腔","瘤细胞核分裂很多见","瘤组织呈浸润性生长","瘤组织富含黏液","瘤组织由散在梭形、星形的间叶细胞构成"],"a":1,"e":"侵袭性血管黏液瘤好发于女性盆腔及会阴，由散在的梭形、星形间叶细胞分布于丰富黏液基质中构成，呈浸润性生长但细胞异型性小、核分裂罕见。"},{"q":"下列关于AIDS的叙述错误的是","o":["AIDS的潜伏期长","AIDS是由HIV感染所引起的","HIV是一种逆转录病毒","AIDS可通过游泳和公共洗浴感染","AIDS常伴有肿瘤的发生"],"a":3,"e":"AIDS由HIV感染引起，HIV为逆转录病毒，潜伏期长，因免疫缺陷易继发机会性感染和Kaposi肉瘤等肿瘤。传播途径为性接触、血液和母婴传播，游泳及公共洗浴不传播。"},{"q":"肾综合征出血热最常见的死亡原因是","o":["急性肾衰竭","急性心力衰竭","出血性休克","呼吸衰竭","中毒性休克"],"a":0,"e":"肾综合征出血热病程中大量血浆外渗、有效血容量下降，少尿期急性肾衰竭是最常见的死亡原因；休克和出血多发生于低血压期，及时透析可降低病死率。"},{"q":"良性肿瘤对机体的影响主要取决于肿瘤的","o":["生长方式","生长部位","生长速度","有无复发","有无转移"],"a":1,"e":"良性肿瘤分化成熟、生长缓慢、不侵袭转移，对机体影响较小，主要表现为局部压迫和阻塞症状，其危害程度主要取决于肿瘤的发生部位。生长速度、复发和转移是良恶性肿瘤的鉴别点，并非良性肿瘤影响机体的决定因素。"},{"q":"肿瘤恶性程度的高低取决于","o":["肿瘤体积的大小","肿瘤患者的临床表现","肿瘤的生长速度","肿瘤细胞的分化程度","肿瘤发生的部位"],"a":3,"e":"肿瘤恶性程度取决于瘤细胞的分化程度，分化越低、异型性越大，恶性程度越高；分级即依据分化程度、异型性和核分裂象数目判定，与体积和部位无关。"},{"q":"下列哪项不是恶性肿瘤","o":["Krukenberg瘤","Ewing肉瘤","Hodgkin瘤","淋巴瘤","多形性腺瘤"],"a":4,"e":"多形性腺瘤属良性肿瘤，由腺上皮、黏液样及软骨样组织构成，常见于涎腺。Krukenberg瘤、Ewing肉瘤、Hodgkin瘤和淋巴瘤均为恶性肿瘤。"},{"q":"诊断慢性浅表性胃炎最有意义的一项是","o":["黏膜浅层有淋巴细胞、浆细胞浸润","黏膜浅层有炎细胞浸润、腺体增生","黏膜浅层有水肿、点状出血和上皮坏死","黏膜浅层有炎细胞浸润、腺体破坏","黏膜浅层有嗜酸性粒细胞和中性粒细胞浸润"],"a":0,"e":"慢性浅表性胃炎镜下以黏膜浅层固有层淋巴细胞、浆细胞浸润为特征，腺体保持完整、无萎缩。腺体破坏或减少是慢性萎缩性胃炎的特点。"},{"q":"大肠癌的好发部位依次是","o":["直肠、升结肠、降结肠、乙状结肠、横结肠","直肠、乙状结肠、横结肠、升结肠、降结肠","直肠、乙状结肠、盲肠、升结肠、横结肠、降结肠","升结肠、横结肠、盲肠、降结肠、乙状结肠、直肠","升结肠、降结肠、盲肠、横结肠、直肠、乙状结肠"],"a":2,"e":"大肠癌好发于直肠，约占50%，其余依次为乙状结肠、盲肠、升结肠、横结肠和降结肠，与肠内容物停留时间及致癌物接触时间长短有关。"},{"q":"绒癌最常继发于","o":["正常妊娠","早产","流产","异位妊娠","葡萄胎"],"a":4,"e":"绒毛膜癌绝大多数与妊娠有关，50%以上继发于完全性葡萄胎，25%继发于自然流产或人工流产，少数发生于正常分娩或异位妊娠之后。"},{"q":"有关食管癌的组织类型，下列哪项最多见","o":["腺癌","类癌","鳞癌","未分化癌","腺鳞癌"],"a":2,"e":"中国人食管癌以鳞状细胞癌最多见，约占90%以上，多发生于食管中段；腺癌次之，多来自贲门或食管黏膜下腺体。"},{"q":"风湿病的特异性病理变化是指","o":["风湿小结形成","结缔组织的黏液变化","胶原纤维的变性、坏死","病灶中发生的纤维素样坏死","病灶内出现梭形小瘢痕"],"a":0,"e":"风湿病的特异性病变是风湿小体，由中央纤维蛋白样坏死、周围风湿细胞和淋巴细胞构成。黏液样变和纤维蛋白样坏死属非特异性改变。"},{"q":"睾丸最常见的生殖细胞肿瘤是","o":["精原细胞瘤","胚胎性癌","卵黄囊瘤","成熟型畸胎瘤","未成熟型畸胎瘤"],"a":0,"e":"精原细胞瘤起源于原始生殖细胞，是睾丸最常见的肿瘤，多见于30～40岁，镜下瘤细胞大而一致、胞质空亮并富含糖原。"},{"q":"关于急性普通型肝炎的病变，下列哪项是错误的","o":["气球样变","嗜酸性变","溶解坏死","肝细胞再生","结缔组织增生"],"a":4,"e":"急性普通型肝炎以肝细胞广泛气球样变、嗜酸性变及点状坏死为特点，可见肝细胞再生；结缔组织增生见于慢性肝炎和肝硬化。"},{"q":"关于恶性肿瘤的超微结构的叙述，错误的是","o":["细胞器数目减少","可见核内陷和怪形核","可见特异性超微结构","细胞间连接减少","核仁数目增多"],"a":0,"e":"恶性肿瘤细胞核大、核仁增多、可见核内陷和怪形核，细胞间连接减少，部分肿瘤有神经内分泌颗粒等提示分化的超微结构；其细胞器因代谢旺盛而增多、形态异常。"},{"q":"急性输卵管炎的基本病变是","o":["黏膜层的增生性炎","肌层的化脓性炎","全层的坏疽性炎","黏膜层的肉芽肿性炎","浆膜层的卡他性炎"],"a":4,"e":"急性输卵管炎时脓性渗出物积聚于输卵管腔，形成积脓，属表面化脓性炎；黏膜的浆液性炎称卡他性炎，与化脓性病变不同。"},{"q":"肺心病时，下列哪种病变最不容易见到","o":["肺动脉圆锥膨隆","心尖钝圆、肥厚，主要由右心室构成","心脏横径增大，形成横位心","室上嵴增厚、增粗","右心室向心性肥大"],"a":4,"e":"肺心病时右心室以扩张伴室壁肥厚为主，肺动脉圆锥膨隆、横位心、室上嵴增粗均可见；向心性肥大是高血压时左心室压力负荷过重的表现。"},{"q":"黏液癌最常见于","o":["血管壁","腹膜后","胃肠道","子宫","胆囊"],"a":2,"e":"黏液癌好发于胃肠道，胃肠道黏液癌侵及浆膜后可种植转移至卵巢形成Krukenberg瘤。"},{"q":"家族性腺瘤性息肉综合征属于","o":["常染色体显性遗传病","常染色体隐性遗传病","X连锁显性遗传病","X连锁隐性遗传病","Y连锁遗传病"],"a":0,"e":"家族性腺瘤性息肉病由APC基因种系突变引起，属常染色体显性遗传，杂合状态即发病，子女患病风险约50%，常在青年期出现大量腺瘤并几乎必然癌变。"},{"q":"在肉芽组织内具有收缩功能，又能产生基质和胶原的细胞是","o":["成肌纤维细胞","巨噬细胞","血管内皮细胞","成纤维细胞","中性粒细胞"],"a":0,"e":"肌成纤维细胞由成纤维细胞转变而来，兼具合成胶原和基质的功能与平滑肌样收缩功能，可缩小创面、促进创口收缩愈合。"},{"q":"细菌性痢疾的肠道病变特点是","o":["浆液性炎","纤维素性炎","肉芽肿性炎","出血性坏死炎","蜂窝织炎"],"a":1,"e":"细菌性痢疾由志贺菌引起，结肠黏膜大量纤维蛋白渗出形成假膜，属纤维素性炎，假膜脱落后遗留不规则浅表溃疡。"},{"q":"如图所示，结核结节主要由什么细胞构成","o":["浆细胞","淋巴细胞","成纤维细胞","巨噬细胞","上皮样细胞和朗汉斯巨细胞"],"a":4,"e":"官方题库缺失图片"},{"q":"下列因素与动脉阻塞无关的是","o":["血栓形成","动脉瘤","肿瘤压迫","动脉粥样硬化","动脉栓塞"],"a":1,"e":"血栓形成、动脉栓塞、动脉粥样硬化和肿瘤压迫均可阻塞动脉腔。动脉瘤是动脉壁局部薄弱后向外膨出形成的局限性扩张，本身不致管腔阻塞，破裂出血才是其主要危害。"},{"q":"贫血性梗死发生于","o":["组织疏松的器官","有双重血液供给的器官","严重淤血的器官","组织结构致密的器官","侧支循环充分的器官"],"a":3,"e":"贫血性梗死发生于组织结构较致密、侧支循环不充分的实质器官，如脾、肾、心和脑；组织疏松或有双重血供的器官多发生出血性梗死。"},{"q":"下面关于慢性支气管炎的描述不正确的是","o":["是一种由呼吸道过敏引起的以支气管可逆性发作性痉挛为特征的慢性阻塞性炎性疾病","支气管壁平滑肌断裂、萎缩","黏膜腺体增生肥大","黏膜上皮可出现鳞状化生","支气管壁充血水肿，淋巴细胞、浆细胞浸润"],"a":0,"e":"支气管可逆性发作性痉挛是支气管哮喘的特征；慢性支气管炎为支气管黏膜及周围组织的慢性非特异性炎，伴黏液腺增生肥大、平滑肌断裂萎缩和鳞状上皮化生。"},{"q":"慢性支气管炎伴哮喘的主要因素是","o":["支气管黏膜内杯状细胞增多","支气管黏膜水肿","支气管壁平滑肌痉挛","支气管腔内黏液增多","支气管管壁炎细胞浸润"],"a":2,"e":"喘息型慢性支气管炎伴哮喘样发作，主要因支气管壁平滑肌痉挛致气道狭窄，出现带哮鸣音的呼气性呼吸困难；腺体增生和黏液增多只加重气道阻塞。"},{"q":"引起急性弥漫性增生性肾小球肾炎的致病抗原常来自","o":["乙型肝炎病毒","葡萄球菌","肺炎球菌","溶血性链球菌","麻疹病毒"],"a":3,"e":"急性弥漫性增生性肾小球肾炎主要由A群乙型溶血性链球菌中的致肾炎菌株感染引起，属感染后免疫复合物介导的肾炎。"},{"q":"如图所见血栓可见于","o":["静脉内柱状血栓的尾部","毛细血管内","急性风湿性心内膜炎的瓣膜闭锁缘","动脉血栓的头部","左心房球形血栓"],"a":4,"e":"官方题库缺失图片"},{"q":"下列哪项不属于细胞异型性","o":["核数目不一","核肿胀，核膜不清","核染色质分布不均","核大小不等，核畸形","病理性核分裂象"],"a":1,"e":"细胞异型性表现为核大深染、核质比增高、核大小不一及畸形、染色质分布不均、核仁明显和病理性核分裂象；核肿胀、核膜不清属细胞水肿等变性改变。"},{"q":"关于小叶性肺炎，下列哪一项是错误的","o":["细支气管和肺泡的化脓性炎","可并发肺脓肿和脑脓肿","严重者病灶发生融合","病灶周围肺组织充血","病灶散在于两肺，以上肺多见"],"a":4,"e":"小叶性肺炎病灶散在分布于两肺，以下叶和背侧多见，而非以上肺多见。其病变为以细支气管为中心的化脓性炎，可融合、并发肺脓肿和脑脓肿，周围肺组织充血。"},{"q":"动脉瘤应该除外","o":["圆柱状动脉瘤","蜿蜒状动脉瘤","囊状动脉瘤","真性动脉瘤","舟状动脉瘤"],"a":3,"e":"动脉瘤按形态和结构分为囊状、蜿蜒状、舟状、圆柱状和假性动脉瘤等类型，真性动脉瘤是与假性动脉瘤对应的结构分类称谓，不属该形态学分型。"},{"q":"化生不可能发生于","o":["支气管假复层纤毛柱状上皮","宫颈柱状上皮","肾盂黏膜上皮","神经纤维","结缔组织"],"a":3,"e":"化生只见于上皮组织和结缔组织等可转化的细胞类型，神经纤维属高度分化的神经组织，损伤后仅能再生，不能由其他组织化生而来。"},{"q":"符合门脉性肝硬化特点的是","o":["结节大小相仿，纤维间隔薄而均匀","结节大小不等，纤维间隔厚薄不均","结节呈细颗粒状，深绿色","结节不明显","肝内散在多个粗大结节"],"a":0,"e":"门脉性肝硬化即小结节型肝硬化，再生结节大小相仿、直径多小于3mm，纤维间隔薄而均匀。坏死后性肝硬化则结节大小不等、纤维间隔宽窄不一。"},{"q":"肾梗死灶大体形态的主要特点为","o":["多呈楔形，暗红色，界限不清","多呈地图形，灰白色，界限清楚","多呈楔形，灰白色，界限清楚","多呈不规则形，暗红色，界限不清","多呈地图形，暗红色，界限不清"],"a":2,"e":"肾由终末动脉供血，梗死灶呈锥形或楔形，切面灰白、界限清楚，周边有充血出血带，属贫血性梗死。"},{"q":"病毒性肺炎的特点中不包括","o":["多由上呼吸道病毒感染蔓延引起","炎症主要累及肺间质","流感病毒常见","肺组织化脓","细胞内可出现包涵体"],"a":3,"e":"病毒性肺炎多由上呼吸道病毒向下蔓延引起，病变主要累及肺间质，流感病毒最常见，增生的上皮细胞内可出现包涵体。肺组织化脓是细菌性肺炎的特点。"},{"q":"下列关于肺癌的描述哪项是错误的","o":["同一肿瘤可有不同的组织学类型","同一肿瘤的不同部位可分化程度不一","未分化腺癌可出现肉瘤样结构","转移癌的组织学类型可与原发癌不同","肺癌中最常见组织类型是小细胞癌"],"a":4,"e":"肺癌最常见的组织学类型是腺癌，小细胞癌约占10%~15%，其分化最低、生长快、转移早，对放化疗敏感但预后最差。"},{"q":"肿瘤血行转移的确切证据是","o":["恶性肿瘤细胞侵入静脉","恶性肿瘤细胞侵入动脉","血液中查见肿瘤细胞","肿瘤细胞栓塞于远隔器官","在远隔器官形成同一类型的肿瘤"],"a":4,"e":"肿瘤细胞侵入血管并经血流到达远隔器官后继续生长，形成与原发瘤同类型的肿瘤，才是血行转移的确切证据。"},{"q":"下述成分是粥样斑块中所不具备的是","o":["胆固醇结晶","纤维结缔组织","中性粒细胞","泡沫细胞","坏死物质"],"a":2,"e":"粥样斑块由纤维帽和粥样坏死物构成，内含胆固醇结晶、泡沫细胞、坏死物质及纤维结缔组织，并有淋巴细胞和巨噬细胞浸润。中性粒细胞见于急性化脓性炎，不参与斑块构成。"},{"q":"下列组织愈合是由瘢痕修复的是","o":["心肌梗死","皮肤的浅表性缺损","月经期子宫内膜脱落","肝细胞点状坏死","慢性细菌性痢疾的假膜性炎"],"a":0,"e":"心肌细胞属永久性细胞，梗死后不能再生，由肉芽组织长入机化形成瘢痕。皮肤浅表缺损、子宫内膜周期性脱落及肝细胞点状坏死均可通过再生完全修复。"},{"q":"沃-弗综合征的发生机制是","o":["细菌性栓子所致的肾上腺广泛出血坏死","败血症引起的急性肾上腺皮质功能衰竭","大量内毒素释放所引起的弥散性血管内凝血","败血症引起的中毒性休克及肾上腺出血","严重感染而致双肾上腺广泛出血及急性肾上腺皮质功能衰竭"],"a":2,"e":"暴发型流脑时大量内毒素释放入血，引起中毒性休克与弥散性血管内凝血，二者相互促进，致双侧肾上腺广泛出血坏死及急性肾上腺皮质功能衰竭，即沃-弗综合征。"},{"q":"动脉粥样硬化合并血栓形成的最主要的机制是","o":["血流涡流形成","局部血流缓慢","内膜受损、胶原纤维暴露","局部血液凝固性增高","炎性细胞浸润"],"a":2,"e":"粥样斑块使内膜破坏、内皮脱落，内皮下胶原纤维暴露，血小板黏附聚集并激活凝血系统，是局部血栓形成的主要机制；血流缓慢和涡流只起促进作用。"},{"q":"关于骨巨细胞瘤的描述，不正确的是","o":["常在20岁以前发病","虽然是良性的，也要切除","长管骨末端常见","约1/2者有局部复发和转移","病变常由含有肿瘤的薄层骨包绕"],"a":0,"e":"骨巨细胞瘤好发于20～40岁青壮年，多位于长骨骨端，呈膨胀性溶骨性破坏，约半数可复发或转移，并非20岁以前发病。"},{"q":"致使肺梗死的血栓栓子一般来自","o":["静脉系统或右心的血栓","二尖瓣疣状血栓的脱落","门静脉的血栓脱落","左心房附壁血栓","动脉及左心房的血栓脱落"],"a":0,"e":"肺梗死多由体静脉或右心腔的血栓脱落形成栓子，随血流阻塞肺动脉分支所致；左心和主动脉系统的栓子进入体循环，引起脑、脾、肾等器官梗死。"},{"q":"下列肠疾病最可能发生癌变的是","o":["出血坏死性肠炎","局限性肠炎","慢性溃疡性结肠炎","肠结核","肠阿米巴病"],"a":2,"e":"慢性溃疡性结肠炎属癌前疾病，因黏膜上皮反复损伤、过度增生而癌变，病程越长癌变风险越高。"},{"q":"肝硬化晚期腹水的形成原因中，哪项是错误的","o":["肝细胞合成凝血酶原减少","肝淋巴液外溢","肝细胞合成蛋白功能低下","抗利尿激素、醛固酮在血内水平增高","门静脉高压"],"a":0,"e":"肝硬化腹水由门静脉高压、肝淋巴液经肝包膜外溢、低蛋白血症致血浆胶体渗透压下降及醛固酮、抗利尿激素灭活减少水钠潴留所致；凝血酶原减少引起的是出血倾向。"},{"q":"下列哪项为动脉粥样硬化早期的病理变化","o":["纤维帽形成","由于氧化LDL的毒性作用使泡沫细胞坏死","血液单核细胞迁入内膜并形成泡沫细胞","中膜平滑肌细胞迁入内膜并增生","淋巴细胞浸润心肌间质"],"a":2,"e":"动脉粥样硬化早期为脂纹，血液单核细胞迁入内膜转变为巨噬细胞源性泡沫细胞是此期的关键事件；纤维帽形成和平滑肌细胞迁入增生属进展期。"},{"q":"关于干酪样肺炎的叙述，下列哪项是正确的","o":["是原发性肺结核的一种常见类型","多由急、慢性空洞内的结核杆菌经血行播散所致","可由浸润型肺结核恶化、进展而来","病变性质为富含脂质的化脓性炎","常发生在免疫力强或变态反应低的患者"],"a":2,"e":"干酪性肺炎可由浸润型肺结核恶化进展而来，也可由急、慢性空洞内结核分枝杆菌经支气管播散引起，镜下为大片干酪样坏死伴肺泡内浆液纤维蛋白渗出。"},{"q":"下列哪种肿瘤的形状，癌的可能性大","o":["息肉状","火山口状溃疡","分叶状","结节状","乳头状"],"a":1,"e":"癌性溃疡一般较大、边缘隆起不整齐、底部凹凸不平，呈火山口状；良性溃疡多呈圆形、边缘整齐，息肉状和乳头状多见于良性肿瘤。"},{"q":"肝脏上有一转移瘤，镜下表现如图，肝外最可能的原发部位是","o":["食管","膀胱","结肠","股骨","小脑"],"a":2,"e":"官方题库缺失图片"},{"q":"胆囊最常见的恶性肿瘤是","o":["鳞癌","腺癌","腺鳞癌","腺棘皮癌","类癌"],"a":1,"e":"胆囊癌多起源于胆囊黏膜的腺上皮，组织学以腺癌最常见，约占90%，鳞癌和腺鳞癌均少见。"},{"q":"下列哪项不属于门脉高压症","o":["脾大","腹水","侧支循环形成","胃肠道淤血","蜘蛛痣"],"a":4,"e":"门脉高压症表现为脾大、腹水、侧支循环形成和胃肠道淤血；蜘蛛痣由肝功能减退致雌激素灭活减少、小动脉末梢扩张引起，属肝功能不全的表现。"},{"q":"大叶性肺炎发生肺肉质变是因为","o":["变态反应剧烈","成纤维细胞增生","机体抵抗力降低","吞噬细胞数量少","病变范围过大"],"a":3,"e":"大叶性肺炎发生肺肉质变的根本原因是中性粒细胞渗出过少，纤维蛋白溶解酶不足，渗出的纤维蛋白不能溶解而机化，肺组织呈肉样外观。"},{"q":"一坏死组织肉眼观察呈白色或微黄色、细腻，最有可能的是","o":["胰腺炎所致的脂肪坏死","脓肿所致的液化性坏死","缺血所致的凝固性坏死","免疫反应所致的纤维蛋白样坏死","结核病所致的干酪样坏死"],"a":4,"e":"干酪样坏死灶呈灰白或微黄色，质地细腻似奶酪，镜下为红染无结构的颗粒状物，是结核病的典型坏死类型。脂肪坏死呈油滴状或皂化斑，液化性坏死形成软化囊腔。"},{"q":"主动脉瓣狭窄的描述中下列哪一项是错误的","o":["心室代偿性肥大","左心房失代偿性扩张","肺淤血水肿","右心代偿性肥大","主动脉瓣区收缩期杂音"],"a":3,"e":"主动脉瓣狭窄使左心室压力负荷增加，先致左心室向心性肥大，失代偿后肺淤血、右心衰竭；右心室代偿性肥大主要由二尖瓣狭窄的肺循环高压引起。"},{"q":"槟榔肝可发展为","o":["坏死后肝硬化","门脉性肝硬化","淤血性肝硬化","胆汁性肝硬化","寄生虫性肝硬化"],"a":2,"e":"长期严重肝淤血使肝小叶中央肝细胞萎缩消失、网状纤维塌陷胶原化，肝星状细胞增生合成胶原增多，形成淤血性肝硬化。"},{"q":"恶性高血压病特征性病变是","o":["细动脉纤维素样坏死","血管壁单核细胞，中性粒细胞浸润","弓形动脉内膜显著增生","小动脉内弹力膜分裂","小动脉内微血栓形成"],"a":0,"e":"恶性高血压的特征性病变是坏死性细动脉炎，表现为细动脉壁纤维素样坏死，主要累及肾。良性高血压的细动脉硬化则为玻璃样变，二者机制不同。"},{"q":"超急性排斥反应多发生在","o":["移植后数月","移植后数分钟或数小时","移植后数日","随时可能发生","移植后数年"],"a":1,"e":"超急性排斥反应由受者体内预存的供体特异性HLA抗体或ABO血型不符引起，属Ⅲ型超敏反应，于移植后数分钟至数小时发生，无法逆转。"},{"q":"口眼干燥综合征患者血清内特征性抗体是","o":["抗HIV抗体阳性","抗HLA抗体阳性","抗IgE分子Fc段抗体阳性","抗核抗体阳性","抗SS-A抗体和抗SS-B抗体阳性"],"a":4,"e":"干燥综合征患者血清中抗SSA抗体和抗SSB抗体阳性，二者对本病具有相对特异性；其靶抗原为核糖核蛋白，与腺上皮及导管上皮损伤相关。"},{"q":"引起成人肾病综合征最常见的原因为","o":["系膜增生性肾小球肾炎","膜增生性肾小球肾炎","局灶性节段性肾小球硬化","脂性肾病","膜性肾小球肾炎"],"a":4,"e":"膜性肾小球病是成人肾病综合征最常见的原因，以基膜增厚、钉突形成为特点，免疫荧光见基膜颗粒状IgG和C3沉积；脂性肾病是儿童肾病综合征最常见的原因。"},{"q":"膜性肾小球肾炎的病变特点是","o":["肾小球毛细血管基膜变薄、断裂，通透性增加","肾小球毛细血管基膜增厚、滤过率降低","肾小球毛细血管基膜变薄、断裂","肾小球毛细血管基膜增厚、通透性增加","肾小球毛细血管基膜增厚呈双车轨状或分层状"],"a":3,"e":"膜性肾小球病以基膜弥漫增厚、通透性增高为特点，上皮侧免疫复合物沉积使蛋白大量漏出，临床主要表现为肾病综合征。"},{"q":"关于慢性纤维空洞型肺结核的叙述，下列哪项是正确的","o":["结核空洞多位于肺下叶","病变局限，组织破坏不明显","无肺功能受损害","少见的继发性肺结核的一个类型","多由浸润型肺结核形成急性空洞后经久不愈发展而来"],"a":4,"e":"慢性纤维空洞型肺结核多由浸润型肺结核形成的急性空洞经久不愈、洞壁纤维化发展而来，空洞多位于肺上叶，可致肺广泛纤维化和肺功能损害。"},{"q":"下列不属于非特异性反应性淋巴滤泡增生特点的是","o":["淋巴结大，淋巴滤泡增生，生发中心明显扩大","增生的淋巴滤泡内有各种转化的淋巴细胞，核较大，有裂或无裂，核分裂象多见","增生的淋巴滤泡有多数巨噬细胞，胞质内含有吞噬的细胞碎屑","增生的淋巴结结构破坏，淋巴滤泡消失","在滤泡之间的淋巴组织内可见浆细胞、组织细胞及少量中性粒细胞和嗜酸性粒细胞浸润，淋巴窦内的组织细胞和内皮细胞增生"],"a":3,"e":"非特异性反应性淋巴滤泡增生时淋巴结结构保存，滤泡增多、生发中心扩大，内有转化B细胞和吞噬碎屑的巨噬细胞，滤泡间有浆细胞浸润。结构破坏、滤泡消失是恶性淋巴瘤的表现。"},{"q":"下列哪一项不符合鼻咽癌的特性","o":["发生于鼻咽部柱状上皮","最常见于鼻咽的顶部","常破坏颅底骨并侵入颅内","癌组织有迅速向深部浸润生长的倾向","晚期常经淋巴道及血行转移至颈部淋巴结及肺、骨、肝等处"],"a":4,"e":"鼻咽癌早期即发生颈淋巴结转移且常为首发症状，并非晚期；癌组织易向深部浸润破坏颅底骨，并经淋巴道、血行转移至肺、骨和肝。"},{"q":"原发性高血压脑出血最常见的部位是","o":["大脑皮质","豆状核和丘脑","蛛网膜下隙","内囊和基底核","侧脑室"],"a":3,"e":"高血压性脑出血最常见于基底核（豆状核）和内囊，因豆纹动脉由大脑中动脉垂直分出，承受压力大，血压骤升时易破裂。"},{"q":"链球菌感染后肾小球肾炎电镜下沉积物多存在于","o":["内皮下","基底膜致密层","基底膜和脏层上皮细胞间，呈驼峰状","基底膜和脏层上皮细胞间，被基底膜钉状突起分隔","壁层上皮下"],"a":2,"e":"电镜下电子致密物主要位于脏层上皮细胞与肾小球基膜之间，呈驼峰状；免疫荧光显示颗粒状IgG、IgM和C3沉积。"},{"q":"膀胱癌的最常见转移部位是","o":["子宫旁、髂动脉旁和主动脉旁淋巴结","种植到卵巢","局部淋巴结","肝","肺"],"a":2,"e":"膀胱癌以淋巴道转移为主要途径，最先转移至盆腔局部淋巴结，晚期可经血行至肺、肝和骨。种植性转移少见。"},{"q":"关于结外NK/T细胞淋巴瘤的叙述，下列哪项是错误的","o":["瘤细胞大小不等，形态多样","伴有凝固性坏死和多种炎细胞浸润","肿瘤性淋巴细胞散在分布或弥漫分布","是一种非霍奇金淋巴瘤","好发于年轻人"],"a":4,"e":"结外NK/T细胞淋巴瘤多见于成年男性，好发于鼻腔，瘤细胞大小不等、形态多样，常伴凝固性坏死和多种炎细胞浸润，属非霍奇金淋巴瘤。"},{"q":"左心衰竭病人的股静脉血栓脱落可引起","o":["肺凝固性坏死","肺液化性坏死","肺出血性梗死","肺贫血性梗死","心肌梗死"],"a":2,"e":"左心衰竭时肺淤血、组织疏松，股静脉血栓脱落后栓塞肺动脉分支，因双重血供和淤血，梗死灶内出血明显，形成肺出血性梗死。"},{"q":"肝豆状核变性的特点是","o":["铁代谢障碍","脂类代谢障碍","铜代谢障碍","糖类代谢障碍","维生素C代谢障碍"],"a":2,"e":"肝豆状核变性为常染色体隐性遗传的铜代谢障碍病，铜不能正常排出而蓄积于肝、脑和角膜，引起肝硬化、锥体外系症状及角膜K-F环。"},{"q":"下列哪种疾病不属于慢性阻塞性肺疾病","o":["支气管炎","肺气肿","支气管哮喘","慢性肺源性心脏病","支气管扩张症"],"a":3,"e":"慢性阻塞性肺疾病包括慢性支气管炎、肺气肿、支气管哮喘和支气管扩张症；慢性肺源性心脏病是这些疾病引起肺动脉高压后所致的心脏病变。"},{"q":"关于肺气肿患者的临床表现，下面错误的是","o":["逐渐加强的吸气性呼吸困难","低氧血症","桶状胸","胸透肺野透明度增加","肺动脉高压和肺源性心脏病"],"a":0,"e":"肺气肿因阻塞性通气障碍出现呼气性呼吸困难，而非吸气性呼吸困难；桶状胸、低氧血症及肺动脉高压、肺心病均为其表现。"},{"q":"胃窦部黏膜组织活检，镜下如图所示，胃黏膜发生的有关病变的描述，错误的是","o":["黏膜腺体中度肠上皮化生","这种分化上的转向，只发生于同源细胞之间","可分为不完全肠化和完全肠化","该化生对机体有利，不会发生恶变","该化生可恶变形成肠型腺癌"],"a":3,"e":"官方题库缺失图片"},{"q":"风湿性心内膜炎会出现以下哪种特征性结构","o":["Osler结节","Negri小体","Aschoff小体","环形红斑","McCallum斑"],"a":4,"e":"风湿性心内膜炎病变累及房、室内膜时引起内膜灶状增厚及附壁血栓形成，受血流反流冲击较重处内膜灶状增厚称为McCallum斑。Aschoff小体位于心肌间质，非心内膜炎特征。"},{"q":"沃-弗综合征发生时，下列哪个器官病变比较明显","o":["甲状腺","肾上腺","胸腺","胰腺","肾脏"],"a":1,"e":"暴发型脑膜炎双球菌败血症时双侧肾上腺广泛出血坏死，急性肾上腺皮质功能衰竭引起休克和皮肤瘀斑，故肾上腺病变最明显。"},{"q":"乳腺癌患者中，常选择哪组抗原检测对临床指导治疗和判断肿瘤预后有积极意义","o":["ER、PR、CK-L、CK-H、P53","ER、PR、P53、CK-P、nm23","ER、PR、nm23、S-100、EMA","ER、PR、nm23、c-erbB-2、P53","ER、PR、c-erbB-2、Ck-P EMA"],"a":3,"e":"乳腺癌检测ER、PR可指导内分泌治疗并判断预后，c-erbB-2过表达提示预后差且可行靶向治疗，nm23与转移抑制、p53与预后相关，该组指标临床意义最大。"},{"q":"关于细胞外基质表述错误的是","o":["生成多种细胞因子","参与血管新生","影响细胞的分化","维持组织的结构和弹性","参与细胞再生"],"a":0,"e":"细胞外基质可维持组织结构和弹性、参与血管新生、影响细胞分化并参与细胞再生，但本身不生成细胞因子；细胞因子由细胞合成并分泌。"},{"q":"以下哪项与流脑、乙脑的区别无关","o":["中枢神经系统病变","病原微生物","传染途径","病变性质","炎症细胞种类"],"a":0,"e":"流脑与乙脑的区别在于病原微生物、传染途径、病变性质及炎症细胞种类，两者均累及中枢神经系统，故中枢神经系统病变不能作为区别点。"},{"q":"慢性支气管炎时，咳黏液泡沫痰的病变基础是","o":["支气管黏膜上皮损伤","黏液腺体肥大，黏膜上皮内杯状细胞增多","支气管壁纤维化、管腔狭窄","支气管平滑肌破坏","支气管扩张"],"a":1,"e":"慢性支气管炎因黏液腺体肥大、杯状细胞增多使黏液分泌亢进，与浆液混合形成黏液泡沫痰，是咳痰的病理基础。"},{"q":"最常见的栓子是","o":["脱落的肿瘤细胞团","空气","血栓","羊水","寄生虫"],"a":2,"e":"最常见的栓子是脱落的血栓或其节段，血栓栓塞占全部栓塞的99%以上；脂肪滴、空气、羊水和肿瘤细胞团均少见。"},{"q":"关于风湿性心内膜炎，下列叙述哪项是错误的","o":["赘生物如粟粒，灰白色，成串珠状、单行排列","赘生物附着牢固，易机化","赘生物多位于瓣膜闭锁缘","受累瓣膜易发生溃疡及穿孔","其实质是白色血栓"],"a":3,"e":"风湿性心内膜炎赘生物为白色血栓，附着牢固、不易脱落，受累瓣膜一般无溃疡和穿孔；溃疡、穿孔是感染性心内膜炎的特点。"},{"q":"下列疾病均能引起门脉高压症，但以哪种疾病的门脉高压最为明显","o":["血吸虫性肝硬化","门脉性肝硬化","胆汁性肝硬化","淤血性肝硬化","坏死后性肝硬化"],"a":0,"e":"血吸虫虫卵在门管区反复沉积，引起纤维组织大量增生形成干线型纤维化，虫卵和纤维条索压迫门静脉分支，门静脉高压出现早且显著，常致巨脾和食管静脉曲张。"},{"q":"急性普通型病毒性肝炎中具有诊断意义的病变是","o":["肝细胞脂肪变性","肝细胞细胞质疏松化和气球样变","肝细胞嗜酸性坏死","肝细胞水肿","肝细胞玻璃样变性"],"a":1,"e":"急性普通型病毒性肝炎以肝细胞广泛水肿为特点，胞质疏松化和气球样变最常见并具诊断意义，坏死多为单个细胞的嗜酸性坏死，程度轻。"},{"q":"下列哪项是伤口二期愈合的特点","o":["创面小","创面不洁、伴感染","手术切口","肉芽组织少","形成瘢痕小"],"a":1,"e":"二期愈合见于组织缺损大、创缘不整、无法对合或伴感染、异物的伤口，坏死组织多，肉芽组织填充后形成较大瘢痕；手术切口创缘整齐、对合严密，属一期愈合。"},{"q":"透明细胞肉瘤免疫组化示","o":["CK（＋）","HMB45（＋）","EMA（＋）","Desmin（＋）","CD117（＋）"],"a":1,"e":"透明细胞肉瘤属黑色素细胞分化肿瘤，免疫表型表达HMB45与S-100；CK、EMA为上皮标志物，Desmin为肌源性标志物，均不表达。"},{"q":"病变呈节段性分布的局限性肠炎是指","o":["慢性溃疡性结肠炎","克罗恩病","细菌性痢疾","肠阿米巴病","伤寒"],"a":1,"e":"克罗恩病又称局限性肠炎，病变呈节段性分布，好发于回肠末端，肠壁全层炎并见纵行溃疡和铺路石样改变，非干酪样肉芽肿为其特征。"},{"q":"引起病毒性心肌炎的常见病原体是","o":["草绿色链球菌","金黄色葡萄球菌","痢疾杆菌","柯萨奇B组病毒","朊病毒"],"a":3,"e":"病毒性心肌炎由嗜心肌性病毒感染引起，常见病毒为柯萨奇B组病毒，其次为柯萨奇A组、埃可病毒和腺病毒。草绿色链球菌、金黄色葡萄球菌所致者为细菌性感染。"},{"q":"心肌脂肪变性引起“虎斑心”时，最易出现变化的部位是","o":["左心房及左心耳内膜下心肌","右心室内膜下心肌及乳头肌","左心室内膜下心肌及乳头肌","右心房及右心耳内膜下心肌","左心室前壁及心尖区心肌"],"a":2,"e":"虎斑心见于慢性缺氧或中毒时的心肌脂肪变，常累及左心室内膜下心肌和乳头肌；脂肪变区呈黄色并与正常暗红色心肌相间，形成黄红相间的斑纹。"},{"q":"寄生虫感染引起的炎症，下列哪种细胞多见","o":["中性粒细胞","嗜酸性粒细胞","单核巨噬细胞","淋巴细胞","浆细胞"],"a":1,"e":"寄生虫感染和IgE介导的过敏反应时，嗜酸性粒细胞在趋化因子作用下浸润病灶，其颗粒中的主要碱性蛋白对寄生虫有独特毒性。"},{"q":"脂肪变性的肉眼观察其主要的病变特点是","o":["体积减小，有油腻感，重量减轻，黄色质软","体积增大，有油腻感，重量正常，白色质软","体积增大，有油腻感，重量增加，黄色质软","体积增大，有油腻感，重量增加，红色质软","体积增大，有油腻感，重量减轻，黄色质软"],"a":2,"e":"脂肪变器官体积增大、边缘圆钝、颜色淡黄、质地柔软，切面有油腻感，重量增加；镜下胞质内出现大小不等的脂滴，重者充满细胞并将核挤向一侧。"},{"q":"恶性高血压患者死于尿毒症的主要原因是","o":["肾小管坏死","肾间质出血","肾动脉血栓形成","肾小球纤维化","肾细小动脉纤维素样坏死"],"a":4,"e":"恶性高血压时肾细小动脉发生纤维素样坏死，继发增生性小动脉硬化和肾小球缺血硬化，短期内出现肾功能衰竭，是死于尿毒症的主要原因。"},{"q":"晚期胃癌常转移到左锁骨上淋巴结，后者又称","o":["Aschoff淋巴结","Ewing淋巴结","Krukenberg淋巴结","Schwann淋巴结","Virchow淋巴结"],"a":4,"e":"胃癌晚期癌细胞经淋巴管进入胸导管，转移至左锁骨上淋巴结，该处即Virchow淋巴结，是胃癌远隔淋巴转移的重要体征。"},{"q":"高分化的恶性肿瘤的主要特征是","o":["细胞形态和组织结构与起源组织相似","不向周围组织直接蔓延","不发生转移","手术切除后一般不复发","对机体危害程度较轻"],"a":0,"e":"高分化恶性肿瘤的细胞形态和组织结构与起源组织相似，异型性小，但仍具浸润和转移能力。分化程度只反映相似性，不能据此否定其恶性生物学行为。"},{"q":"如图，此肿瘤生长方式是","o":["浸润性生长","外生性生长","膨胀性生长","浸润与外生","膨胀与浸润"],"a":0,"e":"官方题库缺失图片"},{"q":"下列病变属于梗死的是","o":["深Ⅱ度烧伤","足坏疽","刀割伤","病毒性肝炎","脓肿"],"a":1,"e":"足坏疽由动脉粥样硬化致肢体缺血坏死，属梗死。深Ⅱ度烧伤为热损伤，刀割伤为创伤，脓肿为化脓性炎，病毒性肝炎为炎症。"},{"q":"单侧肾切除后，残留肾脏发生的病变为","o":["适应性肥大","代偿性肥大","生理性增生","病理性增生","化生"],"a":1,"e":"一侧肾切除后，对侧肾通过细胞体积增大来完成功能代偿，属代偿性肥大；该过程由功能负荷增加引起，不伴细胞数量增多。"},{"q":"霍奇金淋巴瘤中的反应性细胞是","o":["Reed-Sternberg cell","镜影细胞","淋巴细胞、浆细胞","霍奇金细胞","陷窝细胞"],"a":2,"e":"霍奇金淋巴瘤组织学以多种炎症细胞混合浸润为背景，包括淋巴细胞、浆细胞、中性粒细胞、嗜酸性粒细胞和组织细胞等反应性细胞。Reed-Sternberg细胞、镜影细胞、霍奇金细胞和陷窝细胞均为肿瘤细胞。"},{"q":"关于风湿病增生期Aschoff小体的描述中，下列错误的是","o":["小体中心部为纤维素样坏死灶","坏死灶周围可见Aschoff巨细胞","坏死灶周围可见Anitschkow细胞","主要成分为Langhans细胞","小体内还有少量淋巴细胞"],"a":3,"e":"Aschoff小体由纤维素样坏死灶、Aschoff巨细胞、Anitschkow细胞及少量淋巴细胞构成，不含Langhans细胞。Langhans巨细胞是结核结节的组成成分。"},{"q":"进展期胃癌最多见的类型是","o":["息肉型","蕈伞型","溃疡型","浸润型","胶样癌"],"a":2,"e":"进展期胃癌肉眼分型中溃疡型最多见，癌组织坏死脱落形成皿状或火山口状溃疡。息肉型、浸润型相对少见。"},{"q":"动脉粥样硬化固缩肾表现为","o":["表面呈颗粒状","两肾肿大，颜色苍白","肾脏可见凹陷性瘢痕","肾内形成多发性栓塞小脓肿","两肾肿大充血，呈“大红肾”"],"a":2,"e":"动脉粥样硬化斑块合并血栓形成致肾组织梗死后，梗死灶机化遗留较大凹陷瘢痕，多个瘢痕使肾脏缩小，称动脉粥样硬化性固缩肾。"},{"q":"以下关于Barrett食管的说法错误的是","o":["是一种化生性病变","常发生在食管胃交界齿状线以上数厘米","可继发糜烂、溃疡","不会发生癌变","主要并发症包括狭窄、出血、裂孔疝"],"a":3,"e":"Barrett食管是食管远端鳞状上皮被柱状上皮取代的化生性病变，属癌前病变，可继发糜烂、溃疡、狭窄和裂孔疝，并可发生腺癌。"},{"q":"与门静脉高压无关的是","o":["慢性淤血性脾大","食管下段静脉丛曲张","胃肠壁淤血、水肿","肝掌","腹水"],"a":3,"e":"门静脉高压表现为慢性淤血性脾大、食管下段静脉曲张、胃肠壁淤血水肿和腹水；肝掌是肝功能减退致雌激素灭活障碍的表现，与门静脉高压无关。"},{"q":"下列哪项是恶性肿瘤的主要特征","o":["核分裂象多见","细胞丰富","瘤巨细胞形成","浸润性生长和转移","血管丰富"],"a":3,"e":"浸润性生长和转移是恶性肿瘤最主要的生物学特征，也是区别良恶性最可靠的依据；核分裂增多、瘤巨细胞和血管丰富均缺乏特异性。"},{"q":"不符合乳腺癌的描述是","o":["多来源于导管上皮细胞","多发生于外上象限","以鳞癌多见","多数为实性癌","以淋巴道转移多见"],"a":2,"e":"乳腺癌多起源于导管上皮，好发于外上象限，以浸润性导管癌等腺癌为主，多经淋巴道转移至同侧腋窝淋巴结；鳞癌仅偶见于化生性癌，并非多见类型。"},{"q":"胃溃疡的合并症最常见的是","o":["梗阻","穿孔","出血","癌变","粘连"],"a":2,"e":"胃溃疡最常见的合并症是出血，因溃疡底部血管被侵蚀破裂所致；穿孔、幽门梗阻和癌变的发生率均较低。"},{"q":"下列不是病理学的研究范畴的是","o":["病因学","发病学","疾病的治疗","病理变化","患病机体的功能、代谢变化"],"a":2,"e":"病理学研究疾病的病因、发病机制、病理变化及患病机体的功能代谢变化，疾病的治疗属于临床医学范畴。"},{"q":"子宫内膜异位症最多见于","o":["子宫直肠窝","子宫肌层","卵巢","输卵管","子宫韧带"],"a":2,"e":"子宫内膜异位症约80%发生于卵巢，其次为子宫阔韧带、直肠子宫陷凹和盆腔腹膜；异位内膜随月经周期出血，形成紫红色结节并致纤维性粘连。"},{"q":"图为休克死亡者，在肺组织切片中可见","o":["混合血栓","红色血栓","透明血栓","白色血栓","附壁血栓"],"a":2,"e":"休克时微循环内形成透明血栓，主要由纤维蛋白构成，见于毛细血管，为DIC的典型改变。"},{"q":"右冠状动脉阻塞引起的梗死区域为","o":["右心房、右心室","左心室侧壁及右心室","室间隔前2/3、心尖及右心室","左心室后壁、室间隔后1/3及右心室","室间隔后2/3及右心房、右心室"],"a":3,"e":"右冠状动脉供血区为左心室后壁、室间隔后1/3及右心室，其阻塞约占心肌梗死的25%；左前降支阻塞累及左心室前壁、心尖及室间隔前2/3。"},{"q":"慢性支气管炎最常见的并发症是","o":["支气管扩张症","大叶性肺炎","肺气肿","小叶性肺炎","肺脓肿"],"a":2,"e":"肺气肿是慢性支气管炎最常见的并发症。肺气肿指末梢肺组织含气量过多伴肺泡间隔破坏，常继发于慢性支气管炎等肺阻塞性疾病。"},{"q":"经过治疗的毒性甲状腺肿的形态学特征是","o":["滤泡增生，滤泡大小不等","滤泡内胶质少而稀薄","滤泡上皮细胞呈立方形或高柱状","滤泡上皮细胞变矮小，间质血管少","多量淋巴细胞浸润并有滤泡形成"],"a":3,"e":"毒性甲状腺肿经碘剂及抗甲状腺药物治疗后，滤泡上皮变矮、增生减轻，胶质增多变浓，吸收空泡和间质血管减少。未治疗者表现为滤泡上皮高柱状、胶质少而稀薄。"},{"q":"陷窝细胞常见于霍奇金淋巴瘤的哪种组织学类型","o":["结节性淋巴细胞为主型","淋巴细胞为主型","淋巴细胞减少型","混合细胞型","结节硬化型"],"a":4,"e":"结节硬化型经典型霍奇金淋巴瘤的肿瘤细胞为陷窝细胞，伴胶原纤维束将淋巴结分隔成结节；混合细胞型以典型R-S细胞为主。"},{"q":"血管内皮细胞、成纤维细胞、淋巴细胞常见于","o":["急性炎症","炎性肉芽组织","伤口愈合处","肉芽肿性炎","化脓性炎症"],"a":1,"e":"炎性肉芽组织由新生毛细血管、增生的成纤维细胞及浸润的淋巴细胞、巨噬细胞构成，三者并存提示炎症与修复同时进行。肉芽肿性炎以巨噬细胞衍生细胞形成结节为特征。"},{"q":"肺癌切除后，残余肺组织过度充气称为","o":["全腺泡型肺气肿","腺泡中央型肺气肿","腺泡周围型肺气肿","瘢痕旁肺气肿","代偿性肺气肿"],"a":4,"e":"肺叶切除后残余肺组织肺泡代偿性过度充气，称代偿性肺气肿，通常不伴气道和肺泡壁破坏，或仅有少量肺泡壁破裂。"},{"q":"目前认为乙型肝炎病毒引起肝细胞损害的主要机制是","o":["病毒直接破坏肝细胞膜","病毒损坏肝细胞的线粒体","病毒代谢产物的损害作用","激活机体细胞免疫反应损害肝细胞","通过抗原抗体反应激活补体"],"a":3,"e":"乙型肝炎病毒不直接杀伤肝细胞，其抗原表达于肝细胞膜后激活细胞毒性T淋巴细胞，通过细胞免疫反应导致肝细胞损伤和坏死。"},{"q":"下列均为假小叶的特点，但除外","o":["肝小叶内中央静脉缺如","肝小叶内出现汇管区","肝小叶内可有2条以上中央静脉","肝细胞排列紊乱，可出现双核肝细胞","肝细胞广泛凋亡，大量凋亡小体形成"],"a":4,"e":"假小叶内中央静脉缺如、偏位或出现两条以上，可见汇管区，肝细胞排列紊乱并有双核肝细胞；其形成源于肝细胞坏死与结节状再生，而非广泛凋亡。"},{"q":"酒精性肝炎镜下表现为肝细胞脂肪变性，并可见形成","o":["Russell小体","Negri小体","Dutcher小体","Mallory小体","Aschoff小体"],"a":3,"e":"酒精性肝炎的三大病变为肝细胞脂肪变性、Mallory小体形成和点灶状坏死伴中性粒细胞浸润，Mallory小体由细胞角蛋白中间丝聚集而成，是酒精性肝损伤的特征性结构。"},{"q":"Krukenberg瘤指的是转移的","o":["肝细胞癌","胃黏液腺癌","乳腺癌","卵巢癌","肺小细胞癌"],"a":1,"e":"Krukenberg瘤是胃黏液癌（特别是印戒细胞癌）经种植性转移至卵巢形成的转移性黏液腺癌，镜下见富于黏液的印戒细胞弥漫浸润。"},{"q":"下列哪种炎症介质不具有对白细胞的阳性趋化作用","o":["白细胞三烯","IL-8","IL-5","TNF","缓激肽"],"a":4,"e":"缓激肽使细动脉扩张、血管通透性增高、支气管平滑肌收缩并引起疼痛，无白细胞趋化作用。IL-8、IL-5、TNF及白细胞三烯均能趋化和激活白细胞。"},{"q":"风湿性心脏病瓣膜疣赘物的结局是","o":["溶解吸收","机化引起心瓣膜病变","软化脱落引起栓塞","引起瓣膜穿孔","引起败血症"],"a":1,"e":"风湿性心内膜炎的疣状赘生物附着牢固、不易脱落，机化后使瓣膜增厚变硬、瓣叶粘连，导致瓣膜口狭窄和/或关闭不全。"},{"q":"血栓中的纤维蛋白被溶解称为","o":["血栓再通","溶解吸收","血栓机化","血栓钙化","血栓栓塞"],"a":1,"e":"血栓内纤维蛋白被纤溶酶溶解、血栓软化吸收，小的血栓可完全溶解消散；较大血栓溶解不完全时表面可被内皮覆盖或发生机化。"},{"q":"下列哪项不属于动脉性充血","o":["膀胱减压后充血","炎性充血","肝硬化时，胃肠道和脾脏充血","进食后的胃肠道充血","运动时骨骼肌充血"],"a":2,"e":"肝硬化时胃肠道和脾脏充血由门静脉回流受阻所致，属静脉性淤血；减压后充血、炎性充血及进食、运动时的充血才是动脉性充血。"},{"q":"低蛋白血症引起水肿的机制是","o":["毛细血管内压升高","血浆胶体渗透压下降","组织间液的胶体渗透压升高","组织间液的流体静压下降","毛细血管的流体静压升高"],"a":1,"e":"血浆胶体渗透压主要由白蛋白维持，白蛋白合成减少或大量丧失时胶体渗透压下降，有效滤过压增大，组织液生成增多而致水肿。"},{"q":"动脉粥样硬化主要累及","o":["小动脉的内膜","大、中动脉的中膜","大、中动脉的内膜","小动脉的中膜","细动脉壁"],"a":2,"e":"动脉粥样硬化主要累及大、中动脉的内膜，在内膜下形成脂纹、纤维斑块和粥样斑块，导致管腔狭窄。细小动脉玻璃样变则见于高血压和糖尿病。"},{"q":"导致肺褐色硬化的疾病是","o":["肺动脉狭窄","三尖瓣狭窄","二尖瓣狭窄","肺动脉栓塞","硅沉着病"],"a":2,"e":"二尖瓣狭窄使肺静脉压升高、肺长期淤血，肺泡内红细胞被巨噬细胞吞噬形成含铁血黄素，肺组织纤维化呈棕褐色，即肺褐色硬化。"},{"q":"下列哪种疾病不出现肺透明膜","o":["病毒性肺炎","慢性支气管炎","SARS","新生儿呼吸窘迫综合征","腺病毒肺炎"],"a":1,"e":"慢性支气管炎为气道的慢性非特异性炎症，不损伤肺泡上皮及基底膜，故不形成透明膜；透明膜见于病毒性肺炎、SARS和新生儿呼吸窘迫综合征。"},{"q":"大叶性肺炎的病变表现描述中错误的是","o":["肺脏胸膜充血、水肿伴纤维素渗出","病灶的病变特点是以细支气管为中心的化脓性炎","炎症不破坏肺泡壁结构","病变多累及一个大叶或一肺段","炎症以纤维素渗出为主"],"a":1,"e":"大叶性肺炎以肺泡内纤维素渗出为主，病变累及一个大叶或肺段，不破坏肺泡壁结构。以细支气管为中心的化脓性炎是小叶性肺炎的病变特点。"},{"q":"不符合肿瘤性生长的特点是","o":["与机体的需要不协调","致瘤因素消除后就不继续生长","生长旺盛","不同程度失去分化成熟能力","相对自主性生长"],"a":1,"e":"肿瘤性增殖具有相对自主性，即使致瘤因素已消除仍持续生长，与机体需要不协调，生长旺盛并不同程度失去分化成熟能力。"},{"q":"关于肝硬化的叙述，下列哪项是错误的","o":["蜘蛛状血管痣","男性女性化","腹腔积液","胃肠道出血","病因被消除后，肝脏的正常结构可以恢复"],"a":4,"e":"肝硬化时肝小叶结构被假小叶取代、纤维间隔形成，属不可逆病变，病因去除后结构亦不能恢复正常；蜘蛛痣、男性女性化、腹水和消化道出血均为其临床表现。"},{"q":"流行性脑脊髓膜炎最常见的病原菌是","o":["肺炎球菌","脑膜炎球菌","金黄色葡萄球菌","溶血性链球菌","大肠杆菌"],"a":1,"e":"流行性脑脊髓膜炎由脑膜炎双球菌经呼吸道传播引起，冬春季可流行，病变为软脑膜的急性化脓性炎症，脑脊液呈脓性。"},{"q":"髓母细胞瘤具有以下特点，但除外下列哪项","o":["间质较少","核分裂象较多","常发生于成年人","有菊形团形成","瘤细胞多呈圆形、瓜子形，细胞质少，核深染"],"a":2,"e":"髓母细胞瘤发生于小脑蚓部，多见于儿童，属WHO 4级胚胎性肿瘤；瘤细胞小、圆形或瓜子形、胞质少核深染，核分裂象多，可见Homer-Wright菊形团，间质少。"},{"q":"以下关于急性胆囊炎的表现，描述错误的是","o":["麦氏点压痛","腹痛位于右上腹","多有胆囊结石病史","常在进食油腻食物后出现","腹痛程度常随体位改变而改变"],"a":0,"e":"麦氏点压痛是急性阑尾炎的典型体征；急性胆囊炎表现为右上腹痛、进食油腻食物后发作，多有胆囊结石病史，疼痛可随体位改变。"},{"q":"急性炎症时，炎症局部血流速度的减慢主要是由于","o":["血管内流体静压下降","血管口径变小，血流阻力增大","微血管通透性升高的结果","组织水肿升高对血管产生压迫","血管阻塞"],"a":2,"e":"炎症时血管通透性升高致血浆渗出、血液浓缩黏稠，血流阻力增大，血流速度减慢甚至淤滞。血管内流体静压下降并非血流减慢的主要原因。"}];
